INSERT INTO `megalitos` (`id`,`nombre`,`tipologia_id`,`tipologia_texto`,`municipio`,`ubicacion`,`itinerario_texto`,`hoja_cartografica`,`utm_x`,`utm_y`,`altitud`,`lat`,`lon`,`coord_fuente`,`localizado_fecha`,`localizado_fecha_texto`,`localizado_autor`,`descripcion`,`excavacion`,`observaciones`,`caracteristicas`,`otros_aspectos`) VALUES
(1,'ANGAITZA',8,'Dólmen corto cerrado','Concejo de Beorburu. Ayuntamiento del Valle de Juslapeña','Cerca del alto de Angaitza','A 15 minutos desde Beorburu, en dirección Norte Hoja cartográfica Nº 115-12','115-12',603400,4753750,860,42.927499,-1.734226,'utm',NULL,'sábado, abril 15, 1905','P. Urra','Túmulo circular poco determinable. Cámara de recinto rectangular, más bien trapecial por tender las paredes a cerrarse a la entrada. Cubierta desplazada al realizar la cata de reconocimiento, por lo que se encuentra fragmentada. Documentado por tres diapositivas, en las que debido a la maleza tapa la conformación del monumento. ? W.E. 10 m ? N. S. 11m Altura aprox. 1m Tierra y piedra Viane tiene medidas las losas Hoy se ven Losa de cabecera orientada a 15º Losa N (W.E.) orientada a 120º Losa S (W.E.) orientada a 77º 6 piedras ( A6 x 40) al E. 1 piedrra (1 x 70) 1 piedra (1,3 x 1,7) E. enterradas 1 piedra ? E. enterradas 1 piedra 1 x 1 a SE (cierre cámara ?)','En 1932, se realizó una cata de reconocimiento, por P. Urra','P. Urra se lo comunicón a J.M. de Barandiarán y la cata de reconocimiento dio restos humanos cuyo paradero es desconocido. Este dómen tiene posibilidades de ser reconstruido, colocándole la tapa . Hay que levantar un croquis y medir las locas. Topónimo ARANGAITZ en mapa 1/25.000 115-1 Bibliografía: J.M. de Barandiarán. Catálogo des stations. 1946 J.M. de Barandiarán . Hombre prehistórico. 1953',NULL,'Bloc 12. Atez Ulzama'),
(2,'LIXETO',1,'¿Dolmen?','Olave','Al NE del pueblo de Olave en la cota 912m','Osacain',NULL,615830,4749735,912,42.889568,-1.582778,'utm','1977-10-22','sábado, octubre 22, 1977','Franciso Ondarra','Túmulo de unos 18m ? con caráter central de uno 8m de parte a parte altura media de 1,5m Dos losas erguidas: Losa nº 1. W de 0,5m de alto, 1,5m de largo y 0,2m de grueso Losa nº 2 SE 1,7m " , 0,75m " y 0,2/0,25m " Sobre esta losa se alza un buzón de montañeros con la leyenda: S.D. ERLAITZ-IRUN Losas calizas del terreno. El túmulo se encuentra cubierto de bojes y avellanos, zarzamoras y arbustos.','No se conoce','Bibliografía: Príncipe de Viana nº 165. 1982',NULL,'Bloc 12. Atez Ulzama'),
(3,'ARMAIIA',1,'Dolmen','Usechi','En la ladera E. del monte Baratxueta (1141m)','Usechi Hoja cartográfica Nº 115-8','115-8',617870,4757340,1010,42.957719,-1.556204,'utm','1962-09-30','domingo, septiembre 30, 1962','Tomás López Sellés','Losas: 2 Características: Calizas. Túmulo: 27m Túmulo de 27m de diámetro y 2m de altura. Cámara con dos losas en el cráter central y otra desplazada de cráter. Calizas del terreno','No se conoce','Catálogo en Munibe con el nº 60-2. 1973',NULL,'Bloc 12. Atez Ulzama'),
(4,'BAIIARNEGI',1,'Dolmen','Iragi - Egozkue','En lo alto de la segunda cota después de Tamporrene','Iragi Hoja cartográfica Nº: 115-4','115-4',617280,4758800,980,42.970953,-1.563129,'utm','1959-11-29','domingo, noviembre 29, 1959','Florencio Sarasate','Túmulo de 14m de diámetro y 1,5m de altura de piedras. Cráter central sin losas de cámara.','No se conoce','Aunque lo localizó F. Sarasate, fue publicado por Tomás López Sellés Está catalogado en Munibe con el nº 60-1. 1973',NULL,'Bloc 12. Atez Ulzama'),
(5,'KARETE',2,'Túmulo (5)','Arizu','500m al NW. De la iglesia de Arizu','Arizu Hoja cartográfica Nº: 115-3','115-3',612580,4759380,674,42.976884,-1.620631,'utm','1975-08-11','lunes, agosto 11, 1975','Francisco Ondarra','Túmulo 1: Ovalado. Diámetro E-W: 8m. Diámetro N-S: 6m. Alltura: 0,3m Túmulo 2: Diámetro, 6m . Altura: 1m al E.; 0,2m al W. Túmulo 3: Diámetro, 4m. Altura: 0,6m por el E. y 0,2m por el W. Túmulo 4: Diámetro, 7m. Altura: 1m por el N. y 0,2m por el SW.','No se conoce','Francisco Ondarra no asegura, sino que los da como posibles túmulos. Bibliografía: Príncipe de Viana: 144/145, 1976,',NULL,'Bloc 12. Atez Ulzama'),
(6,'LANZ',2,'Túmulo','Lanz','Frente a la Venta de Arraiz, camino a Lanz','Arraiz Hoja cartográfica Nº: 90-15 Escala: 1:10.000','90-15',612225,4763000,780,43.009525,-1.624256,'utm',NULL,'martes, abril 18, 1905','Victoriano Larrainzar','Túmulo de 12m de diámetro y 1,1m de alto. Cráter central sin losas de cámara. Calizas del terreno.','No se conoce','El localizador se lo comunicó a J.M. Barandiaran, quien lo dio a conocer. Está catalogado en Munibe con el nº 59-5 Cercano a este túmulo existe otro de similares proporciones, de piedra. Bibliografía: Munibe, 1973.',NULL,'Bloc 12. Atez Ulzama'),
(7,'AGIÑETA',2,'Túmulo','Lanz','A 2,6 km al E.NE. De Lanz','Lanz',NULL,615265,4762090,905,43.000878,-1.587152,'utm','1975-08-11','lunes, agosto 11, 1975','Francisco Ondarra','Túmulo de 9m de diámetro y 1m de altura en el lado W.SW. Y 0,3m por el E.NE., de piedras. No se distingue cráter central. Está cubierto de musgo y hojarasca. Areniscas del terreno','No se conoce','Bibl.: Príncipe de Viana, 144/145. 1976',NULL,'Bloc 12. Atez Ulzama'),
(8,'AGIÑETA I',7,'Dolmen corto abierto','Lanz','A 50m del túmulo y 110?','Lanz Hoja cartográfica Nº: 90-16 E: 1/10.000','90-16',615315,4762090,905,43.000871,-1.586539,'utm','1975-08-16','sábado, agosto 16, 1975','Francisco Ondarra','Túmulo de 6m de diámetro y 0,8m de altura por el SW. y a ras del suelo al NE. Dos losas clavadas. El túmulo es e piedras recubierto de musgo y en él crecen seis hayas; abundan las raíces. Dimensiones de las losas: 1.- Losa N.: 0,35m alto, 1,85m largo y 0,05/0,10 m grosor. 2.- Losa S.: 0,70m alto, 1,75m largo y 0,07m grosor. La losa S. está partida en tres trozos. La losa N. está inclinada hacia el interior. Al pie del galgal, a 180? hay un trozo de losa de 1m de largo y 0,70m de ancho y 0,18m de grosor. La cámara mediría 0,80m de andho. Areniscas.','No se conoce','Bibl.: Príncipe de Viana nº 144/145. 1976.',NULL,'Bloc 12. Atez Ulzama'),
(9,'AGIÑETA II',7,'Dolmen corto abierto','Lanz','A 50m. y 90','Lanz Hoja cartográfica Nº: 90-16 E: 1/10.000','90-16',615365,4762091,910,43.000872,-1.585926,'utm','1975-08-16','sábado, agosto 16, 1975','Francisco Ondarra','Túmulo de 13m de diámetro y 1m de alto por el lado S. y a ras del suelo en el N.NE., de piedras cubiertas de musgo. En el túmulo crecen unas 13 hayas. Tres losas incadas: 1. Losa N.: 0,5m de alto; 0,95m de largo y 0,1m de grueso 2. Losa E.: 0,6m de alto; 2,1m de largo y 0,05/0,2m de grueso 3. Losa W.: 0,7m de alto; 1,75m de largo y 0,15/0,2m de grueso Las losas N. y E. están inclinadas hacia el interior. La losa W., hacia el exterior.','No se conoce','Bibl.: Príncipe de Viana 144/145, 1976',NULL,'Bloc 12. Atez Ulzama'),
(10,'ETENEKO GAÑA',1,'Dolmen?',NULL,NULL,'8-D Hoja cartográfica Nº: 90-11/C Nos situamos en el alto del Puerto de Velate, junto al edificio de Venta Quemada, a la derecha de este edificio parte una pista y traspasando una puerta de hierro continuamos por la pista que sube al repetidor de Velate, dejando un ramal a nuestra izda. Como a unos 100m dejamos la pista de decha, continuando por la izda que entre hayas asciende, pasando a la izda de una casa refugio. Descendiendo del repetidor al collado de Bentatxar donde veremosun arboleda enfrente al final de una loma alargada. Cruzaremos la alambrada del collado en la puerta que deja el barranco a la izda y la loma a la decha; la pista continúa hasta el final de la loma, continuando por otra loma a la izda; desde esta curva, continuamos el collado de ETENETAKO GAÑA donde veremos el túmulo de su nombre. 54-5. A nuestra izda, habrá quedado la cima de Putxetako Gaña y la del Txaruta.','90-11/C',609200,4768240,1030,43.057139,-1.660338,'utm',NULL,'jueves, mayo 04, 1905','J. Elosegui','¿Dolmen? Túmulo circular de 14m de diámetro y 1m de altura, de piedras. Cráter central sin losas de cámara. Calizas del terreno.','No se conoce excavación',NULL,NULL,'Bloc 12. Atez Ulzama'),
(11,'ARKATXU',NULL,NULL,'Suarbe','En una planicie al S. de Ilarregi y al O. del monte Zugasmendi',NULL,NULL,NULL,NULL,775,42.988730,-1.754274,'gpx',NULL,NULL,NULL,'6 losas. Piedras y tierra Túmulo desfigurado por el E. por algún haya y rebajado por el lado S. Es difícil precisar sus dimensiones, aunque en el eje N-S medimos un diámetro de 12m; en el eje E-O, diámetro 14m; de altura tiene unos 0,8m. Cámara alargada de unos 3,25m de largo por 0,9m de ancho. Formado por cuatro losas laterales y otras dos en al cabecera paralelas entre sí. Actualmente la forma original de la cámara está deformada, teniendo aspecto trapezoidal, orientado N-S. Hay pequeños trozos de losas esparcidas por el túmulo que podrían corresponder a la tapa rota.',NULL,NULL,NULL,'Bloc 12. Atez Ulzama'),
(12,'AUZALDIA GAÑE',2,'Túmulo',NULL,NULL,'Hoja cartográfica Nº: 115-2/D. Itinerario nº 4.','115-2/D',604710,4759030,732,42.974856,-1.717189,'utm',NULL,'domingo, mayo 07, 1905','J. Elosegui','Túmulo circular de 22m de diámetro y 1,3m de altura de piedras. Cráter central sin losas de cámara. Calizas margosas. Existe hoy un montón de piedras y tierra revueltos, sin aspecto de túmulo funerarios y de medidas indefinidas. Poco más adelante hay un túmulo natural, que coincide con las medidas de la descripción, actualmente no tiene ningún rasgo de dolmen, estando cubierto totalmente de maleza, parece que las piedras amontonadas pudieron pertenecer a este túmulo, ya que se encuentra en lado sur, con un corte plano. Más debajo de esta zona, en un campo trabajado, exiten varios montones de piedras recogidas y un túmulo de características parecidas a la descripción.','No se conoce excavación',NULL,NULL,'Bloc 12. Atez Ulzama'),
(13,'MAXKAR',NULL,NULL,NULL,NULL,'No incluye ningún itinerario , debido a que es imposible verlo en la actualidad, dado que la maleza que existe impide entrar en el pequeño bosque de robles.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'domingo, mayo 07, 1905','J. Elosegui','Túmulo circular de 60m? de diámetro y 2m de altura. Actualmente poblado de robles. Calizas del terreno.',NULL,NULL,NULL,'Bloc 12. Atez Ulzama'),
(14,'BEUNZA',1,'Dolmen',NULL,NULL,'Itinerario nº 4.',NULL,604000,4759100,755,42.975583,-1.725881,'utm',NULL,'domingo, mayo 07, 1905','J. Elosegui','Túmulo circular de 16m de diámetro y 1,5m de altura. Cámara de 5 losas. Orientación E-W según Tomás López Sellés. Margas sobre terrenos del flysch cretácico. En la actualidad en la zona donde está ubicado no se puede penetrar debido a la abundancia de maleza que existe en el bosque de pinos donde se encuentra, por lo que no pudo ser fotografiado.','No se conoce excavación',NULL,NULL,'Bloc 12. Atez Ulzama'),
(15,'AUZALDIA',1,'Dolmen',NULL,NULL,'Itinerario nº 4. Hoja cartográfica Nº: 115-2/D','115-2/D',604650,4759050,735,42.975044,-1.717921,'utm',NULL,'domingo, mayo 07, 1905','J. Elosegui','Dolmen poligonal. Túmulo circular de 15m de diámetro y 1,2m de altura, de piedras. Cámara de cinco losas con recinto poligonal abierto. Sin cubierta. Orientación a 90? según J. Elosegui. Flysch cretácico según Lamare. En la actualidad han desaparecido ltodas las losas, viendose solo el hueco rectangular rellenado de piedras pequeñas rotas. El túmulo ha perdido todo aspecto o vestigios de tal.',NULL,NULL,NULL,'Bloc 12. Atez Ulzama'),
(16,'ARAÑOTZ - SANTA LUCIA',1,'Dolmen','Iraizoz','Hoja cartográfica Nº: 115-3/A','Nº 2-A A unos setenta metros al N. de la ermita de Santa Lucía en Iraizoz, entre dicha ermita y la cumbre de Arañotz (838m)',NULL,609260,4760170,818,42.984479,-1.661182,'utm',NULL,NULL,NULL,'Se conserva un pronunciado galgal de 11/12m de diámetro y una altura de 1,5m al S. En cambio, por el N. destaca poco. Hoyo central bastante acusado, no apreciándose losas, aunque sí piedras sueltas. En la cota 791, gran bloque de piedra partido en dos, aunque bastante informe. Altitud: 800m Coordenadas en la hoja Gulina 115: 2º 01´ 33´´ de longitud y 12º 59´ 02´´ de latitud N.',NULL,'57-B/I',NULL,'Bloc 12. Atez Ulzama'),
(17,'BURDINDOGI S.',1,'Dolmen corto ?',NULL,NULL,'5-B Hoja cartográfica Nº: 115 A/B y 90-16D Volviendo a la pista desde el domen Agiñeta, tomamos la dirección E. La pista se divide en tres ramales. Seguir por la más ancha y mejor conservada que asciende suavemente por la ladera N. del contrafuerte. Nueva bifurcación a 1062m y seguidamente se alcanza la divisoria con la regata Igirena. Pequeño raso herboso con juncos y helechos. Cambio de vertiente. Ascenso por la ladera S. del monte Eride. Llegando al collado Iturriotz o Iturriko lepo a 1112m en la divisoria con la regata Zuriain. Bajo hayedo no se ve nada. Se separan tres pistas: por la que seue al NE llega el camino de Sallestur. La del frente termina pronto; girar al SE por el ancho camino que recorre la divisoria. Hayedo más retorcido; al O. claro en el bosque. Hacia los 1130m. Losas y charcos en el camino. Por la decha llega del SO. El camino del collado Gerendiain; a escasos metros del mismo queda la fuente. Empieza el camino más acusado. Camino definido y desdoblado. A la izda corro de brezo, despejado desde que se ve la cresta Eride-Zurriain. Suave ascenso bajo hayedo retorcido. A los 1235m aprox. En el bosque de hayas, tangente a la roca que aflora en lo más alto del monte Burdindogi, a 1241m. Implantado a 150m de la ermita, a 30? de ella. Hay un mojón a 100m a 150?.','115 A/B',618050,4762050,1235,43.000091,-1.553003,'utm',NULL,'martes, octubre 02, 2440','Francisco Ondarra','Túmulo circular de 13m de ? y 1m de altura; de piedra recubierta de musgo. 5 Losas desordenadas. No se aprecia cráter definido.','No se conoce excavación',NULL,NULL,'Bloc 12. Atez Ulzama'),
(18,'BURDINDOGI N.',NULL,NULL,NULL,NULL,'5-B Hoja cartográfica Nº: 115-4 B y 90-16 D Tras el itinerario del Burdindogi S.: por la izda reaparece el camino y pasa junto a un charco a los 1218m de altitud; vemos el mojon con iniciales A/Y en zona llana. Ermita de la Santa Cruz de Burdindogi. Pozo-fuente a unos 30m al W. Hayas. Prisma cuadrangular truncado metálico con un medallón con la efigie de Michel Buzunariz y la inscripción "A la memoria del amigo / el 30 de abril de 1972. En los Picos de Europa." El dolmen Burdindogi N. está situado a 40m y a 320? del anterior. Un sendero transcurre tangente al galgal por su costado.','115-4 B',618090,4762050,1235,43.000085,-1.552512,'utm',NULL,'lunes, julio 29, 2441','Francisco Ondarra','F. Ondarra no asegura que sea un dolmen. Túmulo de 10m ? y 0,8m de altura; de piedra u tierra cubiertas de musgo. Se aprecia una ligera concavidad o cráter central. No se ven losas ni fragmentos de las mismas. Areniscas del terreno.','No se conoce',NULL,NULL,'Bloc 12. Atez Ulzama'),
(19,'MUGASORO',1,'Dolmen corto ?','Elzaburu','Nº 26 Hoja cartográfica Nº: 90-10 D Longitud: 1º 58´ 32´´ Latitud: 43º 03´ 08´´','A hora y cuarto desde lel pueblo de Elzaburu, subiendo por el camino que lleva la collado de Mugasoro por Zapiturrieta; en la proximidad de la cota 843m A unos 10´ del mojón que da nombre al paraje. Divisoria atlántico-mediterránea, a 840m s.n.m.',NULL,605000,4767630,840,43.052240,-1.712016,'utm',NULL,'jueves, mayo 04, 1905','J. Elosegui','Túmulo circular de 12m de diámetrp y cámara reducida a dos losas que forman ángulo agudo, siendo la E. la cabecera y la N. una pared. Orientación a 80? según J. Elosegui Calizas del terreno','No se conoce','Munibe 54-6 E.270',NULL,'Bloc 12. Atez Ulzama'),
(20,'GANBELETA',1,'Dolmen. Es dudoso su carácter dolménico','Elzaburu','Long. 1º 59´ 27´´ Lat. 43º 02´ 42´´','En un amplio y llano collao situado a 400m al SE. De la cota 938m llamada Kulpittu, a 10´ de Arpegi en dirección NW. a 815m s.n.m.',NULL,606160,4766920,870,43.045686,-1.697911,'utm',NULL,'miércoles, mayo 10, 1905','J. Elosegui','Túmulo circular desfigurado por las hayas. Cámara reducida a una losa, orientada a 130º En 1934 fue revisado por vecinos de Elzaburu practicando una zanja en derrredor de la losa, sin hallar nada. Luego se colocó la losa en su posición original.','No se conoce','No se distingue túmulo',NULL,'Bloc 12. Atez Ulzama'),
(21,'ARPEGI ULZAMA',7,'Dolmen corto abierto','Elzaburu','Sobre un pequeño collado, entre dos cotas cercanas, próximo al dolmen de Ganbeleta. Long. 1º 59´ 45´´ Lat. 43º 02´ 30´´','A hora y media desde Alzoz siguiendo una pista forestal hacia Larremiar (camino de Larremiar) se llega al dolmen; 820m s.n.m.',NULL,606715,4766520,859,43.042008,-1.691175,'utm',NULL,'martes, mayo 16, 1905','T. López Sellés','Túmulo circular de 13m de ?, desfigurado y rebajado, acusándose más la prominencia hacia el S. Cámara de 3 losas con recinto rectangular, ligeramente desfigurado por la presión de la cubierta sobre una losa lateral desplazada. Orientación al E.',NULL,'En visita realizada el 1998/03/22 se constata que la losa O. , cabecera de la cámara, ha caído al suelo. En los alrededores se observanevidencias de haber sacado madera recientemente.',NULL,'Bloc 12. Atez Ulzama'),
(22,'AIZTALUZ',7,'Dolmen corto abierto','Elzaburu','En una cota al SE. del dolmen de Arpegui Ulzama. Long. 2º 00´00´´ Lat. 43º 02´ 25´´ Alt. 843m','Se advierte sobre el terreno indicios de sendas o caminos que descienden al camino más marcado que desde Maiterne se dirige a Arpegi y Ganbeleta. Este camino queda a la izquierda a 820m s.n.m.',NULL,607030,4766335,843,43.040298,-1.687344,'utm',NULL,'martes, mayo 16, 1905','T. López Sellés','Túmulo circular rebajado. Cámara de tres losas, una de las laterales inclinada hacia el exterior de recinto rectangular, sin cubierta. Orientación al E.','No se conoce',NULL,NULL,'Bloc 12. Atez Ulzama'),
(23,'LARREMIAR',2,'Túmulo','Urroz de Santesteban','Sobre un collado al E. de la cota 945m (Elkarrikoa) Long. 1º 59´ 35´´ Lat. 43º 03´ 25´´','Junto y a la derecha del camino que a Larremiar; 1 km antes de llegar a la fuente, al S. queda la loma sobre la que se hallan los dólmenes de Ganbaleta, Arpegi y Aiztaluz, a 920m s.n.m. Ruta 26-4 Mapa 90-10 B',NULL,606330,4768025,920,43.055611,-1.695613,'utm',NULL,'martes, mayo 16, 1905','T. López Sellés','Túmulo circular de 8m ? y de 0,70m de altura, de piedras. En el sector S., un cráter cuadrado sin rastro de losas de cámara.','No se conoce','Túmulo de anillo de unos 17m de diámetro y 0,5, de altura. Descripción que no coincide en absoluto con la realizada por López Sellés Munibe 54-52',NULL,'Bloc 12. Atez Ulzama'),
(24,'PITXORTAR',7,'Dolmen corto abierto','Urroz de Santesteban','A varios cientos de metros del dolmen de Mugasoro en dirección WNW., a 80m al N. de la cota 882m, en medio de un hayedo, a 878, s.n.m. Long. 1º 58´´ 05´´ Lat 43º 03´ 14´´',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'domingo, mayo 07, 1905','J. Elosegui','Túmulo circular de 12m de ? y 1,7m de altura. Cámara de 4 losas y cubierta al parecer in situ, con recinto rectangular. Orientación a 90º.','No se conoce',NULL,NULL,'Bloc 12. Atez Ulzama'),
(25,'KOPA GAIN',3,'Indefinido (derruido)','Arraiz - Ulzama','En el puerto de Velate, a unos 400m de la fuente Hoja cartográfica Nº: 90-15','Ulzama - Belate',NULL,611420,4765260,810,43.029989,-1.633679,'utm',NULL,'lunes, febrero 10, 2442','Francisco Ondarra','Conserva suficientes rasgos definidos, como el túmulo de tierra y piedras con una altura de 1m visto del W. Conserva también dos losas en línea, orientadas a 160º en un hoyo de unos 2m de ancho y 0,5m de profundidad al N. Las losas con un espacio entre sí miden: A.- Alto 0,9m; largo: 1,3m en la base y 0,6m en la parte superior; grosor 0,17, a 0,25m B.- Alto 0,32m; largo 0,2m; grosor 0,1m. El conjunto está en un bosque de hayas con mucha hoja desprendida.','No se conoce','Aunque no se conoce excavación, sí se observa que este monumento, al igual que otros muchos de Navarra, ha sido profanado por los buscadores de tesoros. Con fecha 1987/10/03, le fue colocado un hito señalizador por el grupo de socios Gorosti. El topónimo correspondiente, tiene otras formas; por ejemplo, el P. Fco. Ondarra lo dio a conocer como Koarain. Se ha marcado como Kopa Gain por ser la forma que más se conoce entre los lugareños.',NULL,'Bloc 12. Atez Ulzama'),
(26,'GILTZURRIN HARRIE',4,'Sin clasificar (derruido)','Arraiz Ulzama','En la cota 941m que se alza sobre el km 31 del Puerto de Belate','Ulzama Belate',NULL,611855,4766150,941,43.037937,-1.628163,'utm',NULL,'lunes, febrero 10, 2442','Francisco Ondarra','Conserva los suficientes rasgos definidos para considerarlo dolmen. Las dos losas forman ángulo recto. No se distingue cámara. Una losa orientada a 170º es la mayor, en posición N-S, que no es la cásica en estos monumentos (generalmente W-E). Medidas: alto 0,95m, ancho 0,30m en el centro, los extremos terminan en 0,03m de grosor. La otra losa, orientada al N., mide: alto 0,52m, largo 0,95m, grueso 0,30m en el centro. Dada la posición del conjunto en una loma que recibe constantemente fuerte viento, hace que el túmulo esté llano al W. Con fecha 3 de octubre de 1987, un grupo de Gorosti le colocó un hito señalizador.','No se conoce','Es anecdótico que el P. Ondarra cuando lo encontró vio entre la losas una botella de agua mineral de Belascoain, lo que no deja de ser curioso si lo recacionamos con el topónimo, que quiere decir "piedra del riñón". Cuando se consultado con las personas mayores sobre el mismo, éstas sonrien cuando se acuerdan del esfuerzo que tenían que soportar al ascender esta montaña transportando un paquete, donde hacía falta "riñones". Eran tiempos en los que la juventud se empleaba de "paqueteros", argot empleado en el ejercicio del contrabando. Este topónimo también tiene otras acepciones como por ejemplo: Giltzurrin arri o Giltzurrien arrie, que significan lo mismo. Se ha respetado el que figura dado que el P. Ondarra, el cual pertenece a la Real Academia de la Lengua Vasca, Euskaltzaindia.',NULL,'Bloc 12. Atez Ulzama'),
(27,'ARTXAR',2,'Túmulo','Arraiz','En medio de un bosque de hayas y quejigos Hoja cartográfica Nº: 90-15/C','Nº 8-E',NULL,609880,4764465,750,43.023056,-1.652734,'utm','1975-08-27','miércoles, agosto 27, 1975','Francisco Ondarra','Túmulo circular de 8m ? y 1m en el punto más elevado al NE., compuesto de piedra recubierta de musgo, abunda la hojarasca. En el galgal crece un quejigo y dos hayas casi tangentes al mismo. En el cuadrante SW muy cerca del centro del conjunto, hay una piedra que tiene la figura de una cubo muy tosco. Areniscas del terreno. No ser puede hallar el cráter cental.','No se conoce','En la revista Gure Mendiak del C.Deportivo Navarra Nº 75 de marzo de 1988, en la pag 48, Dólmenes Inéditos de la Ulzama y Basaburua, Patxi Ripa hace mención del mismo refiriéndose que desde que lo vio en compañía de Petete Sarobe el 5-2-84 y en otras ocasiones, examinando las piedras componen el conjunto les merece la calificación de Dolmen. 59-L1 Bibl. Revista Príncipe de Viana 144-145, año 1976. Nuevos monumentos megalíticos en Navarra.',NULL,'Bloc 12. Atez Ulzama'),
(28,'ZARDAI',1,'Dolmen',NULL,'Long. 1º 59´ 03´´ Lat. 43º 02´ 10´´ Alt. 882',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1986-05-29','jueves, mayo 29, 1986','Miguel Ezcurdia','El túmulo mide prox. 10m de ? al N-S, de unos 2m de alto y al S. 0,8m; de tierra y piedra. Alturas: de la cámara 0,8m.; del túmulo al S. 0,3m., de la losa de N-S 2m.; del túmulo 0,6m. Vimos que el dolmen tenía losa de cubierta sobre tres losas que forman la cámara sepulcral. Siete trozos de losas esparcidos por encima del túmulo. Se ve un pequeño cráter como de 3m de ? circundando la losa de cámara. Al parecer, la tierra y la tierra que le falta cubría la losa de la cámara. Orientación E. a 295º. La cámara bien formada queda abierta y como a 1m aprox. Hay un trozo cubierto que ha podido pertenecer a la cámara, en cuyo caso se trataría de un dolmen largo abierto.',NULL,'Patxi Ripa en la revista Gure Mendiak Nº 75 de marzo de 1988 del C.D. Navarra lo sitúa en la hoja castastral Nº 90 - Sumbilla Long. 1º 59´ 03´´ Lat. 43º 02´ 10´´ Alt. 882 y lo detalla como un dolmen integrado por las tres rocas que forman el nicho., sin piedra visible que pudiera corresponder a su cubierta, sito al pie de un espino albar, fecha 12-6-87. Si estamos hablando del mismo dolmen no cabe duda que del 25-5-86 al 12-6-87 este dolmen ha sufrido profanación, al faltarle la losa que cubría el recinto, la cubierta. En ambas reseñas, indican tres losas conformando el nicho o cámara sepulcral y en la primera había una losa de tapa. Día 8-6-88 miércoles. En compañía de Jesús Viana y de Josu fuimos por Santesteban a Mugako Soroa para ver los caminos. Llegamos a lo que nos pareció Mugako Soroa y Pixortar, viendo el dolmen de Patxi y otro más alto. Vimos después los embalses y volvimos a El Solano para visitar Zardai, comprobando en ¿dos pesade? que los dólmenes eran los mismos. Quedamos que Jesús Viana comprobaría si son o no los mismos. Y en vista de que llovía, volvimos, teniendo un accidente con el Suzuki al bajar la pista. Nos ayudaron de una casa de Elzaburu, a los que obsequiamos con dos botellas de champán (padre e hijo)',NULL,'Bloc 12. Atez Ulzama'),
(30,'ROIZU BERA',1,'Dolmen corto?','Isaba','Campas de Roizu en el barranco de Mintxate, a 6,3km de la foz.','Mintxate',NULL,670490,4756050,1060,42.936154,-0.911820,'utm',NULL,'lunes, mayo 08, 1905','R. Ripa Vega','Válida en 1985. Dolmen corto? Túmulo circular muy bajo y un posco desfigurado. Cámara reducida a 2 losas paralelas. La E. en pie y la W. inclinada. A unos 3m hacia el riachuelo hay otras dos losas. Orientación N.-S., según T. López Sellés, quien lo localizó en 1956. Catálogo MUNIBE 1973. Nº 64-4. Datos geográficos Miguel Escurdia. Datos dados por Tomás López Sellés: altitud 1090m snm; coordenadas: 46º56´12´´ de latitud y 2º46´21´´ de longitud; medidas de las losas: la del E., 2m x 0,78 x 49; la del W., 2,3m x 0,3 fuertemente inclinada y hundida en el suelo; la tapa?: 2,85m x 1,85 x 0,34. A unos 3m hacia el río, dos losas. La cámara tiene una anchura de 0,45m; la largura, irregular.','No se conoce','En julio y agosto de 1985 durante los campamentos organizados por el Servicio de Juventud del Dpto. de Educación y Cultura del Gobierno de Navarra. Campo de Trabajo Mintxate. Iniciación a la arqueología. Dirigido por los monitores: Miguel Bañales (Museo de Navarra), Fernando Gil (Guía de El Roncal) y Miguel Ezcurdia (Director Secc. Prehistoria de la SCN GOROSTI). Se limpió el monumento y se verificaron los datos de la descripción. La Secc. De Prehistoria de Gorosti tiene previsto efectuar una cata de reconocimiento, medición y croquis, con la autorización del Museo de Navarra e invitar a la Agrupación del Roncal Oratxe. Durante el campamento se colocó un hito señalizador con una placa bastante deficiente. En 1987 Isaac Santesteban comunica que el hito se encuentra partido. Denunciado el hecho en el Museo de Navarra, encarga éste que se averigüe lo sucedido. Se pasa al Museo un informe en el que se indica que la rotura la hizo un contratista de Guipúzcoa al ensanchar la carretera que asciende hacia Lapatia y que continúa hacia Roizu Goiti. BIBLIOGRAFÍA: F. Ripa, Cumbres de la región… (1985) 88-93. T. López Sellés, Nuevos hallazgos… (1957) 105-112. Juan María Apellaniz, Corpus de Materiales. Suplemento nº1 MUNIBE scn Aranzadi, San Sebastian 1973','Losas: 2 en cámara, 2 en túmulo Características: Calizas del terreno Túmulo: bajo y desfigurado','Bloc 18. Pirineo roncalés y Romanzado'),
(31,'ROIZU GOITI',1,'Dolmen corto?','Isaba (Propietario del terreno: Arcadio Anaut Anaut, restaurante Txamantxoia)','Al fondo del barranco Mintxate. Cercano a la borda de Garcés, 150m aprox.','Mintxate',NULL,670660,4756330,1080,42.938636,-0.909653,'utm',NULL,'miércoles, junio 07, 1905','José María Esparza Galé del Roncal','Dolmen corto? Túmulo desfigurado. Cámara reducida a dos losas semi-paralelas en inclinadas ligeramente hacia el N. Una losa posiblemente cubierta en el túmulo, algo cortado por el camino que se dirige a la borda Garcé y al barranco Lapatia Datos geográficos Miguel Ezcurdia. Nº Catálogo MUNIBE (no tiene)','No se conoce','En la preparación del Campamento Campo de Trabajo Mintxate, Inciciación a la Arqueología. Organizado por el Servicio de la Juventud (Dpto. Edu. y Cult. del Gobierno de Navarra) se lo comunicó a M. Ezcurdia, responsable de secc. De Preshistoria de Gorosti, quien lo incluyó dentro de las actividades del trabajo del Campamento, siendo limpiado, medido y señalizado con un hito del modelo aprobado. El croquis levantado no indica la posición de las losas, por lo que habrá que hacerlo como una actividad de Gorosti. Este dolmen no estaba catalogado, pasando inadvertido, incluso para los naturales y propietarios. Requiere una cata de reconocimiento dentro de un plan de trabajo igual que el previsto para el dolmen de Roizu Bera.','Losas: 2 de cámara 1 de cubierta Características: calizas del terreno Túmulo: bajo y desfigurado','Bloc 18. Pirineo roncalés y Romanzado'),
(32,'LUBRAKIETA',1,'Dolmen corto?','Isaba (Propietario del terreno: Emilio Anaut, casa Txibarro)','En el km 6 de la carretera a Zuriza por el valle de Belabarce','Belabarce',NULL,676100,4749170,1050,42.872967,-0.845271,'utm',NULL,'miércoles, abril 26, 1905','Jesús Elosegui de Tolosa','La cámara de dos losas alineadas y otra paralela, tal vez indiquen un dolmen largo. No tiene cubierta. Orientación a 113º. El monumento está bajo la sombra de un que crece en el túmulo. Datos de Miguel Ezcurdia. Nº Catálogo MUNIBE 64-1','No se conoce excavación','Durante el Campamento de Trabajo Mintxate-85, en los meses de Julio-Agosto, se le quitó mucha maleza y arbustos que crecían en el túmulo y se señalizó con un hito del modelo aprobado y subvencionado por la I.P.V. Gorosti tiene previsto hacer cata de reconocimiento y mediciones de la posición de las losas, dentro del mismo plan de la estación dolménica. Bibliografía: Elósegui, J. Nota previa (1953) pg 21 Materiales (1953) Barandiarán, J.M. Hombre prehistórico (1953)','Losas: 2 alineadas, 1 paralela Caracterísicas: Calizas del terreno Túmulo: 15m ?; 1,75m alto','Bloc 18. Pirineo roncalés y Romanzado'),
(33,'ASOLAZE',1,'Dolmen corto?','Isaba (Propietario del terreno: Ayuntamiento de Isaba)','En el camping de Asolaze, en el barranco de Maze','Barranco de Maze',NULL,672880,4752230,920,42.901239,-0.883726,'utm',NULL,'miércoles, junio 07, 1905','Jesús Elosegui Aldasoro','Una losa cameral hincada en el túmulo de 2,3m de larga en su mayor extensión, sobresaliendo del suelo 0,8m dos fragmentos alineados. Una losa desplazada, posiblemente la cubierta, de medidas exteriores 2,4m de larga, 1,82m de ancha y grueso max, 0,3m. Las losas muy erosionadas. Túmulo muy desfigurado de 10,5m. ?; al W. a ras del terreno; al E. 1,4m. De alto; al N. 1,2m y al S. 0,9m. de alto; grueso de las losas: máx de la cameral 0,3m y la posible cubierta , igual.','No se conoce','Sobre su localización, primeramente Jesús Elosegui Aldasoro, después Isaac Santesteban y últimamente José Mª Esparza Galé se lo comunicaron a Miguel Ezcurdia, quien lo reconoció como dolmen seguro, siendo incluido dentro de las actividades del Campamento de Trabajo Mintxate-85, al igual que los demás monumentos de la estación dolménica. Este dolmen se encontraba en pésimas condiciones de conservación, por lo que resultaba difícil su identificación. Tiempo atrás había sido aprovechado por un pastor para construir encima de él una txabola con las piedras del túnulo. La txabola fue derruida y tiempo después ha sido motivo de juego de los niños, quienes contruyeron cabañas, quedando el monumento totalmente desfigurado. Se empleó mucha mano de obra para limpiarlo, separando piedra a pidra y cortando mucha maleza y arbustos y bojes que tenía encima, logrando darle un aspecto de dolmen. Se colocó su correspondiente hito señalizador. Está previsto hacer una cata de reconocimiento.','Losas: 1 lateral, 1 cubierta?, 1 pequeña alineada Características: Calizas del terreno Túmulo: Desfigurado','Bloc 18. Pirineo roncalés y Romanzado'),
(34,'SAKULO',9,'Dolmen largo abierto? o poligonal','Isaba (Propietaria: Milagros Marco Lallana, Mendigatxa s/n)','Un poco más adelante del km 7, por la borda de Tapia a la izda 40m + alt.','Belagua',NULL,673230,4753380,925,42.911509,-0.879087,'utm',NULL,'viernes, mayo 05, 1905','B. Marco, quien lo comunicó a J. Elosegui','Cámara de recinto poligonal casi o rectangular con tendencia muy remarcada a la poligonalidad. Cubierta rota al parecer "in situ". Orientación a 140º. Datos de MUNIBE 64-3. Los datos geográficos están muy desplazados. Datos de la ficha: Miguel Ezcurdia','Servicio de Excavaciones de Navarra en 1961 y 1963 (Ajuar al dorso) * en anexo','Durante el Campamento de Trabajo-85 se limpió de arbustos y muchísima maleza, lo que permitió verlo a distancia. Se colocó un hito señalizador, al igual que a los demás monumentos de la estación dolménica. Estaba tan escondido que su localización resultaba dificilísima, incluso para los nativos, que lo desconocían. Es un monumento de gran tamaño. Gorosti tiene previsto su mantenimiento de limpieza y medición. Bibliografía: Elosegui, J. Nota previa (1953) Pg. 21. Materiales (1953). Barandiarán, JM. Hombre Prehistórico (1953). Maluquer de Motes, J. Notas (1963) Pag. 93.147.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(35,'ARRAKO',NULL,'Sepulcro de galería y crómlech','Isaba (Propietario del terreno: Cipriano Ezker Anaut)','Cercano a la Ermita de Andramari de Arrako, poco antes del km 10.','Belagua',NULL,674680,4755630,960,42.931426,-0.860634,'utm',NULL,'viernes, mayo 05, 1905','B. Estornés, quien lo comunicó a J. Elosegui','Recinto rectangular-trapezoidal. Losa de entrada con tendencia a cerrarse suavemente. Cubierta in situ. Orientación a 125º.','En 1961 por D.Fernando Medrano. No se conoce ajuar.','Hacia los años 1940 fue removido por los vecinos del contorno. En 1985 durante el campamento de Trabajo Mintxate-85 fue limpiado y se le colocó un hito señalizador, las placas de este monumental dolmen y las de la estación dolménica están grabadas deficientemente. Al N. del dolmen, como a unos 200m en el meandro del arroyo, se ven tres formaciones circulares de piedras, de forma continuada, distinta de los crómlech, similares a estas formaciones existen en Urdanarre, en la estación prehistórica de Urkulu, y que también tiene forma de corona. Bibliografía: Elosegui, J. Nota previa (1953) Pg. 21. Materiales (1953). Barandiarán, JM. Hombre Prehistórico (1953). Maluquer de Motes, J. Notas (1963) Pag. 93-147.','Losas: 7 en cámara, 1 cubierta Características: Calizas del terreno Túmulo: Ovalado 8-10 ?; crómlech 8m ? 15 testigos','Bloc 18. Pirineo roncalés y Romanzado'),
(36,'BELABARCE',2,'Túmulo ?','Isaba','En lo alto del Puerto de Belabarce, en la misma divisoria con Huesca','Belabarce',NULL,677495,4748520,1310,42.866795,-0.828409,'utm',NULL,'miércoles, mayo 17, 1905','Tomás López Sellés','Cráter sin losas. En la actualidad no ha podido ser localizado por los guías del Roncal (Grupo Oratxe). Tampoco fue localizado por Francisco Ondarra, quien lo intentó con los datos de López Sellés. La zona está cubierta de helechos y mucha vegetación, que impide su localización. De cualquier forma, pierde su interés como monumento prehistórico. Sería interesante hacer un intento más para localizarlo, y así poder cambiar de criterio','No se conoce','Losas: No tiene Características: Piedra menuda de calizas del terreno Túmulo: 11m de ?; arrasado y rebajado Bibliografía: López Sellés, T. Contribución (1965)',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(37,'LARRA',7,'Dolmen corto abierto','Burgui','En el valle de Larra, en la carretera de subida desde Burgui a la ermita.','Virgen de la Peña',NULL,664700,4729830,1125,42.701452,-0.990400,'utm',NULL,'lunes, mayo 08, 1905','Tomás López Sellés','Cámara con recinto rectangular, las tres losas inclinadas fuertemente orientación al S., según López Sellés. El 16-10-1957 es visitado por Tomás López Sellés, observando que las tres losas forman un hueco en forma de triángulo que al parecer se aprovecha para guardar herramientas, dado que el interior está arreglado. Las medidas de las tres losas son: Losa E.: 1,54m de altura; 0,85m de ancho; 0,30m de grueso Losa W.: 1,54m ; 1,43m ; 0,30m Losa N.: 1,15m ; 0,80m ; 0,25m La cámara sepulcral es irregular en la razón de que la losa W sobresale algo más, en anchura la altitud es de 1,50m. Todas las medidas son interiores. El monumento está cubierto de bojes al exterior.','No se conoce','Está previsto por Gorosti visitarklo y medirlo, colocandole un hito señalizador. Bibliografía: López Sellés, T.: Nuevos hallazgos (1957) pag. 105-112','Losas: 3 inclinadas Características: Calizas del terreno Túmulo: 11m ? y 0,70m de altura, de piedras.','Bloc 18. Pirineo roncalés y Romanzado'),
(38,'LARRAUN-SOGOITIA',7,'Dolmen corto abierto','Izal','A 400m. al E. de la divisoria de Aietxu','Izal',NULL,650410,4742550,1125,42.818871,-1.161398,'utm',NULL,'jueves, mayo 11, 1905','Patxi Ripa','Túmulo circular de 20. de ? y 1,70m de alto de piedra caliza. Cámara de tres losas con recinto rectangular. Orientación al W.','No se conoce','Catalogado en MUNIBE con el nº 65-2. Suplemento nº1 Año 1973',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(39,'AIKOA - I',1,'Dolmen (destruido)','Imirizaldu','A 30m de la orilla izquierda del río Areta y a unos 500m antes de la foz de Aikoa','Imirizaldu',NULL,643005,4732945,525,42.733833,-1.254370,'utm',NULL,'jueves, mayo 11, 1905','Tomás López Sellés','Túmulo desaparecido totalmente por labores de labranza. Cámara reducida a dos losas paralelas al N. y S., estando en la actualidad completamente arruinado',NULL,'Catálogado en MUNIBE con el nº 62-7. Suplemento nº1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(40,'AIKOA - II',NULL,'Dolmen corto','Imirizaldu','En la foz de Aikoa, a 100m del río Areta','Imirizaldu',NULL,642865,4732685,540,42.731519,-1.256145,'utm',NULL,'jueves, mayo 11, 1905','Tomás López Sellés','Túmulo circular de 16m ? y 2m de altura. Cámara de dos losas y otra de cubierta. Orientación E.','No se conoce','Registrado en Munibe con el nº 62-8. Suplemento nº 1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(41,'ANGERTA',NULL,'Dolmen corto','Napal','En un collado que desciende del monte Bluntza, divisoria de los valles Romanzado y Urraul Alto','Imirizaldu y Napal',NULL,643800,4731880,720,42.724099,-1.244934,'utm','1958-01-06','lunes, enero 06, 1958','Tomás López Sellés','Túmulo circular de 18m ? y 1m de altura. Cámara reducida de dos losas paralelas y otros dos formando cámara, inclinadas bajo el peso de la losa de cubierta. Orientación E.-W. Calizas del terreno','No se conoce','El habitáculo tiene una aportación de piedras pequeñas tapando huecos, aprovechado por cazadores. Catálogado en MUNIBE con el nº 62-6. Suplemento nº1, año 1973',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(42,'BOLUNTZA - SORTALDE',7,'Dolmen corto abierto','Napal','A 400m al W. de la cota, en un altozano','Napal',NULL,644735,4731775,822,42.722978,-1.233546,'utm','1958-01-06','lunes, enero 06, 1958','Tomás López Sellés','Túmulo de piedras calizas del terreno de 16m ? y 0,9m de altura. Cámara de tres losas formando un recinto rectangular, cubierta desplazada al N. Orientación E.','No se conoce','Catalogado en MUNIBE con el nº 62-4. Suplemento nº1. Año 1973 Sobre el túmulo se observa una pequeña cámara de piedras, a modo de una pequeña cista.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(43,'BOLUNTA - MENDEBAL',NULL,'Dolmen corto','Napal','A 300m al SW. Del domen Boluntza - Sortalde','Napal',NULL,644480,4731715,791,42.722486,-1.236674,'utm','1958-01-06','lunes, enero 06, 1958','Tomás López Sellés','Túmulo de piedras calizas del terreno de 16m ? y 1,2m de altura. Cámara de dos losas formando un recinto rectangular. Cubierta desplazada al N. y partida en tres trozos. Orientación E.-W.','No se conoce','Catalogado en Munibe con el nº 62-5. Suplemento nº1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(44,'UGARRA - I',7,'Dolmen corto cerrado','Napal','A 1km al NE de la ermita de San Esteban',NULL,NULL,645615,4731480,760,42.720156,-1.222878,'utm',NULL,'miércoles, mayo 10, 1905','Tomás López Sellés','Túmulo de 17m de ? y 1,7m de altura de piedras calizas del terreno. Cámara de cuatro losas con recinto rectangular. Cubierta desplazada y partida en dos trozos. Orientación E.-W.','No se conoce','Catalogado en MUNIBE con el nº 62-1. Suplemento nº 1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(45,'UGARRA - II',1,'Dolmen','Napal','Al W. de la ermita de San Esteban, a poco menos de 1km.','Napal',NULL,645500,4731430,742,42.719728,-1.224295,'utm',NULL,'jueves, mayo 11, 1905','Tomás López Sellés','Túmulo de 12m ? y 1,2m de altura, de piedras calizas del terreno. Cámara de una losa.','No se conoce','Catalogado en Munibe con el nº 62-2. Suplemento nº 1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(46,'UGARRA - III',1,'Dolmen','Napal','A unos 200m al E. de la ermita de San Esteban y del Ugarra-II a 300m al SW.','Napal',NULL,645600,4732135,745,42.726055,-1.222893,'utm',NULL,'jueves, mayo 11, 1905','Tomás López Sellés','Túmulo poco definido. Cámara de dos losas, una partida. Cubierta partida en dos trozos. Orientación a 90º. Calizas del terreno','No se conoce','Catalogado en MUNIBE con el nº 62-3. Suplemento nº1. Aó 1973. Túmulo desfigurado y piedras de cualquier forma amontonadas desfiguran el aspecto, debido a labores de labranza.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(47,'UGARRA - IV',1,'Dolmen','Urraul Ekialde (Romanzado)',NULL,'De Pamplona ir hacia Lunbier y seguir hacia Navascues, para coger un desvío hacia el pueblo de Napal, al pie del puesto de Iso. Desde el pueblo seguir una pista hacia el norte hasta llegar a la altura de la ermita de San Esteban. Justo al sur de la misma, en un amplio collado a 762m coger rumbo hacia el suroeste por un terreno un tanto sucio hasta llegar casi al borde del barranco de la foz de Domeño. El monumento se halla rodeado de árboles y boj, por lo que la visibilidad es bastante corta. El dolmen Ugarra-I se halla a unos 300m al SE. en la misma cresta.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1995-04-15','sábado, abril 15, 1995','Iñaki Gaztelu Iraundegi','Consta de un túmulo de piedras de 10m ? y 1m de altura máxima, estando todo él bastante rebajado y faltando bastante material por todo el túmulo, sobre todo en la parte central. En el lado E. del túmulo se halla un fragmenteo de losa que podría ser parte de la tapa del dolmen, que tiene las siguientes medidas: 0,9m de alto; 1,4m de largo; 0,4m de grosor. En la parte central del túmulo se observan los restos de dos losas pertenecientes a la cámara del dolmen. La losa S., que parece se halla in situ aunque ligeramente inclinada hacia el interior, tiene las siguientes medidas: 0,6m de alto; 1,5m de largo; 0,3m de grosor. Los restos de la losa O. miden: 0,2m de alto; 0,55m de largo; 0,15m de grosor, Calizas del terreno',NULL,NULL,NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(48,'UGARRON',7,'Dolmen corto abierto','Imirizaldu','En un collado al E. de la foz de Aikoa, al S. del rio Areta','Imirizaldu',NULL,642390,4731735,641,42.723056,-1.262184,'utm',NULL,'jueves, mayo 11, 1905','Tomás López Sellés','Túmulo de 18m de ? y de 1,6m de altura. Cámara de tres losas basculadas. Cubierta desplazada al S. del recinto rectangular. Orientación E. Calizas del terreno','No se conoce','Catalogado en MUNIBE con el nº 62-9. Suplemento nº 1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(49,'PUYOMEDIANO',1,'Dolmen','Domeño','Entre los km 90-91 de la carretera de Lumbier a Navascues, a la izquierda de un pequeño collado entre dos cotas.','Domeño',NULL,646250,4727515,630,42.684346,-1.216149,'utm',NULL,'jueves, mayo 18, 1905','Tomás López Sellés','Túmulo de 10m ? de piedras, que se encuentra arrasado. Cámara de dos losas tendidas en cráter y otra más pequeña sobre el túmulo. Calizas del terreno.','No se conoce','Catalogado en MUNIBE con el nº 62-10. Suplemento nº1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(50,'OSOSKI - PUENTE DE BIGUEZAL',8,'Dolmen corto cerrado','Biguezal','A unos 25m de carretera NA-178, entre ésta y el río Salazar, poco más alla del cruce de Biguezal','Biguezal',NULL,649895,4729140,537,42.698271,-1.171250,'utm',NULL,'lunes, mayo 08, 1905','J.M. Mikeleiz y V. Araguas','Túmulo desfigurado y ovalado de 12m ? y 7m entre los ejes mayor y menor. Cámara de 4 losas con recinto rectangular. Sin cubierta, dos losas terminan el cierre. Orientación a 320º-110º. Calizas del terreno.','J.M. Maluquer de Motes en 1955','Se conocen: 16 piezas dentarias y dos fragmentos de cerámica. Museo de Navarra Por motivos de labranza se desfiguró el túmulo. El dolmen es utilizado como basurero por quienes acuden al río los fines de semana. Al otro lado de la carretera se observa un monolito, al igual que se ha observado en otros monumentos de Urbasa y Aralar. Está catalogao en MUNIBE con en nº 63-2. Suplemento nºº. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(51,'PIEZA DE LUIS',1,'Dolmen','Biguezal','Al W. de Biguezal, hacia Periela.','Biguezal',NULL,650635,4728070,770,42.688495,-1.162504,'utm',NULL,'domingo, mayo 14, 1905','Fernando Medrano','Túmulo de 12m ? y 1,1m de altura, de piedras calizas del terreno. Cámara reducida a una losa en el centro con cráter revuelto. La losa mide 1,6m de altura; 1,58, de anchura y 0,26m de grosor.','Por Fernando Medrano en 1961','De la excavación se conocen: - 3 lascas, una con retoque en un margen - 1 hojita rota - 1 fragmento de núcleo - huesos humanos fragmentados Museo de Navarra Está catalogado en MUNIBE con el nº 63-11. Suplemento nº1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado');
INSERT INTO `megalitos` (`id`,`nombre`,`tipologia_id`,`tipologia_texto`,`municipio`,`ubicacion`,`itinerario_texto`,`hoja_cartografica`,`utm_x`,`utm_y`,`altitud`,`lat`,`lon`,`coord_fuente`,`localizado_fecha`,`localizado_fecha_texto`,`localizado_autor`,`descripcion`,`excavacion`,`observaciones`,`caracteristicas`,`otros_aspectos`) VALUES
(52,'FAULO',8,'Dolmen corto cerrado','Biguezal','En el camino que sube del pueblo a la ermita de San Quirico','Biguezal',NULL,651735,4728690,1010,42.693860,-1.148917,'utm',NULL,'viernes, mayo 05, 1905','Patxi Ripa','Túmulo de 12m de ? y 0,6m de altura, de piedras calizas del terreno. Cámara de 5 losas, una partida, con recinto rectangular, una de las losas más baja, como de ventana. Cubierta ladeada. Orientación a 140º.','Por Maluquer de Motes en 1955','De la excavación se conocen: - 1 punta de pedinculo central de aletas, de corte transverso, de pátina azulada. - 1 fragmento de cuenco campaniforme decorado en el interior y exterior con técnica y decoración de cienpozuelos. - 1 fragmento de panza con decoración incisa en zigzag - 1 fragmento de borde de vaso con cuello casi recto - 1 fragmento de fondo plano - 1 silbato? De heso, con orificio central - 1 hueso con marcas, tal vez de animales - 1 cuenta discoidea de esteatita - Restos humanos de 6 individuos. Museo de Navarra En 1961 el mismo excavador lo hizo en el túmulo sin encontrar ajuar. Catalogado en MUNIBE con el nº 63-1. Suplemento nº1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(53,'PUZALO (Corona de Hualde)',8,'Dolmen corto cerrado','Biguezal','A la derecha de la carretera de Biguezal a Salvatierra, casi en línea con el dolmen de Faulo','Biguezal',NULL,651785,4727130,897,42.679808,-1.148725,'utm','1952-05-17','sábado, mayo 17, 1952','Tomás López Sellés','Túmulo circular de 14m ? y de 1,9m de altura, circundado por una pared de piedras de mampostería de 1,1m de anchura y 0,8m de altura, formando un círculo de 23m de ?. Cámara formada por cuatro losas con recinto rectangular de 1,65m de largo; 1,25m de ancho; 1,32m de altura. Orientación a 130º. Calizas del terreno. La losa E. mide 2,4m de largo y la losa W. mide 2m. La losa de cabecera mide 0,75m de alto, a modo de ventana al SE. La losa de cubierta, destruida.','Fernandez Medrano en 1961','De la excavación se conoce: - 3 lascas amorfas de silex - 1 cuenta de esteatita? De tipo discoideo negro - Huesos humanos muy fragmentados de 1 individuo. - 2 hojas fragmentadas y una hoja con escotadura lelve abatida por retoque abrupto que parece fragmento, tal vez de un trapecio. Recogido en el túmulo hay: - 1 botón en hueso cónico en perforación en V media esfera de arenisca perfectamente pulimentada Museo de Navarra Respeto a la tapa de cubierta, hay constancia de que existió en el año 1900. En el pueblo nunca se ha dado importancia a estos monumentos que se llamaron "sepulcos de moros". Catalogado en MUNIBE con el nº 63-13. Suplemento nº1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(54,'PASO MUERTO',2,'Túmulo','Castillo Nuevo','Cercano a la mojonera, a unos 200m del Portillo','Navascués',NULL,655850,4728000,1210,42.686826,-1.098897,'utm','1959-03-25','miércoles, marzo 25, 1959','Tomás López Sellés','Túmulo de piedras desfigurado de 8m de ?, estando desparramado por el N. con cráter central sin losas de cámara. Calizas del terreno','No se conoce','Catalogado en MUNIBE con el nº 63-7. Suplemento nº1. 1973',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(55,'RECIMONTE',1,'Dolmen?','Biguezal','Al E. de Biguezal, en una loma de la Sierra de Illón','Biguezal',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'martes, mayo 09, 1905','Eduardo Mauleon','Túmulo pequeño. Cámara de una losa y otras dos sueltas, que parecen fragmentos de la primera.','Se desconoce','En el año 1956 E.Mauleon y T.López Sellés intentaron localizarlo sin encontrarlo. En 1988 miembros de la Sección de Prehistoria de Gorosti tampoco lo pudieron localizar. Solamente vieron unas enormes piedras que a lo lejos podrían confundir con un dolmen.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(56,'JORABILA',7,'Dolmen corto abierto','Biguezal','Al N. de la Sierra de Leyre','Biguezal',NULL,654975,4725710,1065,42.666391,-1.110198,'utm','1960-04-06','miércoles, abril 06, 1960','Tomás López Sellés','Túmulo de 14m ? y 2m de altura de piedras calizas del terreno. Cámara de tres losas con recinto rectangular. Orientación 110º. El recinto sepulcral mide: - Losa N.: 1,35m de largo; 1m de ancho; 0,20m de grosor - Losa S.: 1,75m de largo; 1,08, de ancho; 016m de grosor - Cabecera: 1,05m de altura; 0,72m de ancho; 0,23m de grosor A 500m al S. en un claro se distingue una formación tumular que ha sido cortada. Ubicación a 1070m snm.','No se conoce','Catalogado por MUNIBE con el nº 63-10. Suplemento nº1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(57,'LANDO (Fuente de la Pila)',1,'Dolmen?','Biguezal','A 500m al E., donde acaba la carretera forestal.','Biguezal',NULL,652360,4724940,1075,42.659983,-1.142298,'utm',NULL,'miércoles, mayo 24, 1905','J. Maluquer de Motes','Sin túmulo. Cámara de dos losas, una en pie y otra caída. Areniscas del terreno','No se conoce','Catalogado por MUNIBE con en nº 63-12. Suplemento nº1. Año 1973. Hay que señalar que Tomás López Sellés con fecha 6-4-1960 publicó en MUNIBE cuaderno nº3, 1957 con las mismas coordenadas el "Trilito de Lando" dando las siguientes medidas: - Losa inhiesta: 0,68m altura; 0,63m de ancho y 0,24m grueso - Losa tumbada: 2,2m largo; 0,7m de ancho al E. y 0.42 al W. El pastor que le indicó la existencia del dolmen decía haber conocido una tercera losa hoy desaparecida.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(58,'OLATE ATAKA',5,'Crómlech','Navascues','En le Portillo de Olate, al S. de una borda en ruinas.','Navascues',NULL,658800,4728630,1083,42.691893,-1.062731,'utm',NULL,NULL,NULL,'Los testigos de piedra semi enterrados forman un semi círculo, en el que más de un tercio no tiene testigos.',NULL,'Al para de ruinosa borda exiten dos formaciones tumulares, en las que se supone hay enterrados dos ejecutados en el año 1936.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(59,'ZUTIKAKO KAPESAK (Puntallo de las Capezas)',1,'Dolmen','Navascues','En el altozano, al W. del dolmen de Olate','Navascues',NULL,658450,4729075,1147,42.695970,-1.066877,'utm',NULL,'lunes, mayo 08, 1905','Maluquer de Motes','Túmulo circular de piedras. Cámara de 5 losas con recinto rectangular, probablemente faltan dos losas. Orientación SE. Calizas del terreno','En 1955 por Maluquer de Motes','Se conocen 3 fragmentos informes de cerámica y dos piezas dentarias. Museo de Navarra Catalogado en Munibe con el nº 63-5. Suplemento nº1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(60,'ILTZE TOKI (Claverito)',7,'Dolmen corto abierto','Navascues','En el camino antiguo que desciende al valle','Navascues',NULL,657780,4729100,1060,42.696333,-1.075045,'utm',NULL,NULL,NULL,'Túmulo de 12,5m ? de piedras calizas del terreno. Cámara de 4 losas con recinto triangular. Cubierta in situ. Orientación SE.','No se conoce','Catalogado en MUNIBE con el nº 63-6. Suplemento nº1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(61,'LEGAROZ',1,'Dolmen corto','Navascues','En el raso de su nombre, bajo el monte Borreguil','Navascues',NULL,659640,4729500,1115,42.699549,-1.052238,'utm',NULL,NULL,NULL,'Túmulo de 15m ?. Cámara de dos losas, una al parecer de cabecera y otra de la pared oriental y una tercera desaparecida. Calizas del terreno.','No se conoce','Catalogado en MUNIBE con el nº 63-3. Suplemento nº1. Año 1973. Visitado en el año 1987, se le distingue la cámara, las dos losas en pie forman un ángulo casi recto, siendo la losa mayor casi rectangular al N. apoyándose en la otra más pequeña.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(62,'TURENDO',8,'Dolmen corto cerrado','Navascues','A 360m al W. del dolmen de Lagaroz','Navascues',NULL,659380,4729320,1120,42.697983,-1.055461,'utm','1987-04-19','domingo, abril 19, 1987','Miguel Ezcurdia y Ángles Sáez','Túmulo de piedras de unos 8m de ? que por el lado S. alcanza una altura de 3,5m raseado y desaparramado por el N. Compuesto de piedras y tierra. Cámara de tres losas formando rel recinto sepulcral, tendiendo a cerrarse por el W., cubierta por una losa de tapa, que presenta un trozo roto al N. Orientación n.E.N','No se conoce','Monumento inédito, siendo esta ficha la primera comunicación.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(63,'OLATE (Portillo de Ollate)',7,'Dolmen corto abierto','Navascues','Cercano a la balsa','Navascues',NULL,658510,4728635,1091,42.691998,-1.066268,'utm',NULL,'lunes, mayo 08, 1905','J. Maluquer de Motes','Túmulo de 14m de ? y 0,5m de altura. Cámara de 3 losas de calizas del terreno, con recinto rectangular sin cubierta. Orientación al E.','Excavación por el mismo en 1955','El ajuar conocido es: - 1 punta foliácea (de sauce) de talla bifacial. - 1 fragmento de cerámica inidentificable. Dientes de dos individuos al menos. Museo de Navarra Catálogo en MUNIBE con el nº 63-4. Suplemento nº1. Año 1973.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(64,'FINESCASAS',6,'Cista','Rocaforte','Al S. de la Foz de Lumbier, en la cadena montañosa','Rocaforte',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1977-11-06','domingo, noviembre 06, 1977','P. Valentin Saez','Formado por tres losas clavadas en forma triangular, abierto por un lado tiene hoyo central en el que aparecen varios trozos de losas apoyándose en las losas clavadas. Las medidas del hoyo 1m de largo, 0,8m/0,4m de ancho. Losas: - Nº1: 0,21m alto; 1,54m de largo; 0,25m grosor medio - Nº2: 0,12m 0,62m 0,15m - Nº3: 0,2m 0,6m 0,02m - Nº4: - 0,28m - - Nº5: 0,04m 1,38m 0.24m - Nº6: 0,68m 0,9m 0,12m Hay varios trozos más sobre las losas clavadas, siendo todas de areniscas sobre el hoyo de arcilla.','No se conoce','El conjunto ha sido observado por Francico Ondarra, quien da la descipción, y por la arqueóloga MªAmor Beriguistain sin que llegasen a la conclusión de si efectivamente se trata de algo prehistórico. Bibliografía: Revista Príncipe de Viana nº 165. Año 1982.',NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(65,'PIEDRA BLANCA',1,'Dolmen','Navascues','A 1km al N. del dolmen de Legaroz','Navascues',NULL,659600,4730400,1000,42.707658,-1.052472,'utm','1987-04-19','domingo, abril 19, 1987','Miguel Ezcurdia y Ángeles Sáez','Túmulo de tierra y piedra. Cráter central en el que se conserva un losa y varios trozos de otras, dispersas por el enorme túmulo. El dolmen está arruinado.','No se conoce',NULL,NULL,'Bloc 18. Pirineo roncalés y Romanzado'),
(66,'LAPASTEGI',1,'Dolmen corto','Baraibar','Al W. del pueblo, a 1km aprox.','Baraibar - A',NULL,586840,4760370,730,42.989168,-1.936091,'utm',NULL,'jueves, mayo 18, 1905','J. Elosegui','Cráter sobre túmulo. Cámara excéntrica de dos losas. Orientación probable al E. Está señalizado con un hito de identificación por Gorosti.','No se ha practicado','Prevista su medición',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(67,'POSTAN',1,'Dolmen','Baraibar','A 1,5km de Baraibar',NULL,NULL,586230,4760070,810,42.986536,-1.943618,'utm','1967-08-15','martes, agosto 15, 1967','Tomás López Sellés','Túmulo de tierra y alguna piedra con cámara sepulcral deformada. Un espino y avellanos fueron eliminados por Tomás López Sellés. Losas: 3; calizas del terreno; túmulo: 10m ? y 1,5m de altura. - Losa N.: largo 2,5m ;alto 0,6m ; grueso 0,15/0,25m - Losa S.: 0,6m 0,3m 0,1m - Losa S.: 0,8m 0,2m 0,2m','Se desconoce','Tiene hito colocado por Gorosti y patrocinado por el Gobierno de Navarra. Cuando se efectuó esta operación se encontró el túmulo lleno de piedras que cubrían la cámara, piedras que se habían quitado al túmulo y otras repartidas por la campa; por lo que el túmulo quedó como un amontonamiento forrado de hierba. El 12 de nayo de 1958. Los datos dados por T. López Sellés en la hoja 114, escala 1:50.000 son incorrectos. Bibliografía: Tomás López Sellés. Contribución al catálogo dolménico. MUNIBE 1973.',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(68,'TXURITXOBERRI',7,'Dolmen corto abierto?','Iribas','A la derecha de la pista que desde Iribas asciende a Burnigurutz.','Iribas-Baraibar-A por Burnigurutz al Santuario de San Miguel y valle de Ata.',NULL,587570,4758110,800,42.968736,-1.927492,'utm',NULL,'sábado, marzo 25, 1905','J.Aranzai y F.Ansoleaga','La descripción dada en 1911 fue de: 2 losas formando escuadra y cubierta desplazada, con una losa tendida. Orientación s/ J.Elosegui a 104º. Debido a la imprecisión de datos de localización de entonces, fue dedoblado en dos, apareciendo como dolmen de Iribas disntinto al reseñado. Actualmente se removieron las losas tendidas y desplazadas, formando una cámara que por el tamaño y posición de las losas volvieron a tomar la posción lógica y posiblemente original.','Cata de reconocimiento que dio varios huesos humanos. En 1951 se efectuó una excavación por J.Elosegui, quien encontró una punta trapezoidal y varios fragmentos de cerámica. Paradero desconocido.','En el verano de 1981 estuvo a punto de desaparecer, al ampliar la pista de Iribas. Una excavadora o pala mecánica seccionó el túmulo por la mitad, dejando a la vista restos de enterramientos y también se encontraron varios huesos esparcidos por la pista donde vertieron el material quitado el túmulo. Hasta noviembre de 1985 cuando se reparó, el dolmen ha estado a punto de destrucción total; por un lado, debido a que dos hayas que crecieron junto a la cámara quedaron con la mitad de las raíces al aire al desaparecer parte del túmulo, estando a punto de derrumbarse con el peligro de arratrar las losas de la cámara, una de ellas ya había caído; y por otro lado, las gentes al excarvar en busca de restos de enterramientos. Cabe destacar que el pastor de Iribas, con treinta años de oficio en la zona, desconocía la existencia del dolmen. Una vez conocida esta existencia y su carácter, supo paralizar al poco tiempo el atropello que se estaba comentiendo y comunicarlo al autor de esta obra, quien a su vez salió al paso ante las Instituciones Públicas y denuciór el hecho en la prensa. El pastor citado se llama Andrés Iribarren. En noviembre de 1985, patrocinado por el Dpto. de Cultura del Gobierno de Navarra, a través de la secc. De Museos y Patrimonio Arqueológico de Navarra, se reparó el dólmen, aportando tierra y piedras del lugar, rellenando el túmulo, trabajo efectuado con la ayuda de un camión volquete y una pala excavadora. Como retoque final, se colocaron piedras de la misma forma que la parte original, y aprovechando los medios, se movieron las losas esparcidas y las desprendidas, colocándolas de forma que ocuparan de forma lógica el lugar que posiblemente tuvieran originalmente. No se puede garantizar, al no encontrar información escrita ni fotográfica, que esta posición actual sea la originaria. El monumento tiene colocado un hito señalizador colocado por Gorosti y patrocinado por el Gobierno de Navarra. Bibliografía: Iturralde y Suit: La Prehistoria en Navarra. 1911 Elósegui, J.: Cuatro nuevos volúmenes. 1915 Barandiarán, JM.: El hombre prehistórico. 1953.',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(69,'ARRANAZPIETA',1,'Dolmen corto?','Baraibar','A la izquierda de la pista que se dirige Burnigurutze desde el 6km.','(Burnigurutze) Baraibar - B',NULL,587130,4758000,780,42.967796,-1.932903,'utm',NULL,'sábado, mayo 06, 1905','J.Elosegui','Túmulo originariamente circular. Hoy recortado en el sector WNW por obras de pista. 11m ? y 1m altura. Calizas del terreno. Cámara de dos losas paralelas con recinto rectangular, cubiertas por el túmulo. Losa S. muy inclinada Orientación al E.','No se conoce','Señalizado con un hito de identificación por la Sociedad Gorosti.',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(70,'ARMENDIAGA',7,'Dolmen corto abierto?','Huarte Araquil','A 2,5km al W. de Madoz','Madoz-Agiri. Huarte Araqui-Agiri',NULL,588700,4755030,803,42.940875,-1.914126,'utm',NULL,'miércoles, junio 07, 1905','J.Iturralde y Suit','Túmulo desfigurado y rebajado. Calizas del terreno. 22m ?. 4 losas en cámara, una en cabecera. Una de las losas está apareada con una losa lateral. Tal vez fuera originariamente la cabecera. En este caso las paredes tenderían a cerrarse a la entrada. Orientación a 90º. Ajuar encontrado en la excavación: - 1 anillo de bronce de cinta, analizado fig. 228B - 1 punta de flecha de metal, no anillada. Perdida. - Huesos humanos de al menos 8 inhumanos. - Huesos de animales. Museo de Navarra-Pamplona.','En 1915 por T.Aranzadi y F.Ansoleaga','Los avellanos y matorrales que crecen en el mismo impiden a veces verlo. Se ha limpiado de matorrales, quedando visible desde el camino de Armendiaga. Durante la campaña de señalización le fue colocado un hito. A unos 60m en dirección N. existe una enorme piedra montada sobre tres apoyos de piedra, que descansan en una hilera de roca. Tiene forma de caparazón de tortuga gigante y según consultas a la dirección del Museo de Navarra, apuntan a la posibilidad de que se trate de una ara. Bibliografía: - Iturralde, J.: La Prehistoria en Navarra. 1911 - Aranzadi, T.: Exploración de Aralar. 1918 - Aranzadi, T.: Exploración de Aralar. 1924 - Pericot, L.:Los sepúlcros megalíticos. 1950 - Barandiaran, JM..: El hombre prehistórico. 1953',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(71,'PIKABOTZ',1,'Dolmen corto?','Oderiz','A 1km de Oderiz en dirección a Astiz','Oderiz-Astiz',NULL,591730,4756880,725,42.957173,-1.876691,'utm',NULL,NULL,'J.Goldarazena','Túmulo recortado difícil de precisar. Cámara de 2 losas paralelas. Calizas del terreno. Orientación 101º.','Se desconoce','El señor Goldarazena le comunicó el hallazgo a J.Elosegui en 1953. El antiguo camino de Oderiz a Astiz, en donde se ubica el dolmen, al no ser utilizado, junto a la falta de paso de ganado y a la aspereza del terreno, se ha llenado de vegetación y lo oculta. En la campaña de colocación de hitos en la Sierra de Aralar patrocinada por el Gobierno de Navarra, se limpió el emplazamiento y se colocó el hito.',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(72,'AZOLAPE',1,'Dolmen','Oderiz','En zona de Bordongo','Oderiz',NULL,591500,4756630,753,42.954949,-1.879551,'utm',NULL,'miércoles, mayo 03, 1905','J.Elosegui','Túmulo circular de 12m ? de piedras y muy rebajado, por lo que es difícil precisar la altura del mismo. Cráter central. 1 losa tendida y dos trozos. Calizas del terreno.','Cata de reconocimiento en 1951 por J.Elosegui. (Algunos huesos humanos)','El lugar donde se ubica es conocido como Bordongo. El nombre se debe a que cerca hay ruinas de una borda conocida también como Errandeko Borda. El nombre ha tomado el nombre del topónimo de la zona. En la campaña de colocación de hitos en la Sierra de Aralar patrocinada por el Gobierno de Navarra le fue colado un hito. Bibliografía: - Elosegui, J.: Cuatro nuevos dólmenes. 1951 - Barandiran, JM.: Hombre prehitórico. 1953',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(73,'PAGAMENDI-I',7,'Dolmen corto abierto','Oderiz','En las cercanías del pueblo de Oderiz','Oderiz',NULL,591850,4756325,758,42.952161,-1.875311,'utm',NULL,'sábado, mayo 06, 1905','J.Goldarazena','Túmulo circular de 12m ?. Calizas del terreno. Cámara con recinto trapezoidal con tendencia de las paredes a cerrarse. Cámara con 3 losas y 1 losa de cubierta rota. Orientación a 130º.','No se conoce','El localizador comunicó este hallazgo a J.Elosegui en 1953. El dolmen es fácilmente visible desde la carretera de Oderiz a Astiz. En la campaña de señalización con hitos de los dólmenes de la Sierra de Aralar patrocinada por el Gobierno de Navarra le fue colocado un hito. Existe otro dolmen con este mismo topónimo el el municipio de Etxarri-Aranaz denominado Pagamendi-II.',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(74,'LARRAZPIL',9,'Dolmen largo abierto','Madoz','En un collado en la divisoria de Madoz y goldaraz','Madoz-Oderiz',NULL,593570,4755820,1050,42.947405,-1.854314,'utm',NULL,'miércoles, mayo 03, 1905','J.Elosegui','Túmulo irregular en las direcciones E-W y N-S. Calizas del terreno. Recinto sepulcral formado por 6 losas y la cubierta. Una de las losas desplazada. La cámara vaciada para construir una choza pastoril. Las losas tienden a cerrarse. Orientación 120º.','En la cata de reconocimiento aparecieron huesos humanos y un fragmento de cerámica.','El dolmen transformado en choza pastoril y aprovechada para cazadores, quitándole las piedras al túmulo se formó un recinto. De no haber sufrido esta transformación habría sido uno de los dólmenes digno de ofrecese para la contemplación por su tamaño y esbelta construcción, situado en un lugar vistoso y accesible. Con esta idea merecería considerar la conveniencia de reconstruirlo. Durante la campaña de señalización patrocinada por el Gobierno de Navarra le fue colocado un hito. Parece ser que el dato de altitud señalados en el hito no son correctos. Bibliografía: - Elosegui, J.: Cuatro nuevos dólmenes.1951. - Barandiaran, JM.: Hombre prehistórico. 1953.',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(75,'MILALDAPA',11,'Dolmen poligonal','Oderiz','A 1km de Oderiz, en el antiguo camino a Astiz','Larraun-Oderiz',NULL,592500,4757220,735,42.960141,-1.867196,'utm',NULL,'jueves, mayo 04, 1905','J.Elosegui','Cubierta desplazada. Recinto de la cámara ligeramente poligonal. Difícil de precisar si la planta responde a su diseño original, ya que la presión del túmulo muy alto y que cubre casi completamente el monumento, ha debido hacer variar la posición original de las losas. Cabecera ligeramente apuntada. Cámara vacía. Orientación 120º.','Cata de reconocimiento que arrojó varios huesos humanos.','En la campaña de colocación de hitos en la Sierra de Aralar le fue colocado uno, siendo uno de los primeros colocados por el grupo Gorosti. Bibliografía: - Elosegui, J.: Cuatro nuevos dólmenes.1951. - Barandiaran, JM.: Hombre prehistórico. 1953.',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(76,'LAMEAR',1,'Dolmen','Madoz','Al E. de Madoz, subiendo en dirección a Larrazpil desde el final del puerto','Madoz',NULL,592980,4754900,960,42.939194,-1.861698,'utm','1984-11-01','jueves, noviembre 01, 1984','Luis Millan y Arantza Lizarralde','Túmulo irregular, con 4 losas formando cámara en el centro. 15-16m ?; 0,5m al N. y 2m al S. Túmulo de tierra y piedras de regular tamaño. Calizas del terreno La losa N. Mide: 1,9m largo; 0,7m alto; 0,35m grueso W. 1m 0,7m 0,28m S. 0,5m 0,3m 0,1m E. 0,65m 0,3m 0,05m','No se conoce','Durante la campaña de señalización de hitos, patrocinada por el Gobierno de Navarra, le fue colocado un hito. La altitud marcada en el hito está equivocada: dice 917m cuando son 960m. El motivo fue la precipitación al confeccionar la placa y los datos recibidos. La orientación desde la borda de Mintxerizarreta es de 240º. Bibliografía: - Millan San Emeterio, Luis: Nuevos monumento megalíticos de Navarra y Vizcaya. KOBIE Bilbao Nº XV-1985/86.',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(77,'PIAN',1,'Dolmen','Madoz','Al E. de Madoz, en la subida a Larrazpil desde el alto del puerto','Madoz-B',NULL,592940,4754500,908,42.935598,-1.862254,'utm','1986-03-19','miércoles, marzo 19, 1986','Txomin Goñi','Túmulo compuesto de piedra menuda y tierra. Una losa y resto de otras. La losa mide 0,7m de alto, 1,8m de largo y 0,2m de grueso medio. La losa se ve algo descompuesta.','No se conoce','Fue visto por casualidad al ir a localizar el dolmen de Lamear y comunicado su hallazgo a Luis Millan. La ubicación del dolmen y la altitud dadas en la reseña son incorrectas. En posterior comprobación se midió los datos de la ficha. Bibliografía: - Millan San Emeterio, Luis: Nuevos monumento megalíticos de Navarra y Vizcaya. KOBIE Bilbao Nº XV-1985/86.',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(78,'AKELAR',1,'Dolmen','Alli','En un raso al SSE. De Alli, junto al mojón nº13 de la carretera','Larraun-Alli',NULL,590300,4760290,620,42.988045,-1.893669,'utm',NULL,'lunes, mayo 08, 1905','J.Elosegui','Las 2 losas en escuadra se encuentran enterradas y el material de las mismas está disperso, posiblemente al construirse la pista que discurre tangente al mismo. Túmulo rebajado. El aspecto actual define poco a un dolmen.','No se conoce','En la campaña de colocación de hitos en Aralar le fue colocado uno. Entre la carretera que une a Madoz con la de Aralar y entre la misma y el dolmen se encuentra la cueva del mismo nombre, a unos 80m. La cueva es alargada, teniendo salida o comunicación al aotro lado de la carretera.',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(79,'LARDAMINGO',1,'Dolmen','Astiz','A 15m al NE. De Goldarazko langa, en el camino Astiz Goldaraz','Astiz',NULL,592960,4757615,920,42.963641,-1.861492,'utm',NULL,'lunes, mayo 08, 1905','J.Elosegui','Túmulo en el que han crecido mucha vegetación, avellanos en su mayoría, que oculta el carácter de dolmen, que de por sí tiene poco, encontrándose como la mayoría de los dólmenes en estado ruinoso por no haber sido respetados.','No se conoce','En la campaña de colocación de hitos en Aralar se limpió el túmulo cortando los avellanos que lo tapaban, mejorando notablemente su aspecto. Tiene un hito. Bibliografía: Elosegui, J.: Prospecciones…. 1956',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(80,'IZEINITURRI',7,'Dolmen corto abierto?','Huarte Araquil','A 250m del dolmen Ziñeko Gurutze, al W. cercano a la pista','Larraun, Santuario San Miguel, Ata, Baraibar',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(81,'ZIÑEKO GURUTZ',7,'Dolmen corto abierto','Huarte Araquil','En el camino de Iribas y Baraibar al Santuario San Miguel','Larraun, Santuario San Miguel, Ata, Baraibar',NULL,NULL,NULL,975,NULL,NULL,NULL,NULL,'jueves, marzo 30, 1905','T.Aranzadi y F.Ansoleaga','Túmulo circular y cámara de 3 losas y 1 losa de cubierta. 15m ? y 2,7m de altura. Calizas del terreno. La cámara está cubierta por el túmulo, excepto la entrada en la que crecen unos cuantos avellanos que dificultan su localización. Es uno de los pocos monumentos que conservan su estado original, posiblemente por las dificultades que ha tenido su localización. Ajuar encontrado en la excavación: - Guijas brillantes - Restos humanos de al menos 5 inhumados que pertenecen a los tipos medios de la raza pirenaica occidental. Dos frag. De bóveda craneana parecen, sin embargo, no corresponder a dicho tipo. En el Museo de Navarra, Pamplona, se conserva como perteneciente a este dolmen: - 1 lasca apuntada de silex con parte de un margen retocado con retoque menudo - 1 frag. De fondo plano de gran vao y frag. De tres vasos inidentificables.','Por los localizadores en el mismo año.','El topónimo, que indica "santiguarse en la cruz", es más moderno que el que lógicamente le correspondería, de Burnigurutze que es el mombre del collado cercano en que se encuentra, al ser relativamente de la misma época. No obstante, lo más lógico sería, por la zona en que está ubicado entre fuentes y humedad, tomar el nombre de Izeiniturri (a 250m está el denominado así). Pero siguiendo la pauta recomendada por Euskaltzaindia de respetar los topónimos que han sonado en 100 años, se ha marcado en la placa el nombre respetado durante la campaña de colocación de hitos en la Sierra de Aralar, patrocinada por el Gobierno de Navarra. No cabe duda que ha habido una transformación fonética de Izei… Izai, que indica sanguijuela, al de izeñi? A la composición ziñeko, y la colocación de una cruz de hierro en el collado Burnigurutz, cruz de hierro. El dolmen es de los mejor conservados y, no cabe duda de que la excavación a que fue sometido, habría sido con nuevas técnicas y sin desmontar. Bibliografía: Aranzadi, T.: Los gentiles de Aralar. 1919 Aranzadi, T.: Exploración de… Aralar. 1918 Pericot, L.: Los sepulcros megalíticos. 1950 Barandiaran, JM.: Hombre prehistórico. 1953 Barandiaran, JM.: El mundo… 1961 Riquet, R.: Les cranes d''Urtiaga. 1962',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(82,'ARRATE BERRI',9,'Dolmen largo abierto','Huarte Araquil','En el camino que desde la fuente de Zubigoien va a Burnigurutze','Larraun, Santuario San Miguel, Ata, Baraibar',NULL,NULL,NULL,1006,42.956368,-1.934156,'gpx',NULL,'sábado, mayo 06, 1905','S.Peña y S.Zubeldia','Túmulo circular y cámara con recinto circlar (con 5 losas, 3 tendidas) y una de las losas en 3 fragamentos. Parte de las losas están incliadas y basculadas. Calizas del terreno. 25m ? y 1,4m de altura. Cámara vaciada. Orientación a 130º. Los localizadores anunciaron el hallazgo a J.Elosegui antes de la fecha citada. El dolmen se encuentra con el aspecto de estar muy removido, posiblemente debido a una excavación inadecuada o por la búsqueda de "tesoros".','No se conoce','Este dolmen fue catalogado por Elosegui con el nº 308 y por MUNIBE en el suplemento nº1 Corpus de Materiales con el nº 47-11 con nombre de Izeñiturri-II, posiblemente por estar ubicado cercano al límite de la zona. La subsección que estudia los topónimos, a la que pertenece Jose Mª Ustarroz de Huarte Araquil, encontró que el dolmen se ubica en la paso de Ata a Burnigurutz, más conocido por los nativos con el topónimo de Arrate Berri, que fue aceptado por Euskaltzaindia. Gorosti colocó la placa en la campaña de señalización de Aralr, patrocinda por el Gobierno de Navarra. Bibliografía: Barandiaran, JM.: Hombre prehistórico… 1953.',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(83,'ILLUNBETAKO ARRATE',7,'Dolmen corto abierto','Huarte Araquil','A la derecha del camino de Ata a Burnigurutz','Larraun, Santuario San Miguel, Ata, Baraibar',NULL,587640,4756800,990,42.956934,-1.926839,'utm',NULL,'viernes, mayo 05, 1905','J.Elosegui','Túmulo circular de piedras de 14m ? y 1,4m de altura. Calizas del terreno. Cámara con recinto triangular con tres losas y una de cubierta. Difícil de precisar si las losas guardan la posición originaria. Cubierta desplazada hacia el E. Orientación a 90º.','No se conoce','Bastante bien conservado a pesar de tener la cubierta desplazada, posiblemente como otros muchos por el afán de buscar "tesoros". No es fácil dar con él siguiendo las sendas y caminos que normalmente se pisan. El lugar, como su topónimo indica, es muy cerrado y oscuro. Este dolmen fue catalogado por J.Elosegui con en nº E-294 y por MUNIBE Suplemento nº1 Corpus de Materiales… 1973 con el nombre topónimo Arrate Illuneta. Con el estudio por parte de la Subsección de Gorosti de toponimia y con la aprobación de Euskaltzaindia se le colocó la placa correspondiente con el topónimo Ilunbetako Arrate (pronúnciese illunbetako) durante la campaña de señalización patrocinada por el Gobierno de Navarra. Bibliografía: Elosegui, J.: Nota previa… 1953 Elosegui, J.: Materiales… nº6 Barandiaran, JM.: Hombre prehistórico… 1953',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(84,'SEAKOAIN-I',1,'Dolmen','Huarte Araquil','Aproximadamente en el centro del valle de Ata','Larraun, Santuario San Miguel, Ata, Baraibar',NULL,587230,4756440,958,42.953739,-1.931921,'utm',NULL,'miércoles, marzo 08, 1905','J.Iturralde y Suit','Túmulo circular. 14m de ? y 1,5m de altura. Calizas del terreno. Cámara con 2 losas y 1 de cubierta, que se abren en dirección ENE., tendiendo a juntarse en dirección WSW. Cubierta desplazada. Este dolmen poseyó al menos una losa más. Ajuar encontrado durante la excavación: - huesos, dientes y muelas de 1 individuo - huesos de animales Museo de Navarra. Pamplona.','En 1915 por T.Aranzadi y F.Ansoleaga','Cercana a este dolmen, como a unos 90m al E., se encuentra la cueva Etxezar. En la campaña de señalización patrocinada por el Gobierno de Navarra le fue colocado un hito por los miembros de la Sección de Prehistoria de Gorosti. Bibliografía: Iturralde y Suit, J.: La prehistoria en Navarra. 1911. Aranzadi, T.: Exploración de…. Aralar. 1918. Barandiaran, JM.: Hombre prehistórico… 1953',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(85,'SEAKOAIN-II',11,'Poligonal, tal vez abierto largo','Huarte Araquil','A unos 140m del Seakoain-I, dirección NNE','Larraun, Santuario San Miguel, Ata, Baraibar',NULL,587250,4756580,966,42.954998,-1.931654,'utm',NULL,'viernes, mayo 05, 1905','J.Elosegui','Túmulo de piedras. 14m de ? y 1m de altura. Calizas del terreno. Cámara formada por las cinco losas y cubierta partida. Dos losas se cierran al E., por lo que parece un recinto poligonal; cierre provocado al parecer por el túmulo, en cuyo caso sería un dolmen abierto largo. Hoy se ve como un dolment poligonal.','No se conoce','En la campaña de señalización de Aralar se le colocó un hito. Bibliografía: Elosegui, J.: Nota previa… 1953 Elosegui, J.: Materiales… 1953 Barandiaran, JM.: Hombre prehitórico… 1953',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(86,'LIZARRANDIGAÑE',1,'Dolmen dudoso','Huarte Araquil','En lacumbre de su nombre, a 3,3km de Irañeta','Camino de Huarte Araquil al valle de Ata',NULL,587180,4756190,1009,42.951494,-1.932572,'utm',NULL,'jueves, marzo 09, 1905','J. Iturralde y Suit','Según Barandiaran, el dolmen se halla cubierto por una gran losa arqueada. Según Elosegui, sería necesario poenr muy seriamente en duda su caráter prehistórico. Su situación en una hilada de estratos que buzan al S.75º y la maleza impiden un examen atento, lo que dificulta una demostración definitiva. A 15m al W aparece una formación natural que ha dado origen que ha dado origen a consideraciones prehistóricas. Su existencia la delató J.Iturralde y Suit en el mismo año. Siendo reconocido por J. Elosegui en 1952, se inclinó por negar su carácter prehistórico. Estos dos supuestos dólmes fueron catalogados por Elosegui como E-22 y 23 y por MUNIBE en el Suplemento nº1 Corpus de Materiales… 1973 como Lizarrandigañe I y II. Fueron visitados varias veces para determinar se se les colocarían o no la placa e hito correspondiente. Observados detenidamente se consideró que, sin hacer un reconocimiento mediante catas que demostraran guardar enterramientos, no se podían considerar como dólmenes.','Se desconoce','Bibliografía: Iturralde y Suit, J.: La prehistoria en Navarra. 1911. Barandiaran, JM.: Hombre prehistórico… 1953',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(87,'PANPLONAGAIN',7,'Dolmen corto abierto','Huarte Araquil','Cercano a la nueva carretera de Huarte Araquil al Santuario','Larraun, Santuario San Miguel, Ata, Baraibar',NULL,587245,4755720,855,42.947255,-1.931849,'utm',NULL,'miércoles, marzo 08, 1905','J. Iturralde u Suit','Túmulo circular. 13m ? y 1,5m de altura. Calizas del terreno. Cámara de 3 losas (una rota) y cubierta desplazada al E. Las paredes tienden a cerrarse. Orientación 100º. Ajuar encostrado en la excavación 3 cuentas de-ciervo, cuerno 1 cuenta en polipero fósil 1 tubo como alfiletero varios objetos no identificados de madera, tal vez azabache, como mangos 1 punta de flecha 1 lámina. Piedrecillas brillantes __restos humanos de al menos 7 inhumados El Museo de Navarra guarda como perteneciente a este dolmen, los siguientes objetos: Varias piedras calizas de las que algunas asemejan hojas nº 1 y 2 1 hojita con doble escotadura retocada y margen opuesto también retocado. Nº 3 1 lasca con un margen retocado con retoque marginal menudo. Nº. 4 1 cuenta sobre un polípero fósil nº 11( su forma es globular, pero ha conservado la forma original del fósil) 1 frag. de azabache de una cuenta de tipo cilíndrico 2 frag. muy grandes de sendas cuentas de tipo cilíndrico de azabache. Probablemente los Excavadores se refirieron a esto cuando hablaban de piezas de madera como mangos nº 6 y 7 E1 azabache está muy alterado y de ahí que se la pueda confundir o asemejar a la madera 2 fragmentos de azabache de tipo tonelete nº 8 y 1 cuenta de polipero fósil al que se han abatido solamente las superficies superior e inferior pero no el resto nº 13 1 fragmento y borde.de panza de vaso troncocónico.inverso.? con pitón.ovalado, casi redondo sobre el borde. fig. A 1 frg. de borde y panza y cuello de pequeño vaso carenado; de carena casi alta fig; B 1 frg. de panza de vaso ovoideo de cuello vuelto? decorado con impresiones de uñas. Fig. C Fragmentos informes de cerámica 1 cuenta segmentada con elementos cilíndricos. Probablemente se trata de lo que excavadores llamaron tubo o alfiletero. La pieza esté perdida, pero por su interés se representa en la fig. 12','En 1913 por T. Aranzadi y F. Ansoleaga',NULL,NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(88,'ANSARETAKO ZAPARRA',1,'Dolmen largo?','Etxarri Aranaz','En la ladera NW que forman las cotas de Etaio y Puterri','Pto. Lizarrusti - Alleko - Ireio (Iraio) y Pto Lizarrusti por Kifosa',NULL,576250,4758320,1115,42.971844,-2.066254,'utm','1983-04-17','domingo, abril 17, 1983','Txomin Goñi y Ángel Barcenilla','Medidas del túmulo: 15m ? de E-W y 17m ? de N-S. Calizas del terreno. Cámara sepulcral con 4 losas camerales, dos sueltas y una en el túmulo, tapa?. Medidas de las losas: - Losa W de cierre: anchura parte inferior 0,8m y superior 0,3m; altura 1,4m; grueso 0,2m; hincada - Losa S: largo 2,2m; alto 1,2m; grueso 0,3m; hincada - Losa de: largo 1,1m; alto 0,6m; grueso 0,2m; en pie, suelta - Losa N: largo 1,1m; alto 1,4m; grueso 0,3m; hincada - Losa de: largo 1m; alto 1m; grueso 0,25m; hincada Existe otra losa pegando al W que apenas se aprecia. Existe otra losa al S, ¿la cubierta?, en el túmulo. La cámara presenta el aspecto de haber sido removida, violada. Su conservación es regular.','No se conoce','Los datos son aportados por Luis Millan del Grupo de Prehistoria de Gorosti, que localizó y fotografió el dolmen con fecha 22 de junio de 1983. El dolmen está ubicado en la zona navarra occidental de la Sierra de Aralar. Como quiera que en la zona navarra occidental no aparece ningún otro monumento, se incluye en la zona central. Lo que podría ser continuación de la sierra por el término de Echarri Aranaz, se considera cortada la sierra por el Pto. de Lizarrusti y distinta la estación dolménica.',NULL,'Bloc 2. Sierra de Aralar oriental (Larraun-S)'),
(89,'ARTESIAGA',2,'Túmulo','Eugui - Irurita','En el alto del collado entre Eutegi y Larrakarte Hoja cart.: 90-12','Artesiaga',NULL,619140,4767650,986,43.050333,-1.538438,'utm','1963-11-17','domingo, noviembre 17, 1963','Tomás López Sellés','Túmulo de piedra menuda, convertido prácticamente en un cráter.','Desconocida','Catalogado por MUNIBE con el nº 59-6, Suplemento nº1 año 1973.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(90,'GURUTZE MEAKA - SORTALDEA',5,'Crómlech','Baztan','Entre las cumbres de Astabizker y Araun Hoja cartográfica Nº: 91-9','Artesiaga - Nagusaroi',NULL,NULL,NULL,1027,NULL,NULL,NULL,'1975-05-19','lunes, mayo 19, 1975','Francisco Ondarra','13 Testigos asoman entre la hierba (segúramente que habrá más ocultos) formando una circunferencia de 6,5m. Las piedras son de arenisca.','No se conoce.','F. Ondarra lo publicó primeranente en Príncipe de Viana nº165, año 1982 con topónimo de GURUTXE MEEKA, corrigiéndolo posteriormente.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(91,'GURUTZE - MEAKA MENDEBAL',5,'Crómlech','Baztan','A 20m del crómlech Sortalde. Hoja cartográfica Nº: 91-9','Artesiaga - Nagusaroi.',NULL,621285,4768985,1027,43.062011,-1.511818,'utm','1978-03-11','sábado, marzo 11, 1978','Francisco Ondarra','Túmulo de tierra y piedras de 3,5m ? y de 0,25m de altura. Se ven más piedras calizas del terreno en la periferia, salvo dos de ellas que son areniscas; una de las mayores mide 0,3m x 0,45m x 0,06m.','No se conoce.','Príncipe de Viana Arqueología nº7 año 1988.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(92,'GURUTZE - MEAKA IPAR',2,'Túmulo','Baztan','Al N. del collado cercano a los crómlech, situados algo más altos. Hoja cartográfica Nº: 91-9','Artesiaga - Nagusaroi.',NULL,621245,4769000,1000,43.062153,-1.512306,'utm','1983-07-10','domingo, julio 10, 1983','Francisco Ondarra','Túmulo de forma elíptica, eje N-S: 4,5m (350º - 170º) y el eje E-W: 3m (80º - 260º). Unas 20 piedras calizas del terreno alineadas por la periferia y otras esparcidas en el interior hacen de testigos del monumento. Las mayores son: - nº1: 0,68m de largo y 0,1m de grueso - nº2: 0,5m " 0,1m " - nº3: 0,6m " 0,1m " Las nº 2 y 3, tumbadas.','No se conoce.','F. Ondarra lo da a conocer de forma dudosa como crómlech, sin embargo lo cataloga como túmulo, por parecer más definido. En otros lugares se conocen estas formaciones tumulares de forma elíptica y que todavía no hay una definición aclaratoria de los mismos. Bibliografía: Revista de Arqueología nº7 del año 1988 editada por el Gobierno de Navarra.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(93,'OIALEGI LEPOA',2,'Túmulo','Baztan','Collado situado al SE de Astabizker Hoja cartográfica Nº: 91-9','Nagusaroi',NULL,622102,4768850,1053,43.060665,-1.501818,'utm',NULL,'viernes, mayo 26, 1905','Patxi Ripa','Túmulo de 11 m de ? y 0,3 m de altura por el WSW, de varias piedras sin orden apraente sobre el túmulol - nº1: 0,85 m de alto; 0,6 m de largo; 0,3 m / 0,35 m de grueso - nº2: 0,56 m " 1,1 m " 0,2 m / 0,3 m " - nº3: 0,8 m " 0,65 m " 0,25 m " - nº4: 0,57 m " 0,25 m de ancho; 0,2 m " - nº5: 0,85 m " 0,2 / 0,25 0,23 m " La 1 y la 3 están clavadas casi verticalmente. La 2 está clavada sumamente inclinada La 4 y la 5, tumbads, parecen estar trabajadas para ser utilizadas como mojones.','No se conoce','En la publicación "Rutas ORY - VELATE" se menciona como dolmen. En la pubicación Príncipe de Viana nº 165 del año 1982, Francisco Ondarra lo menciona como monumento y posteriormente en la Revista Arqueología nº7, lo define como túmulo. Cercanos existen dos o tres crómlech no clasificados todavía.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(94,'OTARRA BIZKARRA',5,'Crómlech','Quinto Real','En lo más alto de la cota 1170 al S de Urrizburuko Munoa Hoja cartográfica Nº: 91-9','Urkiaga',NULL,622770,4767980,1198,43.052726,-1.493809,'utm','1974-08-12','lunes, agosto 12, 1974','Francisco Ondarra','Son 3 crómlech alineados de N-S. Nº 1: El más septentrional. Es de 4,5 m de ? y de 22 testigos de piedras de roca cuarzosa, muy pequeños, no pasando de 0,25 m la de mayor altura. Nº 2: Al sur del anterior, a 0,8 m del mismo. Es de 4 m de ? con hoyo de 0,5 m de profundidad en el centro. Varias piedras pequeñas trazan el círculo, siendo la mayor nº1 de 0,2 m de alto y 0,63 m de largo. Tendida entre las demás piedras, hay una que sería un mojón, que tiene marcado el nº 86, divisoria de Quinto Real y Erregerrena; mide 1,47 m de largo; 0,25/0,32 m de ancho y 0,14 m de grueso. Nº 3: A 0,8 m del Nº 2. Formado por 13 testigos que marcan una circunferencia de 4,5 m ? de piedras muy pequeñas. A unos 150 m al S y a la misma distancia de la alambrada hay un túmulo circular con una prolongación, que posiblemente sea un fondo de cabaña.','No se conoce.','Bibliografía: Revista Príncipe de Viana nº 142/143 año 1976.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(95,'LURGORRIKO LEPOA',2,'Túmulo','Quinto Real','En el collado entre Arsal y Otarra Bizkarra Hoja cartográfica Nº: 91-9','Urkiaga',NULL,622735,4767225,1180,43.045935,-1.494405,'utm',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(96,'BEOTRIN',1,'Dolmen','Quinto Real','Al SE de Luurzu y al S de Argintzu Hoja cartográfica Nº: 91-9','Urkiaga',NULL,624215,4768170,1015,43.054201,-1.476029,'utm','1972-06-17','sábado, junio 17, 1972','Francisco Ondarra','Túmulo de 12 m de ? y 1,5 m de altura, de tierra y abundantes piedras. Dos losas in situ y una tercera tendida sobre el túmulo, probablemente la cubierta. Losa nº 1: de 1,25 m de alto; 2 m de largo; 0,35 m de grueso " 2: 0,75 0,2 " 3: de 1 m de ancho; 2,5 m de largo y 0,2 m de grueso Las dos primeras inclinadas al interior de la cámara, que mide 2 m de largo y 0,9 m de ancho. Orientación 105º. Las losas son de areniscas y las piedras del túmulo de pizarra.','No se conoce.','Se está utilizando como palomera, teniendo construido un parapeto de piedras que impide medir la largura de la losa nº 2. Bibliografía: Revista Príncipe de Viana nº 142/143 año 1976.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(97,'UZTANBORRO',1,'Dolmen','Quinto Real','En el collado entre Okoro u Luurzu, en la línea divisoria. Hoja cartográfica Nº: 91-9','Urkiaga',NULL,622690,4768040,1173,43.053279,-1.494778,'utm','1958-10-26','domingo, octubre 26, 1958','Tomás López Sellés','Túmulo de 16,5 m de ? y de 1 m de altura, algo mayor por el lado E, con 3 losas clavadas. Nº 1: de 0,85 m de alto; 1,6 m de largo; 0,05/ 0,25/ 0,1 m de grueso Nº 2: 0,3 m " 1 m " 0,1 m " Nº 3: 1 m de ancho; 1,7 m " 0,2/ 0,1 m " La nº 1, firmemente clavada en posción vertical. La nº 2 " " inclinada al centro La nº 3, posiblemente parte de la cubierta. El túmulo ha sido variado totalmente por el ldo W. Parece haber sifo utilizado en la construcción de obras militares.','No se conoce.','T. López Sellés lo publicó en MUNIBE nº 2 y 3 en el año 1960. Francisco Ondarra corrigió datos en la Revista Arqueología nº 7 de 1988, de donde se extraen estos datos.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(98,'UZTANBORRO I',5,'Crómlech','Quinto Real','A 14 m del túmulo de Uztamborro. Hoja cartográfica Nº: 91-9','Urkiaga',NULL,622680,4767970,1168,43.052650,-1.494916,'utm','1982-08-13','viernes, agosto 13, 1982','Luis Millan, Francico Ondarra y vidal Pérez','Nº I: de 4,5 m de ? y de 0,3 m de alto al S-SE, vaciado a ras del suelo, areniscas del terreno. Nº II: a 4 m al S del túmulo, que lo cruzan varios senderos; de 2,6 m de ?; unos 15 testigos de piedra forman la periferia del círculo. Las piedras de arenisca miden La nº 1, casi al N: 0,2 m de alto; 0,38 m de largo; 0,1 m de grueso 2, al SE: 0,15 m " 0,5 m " 0,18 m " 3, al W: 0,08 m " 0,35 m " 0,08/ 0,17 m ".','No se conoce.','El Nº I tal vez sea un crómlech tumular. Seguir tomando piedras para las palomeras existentes hace que se vayan desfigurando poco a poco. Bibliografía: Revista Arqueología nº 7 año 1988, editada por el Gobierno de Navarra.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(99,'UZTANBORRO II - III - IV',2,'Túmulos','Quinto Real','A 33 m y a 45º de un obra militar. Hoja cartográfica Nº: 91-9','Urkiaga',NULL,622730,4768090,1175,43.053722,-1.494276,'utm',NULL,'jueves, mayo 25, 1905','Tomás López Sellés','Los 3 son de areniscas y de forma elíptica y tangentes. II.: de 4,5 m / 3,5 m ? y de 0,4 m de alto, con ligero hoyo central o depresión, formado por piedras pequeñas. III.: de 4 m / 3 m de ? y de 0.3 m de alto, de piedras pequeñas que pueden tener la más larga 0,35 m y las más anchas 0,2 m y las más gruesas unos 0,1 m. IV.: de 4 m de ? , al que al parecer se le han extraído piedras.','No se conoce.','Bibliografía: Revista Arqueología nº 7, editada por el Gobierno de Navarra.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(100,'ERNAZABALGO SOROA',5,'Crómlech','Quinto Real','A 500 m al S. de los crómlech Otarra Bizkarra y a 250 m al N., la cota 1188. Ernalegi Hoja cartográfica Nº: 91-13','Urkiaga',NULL,622940,4766425,1160,43.038700,-1.492065,'utm','1974-08-31','sábado, agosto 31, 1974','Francisco Ondarra','crómlech de 21 testigos de piedras areniscas, pizarras y otra clase. Forma un círculo de 6,4 m de ?, ligeramente tumular. Las piedras son de pequeño tamaño: nº 1, de 0,45 m de largo; nº2, de 0,55 m; nº3, de 0,2m de alto.','No se conoce.','Bibliografía: Revista Píncipe de Viana nº 142 / 143, año 1976. Al parecer en total hay 6 crómlech marcados en la hoja también por L.M. como Ernezalaieta. 4 de T.L.S. - 21.6. 1975 - I.: F.O. en P.V 1976. 144-145 Pág.: 349 - II.: F. O. en P.V. 1976- 142-143 Pág.: 36-38 - III.: F.O. en Arqueología 17 Pág.: 128 - IV.: L.M.S.: lo da a conocer así F.O. como destruído.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(101,'ERNAZABALGO SOROA IPAR-I',5,'Crómlech','Quinto Real','Aunos 40 m al N de Enazabalgo Soroa Hoja cartográfica Nº: 91-13','Quinto Real',NULL,622940,4766560,1160,43.039915,-1.492035,'utm','1975-06-21','sábado, junio 21, 1975','Tomás López Sellés','De 5 m de ?, con 10 testigos de piedra que miden: 1.- (S-SW) 0,5 m largo tumbada en el suelo 2.- (W-NW) 0,26 m largo; 0,16 m de alto y 0,2 m de grueso 3.- (SE) 0,2 m largo; 0,18 , de alto y 0,13 m de grueso',NULL,NULL,NULL,'Bloc 16: Artesiaga - Quinto Real.');
INSERT INTO `megalitos` (`id`,`nombre`,`tipologia_id`,`tipologia_texto`,`municipio`,`ubicacion`,`itinerario_texto`,`hoja_cartografica`,`utm_x`,`utm_y`,`altitud`,`lat`,`lon`,`coord_fuente`,`localizado_fecha`,`localizado_fecha_texto`,`localizado_autor`,`descripcion`,`excavacion`,`observaciones`,`caracteristicas`,`otros_aspectos`) VALUES
(102,'ERNEZABALGO SOROA IPAR-II',5,'Crómlech','Quinto Real','A 1/2 m de Ipar-I Hoja cartográfica Nº: 91-13','Urkiaga',NULL,622940,4766510,1160,43.039465,-1.492047,'utm','1983-11-12','sábado, noviembre 12, 1983','Francico Ondarra','crómlech de 5,6 m de ?, con 7 testigos de piedra (areniscas y pizarras) colocados de forma radial y marcadas en el croquis con los nº 1, 3, 4 y 5; la nº 2 mide 0,18 m de alto, 0,25 m de largo y 0,2 m de grueso.','No se conoce','Bibliografía: Príncipe de Viana. Arqueología nº 7, año 1988.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(103,'LUURZU - HEGO',2,'Túmulo','Quinto Real','A 300 m al W del dolmen Luurzu - hego Hoja cartográfica Nº: 91-9','Urkiaga',NULL,623080,4768280,1120,43.055376,-1.489937,'utm','1975-06-21','sábado, junio 21, 1975','Tomás López Sellés y Francisco Ondarra','Túmulo de 9,5 m de ?, 1,5 m de alto al SE y 0,5 m al W, de tierra; no se distinguen cráter ni losas.','No se conoce.','A 320 m en dirección E desde el dolmen hay unas formaciones tumulares a 1025 msnm. En la misma línea , a 1 km se encuetra el túmulo de Luurzu - SE y el dolmen de Beotrin. Bibliografía: Revista Príncipe de Viana nº 144/145, año 1976.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(104,'LUURZU - HEGO-I',5,'Crómlech','Quinto Real','A unos 450 m y a 340º se levanta Luurzu Gaina Hoja cartográfica Nº: 91-9','Urkiaga',NULL,622134,4768175,1060,43.054584,-1.501573,'utm','1983-06-29','miércoles, junio 29, 1983','Francico Ondarra','crómlech de 20 testigos de piedras areniscas, formando un círculo de 5,5 m de ?. Medidas de las mayores: 1.: (N) 0,25 m de alto; 0,9 m de largo; 0,1/0,23 m de grueso 2.: (S-SE) 0,9 m " 3.: (S-SE) 0,25 m " 0,7 m " 0,25 m " 4.: (S) 0,26 m " 0,55 m " 0,23 m " En el exterior de la circunferencia hay más piedras que pudieron ser restos de alguna construcción ya destruída.','No se conoce.','Bibliografía: Educación y Cultura del Gobierno de Navarra. Arqueología nº 7 año 1988.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(105,'LUURZU HEGO-II',5,'Crómlech','Quinto Real','A 250 m por el N del dolmen. Hoja cartográfica Nº: 91-9','Urkiaga',NULL,622136,4768016,1060,43.053152,-1.501583,'utm','1983-06-29','miércoles, junio 29, 1983','Francisco Ondarra','Unos 20 testigos de piedra arenisca, formando un círculo de 4 m de ?. Los mayores son: - 1.: (N-NE) de 1 m de largo - 2.: (SE) 0,7 m " - 3.: (S) 1,15 m " - 4.: (W) 1,4 m de alto y de 1,15 m de perímetro a 1 m de altura. Las 1, 2 y 3 son gruesas y parecen estar tumbadas; la nº 4 está muy inclinada hacia el interior y es un monolito.','No se conoce.','Bibliografía: Revista Arqueología nº 7, editada por el Gobierno de Navarra en el año 1988.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(106,'LUURZU - IPAR',1,'Dolmen','Baztan','A unos 250 m al W del crómlech de Argintzu-III Hoja cartográfica Nº: 91-9','Urkiaga',NULL,623310,4768880,1175,43.060740,-1.486981,'utm','1972-04-02','domingo, abril 02, 1972','Francisco Ondarra','Túmulo de 6 m de ? y 0,7 m de altura con cámara sepulcral de 1,4 m de larga y 1 m de ancha. Orientación 120º. Hay 3 losas de arenisca "in situ", más una cuarta, encima, la de cubierta. La losas N, S y la de cabecera están muy inclinadas, dando la impresión de que el conjunto se ha desplomado hacia el SW. La losa 1 (S) mide 0,7 m de alto; 1,6 m de largo y 0,15 m de grueso 2 (N) 0,9 1,6 0,15 3 0,5 1 0,05 3 partida verticalmente en dos trozos de cubierta de 1,7 m de largo 1 m de ancho 0,28','No se conoce.','Bibliografía: Revista Príncipe de Viana nº 142/143, año 1976.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(107,'LUURZU LEPOA-I',1,'Dolmen','Quinto Real - Irurita','Al W de la peña de su nombre, en el collado. Hoja cartográfica Nº: 91-9','Urkiaga',NULL,623140,4768580,1175,43.058067,-1.489134,'utm','1957-05-22','miércoles, mayo 22, 1957','Tomás López Sellés','Túmulo de piedras de 11/12 m de ? y de 0,8 m de altura, con cráter cenrtral y cuatro losas sueltas de calizas del terreno: Losa nº 1 (N) de 0,5 m de alto; 1,7 m de largo; 0,15 m de grueso " 2 (S) 1,3 m 1,7 m 0,28 ambas hincadas en tierra muy inclinadas hacia afuera Hay otros dos fragmentos: - nº 3: de 1,2 m de largo; 0,5 m de ancho y 0,25/0,3 m de grueso - nº 4: 1 1/0,8 0,2/ 0,25 El centro del galgal tiene un hoyo de 0,8 m de profundidad. La cámara podría haber tenido unos 0,8 m de ancho. Orientación a 100º.','No se conoce','El monumento se está utilizando como una palomera de caza. Catalogado en MUNIBE con el nº 71-13, suplemento nº 1, año 1973.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(108,'LUURZU - SE',2,'Túmulo','Quinto Real','A unos 700 m se alza la cumbre Luurzu a 320º. Hoja cartográfica Nº: 91-9','Túmulo de 9 m de',NULL,623650,4768190,995,43.054473,-1.482960,'utm','1983-06-29','miércoles, junio 29, 1983','Francisco Ondarra','Túmulo de 9 m de ? y de 0,8 m de altura, compuesto de piedras areniscas bastante grandes. Entre el musgo y el brezo se distingue en el centro un hoyo rebajado en el que no se ven losas.','No se conoce.','Bibliografía: Príncipe de Viana Arqueología nº 7, año 1988. En dirección al dolmen de Luurzu Hego, a unos 120 m W-WN, existe otra formación tumular, pendiente de tomar datos.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(109,'LUURZU-AITZ ZABALTOKI',13,'Monolito','Quinto Real','A 10 m del túmulo y 40 m del dolmen. Hoja cartográfica Nº: 91-9','Urkiaga',NULL,623050,4768610,1160,43.058352,-1.490233,'utm',NULL,NULL,NULL,'De 2,50/5 m de largo; 0,5 m de ancho y 0,6/0,7 m de grueso; de arenisca roja; tendido en el suelo; orientación a 35º. La superficie del extremo o cara SW ha podido ser labrada.',NULL,'Bibliografía: Revista Príncipe de Viana nº 142/143, año 1976.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(110,'LUURZU I-II-III-IV',2,'Túmulos','Quinto Real','Junto al dolmen de Luurzu, a unos 40 al E Hoja cartográfica Nº: 91-9','Urkiaga',NULL,623010,4768580,1170,43.058088,-1.490730,'utm','1973-03-24','sábado, marzo 24, 1973','Francisco Ondarra. En esa fecha los nº I y II. El 2 de junio de 1983 los nº III y IV.','Túmulo: - nº I : de 5 m de ? y 0,4m de alto, de tierra y piedras areniscas - nº II, a 5 m del dolmen: de 3 m de ? y 0,2 m de altura, de tierra y piedras areniscas, recubierto de hierba - nº III, a 0,5 m del dolmen, a 20º: de 2,5 m de ? y 0,25 m de alto de tierra y piedras areniscas - nº IV, a 5,4 m de III por el S-SW: de 3 m de ? y 0,3 m de alto de tierra y piedras areniscas.','No se conoce','Bibliografía: Educación y Cultura del Gobierno de Navarra. Arqueología nº 7 año 1988.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(111,'LUURZU LEPOA HEGO-I',1,'Dolmen','Quinto Real','A unos 500 m al S de la cumbre de Luurzu. Hoja cartográfica Nº: 91-9','Urkiaga',NULL,623210,4768260,1095,43.055175,-1.488346,'utm','1972-10-08','domingo, octubre 08, 1972','Francisco Ondarra','Túmulo de 12,5 m de ? y de 0,8 m de altura, compuesto de piedras y tierra y de dos losas "in situ", areniscas y pizarras. La losa nº 1: de 1,6 m de largo y 0,12 m de grueso; orientada a 145º. La losa nº 2: de 1 m de largo y 0,08 m de grueso y 0,22 m de alto; orientada a 30º. Tiene un hoyo central de 4 m de ? con muy poca profundidad.','No se conoce.','Bibliografía: Revista Príncipe de Viana nº 142/143, año 1976.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(112,'LUURZU LEPOA-II',5,'Crómlech','Quinto Real','En el collado de Luurzu. Hoja cartográfica Nº: 91-9','Urkiaga',NULL,622695,4768530,1170,43.057689,-1.494608,'utm',NULL,NULL,NULL,'De unos 20 testigos de areniscas muy pequeñas, formado un circunferencia de 9 m de ?. La piedra nº 1: de 0,92 m de alto; 0,4/0,2 m de ancho y de 0,2/0,3 m de grueso. nº 2: de 1 m de largo. nº 3: de 0,6 m de alto; 0,8 m de largo y 0,3 m de grueso nº 4: de 0,8 m de largo','No se conoce.','Bibliografía: Revista Príncipe de Viana nº 142/143, año 1976.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(113,'ARGINTZU LUURZU',2,'Túmulo','Quinto Real - Irurita','En el collado entre Luurzu y Argintzo Hoja cartográfica Nº: 91-9','Urkiaga',NULL,623480,4768780,1138,43.059812,-1.484916,'utm',NULL,'jueves, mayo 11, 1905','Tomás López Sellés','Túmulo circular de 11 m de ? y 1 m de altura, de piedras calizas del terreno. Ligero cráter central sin piedras ni losas de cámara. Solo se ve una piedra a pocos metos al S. A 20m al S existen dos crómlech.','No se conoce','Catalogado en MUNIBE con el nº 71-14, suplemento nº 1, año 1973.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(114,'ARGINTZU-AITZ ZABALTOKI',13,'Monolito','Quinto Real','Entre el túmulo y el crómlech Argintzu-I Hoja cartográfica Nº: 91-9','Urkiaga',NULL,623460,4768860,1140,43.060535,-1.485144,'utm','1973-03-24','sábado, marzo 24, 1973','Francisco Ondarra','De 3,65 m de largo; 0,5/1,25 m de ancho; orientado a 10º; tendido sobre el suelo; piedra arenisca.',NULL,'Bibliografía: - Revista Príncipe de Viana nº 142/143, año 1976 - MUNIBE nº 35, año 1983',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(115,'ARGINTZUKO LEPOA',5,'Crómlech (3)','El I y II en Quinto Real y el III en el Baztan','En el collado entre Argintzu al NE y Luurzu al SW. Hoja cartográfica Nº: 91-9','Urkiaga',NULL,623485,4768820,1138,43.060171,-1.484846,'utm','1973-03-24','sábado, marzo 24, 1973','Francisco Ondarra','Nº I: a 15m al SE del túmulo, formado por 16 testigos de piedra arenisca que forman un círculo de 5 m de ?; medidas de las piedras. - nº 1: 1,5 m de alto; 0,5 m de ancho y 0,2 m de grueso; muy inclinada hacia el S. - nº 2: 0,9 m de largo, tendida y casi sepultada - nº 3: 0,9 m de alto - nº 4: 0,8 m de largo - nº 5: 0,8 m de largo y 0,8 m de ancho y casi oculta Nº II: a 45 m al NE del túmulo, formado por 30 testigos de piedras arenicas pequeñas que forman un círculo de 3,5 m de ?; en su interior existe un concavidad. La piedra nº 1 está sepultada en parte y mide 1,35 m de largo; la piedra nº 2 tiene 0,9 m de largo y la nº 3 tiene 0,85 m de largo. Nº III: a 30 m al W del túmulo en término de Baztan, tiene 10 testigos de piedras areniscas que forman un círculo de 6 m de ?, cóncavo en su interior con la mitad de los testigos dispuestos radialmente. El nº 1 mide 0,55 m de largo; el nº 2 mide 0,35 m y otra tumbada en el centro de 0,9 x 0,6 x 0,15 m.','No se conoce','Bibliografía: Revista Príncipe de Viana nº 142/143, año 1976.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(116,'ARGINTZU SOLTALDEA',5,'Crómlech','Quinto Real','Situado en el cabezo, estribación de Argintzu. Hoja cartográfica Nº: 91-9','Urkiaga',NULL,624000,4768700,1122,43.059007,-1.478550,'utm','1973-11-03','sábado, noviembre 03, 1973','Francisco Ondarra','Unos 30 testigos de piedra, la mayoría de pizarras, menos los marcados en el croquis con los números 1, 14 y 21 que son de arenisca y el 18 que es de cuarzo blanco. Forman un círculo de 6 m de ?. Las piedras más altas miden 0,3 y 0,25 m; la nº 11, que está tendida, mide 0,7 m de largo, 0,7 m de ancho y 0,05 m de grueso.','No se conoce.','Bibliografía: Revista Príncipe de Viana nº 142/143, año 1976.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(117,'ANTZABAL',1,'Dolmen','Irurita','Irurita Hoja cartográfica Nº: 91-9','Irurita',NULL,NULL,NULL,670,43.075345,-1.495061,'gpx','1982-11-01','lunes, noviembre 01, 1982','Francisco Ondarra','Túmulo de unos 6 m de ? y 0,4 m de altura por el lado W, pero desapareciendo por el lado S; de tierra y piedras con 6 losas de arenisca que miden: - nº 1 (N): 0,4 m de alto; 1,45 m de largo; 0,16 m de grueso - nº 2 (N): 0,1 m 0,45 m 0,1 m - nº 3 (E): 0,3 m 0,65 m 0,13 m - nº 4 (W): 0,35 m 0,8 m 0,1/0,17 m - nº 5 (W): 0,5 m 1 m 0,1, 0,17 m - nº 6 ¿cubierta?: 0,75 m de ancho; 2,42 m de largo y 0,25 m de grueso. Las losas 1, 2, 4 y 5 están clavadas verticalmente. Las losas 1, 4 y 5 han sido parcialmente destruídas, rebajando su altura. La losa 3 está clavada e inclinada hacia el exterior. La losa 6 está partida en 2 trozos y el trozo W mide 0,8 m de largo y está tumbdo sobre la losa 5. Existen más trozos de losas. La cámara podría medir 1 m de ancho y unos 2 m de largo; orientada 105º. Hay un haya en el estremo W.','No se conoce.','Bibliografía: Revista Arqueología nº 7, editada por el Gobierno de Navarra en el año 1988.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(118,'AUTRIN',1,'Dolmen','Baztan','En lo alto de la cota 976 m. Hoja cartográfica Nº: 91-9','Urkiaga',NULL,624390,4770000,976,43.070646,-1.473472,'utm','1973-12-28','viernes, diciembre 28, 1973','Francisco Ondarra','Túmulo poco definido con una losa de 1,5 m de alto, de 1,10 m de largo y 0,2 m de grueso que es posiblemente de la cabecera y con dos losas fragmentadas, posiblemente las del N.: nº 2 de 0,2 m de alto , 0,33 m de largo y 0,1 m de grueso; nº 3 de 0,16 m de alto, 0,7 m de largo y 0,11 m de grueso. Orientación a 110º. Areniscas del terreno.','No se conoce.','Bibliografía: Revista Príncipe de Viana nº 142/143, año 1976.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(119,'AZALDEGIKO LEPOA-I',1,'Dolmen','Baztan','A 50 m al NE del crómlech, al S de la cima de Autrin. Hoja cartográfica Nº: 91-9','Urkiaga',NULL,624370,4769810,950,43.068939,-1.473760,'utm','1973-03-28','miércoles, marzo 28, 1973','Tomás López Sellés','Túmulo de 12/13 m de ? con 2 losas plantadas y otra tendida horizontalmente. Areniscas del terreno. Las medidas de las losas son: - nº 1: 0,25 m de altura; 0,8 m de largo y 0,12 m de grueso - nº 2: 1m " 0,45 m " 0,2 m " . Oreintada a 85º. - nº 3 tendida: 1,5 m de ancho; 1,7 m de largo y 0,15 m de grueso','No se conoce.','Bibliografía: Revista Príncipe de Viana nº 142/143, año 1976.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(120,'AZALDEGIKO LEPOA-II',5,'Crómlech','Baztan','Al S de la cima de Autrin. Hoja cartográfica Nº: 91-9','Urkiaga',NULL,624350,4770000,950,43.070652,-1.473963,'utm','1973-12-28','viernes, diciembre 28, 1973','Francico Ondarra','4 Testigos constituyen un círculo de 5 m de ?. Son de areniscas del terreno. La piedra nº 1, que es la mayor, mide 0,9 m de alto; 0,3 m de largo y 0,25 m de grueso. Las piedras nº 3 y nº 4 miden 0,3 m de alto y 0,5 m de largo. La nº 4 está completamente enterrada.','No se conoce.','Bibliografía: Revista Príncipe de Viana nº 142/143, año 1976.',NULL,'Bloc 16: Artesiaga - Quinto Real.'),
(121,'EZKIREGI',7,'Dolmen corto abierto','Ardaiz','En la loma de su nombre, junto y a la derecha de la carretera. Hoja cartográfica Nº: 116-9','Valle del Arriasgoiti',NULL,625503,4750400,695,42.894026,-1.464207,'utm',NULL,'lunes, abril 17, 1905','José Miguel de Barandiaran','Túmulo desfigurado. 2 Losas y una cubierta fragmentada. Calizas del terreno. Según el croquis y los datos que figuran en Munibe cuando fue localizado, el monumento tenía cámara formada por tres losas con recinto rectangular en su origen. Hoy casi triangular, cubierta desplazada y rota en dos fragmentos apoyados en el túmulo, que tiene es su cara superior un surco artificial, que partiendo de un punto que dista 0,5 m del borde occidental y formando un zig-zag, va a desembocar en el borde oriental. En la acualidad (26-9-1987), la losa de cámara N está fraccionada en unos ocho trozos desparramados por la cámara. Al desconocer las medidas que puedo tener el túmulo en la fecha de localización, no se puede hacer una comparación de conservación. Sí se puede decir que en su parte S. hay un allanamiento del terreno, si no muy reciente, sí posterior a la fecha de su localización. En cuanto al resto de materiales, no parece que hayan sufrido modificación intencionada, como parece que le ha ocurrido a la losa mencionada.','De la cámara, en 1934 por José Miguel de Barandiaran.','Ajuar de la excavación: - 2 Hojas, una con retoque de uso, 1 lasca - 1 frag. De borde y cuello de cerámica inidentificable. Según J.M. de Barandiaran, existieron 5 útiles de silex fig. 1, 2, 3 y 5. Museo Arqueológico de Álava. Vitoria. Bibliografía: Barandiaran, JM: Huellas de Arte (1935).375 " : Catalogue des stations (1946) " : Hombre Prehistórico… (1953) " : Notas… (1963-64) Pág. 119 Fernández Medrano, D.:Guía Sumaria… (1948)',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(122,'ARDAIZ - I',9,'Dolmen largo abierto','Ardaiz','Al NE. del pueblo, en el monte Argitxoain, en el término Orgal. Hoja cartográfica Nº: 116-9','Valle del Arriasgoiti',NULL,627150,4751075,945,42.899830,-1.443890,'utm',NULL,'lunes, abril 17, 1905','José Miguel de Barandiaran','Túmulo desfigurado de unos 20 m de ?. 5 Losas y una tendida. Calizas del terreno. Sobre un túmulo desfigurado de piedras, cubierto totalmente de bojes, se encuentran cinco losas más una tendida que parecen formar un recinto rectangular muy desfigurado. Cámara totalmente vaciada. Orientación a 110º.','No se conoce.','Los bojes que cubren el túmulo esconden el conjunto, impidiendo verlo. Aunque no se conoce excavación, se observa que a través del tiempo este monumento ha sufrido violaciones en busca del consabido tesoro. Con fecha 26-9-1987 se le colaca un hito señalizador, actividad de los socios de Gorosti. Bibliografía: Barandiaran, JM: Huellas de Arte (1935).375 " : Catalogue des stations (1946) " : Hombre Prehistórico… (1953) Fernández Medrano, D.:Guía Sumaria… (1948)',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(123,'ARDAIZ - II',7,'Dolmen corto abierto','Ardaiz','Al NE del pueblo, monte Argitxoain, término Orgal, a 100 m al E. del Ardaiz-I Hoja cartográfica Nº: 116-9','Valle del Arriasgoiti',NULL,627000,4751100,945,42.900080,-1.445721,'utm',NULL,'lunes, abril 17, 1905','Por José Miguel de Barandiaran','Túmulo de piedras de 19 m de ?. Calizas del terreno. 3 Losas formando recinto y una de cubierta. Recinto trapezoidal al cerrarse las paredes a la entrada. Losas basculadas por presión de la cubierta. Orientación a 130º. Túmulo casi tapado por los bojes.','No se conoce.','Al igual que el Ardaiz-I, con fecha 26-9-1987 se fue colocado un hito señalizador por el grupo Gorosti. Bibliografía: Barandiaran, JM: Huellas de Arte (1935).375 " : Catalogue des stations (1946) " : Hombre Prehistórico… (1953) Fernández Medrano, D.:Guía Sumaria… (1948)',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(124,'OIARZABAL IPAR (BIORRETA - I)',7,'Dolmen corto abierto','Ardaiz - Zunzarren','En la cresta divisoria de Biorreta - Ardaiz, prolongación monte Etarte. Hoja cartográfica Nº: 116-9','Valle del Arriasgoiti',NULL,627500,4748750,970,42.878842,-1.440132,'utm',NULL,'sábado, mayo 06, 1905','Tomás López Sellés','Túmulo de 10 m de ? y 0,45 m de alto. Calizas del terreno. 3 Losas y cubierta desplazada. Túmulo rebajado y recinto de la cámara rectangular. Orientación E.','No se conoce','Pendiente de colacar hito señalizador. En el mes de marzo de 1988 se recopilan nuevos topónimos de la zona donde se ubica el dolmen. Esta cota se denomina Oiarzalmendi, antes Aska. Desde el monumento, en la prolongación W, al SW se divisa Elomendi; al S., Peña Izaga; al N., Asi. Bibliografía: López Sellés, Tomás: Nuevos dólmenes… 1956 nº 3. " : Nuevos hallazgos… 1960. 246',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(125,'OIARZABAL HEGO BIORRETA - II',7,'Dolmen corto abierto','Zunzarren','Al SE. del Biorreta - I, en una pequeña loma que desciende a Biorreta. Hoja cartográfica Nº: 116-13','Valle de Arriasgoiti',NULL,627565,4748000,800,42.872080,-1.439507,'utm',NULL,'sábado, mayo 06, 1905','Tomás López Sellés','Túmulo de piedras desfigurado por una alambrada. Sin cubierta Orientacion E.','No se conoce.','Pendiente de colocación de un hito señalizador. Tópez Sellés, Tomás: Nuevos hallazgos… 1960. 246',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(126,'Argibel',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,43.094616,-1.471491,'gpx',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(127,'DONDORO',9,'Dolmen largo abierto','Espinal','A 1,3 km al WNW del pueblo Hoja cartográfica Nº: 116-2','Ruta 5, Itinerario 4: Espinal septentrional',NULL,631760,4760780,896,42.986409,-1.385162,'utm',NULL,'viernes, abril 07, 1905','Silvestre Irigoyen','Túmulo muy poco apreciable de calizas del terreno y 4 losas. Probablemente circular. La cámara forma un recinto rectangular abierto. Orientación a 90º. Resultado de la excavación: No se conoce ningún ajuar. En el Museo de Navarra, Pamplona, existe una lasca.','T. Aranzadi y J.M. Barandiaran en 1925','Con fecha 25-7-1989 le fue colocado un hito señalizador por el grupo de Gorosti y voluntarios del lugar. Descripción de la zona de Espinal - Aurizperri y listado de monumentos megalíticos. (Ver en Anexos) Bibliografía: MUNIBE 1973, Suplemento nº 1. Nº de catálogo: 68-4.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(128,'URDANTXARRETA',1,'Dolmen corto?','Espinal','1,7 km NNW pueblo, ladera meridional Mendiaundi. Hoja cartográfica Nº: 116-2','Ruta 5, Itinerario 4: Espinal septentrional',NULL,632520,4761500,905,42.992758,-1.375673,'utm',NULL,'viernes, abril 07, 1905','Silvestre Irigoyen','Túmulo circular con 3 losas y 10 m de ? y 0,9 m de alto. En 1925, de las losas de la cámara, dos están en una pared y una en la opuesta. Orientación E - W.','T. Aranzadi y J.M. Barandiaran en 1925.','Resultado de la excavación: una lasca informe de silex (Museo de San Telmo, San sebastián) Bibliografía: MUNIBE 1973, Suplemento nº 1. Nº de catálogo: 68-3. En 1984 se pudo comprobar había desaparecido como tal al pasar por encima la pista que ampliaba el camino adyacente al monumento. Hoy se percibe una forma tumular con piedras dispersas.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(129,'OTEGI',1,'Dolmen','Espinal','Lado izdo. Carretera a Burguete. Entre bifurcaci. Aoiz - Garralda Hoja cartográfica Nº: 116-3','Ruta 5, Itinerario 3: Espinal oriental.',NULL,634575,4759770,872,42.976825,-1.350891,'utm',NULL,'sábado, abril 08, 1905','T. Aranzadi y J.M. Barandiaran','Dolmen con 1 losa. Túmulo circular. Cámara reducida a una losa vertical y fragmentos dispersos de otras.','T. Aranzadi y J.M. Barandiaran en 1925.','En la excavación subsiguiente al descubrimiento del dolmen no se obtuvo ajuar alguno. Esta circunstancia llevó a los excavadores a no considerar el monumento como dolmen. J.M.Barandiaran lo admite como tal. Hacia finales de mayo de 1989, los terrenos donde estaba ubicado el dolmen fueron labrados para la siembra de patata. Por este motivo el dolmen ha desaparecido. Este hecho tuvo como réplica un escrito de la Sociedad Gorosti que, difundido por prensa y radio, denunciaba a la opinión pública el atropello cometido. La denuncia fue difundida hacia el 3 de julio de 1989. Bibliografía: MUNIBE 1973, Suplemento nº 1. Nº de catálogo: 68-9.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(130,'MUGARRI',2,'Túmulo','Viscarret','45´en camino Tiratun, entre barrancos Bordasoro - Odiako erreka Hoja cartográfica Nº: 116-1','Ruta 5: Itinerario nº 1, Linzoain.',NULL,627245,4759965,1080,42.979840,-1.440707,'utm',NULL,'jueves, mayo 11, 1905','Tomás López Sellés','Túmulo circular de 12 m de ? y 1 m de alto. Cráter central sin losas de cámara.','No se conoce,','MUNIBE, nº de catálogo: 68-13.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(131,'ARRIURDIN',9,'Dolmen largo abierto','Mezquiriz','10´ alto y 100 m alambrada divisoria de Mezquiriz y Espinal. Hoja cartográfica Nº: 116-2','Ruta 5, Itinerario 2: Alto Puerto de Mezquiriz.',NULL,NULL,NULL,930,42.673426,-1.592545,'gpx',NULL,'viernes, abril 07, 1905','S. Irigoyen','Túmulo circular con 5 losas de calizas del terreno, muy poco apreciable. Cámara con al menos cinco losas, formando un recinto rectangular. Orientación a 90º. Ajuar encontrado en la excavación: - 37 lascas informes de sílex y fragmentos de cerámica. El Museo de Navarra guarda los siguientes objetos: - 1 microraspador en extremos de lasca - 1 lasca con una parte de margen retocado con retoque directo y parte mayor con retoque inverso de la cara opuesta - 2 lascas - 2 hojas menudas - 1 trozo ocre - 1 esquirla apuntada en forma de alisador pulimentado y aguzado al fuego. Bibliografía: MUNIBE 1973, suplemento nº 1 Nº de catalogación: 68-5.','T. Aranzadi y J.M. Barandiaran en 1926.','En el año 1985 apenas se distingue el túmulo, viéndose 4 losas; en la parte oriental hay 1 en pie, rota en 2 trozos. Al S. una losa pqueña recostada en la anterior y otra losa inclinada en la cámara apreciable. En el primer semestre de 1989 una máquina lo destruye al preparar el terreno para sembrar, a pesar de haber sido advertido el maquinista por Juan Mª Martínez Txoperena. Aunque justamente se distingue un pequeño montículo de lo que fue el túmulo, parece ser que la cámara podría seguir existiendo, tapada con tierra. Cuando se prospeccionó esta zona en 1984, se llegó a ver en otra campa labrada al E. unas losas removidas por la máquina, quedando la duda de si pudiera tratarse de otro dolmen.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(132,'ERLEBIZKARRA',1,'Dolmen','Espinal',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Túmulo circular de piedras. No se conoce ajuar. Bibliografía: MUNIBE 1973, suplemento nº 1 Nº de catalogación: 68-7.','T. Aranzadi y J.M. Barandiaran en 1925.','Este dolmen desapareció en 1935 al ampliarse el cementerio.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(133,'URRITZ MUNO',2,'Túmulo','Espinal','0,6 km del pueblo y 30 m de la carretera a Burguete Hoja cartográfica Nº: 116-2','Ruta 5, Itinerario 3: Espinal oriental.',NULL,633950,4759900,877,42.978105,-1.358521,'utm',NULL,'viernes, abril 07, 1905','S. Irigoyen','Túmulo irregular, muy pronumciado por el lado N. y muy rebajado por el lado S. Gran cráter central, del que ha desaparecido la cámara cuando en 1870 se desmanteló el monumento. Ajuar encontrado en la excavaión: - 1 fragmento de cerámica basta (Museo de San Telmo, San Sebastián) - 1 fragmento de panza con pitón pequeño - 1 fragmento de panza con pitón redondo (Museo de Navarra) Bibliografía: MUNIBE 1973, suplemento nº 1 Nº de catalogación: 68-8.','T. Aranzadi y J.M. Barandiaran en 1926.',NULL,NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(134,'BARATZEKO ERREKA',7,'Dolmen corto abierto','Espinal','A 2,2 km de Espinal al ESE., a la derecha de la regata de su nombre Hoja cartográfica Nº: 116-3','Ruta 5, Itinerario 3: Espinal oriental.',NULL,635175,4759200,870,42.971588,-1.343673,'utm',NULL,'viernes, abril 07, 1905','Silvestre Irigoyen','Dolmen corto abierto. Calizas del terreno. Túmulo poco apreciable, que apenas destaca del terreno. Quedó cortado al N. al labrar el terreno, quedando a ras. Cámara con 3 losas, que conforman un recinto trapezoidal, estrechadoal E. hacia la entrada. Las losas están basculadas hacia el interior. No tiene cubierta. La orientación es de 130º. Ajuar encontrado en la excavación: - 3 hojas de sílex - 2 lascas - 1 punta de flecha (cobre o bronce) de pedúnculo central y aletas - restos humanos de al menos 5 inhumados, uno de ellos infante - restos de animales Museo de San Telmo, San Sebastián. Bibliografía: MUNIBE 1973, suplemento nº 1 Nº de catalogación: 68-1.','T. Aranzadi y J.M. Barandiaran en 1925.','La Sociedad Gorosti con la inestimable colaboración de Juan Mª Martínez Txoperena y un grupo de jóvenes de Espinal y Garralda, colocó un hito señalizador el 25 de julio de 1989.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(135,'ARTZILO',8,'Dolmen corto cerrado','Espinal','Ladera meridional del Menzuri, a 2 km al N. de Espinal. Hoja cartográfica Nº: 116-2','Ruta 5, Itinerario 4: Espinal septentrional.',NULL,633157,4762230,930,42.999218,-1.367688,'utm',NULL,'viernes, abril 07, 1905','Silvestre Irigoyen','El túmulo circular de 13 m de ? y 1,5 m de alto está formado por piedras de arenica del terreno. La cámara es un recinto rectangular formado por 4 losas y 1 de cubierta. Una losa se ha corrido hacia el esterior, tal vez por el peso de la cubierta. Ésta parece hallarse "in situ" y está partida en 2 trozos. Orientación a 60º. Ajuar encontrado en la excavación: - fragmentos de cerámica - objetos modernos. Museo de San Telmo, San Sebastián. Bibliografía: MUNIBE 1973, suplemento nº 1 Nº de catalogación: 68-2.','T. Aranzadi y J.M. Barandiaran en 1925.','La Sociedad Gorosti con la inestimable colaboración de Juan Mª Martínez Txoperena y un grupo de jóvenes de Espinal y Garralda, colocó un hito señalizador el 25 de julio de 1989.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(136,'ODIEGO HEGO',7,'Dolmen corto abierto','Valle de Erro','Detrás de Casa Establo del Ayuntamiento de Erro Hoja cartográfica Nº: 91-14','Ruta 5, Itinerario 5: Sorogain Hego.',NULL,629815,4762940,840,43.006186,-1.408508,'utm','1955-04-03','domingo, abril 03, 1955','Tomás López Sellés','El túmulo circular de 10 m de ? fue destrozado al hacer un cargadero de madera. Dolmen de 3 losas. La losa E mide 1,63 m de largo; 0,7 m de anchura; 0,38 m de grueso. La losa W mide 1,78 m de largo; 1 m de ancho; 0,24 m de grosor. Un espino crece entre ambas. La cámara sepulcral se va estrechando progresivamente y mide 0,71 m al N y 0,5 m al S. A unos 350 m al E puede verse la antigua borda "Casa de Pablo", cuya cubierta es de teja y cinc. Orientación N-S. Bibliografía: MUNIBE 1973, suplemento nº 1 Nº de catalogación: 68-11.','No se conoce','La Sociedad Gorosti con la inestimable colaboración de Juan Mª Martínez Txoperena y un grupo de jóvenes de Espinal y Garralda, colocó un hito señalizador el 23 de julio de 1989.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(137,'ARREGI',7,'Dolmen corto abierto','Espinal','Al S de la Casa Establo del Ayuntamiento de Erro, en el camino a Espinal Hoja cartográfica Nº: 91-14','Ruta 5, Itinerario 5: Sorogain Hego.',NULL,630265,4762430,945,43.001519,-1.403108,'utm','1961-10-05','jueves, octubre 05, 1961','Tomás López Sellés','El túmulo es circular de 15 m de ? y 1,2 m de alto y aparece desfigurado. Calizas del terreno Hay 3 losas en la cámara y 4 en el túmulo. Las 3 losas de la cámara forman un recinto trapezoidal. Orientación al S. Bibliografía: MUNIBE 1973, suplemento nº 1 Nº de catalogación: 68-12.','No se conoce','El 23-7-1989 se le colocó el hito señalizador, tarea en la que colaboraron varios jóvenes del lugar.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(138,'BAGOMULTXU',1,'Dolmen','Espinal','Hoja cartográfica Nº: 91-14','Ruta 5, Itinerario 5: Sorogain Hego.',NULL,630550,4762650,1050,43.003450,-1.399561,'utm',NULL,'sábado, abril 08, 1905','T. Aranzadi y JM. Barandiaran','El túmulo es circular de 8 m de ? y muy poco apreciable. En él se observa un cráter central sin losas de cámara. Areniscas del terreno. Bibliografía: MUNIBE 1973, suplemento nº 1 Nº de catalogación: 68-10.','T. Aranzadi y JM. Barandiaran','La excavación no tuvo resultado positivo: no se encontró ajuar alguno, por lo que estos autores lo consideraron dudoso. Hoy este dolmen no existe, ya que desapareció durante la guerra civil de 1936.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(139,'MENDIAUNDI',7,'¿Dolmen corto abierto?','Espinal','En el collado entre Txasperro y Mendiaundi Hoja cartográfica Nº: 91-14','Ruta 5, Itinerario 5: Sorogain Hego.',NULL,632225,4763270,1130,43.008742,-1.378871,'utm',NULL,'viernes, abril 07, 1905','Silvestre Irigoyen','Túmulo circular de 15 m de ? y 1,15 m de alto desmoronado. Las 2 losas de la cámara formaban escuadra. Hoy desaparecido. Orientación SE. Resultado de la excavación: sólo se conocen objetos modernos. Bibliografía: MUNIBE 1973, suplemento nº 1 Nº de catalogación: 68-8.','T. Aranzadi y J.M. Barandiaran en 1926.',NULL,NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(140,'MENDIAUNDI',2,'Túmulos','Espinal','Entre el Mediaundi y el Menditxipi Hoja cartográfica Nº: 91-14','Ruta 5, Itinerario 5: Sorogain Hego.',NULL,633025,4763250,1148,43.008422,-1.369063,'utm',NULL,'lunes, junio 05, 1905','Miguel Ezcudia','El túmulo de tierra y piedras tiene 8 m de ? con un cráter central de 6 m de ? y 2 m de profundidad. A 120 m al W existe otro túmulo de parecidas características.','No se conoce','No está catalogado en MUNIBE. Registrado con dudas sobre su carácter funerario, ya que da la impresión de haber sido utilizado con fines militares.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(141,'ODIEGO IPAR',1,'Dolmen','Valle de Erro','A 100 m al N de la Casa - Establo del Ayuntamiento de Erro Hoja cartográfica Nº: 91-14','Ruta 5, Itinerario 6: Sorogain Sortalde.',NULL,629790,4763090,840,43.007541,-1.408780,'utm',NULL,'miércoles, mayo 31, 1905','Miguel Javier Urmeneta','Presenta un túmulo rebajado, pero definido. 2 Losas conforman la desfigurada cámara orintada N-S.',NULL,'Resulta extraño que, habiendo pasado por estos lugares prospectores tan expertos y destacados como JM. Barandiaran, T. Aranzadi y Tomás López Sellés (quien dio a conocer el Odiego de la Casa Establo), no señalaran nada de esta otro dolmen que, aunque está profanado, presenta los rasgos característicos de dolmen. En el último catálogo editado en 1973 por MUNIBE, no se dice nada acerca de este dolmen.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(142,'BERASKUAIN',1,'Dolmen','Valle de Erro','En el Collado Baraskain, por el camino al E de Casa de Pablo. Hoja cartográfica Nº: 91-14','Ruta 5, Itinerario 6: Sorogain Sortalde.',NULL,630710,4764658,1009,43.021498,-1.397128,'utm',NULL,'jueves, junio 08, 1905','Luis Millán','Túmulo rebajado, pero apreciable, de piedras y tierra, en el que aparece tirada 1 losa. En la parte E asoma lo que pudiera ser 1 losa.',NULL,'Hacia el S aparece un grupo de diez crómlech de escasa entidad. Así mismo, en una pequeña cota en dirección SE se aprecia una forma tumular de la que sobresalen del terreno unas losas de pequeñas dimensiones. En el hito señalizador, colocado por la Sociedad Gorosti (con la colaboración de Juan Mª Martínez Txoperena y un grupo de jóvenes de Espinal y Garralda) el día 23-7-1989, se alude a esta forma tumular con el nombre Beraskuain Hego',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(143,'ASUNREGI',12,'Fondos de cabaña','Valle de Erro','En el camino desde la Casa-Establo a Estakarriko Lepoa Hoja cartográfica Nº: 91-14','Ruta 5, Itinerario 7: Sorogain Ipar',NULL,629550,4764800,900,43.022974,-1.411326,'utm',NULL,NULL,NULL,'Se trata de ocho promontorios que de forma uniforme se asientan en una ladera de poca vertiente y cercana a un barranco.',NULL,'No se conoce la historia de los mismos, ni están anunciados en el catálogo de MUNIBE. En cuanto a su identidad, hay quien opina que se trata de asentamientos de tiendas militares de campaña; otros los identifican como crómlech y también como fondos de cabaña, que a nuestro parecer es lo más probable. En el hito señalizador colocado por Xantoten Harria se hace alusión a estos promontorios.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(144,'XANTOTEN HARRIA',5,'Crómlech','Valle de Erro','En el camino desde Casa-Establo a Estarriko Lepoa Hoja cartográfica Nº: 91-14','Ruta 5, Itinerario 7: Sorogain Ipar',NULL,629435,4765200,922,43.026595,-1.412644,'utm','1955-04-03','domingo, abril 03, 1955','Tomás López Sellés','Testigos compuestos de 14 piedras (enhiestas unas, otras tumbadas) de tamaño desigual que oscila entre 0,6 m y 0,3 m de altura y que enmarcan un recinto de unos 8 m de diámetro. Le faltan algunos testigos en el lado E. Excavación: Llevada a cabo por Pedro Arrese con objeto de elaborar su tesina y autorizada por el Museo de Navarra. De este trabajo no se conoce resultado alguno, al menos públicamente. Por el contrario, se ha observado que los testigos han quedado mermados de tierra en su base, con el consiguiente peligro de falta de consistencia. Así mismo, en su centro se puede observar una cuadríula a falta de la tierra que la cubría. Bibliografía: T. López Sellés: Contribución a un suplemento de catálogo delménico del País Vasco de J. Elosegui. MUNIBE 1973, pág. 3 y 11.','Pedro Arrese en 1984-85','Sobre el topónimo Santoten Harria, D. José Miguel de Barandiaran lo aplicó al dolmen de Pilotasoro. Escribe en el Diccionario de Mitología Vasca que quiere decir "piedras de Santxote", por ser el lugar donde murió un arriero así llamado. Este fue un famoso trovador al que los pastores de la zona levantaron un monumento con peñas de ortostatos, junto a otro anterior cuyos restos se ven todavía. La Sociedad Gorosti, con la colaboración de Juan Mª Martínez Txoperena y un grupo de jóvenes de Espinal y Garralda, colocó un hito señalizador el día 23-7-1989.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(145,'PILOTASORO',7,'Dolmen corto abierto','Valle de Erro','Collado Estakarri Hoja cartográfica Nº: 91-14','Ruta 5, Itinerario 7: Sorogain Ipar',NULL,629430,4766110,1020,43.034787,-1.412495,'utm',NULL,'lunes, mayo 01, 1905','J.M. Barandiaran','Dolmen de 3 losas de areniscas del terreno y de 15 m de ? y 0,8 m de alto. Primitivamente las losas de la cámara formaban un recinto rectangular. En la actualidad es trapezoidal por cerrarse la losas en la entrada. Sin cubierta. Orientación al E., según JM. Barandiarán. Bibliografía: Barandiaran, JM.: Hombre Prehistórico (1953) Crónica (1949) MUNIBE 1973, nº catalogación 72-6.','No se conoce','A 40 m en dirección NW se puede aapreciar un túmulo circular de 9,2 m de ? y 0,8 m de alto. Fue descubierto en 1948 y no se conoce excavación. En la actualidad las dimensiones del túmulo ham cambiado y se presenta más disminuído. Tiene un pequeño cráter central. La Sociedad Gorosti, con la colaboración de Juan Mª Martínez Txoperena y un grupo de jóvenes de Espinal y Garralda, colocó un hito señalizador el día 23-7-1989.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(146,'ELORRIXAALEA',1,'Dolmen corto','Alduides - Urepel','Detrás de la muga fronteriza 148 Hoja cartográfica Nº: 91-14','Ruta 5, Itinerario 7: Sorogain Ipar',NULL,630350,4766700,890,43.039941,-1.401067,'utm',NULL,'lunes, mayo 01, 1905','JM. Barandiaran','Dolmen de 3 losas, de calizas del terreno y de 16 m ? y 1,8 m de alto. Dos de las losas, paralelas e inclinadas, forman la cámara. La tercera parace ser solo un fragmento y aparece suelta. El túmulo es circular y muy pronunciado al NE y al W. Hoy es imposible determinar con seguridad la planta del monumento. Orientación del eje mayor N-S., según JM. Barandiaran.','No se conoce','En la zona de Urepel (Ultrapuestos) se conocen los siguientes: - IRAZTEI IPAR: 3º 42´ 3´´ - 43º 03´ 28´´. A 3,8 km al SSE de Urepel del collado de Nahala, sobre el alto de su nombre. - KUTXAZARRETA: 3º 44´ 11´´ - 43º 03´ 18´´ - 500m. A unos 2 km al SE de Urepel. - TRAIKARLEPO: 2º 20´ 30´´ - 43º 03´ 08´´ - 1150m (hoja 91-15) 3º 40´ 57´´ - 43º 02´ 53´´ A 100m al N del mojón 160, en un collado al S. de Lauriña (en el que se encuentra el dolment de Lauriña, en término de Valcarlos). Bibliografía: MUNIBE 1973, suplemento nº 1, catalogación nº 72-8.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(147,'ADIKO SOROA',5,'Crómlech','Quinto Real (Administración del Valle de Erro)','Vertiente norte del Adi Hoja cartográfica Nº: 91-14','Ruta 5, Itinerario 8: Sorogain Mendebal',NULL,626950,4764950,1165,43.024763,-1.443191,'utm','1966-09-18','domingo, septiembre 18, 1966','Tomás López Sellés','Distriuidos por la zona existen 10 dromlechs y dos túmulos, compuestos por piedras de diferentes tamaños que destacan en el paisaje. Sus diámetros oscilan entre los 2 y 5 m. Al S y en las cercanías hay una fuente.',NULL,'Tomás López Sellés registró 6 cromlelchs el 18-9-1966, MUNIBE 1973, pág. 4. Posteriormente José Miguel Larrañaga, 4.',NULL,'Bloc 17: Erro - Valcarlos - Arriasgoiti'),
(148,'ERRONDONEKO BORDA',2,'Túmulo',NULL,'Hoja cartográfica Nº: 65-16',NULL,NULL,616000,4781400,625,43.174598,-1.574108,'utm',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'14 Baztan Centro-Sureste'),
(149,'MONOLITO DE LEGATE',13,'Monolito','Baztan','Hoja cartográfica Nº: 65-16','Itinerario nº 28',NULL,616816,4781031,775,43.171151,-1.564150,'utm',NULL,'viernes, mayo 26, 1905','F. Ondarra','Monolito de 3,2 m de largo; 0,55 m de ancho y 0,4 m de grueso. Tumbado. Orientación a 135º.',NULL,'El descubridor lo da a conocer con toda clase de reservas, sin que se atreva a afirmar la intervención humana en su esbelted y armonía. En la misma información da a conocer el túmulo de 4,5 m de diámetro por 0,3 m de alto, sin catalogar como auténtico. Así mismo denunció la desaparición del dolmen Legate II y también la prospección por parte de alguien del crómlech descubierto por JM. Barandiaran.',NULL,'14 Baztan Centro-Sureste'),
(150,'MAIRU - HARRI',1,'Dolmen',NULL,'Hoja cartográfica Nº: 90-4/A','Itinerario nº 28',NULL,615780,4779060,525,43.153567,-1.577304,'utm',NULL,'jueves, mayo 25, 1905','F. Ondarra','Dolmen. Túmulo de base circular de 13/14 m de diámetro por 1,5 m de altura, siendo más bajo por el ldo NW. Dos losas que enmarcan una cámara sepulcral de 1,4 m de alto; 2,6 m de largo y 0,8 m de ancho. La tapa se halla apeada asomando por encima del galgal y destacando en el horizonte. La cámara ha sido utilizada para algún fin, probablemente para pocilga, pues por el lado NNW está limitada por una pared de piedra. En la actualidad esta pared de piedra no está, posiblemente a raiz de la publicación de estos hallazgos en el año 1975.','No se conoce',NULL,NULL,'14 Baztan Centro-Sureste'),
(151,'AZNABASTERRA',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,43.137877,-1.440771,'gpx',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'14 Baztan Centro-Sureste');
INSERT INTO `megalitos` (`id`,`nombre`,`tipologia_id`,`tipologia_texto`,`municipio`,`ubicacion`,`itinerario_texto`,`hoja_cartografica`,`utm_x`,`utm_y`,`altitud`,`lat`,`lon`,`coord_fuente`,`localizado_fecha`,`localizado_fecha_texto`,`localizado_autor`,`descripcion`,`excavacion`,`observaciones`,`caracteristicas`,`otros_aspectos`) VALUES
(152,'MUNAUTZ',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,43.123017,-1.430951,'gpx',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'14 Baztan Centro-Sureste'),
(153,'LEGATE - I',7,'Dolmen corto abierto','Baztan','Hoja cartográfica Nº: 65-16/C','Itinerario nº 28',NULL,616780,4780980,765,43.170697,-1.564603,'utm',NULL,'lunes, abril 03, 1905','JM. Barandiaran','Túmulo circular de 9 m de ? y 0,5 m de altura. Piedras. Cámara de 4 losas con recinto rectangular. Orientación a 115º. Areniscas del terreno.','1947 por E. Zudaire','Hallago en la excavación de 2 fragmentos de cerámica y fragmento de barro cocido amarillento, en paradero desconocido. En la actualidad este monuento está destruido. El motivo parece ser que en la zona hay una explotación de piedra en la que trabajan con palas mecánicas. Catalogación nº 69-1.',NULL,'14 Baztan Centro-Sureste'),
(154,'LEGATE - II',8,'Dolmen corto cerrado','Baztan','A 11m al NE de Legate - I. Hoja cartográfica Nº: 65-16/C','Itinerario nº 28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'lunes, abril 03, 1905','JM. Barandiaran','Túmulo circular de 12m de ? y 0,7 m de altura. De piedras. Cámara de 5 losas con recinto rectangular. Areniscas del terreno. Todo el conjunto ha sido removido y las losas destrozadas; sin cubierta.','No se practicó excavación antes de su destrucción','Catalogación nº 69-2.',NULL,'14 Baztan Centro-Sureste'),
(155,'LEGATE - III',9,'Dolmen largo abierto?','Baztan','A unos 120 m de Legate I y II. Hoja cartográfica Nº: 65-16/C','Itinerario nº 28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'lunes, abril 03, 1905','JM. Barandiaran','Túmulo circular de 10 m de ? y 0,45 m de altura. De piedras. Cámara de 5 losas con recinto rectangular, hoy en día destrozada. Orientación a 115º. Areniscas del terreno.','1920 por JM. Barandiarán','Por los motivos anteriormente apuntados, parece ser que este monumento prehistórico desapareció entre los años 1972 y 1973. Catalogación nº 69-3.',NULL,'14 Baztan Centro-Sureste'),
(156,'LEGATE - IV',NULL,NULL,'Baztan',NULL,'Itinerario nº 28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Túmulo impreciso y rebajado. Cámara reducida a 2 largas losas en escuadra y una losa caída. Orientación al E., según Tomás López Sellés. Areniscas del terreno.',NULL,'Hoy día está cubierto por obras realizadas en la borda lindante.',NULL,'14 Baztan Centro-Sureste'),
(157,'LEGATE - V',1,'Dolmen','Baztan','Hoja cartográfica Nº: 65-16/D y 90-4','Itinerario nº 28-A',NULL,618170,4780598,550,43.167043,-1.547589,'utm','1972-04-15','sábado, abril 15, 1972','F. Ondarra','Túmulo de 9 m de ? y 1 m de altura por el SSW., siendo mucho más bajo por el NNE. Formado por piedras de regular tamaño. Cámara de 3 losas "in situ" con recinto rectangular de 0,8 m de ancho. 2 Losas más, probablemente de la tapa, tumbadas sobre el galgal. Orientación a 90º.','No se conoce',NULL,NULL,'14 Baztan Centro-Sureste'),
(158,'LEGATE - VI (IÑARZETA)',1,'Dolmen','Baztan','Hoja cartográfica Nº: 65-16/C','Itinerario nº 28',NULL,616680,4781530,760,43.175664,-1.565717,'utm','1973-04-01','domingo, abril 01, 1973','F. Ondarra','Túmulo de base circular de 6 m de ? y 1 m de altura, compuesto de tierra y piedras Cámara de 3 losas, de las que 2 parecen "in situ", siendo la tercera la tapa desplazada hacia el lado N del galgal. Las losas del N están inclinadas hacia el interior orientadas a los 135º y la tapa se halla tendida sobre el galgal partida en 2 trozos ensamblados entre sí. Areniscas.','No se conoce',NULL,NULL,'14 Baztan Centro-Sureste'),
(159,'LEGATE - VII',1,'Dolmen','Baztan',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'14 Baztan Centro-Sureste'),
(160,'BAGORDI',13,'Monolito',NULL,'Hoja cartográfica Nº: 65-16/C','Itinerario nº 28-J',NULL,NULL,NULL,NULL,43.168137,-1.533253,'gpx',NULL,'viernes, mayo 19, 1905','T. López Sellés','Túmulo circular de 13 m de ? y 1 m de altura. Cráter central sin losas de cámara. Calizas del terreno.',NULL,'Catalogación nº 69-D/1',NULL,'14 Baztan Centro-Sureste'),
(161,'SORDIKO - BIXKER',NULL,NULL,NULL,NULL,'Itinerario nº 28-J',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'sábado, mayo 27, 1905','F. Ondarra','Una piedra solitaria se alza verticalmente en el paraje. Sus dimensiones son: 1,22 m de altura; 1 m de largura y 0,25 m de grueso. A su lado asoma otra de 0,08 m de altura; 0,6 m de largo y 0,1 m de grueso. Ambas forman un ángulo muy agudo.',NULL,'Catalogación nº 69-D/5',NULL,'14 Baztan Centro-Sureste'),
(162,'EZKITZ',1,'Dolmen?',NULL,'Hoja cartográfica Nº: 65-16/B y D','Itinerario nº 28-A y J',NULL,619615,4782500,826,43.183937,-1.529408,'utm',NULL,'domingo, mayo 28, 1905','F. Ondarra y T. López Sellés','Hay una losa bastante inclinada hacia dentro del monumento de 0,6 m de altura; 1,2 / 1,35 m de largura y 0,18 m de grosor. Podría ser que esté partida en dos que se superponene paralelamente. Puede haber un túmulo de unos 4 m de ? y 0,2 m de altura, formado por tierra y pequeñas losas tumbadas, medio erguidas o inhiestas. La orientación de la losa es de 170º. Areniscas del terreno.',NULL,'Catalogación nº 69-D/6',NULL,'14 Baztan Centro-Sureste'),
(163,'LARRO',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,43.201487,-1.501433,'gpx',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'14 Baztan Centro-Sureste'),
(164,'XOLBORROKO - HARRIA',1,'Dolmen corto?',NULL,'En Lerate Hoja cartográfica Nº: 66-13/A','Itinerario nº 28-B',NULL,622270,4784200,550,43.198815,-1.496372,'utm',NULL,'domingo, mayo 28, 1905','F. Ondarra','Túmulo circular de piedras de 6 m ? y 0,5 m de altura, con cráter central de 3 m de ? y 0,5 m de profundidad. Cámara de 2 losas. Otra tercera, puede ser resto de la cubierta o tapa, que mide 2,78 m de largo; 1,90 m de anchura máxima y 0,15 m de grueso.',NULL,NULL,NULL,'14 Baztan Centro-Sureste'),
(165,'MAISTRUGAIN - I',5,'Crómlech','Baztan','Hoja cartográfica Nº: 66-13/B','Itinerario nº 34-D',NULL,626330,4784875,955,43.204223,-1.446264,'utm',NULL,NULL,NULL,'crómlech de 8 m de ? y 0,2 m de altura. Lo forman solo 5 piedras, siendo la mayor la situada al S. y que mide 0,35 m de alto; 0,85 m de largo y 0,08 m de gruso. Su forma es tumular.',NULL,'Catalogación nº 70. M/1 Fue dado a conocer por F. Ondarra el 4-11-1972. Aclara que hace 25 años anduvo por la zona Blas Taracena y que al parecer los resultados de las excavaciones realizadas en 1948 las dio a conocer Juan Maluquer de Motes y publicadas en Príncipe de Viana en 1963.',NULL,'14 Baztan Centro-Sureste'),
(166,'MAISTRUGAIN - II',5,'Crómlech','Baztan','Hoja cartográfica Nº: 66-13/B','Itinerario nº 34-D',NULL,626330,4784875,955,43.204223,-1.446264,'utm',NULL,NULL,NULL,'crómlech de 6 m de ? y 0,7 m de altura. Lo forman unas 8 piedras, plantadas de manera que su eje mayor, el de la largura, está orientado hacia el centro del círculo. Son piedras pequeñas siendo la mayor de 0,15 m de alto; 0,5 m de largo y 0,08 m de gruso. Su forma es tumular.',NULL,'Catalogación nº 70. M/2 Fue dado a conocer por F. Ondarra el 4-11-1972. Aclara que hace 25 años anduvo por la zona Blas Taracena y que al parecer los resultados de las excavaciones realizadas en 1948 las dio a conocer Juan Maluquer de Motes y publicadas en Príncipe de Viana en 1963.',NULL,'14 Baztan Centro-Sureste'),
(167,'MAISTRUGAIN - III',5,'Crómlech','Baztan','Se encuentra a 1,5m al E. del Maistrugain II. Hoja cartográfica Nº: 66-13/B','Itinerario nº 34-D',NULL,626330,4784875,955,43.204223,-1.446264,'utm',NULL,NULL,NULL,'crómlech de túmulo circular de 5 m de ? y 0,2 m de altura. Lo forman unas 8 piedras, siendo la mayor de 0,4 m de alto; 0,6 m de largo y 0,1 m de gruso.',NULL,'Catalogación nº 70. M/III Fue dado a conocer por F. Ondarra el 4-11-1972. Aclara que hace 25 años anduvo por la zona Blas Taracena y que al parecer los resultados de las excavaciones realizadas en 1948 las dio a conocer Juan Maluquer de Motes y publicadas en Príncipe de Viana en 1963.',NULL,'14 Baztan Centro-Sureste'),
(168,'MAISTRUGAIN - IV',5,'Crómlech','Baztan','Se encuentra a 28m al NNE. del Maistrugain II. Hoja cartográfica Nº: 66-13/B','Itinerario nº 34-D',NULL,626330,4784875,955,43.204223,-1.446264,'utm',NULL,NULL,NULL,'crómlech de túmulo circular de 9 m de ? y 0,4 m de altura. Lo forman 20 piedras, siendo las alta de 0,5 m de alto; 0,5 m de largo y 0,1 m de gruso. Destacan 4 de ellas.',NULL,'Catalogación nº 70. M/IV Fue dado a conocer por F. Ondarra el 4-11-1972. Aclara que hace 25 años anduvo por la zona Blas Taracena y que al parecer los resultados de las excavaciones realizadas en 1948 las dio a conocer Juan Maluquer de Motes y publicadas en Príncipe de Viana en 1963.',NULL,'14 Baztan Centro-Sureste'),
(169,'MAISTRUGAIN - V',5,'Crómlech','Baztan','Se encuentra a 1,5m al NW. del Maistrugain IV. Hoja cartográfica Nº: 66-13/B','Itinerario nº 34-D',NULL,626330,4784875,955,43.204223,-1.446264,'utm',NULL,NULL,NULL,'crómlech de túmulo circular de 9 m de ? y 0,4 m de altura. Lo forman 20 piedras, siendo las alta de 0,5 m de alto; 0,5 m de largo y 0,1 m de gruso. Destacan 4 de ellas.',NULL,'Catalogación nº 70. M/V Fue dado a conocer por F. Ondarra el 4-11-1972. Aclara que hace 25 años anduvo por la zona Blas Taracena y que al parecer los resultados de las excavaciones realizadas en 1948 las dio a conocer Juan Maluquer de Motes y publicadas en Príncipe de Viana en 1963.',NULL,'14 Baztan Centro-Sureste'),
(170,'MAISTRUGAIN - VI',5,'Crómlech','Baztan','Hoja cartográfica Nº: 66-13/B','Itinerario nº 34-D',NULL,626330,4784875,955,43.204223,-1.446264,'utm',NULL,NULL,NULL,'crómlech de túmulo circular de 6,5 m de ? y 0,2 m de altura. Lo forman 14 piedras muy inclinadas casi todas hacia el interior. La mayor mide 0,8 m de alto; 0,9 m de largo y 0,1 m de gruso. Destacan 2 de ellas.',NULL,'Catalogación nº 70. M/V Fue dado a conocer por F. Ondarra el 4-11-1972. Aclara que hace 25 años anduvo por la zona Blas Taracena y que al parecer los resultados de las excavaciones realizadas en 1948 las dio a conocer Juan Maluquer de Motes y publicadas en Príncipe de Viana en 1963.',NULL,'14 Baztan Centro-Sureste'),
(171,'BOZATE',2,'Túmulo?',NULL,'Hoja cartográfica Nº: 66-13/B','Itinerario Bozate a Arizkun',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'miércoles, mayo 31, 1905','Francisco Ondarra','Túmulo dudoso 14 m ? y 1 m de altura, abriéndose un brecha por el lado W (290º). De entre la tierra y el helecho asoman unas piedras de arenisca, ofita y conglomerado. El hoyo central mide 5 m ? y 0,8 m de profundo.',NULL,'Localización: 2º 12´ 43´´ y 43º 11´ 14´´',NULL,'14 Baztan Centro-Sureste'),
(172,'URRIKI - MENDEBAL',1,'Dolmen','Baztan','Hoja cartográfica Nº: 90-4','Itinerario nº 28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'miércoles, noviembre 30, 2439','Francisco Ondarra','Túmulo de unos 9 m ? y 0,5 m de altura por el N, disperso e indefinido por el S. Dos losas que en parte se doblan, aparecen "in situ" plantadas por el lado N.',NULL,'Catalogación nº 69-A/I',NULL,'14 Baztan Centro-Sureste'),
(173,'URRIKI - SORTALDE',1,'Dolmen','Baztan','A 25 m del Urriki-Mendebalde por el WSW. Hoja cartográfica Nº: 90-4','Itinerario nº 28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'miércoles, noviembre 30, 2439','Francisco Ondarra','Túmulo de unos 7 m ? y 0,5 m de altura, formado por tierra y abundantes piedras. 4 losas forman la cámara, más 2 fragmentos que pueden ser restos de la cubierta. Areniscas.',NULL,'Catalogación nº 69-A/I En la actualidad está totalmente removido',NULL,'14 Baztan Centro-Sureste'),
(174,'XALDARRI-SUR',1,'Dolmen','Baztan','Hoja cartográfica Nº: 90-4/A','Itinerario nº 28',NULL,615850,4779000,505,43.153016,-1.576455,'utm',NULL,'miércoles, noviembre 30, 2439','Francisco Ondarra','Actualmente se reduce a un túmulo de 9 m de ? y 1 m de altura, formado por piedras mezcladas de algo de tierra. No se aprecian losas camerales. Una depresión a manera de canal lo atraviesa de parte a parte en dirección de 105º, detalle que se repite en Xaldarri-norte. Areniscas.',NULL,'En la actualidad solamente quedan algunos rastros. Catalogación nº 69-A/III',NULL,'14 Baztan Centro-Sureste'),
(175,'XALDARRI-NORTE',1,'Dolmen','Baztan','Hoja cartográfica Nº: 90-4/A','Itinerario nº 28',NULL,615840,4778995,506,43.152973,-1.576579,'utm',NULL,'miércoles, noviembre 30, 2439','Francisco Ondarra','túmulo de 9 m de ? y 1,2 m de altura por el lado S y mucho más bajo por el lado N. Una losa "in situ" y un trozo de losa tumbado en el centro del galgar. Una depresión que recuerda a la del Xaldarri-sur lo atraviesa de parte a parte en dirección a 115º, que es también la dirección de la losa "in situ" y probablemente la del monumento. Areniscas.','No se conoce','En la actualidad solamente quedan algunos rastros, pero en su aspecto general es dudosa la catalogación como monumento prehistórico. Catalogación nº 69-A/IV',NULL,'14 Baztan Centro-Sureste'),
(176,'SARDIKO - BIXKER',13,'Monolito','Baztan','Hoja cartográfica Nº: 90-4',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'14 Baztan Centro-Sureste'),
