(185,'ERRAZU - SOALAR-I',2,'Túmulo',NULL,'Hoja cartográfica Nº: 91-1/B','Itinerario nº 28-E',NULL,624960,4779330,675,43.154538,-1.464374,'utm',NULL,'domingo, mayo 07, 1905','J. Elosegui','Túmulo de 12 m de ? y 1 m de altura, de piedras. Cráter central sin losas de cámara. Areniscas y pizarras del terreno',NULL,'Catalogación nº 70-10',NULL,'14 Baztan Centro-Sureste'),
(186,'ERRAZU - SOALAR-II',2,'Túmulo',NULL,'Hoja cartográfica Nº: 91-1/B','Itinerario nº 28-E',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'domingo, mayo 07, 1905','J. Elosegui','Túmulo de 12 m de ? y 0,9 m de altura, de piedras. Cráter central sin losas de cámara. Areniscas y pizarras del terreno',NULL,'Catalogación nº 70-11 Según los datos que aporta MUNIBE, está ubicado en la ladrea occidental al N de la cota dea Soalar, cercano al dolmen 71-B/III. Según Francisco Ondarra, existe un túmulo en el collado entre la cota citada y la de Burga. Túmulo e parecidas características. Tomás López Sellés también hizo la misma observación.',NULL,'14 Baztan Centro-Sureste'),
(187,'SOALAR-C',5,'Crómlech',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'14 Baztan Centro-Sureste'),
(188,'BURGA-M',13,'Monolito','Baztan','Hoja cartográfica Nº: 91-1/D','Itinerario nº 28-D',NULL,625190,4777870,800,43.141357,-1.461876,'utm',NULL,'sábado, mayo 27, 1905','Francisco Ondarra','Es una piedra de arenisca roja que mide 4,75 m de largo y 1,6 m de anchura máxima; la vegetación impide apreciar su grosor. Está partida en dos, en el sentido de la anchura Orientación a 110º',NULL,'Está tendida a 50/100 m al S del túmulo de Errazu-Soalar II, prácticamente en lo más bajo del collado entre las cotas de Soalar y Burga. Este túmulo parece ser el mismo que descubrió J. Elosegui catalogado con el nº 71-11.',NULL,'14 Baztan Centro-Sureste'),
(189,'BURGA-C',5,'Crómlech',NULL,'Hoja cartográfica Nº: 91-1/D','Itinerario nº 28-D',NULL,625200,4777900,800,43.141626,-1.461746,'utm',NULL,'domingo, mayo 28, 1905','Francisco Ondarra','Túmulo circular de 3 m de ? y 0,3 m de altura, rodeado de 10 piedras a la vista, pudiendo haber más bajo la vegetación de helecho, argoma, brezo y musgo.La piedra mayor mide 0,5 m de altura; 0,6 m de anchura en la base estrechándose hasta rematar en punta y 0,15/0,2 m de grosor. Areniscas y cuarzo blanco del terreno',NULL,NULL,NULL,'14 Baztan Centro-Sureste'),
(190,'BURGA-D',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'14 Baztan Centro-Sureste'),
(191,'SORGINETXOA',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,43.138067,-1.448581,'gpx',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'14 Baztan Centro-Sureste'),
(192,'ROLAN',11,'Dolmen poligonal?',NULL,'Hoja cartográfica Nº: 91-1/D','Itinerario nº 28-D',NULL,626280,4776230,717,43.126414,-1.448850,'utm',NULL,'sábado, abril 29, 1905','R.P. Zudaire','Túmulo circular muy removido. Cámara de 6 losas, de ellas 4 en pie con recinto poligonal poco preciso y cubierta desplazada al N del túmulo. Orientación al SSW. Areniscas del terreno.','Por R.P.Zudaire, de la que se conoce como ajuar 3 lascas atípicas cuyo paradero se desconoce.',NULL,NULL,'14 Baztan Centro-Sureste'),
(193,'LAMIRILO - LARREMETS',10,'Dolmen largo cerrado',NULL,'Hoja cartográfica Nº: 91-1/D','Itinerario nº 28-D',NULL,626450,4776240,730,43.126475,-1.446759,'utm',NULL,'sábado, abril 29, 1905','R.P. Zudaire','Túmulo circular con crómlech. Cámara de 6 losas con recinto rectangular y cubierta desplazada al N. Orientación ESE - WNW. Areniscas del terreno. Muy estropeado.','Por R.P.Zudaire, de la que no se conoce ajuar.',NULL,NULL,'14 Baztan Centro-Sureste'),
(194,'GOROSPIL',13,'Monolito','Ezpelete','A pocos metros del mojón nº 76 Hoja cartográfica Nº: 66-5',NULL,NULL,626210,4792100,662,43.269278,-1.446087,'utm',NULL,'martes, mayo 02, 1905','Jose Miguel Barandiaran','Tendido sobre el terreno, de sección rectangular y 3,25 m de largo. Cara 1: 3,25 m de largo y 1,6/1,4 m de ancho. Cara 2: 3,25 m de largo y destaca sobre el terreno entre 0,1 m en el extremo NE y 0,4 m en el opuesto. Cara 3: 3,25 m de largo y destaca sobre el terreno 0,25 m. La aoreintación del eje es de 68º. Tiene diveresos grabados en una de sus caras. Areniscas rojas','No se conoce','El material no pertence a la zona; ha debido ser transportado unos cientos de metros. Bibliografía: MUNIBE nº 35, 1983.',NULL,'15 Baztan Norte'),
(195,'SOROAUNDI',1,'Dolmen','Baztan',NULL,'Zugarramurdi',NULL,616885,4789900,580,43.250978,-1.561425,'utm','1949-05-10','martes, mayo 10, 1949','Jose Miguel Barandiaran',NULL,NULL,'Bibliografía: Eus.. Jakintza-1950',NULL,'15 Baztan Norte'),
