(201,'AIRRAGARRIKO LEPOA',13,'Monolito','Zugarramurdi','Hoja cartográfica Nº: 65-8',NULL,NULL,617740,4790210,560,43.253636,-1.550829,'utm','1988-03-12','sábado, marzo 12, 1988','Luis Millan San Emeterio',NULL,NULL,NULL,NULL,NULL);
INSERT INTO `megalitos` (`id`,`nombre`,`tipologia_id`,`tipologia_texto`,`municipio`,`ubicacion`,`itinerario_texto`,`hoja_cartografica`,`utm_x`,`utm_y`,`altitud`,`lat`,`lon`,`coord_fuente`,`localizado_fecha`,`localizado_fecha_texto`,`localizado_autor`,`descripcion`,`excavacion`,`observaciones`,`caracteristicas`,`otros_aspectos`) VALUES
(202,'HAIZPARATZ',2,'Túmulo','Zugarramurdi','A 1 km al SE de Zugarramurdi Hoja cartográfica Nº: 65-8',NULL,NULL,619290,4791280,490,43.263024,-1.531508,'utm','1983-06-04','sábado, junio 04, 1983','Francisco Ondarra','Túmulo de 7,5 m de ? y 0,3 m de altura, de tierra y piedras. Tiene un hoyo central de unos 0,4 m de profundidad y 3 m de ?. No se ven losas.','No se conoce','Bibliografía: Arqueología nº 7, 1988.',NULL,NULL),
(203,'ARNOSKO LEPOA',2,'Túmulo','Baztan','En la ladera E de Mundako Kaskoa Hoja cartográfica Nº: 65-12',NULL,NULL,NULL,NULL,NULL,43.226507,-1.563625,'gpx',NULL,NULL,NULL,NULL,NULL,'Este túmulo figura en el documento de 15 páginas: NUEVOS MONUMENTOS MEGALÍTICOS DE LA ZONA DE ATXURI (NAVARRA). Luis Millan San Emeterio. Ver el documento en los anexos',NULL,NULL),
(204,'BETARTE',13,'Monolito','Maia de Baztan','A unos 200 m al NE de las Peñas de Betarte Hoja cartográfica Nº: 66-9','Atxuela',NULL,621690,4785610,720,43.211601,-1.503198,'utm','1977-12-18','domingo, diciembre 18, 1977','Francisco Ondarra','Monolito de piedra arenisca de 2,05 m de altura, mirando al E. En la base tiene una anchura de 1,5 m y 0,42 m en lo alto, con un grosor medio de 0,5 m. Orientado a 355º.','No se conoce','El costado E mira al Gorramendi; el W a Betarte; el N al Alkurruntz, hacia Artxubieta; el S mira al dolmen de Larro. Bibliografía: MUNIBE nº 35, 1983. Príncipe de Viana nº 166, 1982.',NULL,NULL),
(205,'ETSAIN',2,'Túmulo','Baztan','En la planicie añ SW del Alkurrutz Hoja cartográfica Nº: 66-9','Alkurruntz',NULL,620870,4786270,840,43.217674,-1.513145,'utm','1972-09-19','martes, septiembre 19, 1972','Francisco Ondarra','Túmulo de 6 m de ? y 0,3 m de altura. No se aprecia hoyo central, ni aparecen losas de piedra, de pizarra y tierra.','No se conoce','Lo había visto Tomás López Sellés, cediendo su publicación. Bibliografía: Príncipe de Viana nº 138/139, 1975.',NULL,NULL),
(206,'MENDIXAR',1,'Dolmen','Maia de Baztan','A 300 m al W y en línea recta de Km 67 carretera Otsondo. Hoja cartográfica Nº: 66-9','Maia',NULL,622385,4786050,515,43.215450,-1.494547,'utm','1977-12-18','domingo, diciembre 18, 1977','Francisco Ondarra','Túmulo inapreciable que podría ser de 7,5 m de diámetro y 0,3 m de altura. En un pequeño hoyo central se alzan 3 losas: - nº 1: 0,65 m alto; 0,7 m largo; 0,15 m grueso - nº 2: 0,8 m ; 1,55 m ; 0,15 - nº 3: 0,22 m ; 0,8 m ; 0,13 Las losas 2 y 3 forman un ángulo recto, estando la 1 y 2 en línea. Hay otros 4 trozos de losa dispersos, variando sus tamaños de 0,8 m a 1,3 m de largo y de 0,5 m a 0,8 m de ancho, encima del túmulo. El hoyo mide 0,8 m de ancho y unos 2 m de largo, formado una cámara rectangular. Areniscas del terreno.','No se conoce','Bibliografía: Príncipe de Viana nº 165, 1982.',NULL,NULL),
(207,'ARTXUBIETA',13,'Monolitos (2)','Maia de Baztan','En el collado de su nombre, e la ladrea del Alkurrutz. Hoja cartográfica Nº: 66-9','Maia',NULL,621510,4789930,770,43.250517,-1.504462,'utm','1973-07-07','sábado, julio 07, 1973','Francisco Ondarra','Se trata de 2 monolitos que se encuentran juntos. - IPAR: En pie sobre el terrreno. Con una altura de 1,55 m - en la cara 1: tiene una anchura en la base de 0,6 m y en el extremo superior 0,45/0,2 m. - en la cara 2: en la base mide 0,68 m - en la cara 3 y 4: en la base mide 0,35 m y 0,2 m hacia el extremo. La orientación del eje es de 155º. Areniscas del terreno. - HEGO: En pie, con una altura de 1,65 m, estando muy basculado al N. - las caras 1 y 2 miden en su base 0,5 m y 0,3 m a 20 cm del extremo superior. - la cara 3 tiene 0,3 m en la base. A partir de los 0,8 m se estrecha. En la parte superior mide 0,2 m. - la cara 4 mide 1,3 m de alto y ancho igual.','No se conoce','El monolito Ipar tiene grabado en la cara 3 una M de 0,12 m y en la cara 4 una B. El localizador, en su reseña, hace unas consideraciones respecto a la funcionalidad de los monolitos, descartando que sean mojones, aunque hayan desempeñado tal oficio. Bibliografía: Príncipe de Viana nº 183/184, 1975. MUNIBE nº 35, 1983.',NULL,NULL),
(208,'KANTANEKO BORDA',2,'Túmulo','Arizkun','En la cota 541, bajando del collado Itzulegi. Hoja cartográfica Nº: 66-9','Arizkun',NULL,626350,4786890,588,43.222358,-1.445557,'utm','1979-01-20','sábado, enero 20, 1979','Francisco Ondarra','Túmulo de piedras areniscas y tierra de 7 m de diámetro y 1,5 m de altura ( por los 45º ) y 0,5 m ( a 225º ) en plano inclinado.','No se conoce','Bibliografía: MUNIBE nº 165, 1982.',NULL,NULL),
(209,'BERROZELAI IPAR',1,'Dolmen','Maia','A la izquierda de la carretera que desciende de Otsondo. Hoja cartográfica Nº: 66-9','Maia',NULL,632380,4786720,365,43.219794,-1.371378,'utm',NULL,'lunes, abril 03, 1905','Jose Miguel Barandiaran','Túmulo de 13 m de ? y 1,5 m de altura. Cámara de 1 losa que es continuada por una pared artificial, formando una especie de refugio para animales. Orientación ESE. Areniscas del terreno.','No se conoce','Este dolmen fue publicado con el topónimo de Otsondo N. en MUNIBE, 1973 nº 69-5. En el alto de la estribación de Urlegi y a 400 m en dirección NEE se señala en la hoja restos de otro dolmen. He aquí los datos greográficos: Y 4786980; X 623660; Z 420.',NULL,NULL),
(210,'BERROZELAI HEGO',7,'Dolmen corto abierto','Maia','A unos 100 m al SSE del Ipar Hoja cartográfica Nº: 66-9','Maia',NULL,623355,4786600,370,43.220243,-1.482486,'utm',NULL,'jueves, marzo 23, 1905','José Miguel Barandiaran','Túmulo de 11,5 m de ? y 1,5 m de altura. Tiene cráter central. La altura actual es de 0,9 m. Cámara de 2 losas, en pie, haciendo escuadra. Hoy queda 1 losa en el cráter. Orientación al ESE. Areniscas del terreno.','No se conoce','Fue publicado con el topónimo de Otsondo Sur en MUNIBE, 1973 nº 69-6.',NULL,NULL),
(211,'BERROZELAI',2,'Túmulo','Maia','50 m más abajo, en línea recta del dolmen Berrozelai Hego. Hoja cartográfica Nº: 66-9','Maia de Baztan',NULL,624380,4786540,370,43.219534,-1.469884,'utm','1978-01-02','lunes, enero 02, 1978','Francisco Ondarra','Túmulo de 10,5 m de ? y 2 m de altura por el lado que da a la pista; al NW sólo tiene 0,5 m en rampa. De tierra, piedra arenisca y cuarzo blanco.','No se conoce','100 m al SE hay otro túmulo, señalado en la hoja: Y 4786480, X 623460, Z 370. 500 m al SW hay otro túmulo señalado también en la hoja: Y 4786190, X 623015, Z 347. Bibliografía: Príncipe de Viana nº 165, 1982',NULL,NULL),
(212,'LURUKO - ATEKAK',5,'Crómlech','Maia - Arizkun','Hacia el km 3 de Otsondo a Gorramendi Hoja cartográfica Nº: 66-9','Gorrameni',NULL,624700,4788340,670,43.235684,-1.465538,'utm',NULL,'viernes, mayo 26, 1905','Francisco Ondarra','Desaparecido en la actualidad',NULL,'Consta su existencia desde 1710 en documento que dice: "Junto a un círculo de piedra, en distancia de un tiro de arcabuz", refiriendose al mojón nº 16. Bibliografía: Príncipe de Viana nº 138/139, 1975',NULL,NULL),
(213,'LARRAKA GAINA',5,'Crómlech','Maia','Hoja cartográfica Nº: 66-9',NULL,NULL,624580,4788570,680,43.237775,-1.466964,'utm','1973-10-12','viernes, octubre 12, 1973','Francisco Ondarra','crómlech tumular de 4 m de ? y 0,3 m de altura, de tierra y algunas piedras visibles. 15 testigos de piedras pequeñas de cuarzo blanco. La nº 1 mide 0,5 m de largo y la nº 2 mide 0,4 m de grueso. En el centro del túmulo se aprecia una ligera depresión.','No se conoce','Bibliografía: Príncipe de Viana nº 138/139, 1975',NULL,NULL),
(214,'ANSESTEGIKO LEPOA',2,'Túmulo','Maia - Arizkun','200 m al NE del crómlech Meatzetako Kaskoa Hoja cartográfica Nº: 66-9','Gorospil',NULL,624810,4789110,720,43.242597,-1.464010,'utm','1975-12-13','sábado, diciembre 13, 1975','Tomás López Sellés','Túmulo de 6 m de ? y 0,6 m de altura de tierra y piedras sueltas. Tiene cráter central de 0,5 m de profundidad.',NULL,'La publicación es de Francisco Ondarra, que acompañó a Tomás López Sellés ese día. Según noticias recibidas de Francisco Ondarra, con fecha 13-8-1979 el túmulo había desaparecido por completo. Bibliografía: Príncipe de Viana nº 144/145, 1976',NULL,NULL),
(215,'GORRAMENDI HEGO',5,'Crómlech','Errazu','A unos 200 m de la carretera de Gorramendi Hoja cartográfica Nº: 66-9','Gorramendi',NULL,626800,4785130,950,43.206440,-1.440422,'utm','1972-11-04','sábado, noviembre 04, 1972','Francico Ondarra','5,5 m de diámetro y 12 testigos de piedra arenisca. Destacando: - nº 2: 0,6 m de alto por 0,4 m de largo - nº 5: 0,5 " 0,7 " - nº 8: 0,5 " 0,5 " - nº 10: 0,4 " 0,9 "','No se conoce','Bibliografía: Príncipe de Viana nº 138/139, 1975',NULL,NULL),
(216,'GORRAMAKIL MENDABAL',1,'Dolmen','Errazu','En el collado de su nombre (donde estuvo el radar americano) Hoja cartográfica Nº: 66-10','Gorramendi',NULL,627560,4786800,1070,43.221344,-1.430684,'utm','1972-11-11','sábado, noviembre 11, 1972','Francisco Ondarra','Túmulo de 5,5 m de ? y 0,5 m de altura. En el centro , una losa orientada a 100º, de 1 m de largo y 0,07 m de grueso, casi enterrada. También hay una depresión central de 1 m de lado. Evidencia haber sido profanado.','No se conoce','En el lugar se instaló la Base Americana. Bibliografía: Príncipe de Viana nº 138/139, 1975',NULL,NULL),
(217,'GORRAMAKIL SORTALDE',5,'Crómlech','Errazu','A unos 450 m del dolmen de Gorramakil Hoja cartográfica Nº: 66-10','Gorramendi',NULL,627735,4787000,1050,43.223115,-1.428484,'utm',NULL,'domingo, junio 04, 1905','Luis Millan','crómlech circular de 5,5 m de ? y 0,3 m de altura con 12 testigos de pequeñas dimensiones tapados por la vegetación. Hoyo cental con algunas piedras en el mismo. Areniscas del terreno.','No se conoce','Bibliografía: Arqueología nº 7, 1988',NULL,NULL),
(218,'AMABIJINEI - ARPEA nº 1',1,'Dólmenes (6) nº 1','Errazu','En la cota 857, entre las cotas 961 y 970. Hoja cartográfica Nº: 66-10','Gorramendi',NULL,628770,4788080,885,43.232661,-1.415492,'utm','1972-11-11','sábado, noviembre 11, 1972','Francisco Ondarra','Nº 1 Túmulo de 4 m de ? y 0,4 m de altura; menos elevado por el SE; de tierra y piedras. Dos trozos de losa aparecen tumbados al W. Hoyo de 1 m de largo, 0,5 m de ancho y 0,1 m de profundo.','No consta oficialmente','Francisco Ondarra los dio a conocer como dólmenes, aunque parece tratarse de cistas. Según el localizador, hace 25 años anduvo por esos lugares Blas Taracena y, al parecer, estuvo escavando. Según se dice, habrían aparecido cajas de piedras que contenían cenizas y huesos calcinados. Una losa encima de la caja, tierra encia de esa losa y otra segunda losa encima de la tierra. Bibliografía: Príncipe de Viana nº 138/139, 1975',NULL,NULL),
(219,'AMABIJINEI - ARPEA nº 2',1,'Dólmenes (6) nº 2','Errazu','En la cota 857, entre las cotas 961 y 970. Hoja cartográfica Nº: 66-10','Gorramendi',NULL,628770,4788080,885,43.232661,-1.415492,'utm','1972-11-11','sábado, noviembre 11, 1972','Francisco Ondarra','Nº 2 Al E del nº 1 y tangente con él. Túmulo de 4,5 m de ? y 0,4 m de altura; menos elevado por el SE; de tierra y piedras. En el centro, 3 losas clavadas forman una cámara trapezoidal de 0,9 m de largo y 0,8/0,5 m de ancho, que se estrecha al NW, orientado a 160º. - La losa W mide 0,3 m de alto, 1 m de largo y 0,07 m de grueso - La losa S mide 0,17 m de alto, 0,8 m de largo y 0,07 m de grueso - La losa E mide 0,3 m de alto, 1 m de largo y 0,07 m de grueso Tumbado al SE hay un trozo de losa de 1 m de largo, 1 m de ancho y 0,07 m de grueso','No consta oficialmente','Francisco Ondarra los dio a conocer como dólmenes, aunque parece tratarse de cistas. Según el localizador, hace 25 años anduvo por esos lugares Blas Taracena y, al parecer, estuvo escavando. Según se dice, habrían aparecido cajas de piedras que contenían cenizas y huesos calcinados. Una losa encima de la caja, tierra encia de esa losa y otra segunda losa encima de la tierra. Bibliografía: Príncipe de Viana nº 138/139, 1975',NULL,NULL),
(220,'AMABIJINEI - ARPEA nº 3',1,'Dólmenes (6) nº 3','Errazu','En la cota 857, entre las cotas 961 y 970. Hoja cartográfica Nº: 66-10','Gorramendi',NULL,628770,4788080,885,43.232661,-1.415492,'utm','1972-11-11','sábado, noviembre 11, 1972','Francisco Ondarra','Nº 3 Situado a 2 m al N del nº 2. Túmulo de 4 m de ? y 0,4 m de altura; menos elevado por el SE; de tierra y algunas piedras. En el centro, 2 losas paralelas. Recinto cameral de 1 m de largo y 0,5 m de ancho, orientado a 160º. - La losa W mide 1 m de largo y 0,07 m de grueso - La losa E mide 1 m de largo y 0,07 m de grueso Hay un trozo de losa tumbado al W.','No consta oficialmente','Francisco Ondarra los dio a conocer como dólmenes, aunque parece tratarse de cistas. Según el localizador, hace 25 años anduvo por esos lugares Blas Taracena y, al parecer, estuvo escavando. Según se dice, habrían aparecido cajas de piedras que contenían cenizas y huesos calcinados. Una losa encima de la caja, tierra encia de esa losa y otra segunda losa encima de la tierra. Bibliografía: Príncipe de Viana nº 138/139, 1975',NULL,NULL),
(221,'AMABIJINEI - ARPEA nº 4',1,'Dólmenes (6) nº 4','Errazu','En la cota 857, entre las cotas 961 y 970. Hoja cartográfica Nº: 66-10','Gorramendi',NULL,628770,4788080,885,43.232661,-1.415492,'utm','1972-11-11','sábado, noviembre 11, 1972','Francisco Ondarra','Nº 4 Situado a 2,2 m del nº 3. Túmulo de 6 m de ? y 0,6 m de altura; menos elevado por el SE. No tiene losas hincadas, solo algunos fragmentos dentro y fuera del túmulo. En el centro un concavidad de 4 m de diámetro y 0,9 m de profundidad-','No consta oficialmente','Francisco Ondarra los dio a conocer como dólmenes, aunque parece tratarse de cistas. Según el localizador, hace 25 años anduvo por esos lugares Blas Taracena y, al parecer, estuvo escavando. Según se dice, habrían aparecido cajas de piedras que contenían cenizas y huesos calcinados. Una losa encima de la caja, tierra encia de esa losa y otra segunda losa encima de la tierra. Bibliografía: Príncipe de Viana nº 138/139, 1975',NULL,NULL),
(222,'AMABIJINEI - ARPEA nº 5',1,'Dólmenes (6) nº 5','Errazu','En la cota 857, entre las cotas 961 y 970. Hoja cartográfica Nº: 66-10','Gorramendi',NULL,628770,4788080,885,43.232661,-1.415492,'utm','1972-11-11','sábado, noviembre 11, 1972','Francisco Ondarra','Nº 5 Situado a 2 m del nº 3 y a 3,3 m del nº 4. Túmulo de 4 m de ? y 0,4 m de altura;de tierra y algunas piedras, menos elevado por el SE. La superficie del túmulo es cóncava y no se ven losas ni frgamentos de las mismas.','No consta oficialmente','Francisco Ondarra los dio a conocer como dólmenes, aunque parece tratarse de cistas. Según el localizador, hace 25 años anduvo por esos lugares Blas Taracena y, al parecer, estuvo escavando. Según se dice, habrían aparecido cajas de piedras que contenían cenizas y huesos calcinados. Una losa encima de la caja, tierra encia de esa losa y otra segunda losa encima de la tierra. Bibliografía: Príncipe de Viana nº 138/139, 1975',NULL,NULL),
(223,'AMABIJINEI - ARPEA nº 6',1,'Dólmenes (6) nº 6','Errazu','En la cota 857, entre las cotas 961 y 970. Hoja cartográfica Nº: 66-10','Gorramendi',NULL,628770,4788080,885,43.232661,-1.415492,'utm','1972-11-11','sábado, noviembre 11, 1972','Francisco Ondarra','Nº 6 Situado a 3,5 m del nº 5. Túmulo de 4 m de ? y 0,4 m de altura; de tierra y algunas piedras. En el centro, dos losas clavadas: - La losa S mide 1,3 m de largo y 0,1 m de grueso - La losa E mide 0,6 m de largo; 0,2 m de alto y 0,1 m de grueso. Hay un trozo de losa tumbado al NW. Existe depresión central de 1 m de largo y 0,5 m de anchura.','No consta oficialmente','Francisco Ondarra los dio a conocer como dólmenes, aunque parece tratarse de cistas. Según el localizador, hace 25 años anduvo por esos lugares Blas Taracena y, al parecer, estuvo escavando. Según se dice, habrían aparecido cajas de piedras que contenían cenizas y huesos calcinados. Una losa encima de la caja, tierra encia de esa losa y otra segunda losa encima de la tierra. Bibliografía: Príncipe de Viana nº 138/139, 1975',NULL,NULL),
(224,'BURDIKO LEPOA',5,'Crómlech',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(225,'BARDAXILO',1,'Dolmen','Errazu','200 m al SE de la cumbre Akomendi (961m) Hoja cartográfica Nº: 66-10','Errazu',NULL,628200,4788080,925,43.232758,-1.422509,'utm','1972-11-11','sábado, noviembre 11, 1972','Frnacisco Ondarra','Túmulo de 7 m de ? y escasa altura. Cámara de 1,3 m de alto; 2,7 m de largo y 1,5 m de ancho, rodeada de 6 losas: - Losa nº 1: 1,3 m de alto; 0,4/07 m de largo y 0,05 m de grueso - Losa nº 2: 1,3 m de alto; 0,8 m de largo y 0,08 m de grueso - Losa nº 3: 1,3 m de alto; 0,9 m de largo y 0,04 m de grueso - Losa nº 4: 1,3 m de alto; 0,8 m de largo y 0,04 m de grueso - Losa nº 5: 1,2 m de alto; 0,6 m de largo y 0,04 m de grueso - Losa nº 6: 1,2 m de alto; 1,4 m de largo y 0,05 m de grueso Otras 3 losas impantadas por el SE constituyen la entrada. Varios trozos mas de losas tendidos por el túmulo, probables restos de la tapa; tal es el caso de la: - Losa nº 7: 2,7 m de largo; 1,2 m de ancho y 0,05 m de grueso - Losa nº 8: 1,5 m de largo; 1 m de ancho y 0,07 m de grueso. Las losas nº 9, nº 10 y nº 11 están plantadas en la periferia e inclinadas hacia el exterior. Posiblemente tuviera un crómlech alrededor. Hay gran número de losas de menor tamaño que constituyen el túmulo.','Bibliografía: Príncipe de Viana nº 138/139, 1975','Bibliografía: Príncipe de Viana nº 138/139, 1975. Probablemente la losa nº 1 sea parte de una puerta perforada, al estilo de Artajpja y El Longar, según apunta Jesús Sesma.',NULL,NULL),
(226,'IPARLA',5,'Crómlech (3)','Comuna de Bidarray','2 km al N de Iparla Hoja cartográfica Nº: 66-10','Iparla',NULL,632620,4789400,720,43.243875,-1.367780,'utm','1973-03-17','sábado, marzo 17, 1973','Francisco Ondarra','crómlech 1: Círculo de 5 m de ? y 0,4 m de altura. 11 testigos de piedra arenisca sobre un ligero túmulo cubierto de hierba y helechos. Las piedras mayores miden: - Nº 2: 0,6 m de alto; 0,5 m de largo y 0,1 m de grueso - Nº 3: 0,3 m de alto; 0,9 m de largo y 0,1 m de grueso crómlech 2: Situado a unos 4 m al W del anterior. Túmulo de 8,5 m de ? y 0,4 m de altura. 7 testigos de piedra arenisca, algunos inclinados hacia el interior y el nº 4 tendido en el suelo. Medidas: - Nº 4: 0,6 m de alto; 0,3 m de largo y 0,1 m de grueso - Nº 5: 0,2 m de alto; 0,7 m de largo y 0,05 m de grueso - Nº 6: 0,5 m de alto; 0,3 m de largo y 0,07 m de grueso - Nº 7: 0,6 m de alto; 0,3 m de largo y 0,15 m de grueso crómlech 3: Situado a 10 m al W del anterior. Círculo casi tumular de 3 m de ?. 6 testigos de piedra arenisca; el mayor mide: 0,2 m de alto; 0,5 m de largo y 0,07 m de grueso.','No se conoce','Francisco Ondarra admite que estos crómlech hayab sido publicados con anterioridad por J. Blot. Bibliografía: Príncipe de Viana nº 138/139, 1975.',NULL,NULL),
(227,'IPARALA - I',13,'Monolito','Bidarray (Benabarra)','A 200 m de los crómlech de Iparla Hoja cartográfica Nº: 66-10','Iparla',NULL,632620,4789400,720,43.243875,-1.367780,'utm',NULL,'domingo, mayo 28, 1905','J. Altuna','Monolito en pie con una altura 2,25 m en forma de laja y ligeramente basculado. Cara 1: la anchura en la base es de 1,45 m. A un metro disminuye las 1,1 m hasta su extremo. Cara 2: en la zona media alcanza los 0,2 m debido a la inclinación del terreno Cara 3: oscila entre 0,15/0,2 m de anchura Cara 4: tiene 0,2 m de ancho. Formando ángulo recto con el monolito y en su base, se levanta hasta una altura de 0,7 m un gran bloque de piedra que en uno de sus lados forma escuadra con él. La orientación del eje mayor es de 126º. Areniscas rojas.','No se conoce','Bibliografía: Príncipe de Viana nº 138/139, 1975. MUNIBE nº 35, 1983.',NULL,NULL),
(228,'IPARALA - II',13,'Monolito','Bidarray (Benabarra)','Al S de la cueva de Iparla Hoja cartográfica Nº: 66-10','Iparla',NULL,631680,4787530,1029,43.227208,-1.379800,'utm',NULL,'sábado, mayo 27, 1905','J. Blot','Monolito tendido sobre el terreno de unos 3,5 m de longitud. La cara 1 o superior tiene una anchura que oscila entre 1,2 m al NE y 0,6 m en el extremo opuesto. La cara 2 destaca sobre el terreno entre 0,6 y 0,4 m. La cara 3 es similar a la 2. La aorientación del eje es de 12º. Areniscas roja.','J. Blot y Ch Saave realizaron la limpieza del contorno y una zanja. No encontraron material alguno.','Bibliografía: J. Blot, KOBIE, 1980. MUNIBE nº 35, 1983.',NULL,NULL),
(229,'MEHATSEKO BIZKARRA',13,'Monolito','Bidarray','A pocos metros del collado Mehatse. Hoja cartográfica Nº: 66-6','Artzamendi',NULL,629210,4792500,707,43.272371,-1.409040,'utm','1943-04-29','jueves, abril 29, 1943','JM Barandiaran','Tendido en el suelo. Longitud: 4,2 m. - Cara 1: 1,45 m de anchura en el extremo SW y 0,3 m en el opuesto - Cara 2: Destaca sobre el terreno entre 0,45 m y 0,35 m - Cara 3: Destaca a todo lo largo 0,35 m. La orientación del eje es de 33º Material: arenisca roja.',NULL,'Bibliografía: MUNIBE nº 35, 1983.',NULL,NULL),
(230,'MAILARRETA HEGO',5,'Crómlech','Arizkun','En el collado de su nombre en dirección Gorospil Hoja cartográfica Nº: 66-5','Gorospil',NULL,625000,4790400,687,43.254178,-1.461378,'utm','1949-06-27','lunes, junio 27, 1949','JM. Barandiaran','crómlech de 3 m de diámetro con 20 testigos de piedras pequeñas y muy bajas de cuarzo blando, meno una que es de arenisca y otra de pizarra.','No se conoce','La descripción es de Francisco Ondarra, que dio estos datos con fecha 1-6-1974, no teniendo seguridad de si se trataba del mismo crómlech aludido por JM. Barandiaran y de su carácter prehistórico. Bibliografía: Príncipe de Viana nº 138/139.',NULL,NULL),
(231,'MAIRULARRIETA IPAR (MAILARRETA )',5,'Crómlech (3)','Arizkun','En la cima de la cota, a 150 m del Hego Hoja cartográfica Nº: 66-5','Gorospil',NULL,625100,4790475,699,43.254836,-1.460129,'utm',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(232,'ZOTALETAKO KASKOA HEGO',5,'Crómlech','Arizkun','Entre la cota 752 m, por el S y a 706 m al N. Hoja cartográfica Nº: 66-5','Gorospil',NULL,625970,4791500,740,43.263918,-1.449181,'utm','1973-03-10','sábado, marzo 10, 1973','Francisco Ondarra','Círculo de 4,8 m de diámetro. Consta de más de 20 testigos de piedra arenisca, cuarzo blanco y pizarra; el mayor es de 0,5 m de largo.','No se conoce','Bibliografía: Príncipe de Viana nº 138/139',NULL,NULL),
(233,'IGUZKI MENDEBAL',1,'Dolmen','Arizkun','100 m al NE del mojón internacional nº 78. Hoja cartográfica Nº: 66-6','Artzamendi',NULL,627350,4791870,568,43.267016,-1.432098,'utm','1970-11-09','lunes, noviembre 09, 1970','J. Blot','Túmulo de 7 m de diámetro y 0,5 m de altura. Tiene hoyo central de 2,3 m de ancho y 0,5 m de profundidad. Una sol losa de arenisca. Orientación a 95º. Las piedras del túmulo son de pizarra.','No se conoce','Bibliografía: Príncipe de Viana nº 138/139, 1975',NULL,NULL),
(234,'URLEGI',2,'Túmulo','Maia de Arizkun','Ladera N de la cumbre de Urlegi (717 m) Hoja cartográfica Nº: 66-9','Gorospil',NULL,624760,4787840,660,43.231174,-1.464913,'utm','1972-10-29','domingo, octubre 29, 1972','Francisco Ondarra','Túmulo de 6 m de diámetro y 0,3 m de altura, muy rebajado por el NW. Hoyo central cubierto de juncos. Túmulo de tierra y algunas piedras de arenisca.','No se conoce','A unos 10 m al NNW afloran varias piedras. Podría tratarse algún crómlech. Bibliografía: Príncipe de Viana nº 138/139, 1975',NULL,NULL),
(235,'URLEGI',5,'Crómlech','Maia de Arizkun','A unos 150 m al N del túmulo de Urlegi Hoja cartográfica Nº: 66-9','Gorospil',NULL,624820,4787980,650,43.232424,-1.464142,'utm','1957-11-17','domingo, noviembre 17, 1957','Tomás López Sellés','Son 3 crómlech tumulares: - crómlech nº 1: 12 m de diámetro y cerca de 1 m de alto - crómlech nº 2: 4 m de diámetro y 0,3 m de alto - crómlech nº 3: 3,7 m de diámetro y 0,3/0,4 m de alto. El primero perdió unos 2,5 m del círculo y las piedras que lo formaron por el lado W al construirse la carretera que desde Otsondo se dirige a Gorramendi. No es fácil determinar el número de testigos del crómlech dada la gran cantidad de vegetación existente.','No se conoce','Bibliografía: Príncipe de Viana nº 138/139, 1975. MUNIBE 1973, Contribución al catálogo…',NULL,NULL),
(236,'ORIZKI (ZENTILMENDI)',2,'Túmulo',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(237,'ALDAIKO LEPOA',2,'Túmulo','Baztan','100 m al sur de la txabola visible Hoja cartográfica Nº: 90-11','Saioa',NULL,613370,4767030,990,43.045635,-1.609391,'utm','1974-05-25','sábado, mayo 25, 1974','Francisco Ondarra','Túmulo circular de 4 m. de diámetro y 0,3/0,4 m. de altura. Entre la tierra, la hierba y los brezos asoman algunas piedras. Existe una pequeña depresión al E. del túmulo. Areniscas.','Agosto - 1983, por Pedro Arrese.','La excavación dio como resultado un poco de ceniza. Se comprobó que el túmulo está formado por piedras. Bibliografía: Píncipe de Viana 140/141, pág. 420',NULL,'13 Baztan Sur'),
(238,'GARTZAGA',1,'Dolmen (y Crómlech)','Baztan','En el camino a Saioa, en el collado de su nombre. Hoja cartográfica Nº: 90-11','Saioa',NULL,614500,4767620,1130,43.050777,-1.595400,'utm','1966-09-25','domingo, septiembre 25, 1966','Tomás López Sellés','Túmulo de 7/8 m. de ?, rebajado y desfigurado. En el cráter central queda una losa tumbada de 1,09 m. de largo por 0,75 m. de ancho y 0,1 m. de grueso. Al SE. Se pueden ver dos fragmentos de losa. Uno mide 0,93 m. de largo por 0,69 m. de ancho y 0,1 m. de grueso. El otro mide 1,15 m. de largo por 0,54 m. de ancho y 0,13 m. de grueso. Un crómlech de 13/14 m. de diámetro rodea el domen. Resalta más por el lado E., en donde alcanza una altura de 0,4 m.','No se conoce','Dice Francisco Ondarra que existe un papel de 1892 en el Archivo de Baztan (Elizondo) que habla de la "Peña de Garzaga" y el collado de su nombre, donde se juega a la pelota. Más adelante vuelve sobre lo mismo diciendo que hacia el mojón de la facería de Lanz y Baztan hay una piedra natural con raya, junto al pocillo próximo al juego de pelota. Actualmente hay un hoyo en el que abundan los juncos al S. de Gartzaga. En él se asienta una piedra de 2,2 m. de largo por 1,1 m. de ancho y 0,1/0,25 m. de grueso. Tiene una raya de 0,9 m. de largo señalando a los 155º. Bibliografía: Munibe 1973. Contribución…',NULL,'13 Baztan Sur'),
(239,'GARTZAGA IPAR',5,'Crómlech','Baztan','A 100 m. del dolmen de Gartzaga. Hoja cartográfica Nº: 90-12','Saioa',NULL,614600,4767630,1130,43.050852,-1.594170,'utm','1966-09-25','domingo, septiembre 25, 1966','Tomás López Sellés','5 m. de ?, compuesto de piedras que apenas afloran sobre la superficie de terreno.','No se conoce','Bibliografía: Munibe 1973. Contribución…',NULL,'13 Baztan Sur'),
(240,'GARTZAGA HEGO',5,'Crómlech','Baztan','En las estribaciones de Okolin y ladera S. de Gartzaga Hoja cartográfica Nº: 90-12','Saioa',NULL,614200,4767670,1220,43.051272,-1.599072,'utm','1966-10-10','lunes, octubre 10, 1966','Tomás López Sellés','8 m. de ? y 15/16 testigos, el mayor de ellos mide 0,5 m. de altura.','No se conoce','Bibliografía: Munibe 1973. Contribución…',NULL,'13 Baztan Sur'),
(241,'GARTZAGA LEPOA',5,'Crómlech','Baztan','En el collado de su nombre, a 10 m. del cercano Gartzaga Hego. Hoja cartográfica Nº: 90-12','Saioa',NULL,615250,4767660,1210,43.051023,-1.586185,'utm','1974-05-25','sábado, mayo 25, 1974','Francisco Ondarra','Círculo de 5 m. de ?. 16 testigos de piedras muy bajas; tres de ellas on de 0,5 m. de largo. Siete testigos forman una segunda circunferenica de 0,6 m. de la anterior. Uno de los testigos mide 0,8 m. de largo. Las demás están inclinadas hacia afuera. Areniscas.','No se conoce','Bibliografía: Príncipe de Viana nº 140/141, pág. 416.',NULL,'13 Baztan Sur'),
(242,'ANDDEBERRI',13,'Monolito','Baztan','En la ladera N. de la cumbre de Anddeberri (Gartzaga) Hoja cartográfica Nº: 90-12','Saioa',NULL,615300,4768130,1220,43.055247,-1.585474,'utm','1983-07-17','domingo, julio 17, 1983','Francisco Ondarra','Monolito de 1,3 m. de altura; 0,45 m. de anchura media y 0,2 m. de grueso medio. Inclinado hacia los 130º. Por la uniformidad de la anchura y el grosor, da la impresión de estar trabajando. A su lado hay otra piedra tumbada y con un extremo medito bajo tierra, que mide 1,65 m. de largo por 0,6/0,52 m. de ancho (terminado en punta en el extremo enterrado) y 0,2/0,25 m. de grosor. Orientación del monolito: 25º.','No se conoce','Bibliografía: Arqueología nº 7, 1988',NULL,'13 Baztan Sur'),
(243,'AZKENEKO LEPOA I',5,'Crómlech','Baztan','A unos 9 m. y 350º del domen de Gartzaga Hoja cartográfica Nº: 90-12','Saioa',NULL,614600,4767630,1120,43.050852,-1.594170,'utm','1982-07-19','lunes, julio 19, 1982','Luis Millan','crómlech circular de 3,5 m. de ? con varios testigos semiocultos en la tierra. Destaca uno al NE. De 0,5 m. de largo, asomado apenas del suelo, y otro al SW. De 0,16 m. de alto por 0,55 m. de largo y 0,04/0,14 m. de grosor.','No se conoce','Bibliografía: Arqueología nº 7, 1988',NULL,'13 Baztan Sur'),
(244,'AZKENEKO LEPOA II',5,'Crómlech','Baztan','A 5 m. y orientación 190º del domen de Gartzaga Hoja cartográfica Nº: 90-12','Saioa',NULL,614600,4767630,1120,43.050852,-1.594170,'utm','1982-07-19','lunes, julio 19, 1982','Luis Millan','4,5 m. de ? y testigos de piedras pequeñas. Destacan tres: 1.- Al SSE. 0,09 m. alto; 0,6 m. largo; 0,1/0,18 m. grosor 2.- Al NW 0,15 m. alto; 0,4 m. largo; 0,1/0,28 m. grosor 3.- Al NNE. 0,49 m. alto; 0,5 m. largo; 0,06/0,1 m. grosor. Ésta tumbada','No se conoce','Bibliografía: Arqueología nº 7, 1988',NULL,'13 Baztan Sur'),
(245,'AZKENAZKO LEPOA',1,'Dolmen','Baztan','En collado entre cotas Azkentz (1172 m.) y Anddeberri (Gartzaga 1295 m.) Hoja cartográfica Nº: 90-12','Saioa',NULL,614600,4767630,1120,43.050852,-1.594170,'utm','1966-09-25','domingo, septiembre 25, 1966','Tomás López Sellés',NULL,'No se conoce','Luis Millan ha denunciado dos monolitos en la zona, de los que por el momento no tenemos datos.',NULL,'13 Baztan Sur'),
(246,'OKOLINGO LEPOA',2,'Túmulo','Baztan','En el collado entre Okolin y Saioa Hoja cartográfica Nº: 90-12','Saioa',NULL,616500,4766940,1240,43.044351,-1.570992,'utm','1973-07-07','sábado, julio 07, 1973','Francisco Ondarra','Túmulo de forma elíptica de 6 m. de ? en su eje mayor (NE-SW) y de 5 m. en su eme menor (NW-SE) de 0,7 m. de alto. Abundantes piedras mezcladas con tierra.','No se conoce','El 10-5-1986, Iñaki Gaztelu dio a conocer un monolito denominado Okolin. Bibliografía: Príncipe de Viana 140/141 pág. 141.',NULL,'13 Baztan Sur'),
(247,'OKOLINGO LEPOA IPAR',13,'Monolito','Baztan','En el collado entre Okolin y Saioa Hoja cartográfica Nº: 90-12','Saioa',NULL,616500,4766940,1240,43.044351,-1.570992,'utm',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(248,'OKOLINGO HEGO',13,'Monolito','Anue','400 m. al S. de Okolingo Lepoa Hoja cartográfica Nº: 90-16','Saioa',NULL,616620,4766550,1125,43.040822,-1.569601,'utm',NULL,NULL,'Luis Millan? Iñaki Gaztelu?',NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(249,'SAGARDEGI',5,'Crómlech','Anue','A unos 60 m. al S. del túmulo Hoja cartográfica Nº: 90-16','Saioa',NULL,617780,4766550,1150,43.040643,-1.555364,'utm','1982-05-16','domingo, mayo 16, 1982','Luis Millan','2,5 m. de ?. 10 testigos de piedras pequeñas. 1.- Al N.: 0,1 m. alto; 0,22 m. largo; 0,2 m. grosor 2.- Al E.: 0,6 m. largo 3.- Al ESE.: 0,5 m. largo; 0,3 m. grosor 4.- (interior): 0,05 m. alto; 0,3 m largo; 0,08 m. grosor','No se conoce','Bibliografía: Arqueología nº 7, 1988.',NULL,'13 Baztan Sur'),
(250,'IRUMUGETA',2,'TúmuloS (3)','Anue - Baztan - Lanz','A 1,5 km al S. de Gartzaga Hoja cartográfica Nº: 90-16','Saioa',NULL,614680,4766480,1160,43.040487,-1.593425,'utm',NULL,'197/3/1973','Francisco Ondarra','Túmulo 1: Es el más oriental. Tiene 6 m. de ? y 0,4 m. de altura. Formado de tierra y mucha piedra arenisca Túmulo 2: Tangente al anterior por poniente. Adopta la figura de elipse. El eje mayor está orientado N-S, y tiene 6,5 m. de ?. El eje menor E-W tiene 3,5 m. de ?. En el centro alcanza una altura de 0,4 m. Túmulo 3: 3 m. de ? y 0,3 m. de altura. Dista unos 10 m. del anterior por poniente. Túmulo 4: El 7-8-1989 F.O. da a concer el túmulo en Cuadernos de Etnología nº 56.','No se conoce','El trayecto desde Gartzaga hata Irumugeta está salpicado de ruedas de molino inconclusas y abandonadas. Bibliografía: Príncipe de Viana 140/141 pág. 417.',NULL,'13 Baztan Sur'),
(251,'IRUMUGETA LEPOA',5,'Crómlech','Baztan muga Anue - Lanz','En el collado entre Errebelu y Okolin Hoja cartográfica Nº: 90-16','Saioa',NULL,614620,4766510,1160,43.040766,-1.594155,'utm','1958-12-22','lunes, diciembre 22, 1958','Francisco Ondarra','Cuatro crómlech, tres en línea S-N y uno al E (a 15 m. el túmulo nº 3 de Irumugeta). crómlech 1: Tiene forma tumular y de 1,5 m de altura. El diámetro es de 13,5 m. y está rodeado de 18 testigos. De entre ellos destacan dos: - 1.: Mide 1,6 m. de alto; 0,9 m. ancho; 0,24 m. grosor. - 2.: Mide 1,2 m. de alto; 0,85 m. ancho; 0,15 m. grosor. crómlech 2: Tiene 9 m. de diámetro crómlech 3: Tiene 11 m. de diámetro crómlech 4: Tiene 8 m. de diámetro Escrito a lápiz: crómlech 5: Con fecha 6-8-1983 L.M.G. da a conocerlo. No hay datos crómlech 6: Con fecha 1-12-1985 L.M.G. dice verlo. No hay datos','No se conoce','Bibliografía: Munibe 1973. Contribución…',NULL,'13 Baztan Sur');
INSERT INTO `megalitos` (`id`,`nombre`,`tipologia_id`,`tipologia_texto`,`municipio`,`ubicacion`,`itinerario_texto`,`hoja_cartografica`,`utm_x`,`utm_y`,`altitud`,`lat`,`lon`,`coord_fuente`,`localizado_fecha`,`localizado_fecha_texto`,`localizado_autor`,`descripcion`,`excavacion`,`observaciones`,`caracteristicas`,`otros_aspectos`) VALUES
(252,'IRUMUGETA LEPOA',13,'Monolito','Baztan - Anue - Lanz','En el collado entre Errebelu y Okolin Hoja cartográfica Nº: 90-16','Saioa',NULL,614540,4766480,1160,43.040508,-1.595143,'utm','1982-08-06','viernes, agosto 06, 1982','Luis Millan',NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(253,'IRUMUGETA LEPOA',1,'¿Dolmen?','Baztan - Anue - Lanz','En el collado entre Errebelu y Okolin Hoja cartográfica Nº: 90-16','Saioa',NULL,614680,4766505,1160,43.040712,-1.593420,'utm','1958-12-22','lunes, diciembre 22, 1958','Tomás López Sellés','En la reseña sólo dice que hay un grupo de 6 losas, que parecen naturales. Luis Millan lo señala como posible dolmen.',NULL,NULL,NULL,'13 Baztan Sur'),
(254,'IZKOA',13,'Monolito','Baztan - Ciga','A unos 150 m. al E. de los crómlech. Hoja cartográfica Nº: 90-8','Saioa',NULL,617129,4772780,875,43.096827,-1.562043,'utm',NULL,NULL,'Luis Millan',NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(255,'URDINTZ',13,'Monolito','Baztan - Ciga','En la ladera W. de la cota Urdintz. Hoja cartográfica Nº: 90-8','Saioa',NULL,617365,4772530,890,43.094540,-1.559196,'utm','1975-06-14','sábado, junio 14, 1975','Tomás López Sellés','Piedra de arenisca roja que da la impresión de haber sido labrada. Clavado en tierra y muy inclinado, formando un ángulo de 50º con la base. Parece rota en la parte superior. Mide 2,5 m. alto por 1,15 m ancho y 0,25/0,35 m. grueso.','No se conoce','Bibliografía: Príncipe de Viana 144/145 pág 336.',NULL,'13 Baztan Sur'),
(256,'ELORREGIKO LEPOA',5,'Crómlech','Baztan - Ciga','Hoja cartográfica Nº: 90-8','Saioa',NULL,617220,4772300,910,43.092492,-1.561026,'utm','1985-12-07','sábado, diciembre 07, 1985','Luis Millan',NULL,NULL,'En el monte Elorregi situado al N. de Abartan parece haber un crómlech. Está situado a unos 200 m. de altura máxima, descendiendo ligeramente hacia el W. Visto por Tomás López Sellés el 14-7-1975. A lápiz: Posiblemente sea el Abartango Zelaia ¿situado? poco más de esa distancia al E. en vez de W.',NULL,'13 Baztan Sur'),
(257,'ABARGANGO ZELAIA',5,'Crómlech','Baztan - Ciga','Al SW de Abartan, en el collado. Hoja cartográfica Nº: 90-8','Zuraurre',NULL,616940,4771530,1020,43.085603,-1.564627,'utm','1973-05-26','sábado, mayo 26, 1973','Francisco Ondarra','crómlech tumular de 16 m. de diámetro y de 1,5 m. de altura por el norte, rodeado de 12 piedras pequeñas de caliza cristalina. Destacan las señaladas con el nº7 de 0,7 m. de largo; la nº 10 de 0,15 m de alto por 0,75 m. de largo y 0,06 de grueso; la 11 mide 0,1/0,16 m. alto por 0,95 m de largo y 0,06 de grueso; la nº 12 mide 0,2 m. de alto por 0,8 m. de largo y 0,15 m. de grueso.','No se conoce','Bibliografía: Príncipe de Viana 140/141 pág. 406.',NULL,'13 Baztan Sur'),
(258,'OLARIAGA',5,'Crómlech','Baztan - Ciga','Entre Abartan y Saioa Hoja cartográfica Nº: 90-12','Zuraurre',NULL,616996,4771040,1020,43.081184,-1.564043,'utm','1983-12-24','sábado, diciembre 24, 1983','Francisco Ondarra','2,5 m. de diámetro y 9 testigos que apenas asoman de la tierra y la hierba, excepto el señalado con el nº 1 que mide 0,2 m. de alto por 0,35 m. de largo y 0,1 m de grueso.','No se conoce','a unos 2 m. al S. parece haber otro fenómeno similar. Bibliografía: Arqueología nº 7, 1988.',NULL,'13 Baztan Sur'),
(259,'AKERRETA I y II',2,'Túmulos','Baztan - Ciga','A 1,2 km. desde Zuraurre camino de Abartan Hoja cartográfica Nº: 90-8','Zuraurre',NULL,617850,4775250,440,43.118950,-1.552662,'utm','1983-10-01','sábado, octubre 01, 1983','Francisco Ondarra','Túmulo 1: 3,5 m. de diámetro y 0,3 m. de altura, de tierra y piedras (unas 50 entre la hierba) Calizas Túmulo 2: Situado a 30 m. y 145º de anterior. Tiene 5 m. de diámetro y 0,6 m. de altura de tierra y numerosas piedras calizas entre la hierba.','No se conoce','Bibliografía: Arqueología nº 7, 1988.',NULL,'13 Baztan Sur'),
(260,'MUNUXKETA I y II',2,'Túmulos','Baztan - Ciga','A unos 800 m. al S. en línea recta desde Zuraurre Hoja cartográfica Nº: 90-8','Zuraurre',NULL,617400,4774940,520,43.116229,-1.558257,'utm','1983-12-11','domingo, diciembre 11, 1983','Francisco Ondarra','Túmulo 1: 4 m. de diámetro y 0,7 m. de altura, de tierra. Alguna piedra caída entre la hierba. Túmulo 2: Situado a unos 10 m. del anterior. Túmulo de 3,5 m. de diámetro y 0,7 m. de alto, de tierra. Una piedra caliza asoma entre la espesa hierba.','No se conoce','Bibliografía: Arqueología nº 7, 1988.',NULL,'13 Baztan Sur'),
(261,'ARBORTE',2,'Túmulo','Baztan - Ciga','A 1 km. de Munuxketa a unos 50 m. del camino. Hoja cartográfica Nº: 90-8','Zuraurre',NULL,617480,4774550,575,43.112706,-1.557357,'utm','1983-10-01','sábado, octubre 01, 1983','Francisco Ondarra','Túmulo circular de 8 m. de diámetro y 0,4 m. de altura, de tierra y piedras calizas. Ligero comienzo de concavidad en el centro.','No se conoce','Bibliografía: Arqueología nº 7, 1988.',NULL,'13 Baztan Sur'),
(262,'SOROTA',1,'Dolmen','Baztan - Ciga','2,3 km. Al NEE del monte Abartan Hoja cartográfica Nº: 90-8','Zuraurre',NULL,618010,4773750,647,43.105422,-1.551014,'utm','1972-10-15','domingo, octubre 15, 1972','Francisco Ondarra','Túmulo de 8 m. de diámetro y 2 m. de altura por el NNW. Existe un hoyo central de 5 m. de diámetro y casi 1 m. de profundidad, con un pequeño trozo de losa arenisca en posición vertical. Ésta mide 0,4 m. de alto por 0,6 m. de largo y 0,12 m. de grueso y orientada a 110º. El túmulo abunda en piedra caliza.','No se conoce','Bibliografía: Príncipe de Viana 140/141 pág. 403.',NULL,'13 Baztan Sur'),
(263,'SOATE',1,'Dolmen','Baztan - Ciga','A unos 800 m. del domen Sorota, hacia Abartan Hoja cartográfica Nº: 90-8','Zuraurre',NULL,617630,4773100,760,43.099630,-1.555821,'utm','1982-10-30','sábado, octubre 30, 1982','Luis Millan','No se distingue túmulo. Una losa clavada verticalmente. Medidas: 0,5 m. de altura por 1,7 m. de largo y 0,1 m. de grueso en una de las extremidades y 0,18 m. en la otra. El grosor medio es de 0,14 m. Por el lado del SE. Aparecen algunas piedras entre la hierba.','No se conoce','Bibliografía: Arqueología nº 7, 1988 pág 131.',NULL,'13 Baztan Sur'),
(264,'ABARTAN - IZKOA',5,'Crómlech (4)','Baztan - Ciga','A unos 800 m. al NE, de Abartan Hoja cartográfica Nº: 90-8','Zuraurre',NULL,617120,4772725,910,43.096333,-1.562165,'utm','1972-01-15','sábado, enero 15, 1972','Francisco Ondarra','crómlech nº 1: Túmulo de 9 m. de diámetro y 0,3 m. de altura. 23 testigos de piedras pequeñas en posición vertical. Areniscas. Merecen mención la losa 1: 0,85 m. de largo al igual que la losa 2. las losas 3 y 4 tienen una altura de 0,5 m. crómlech nº 2: Situado a 7,5 m. del anterior en dirección NW. Tiene 2 m. de diámetro y 8 testigos a ras de tierra. crómlech nº 3: A 0,5 m. del anterior. Destaca la señalada con nº1 que mide: 0,5 m de altura y está muy inclinada, al igual que las nº 6 y 7. Las señaladas como 2, 3, 4 y 5 se hallan tumbadas.','No se conoce','Bibliografía: Príncipe de Viana nº 140/141 pág. 404. Se dio a conocer como Abartan, cima de 1093 m. situada al SW a unos 800 m. del emplazamiento de los crómlech, pequeño mogote entre Urlegi y Urdintz llamado Izkoa. Con fecha 25-4-1982 Luis Millan distingue un cuarto crómlech.',NULL,'13 Baztan Sur'),
(265,'SAGARDEGI',2,'Túmulo','Anue','En el collado Lagardegi, entre Saioa y Zuriain Hoja cartográfica Nº: 90-16','Saioa',NULL,617780,4766550,1250,43.040643,-1.555364,'utm','1981-09-17','jueves, septiembre 17, 1981','Francisco Ondarra','Túmulo circular de unos 4 m. de diámetro y 0,2 m. de altura. No tiene hoyo central, más bien una superficie plana. Formado por tierra y piedra arenisca.','No se conoce','Bibliografía: Príncipe de Viana nº 165 pág. 19',NULL,'13 Baztan Sur'),
(266,'ALGORRIETA - ARGORRIETA',5,'Crómlech','Valle de Anue - Lanz','A 500 m. al SW de Irumugeta Hoja cartográfica Nº: 90-16','Saioa',NULL,614245,4766340,1106,43.039292,-1.598793,'utm','1972-07-11','martes, julio 11, 1972','Francisco Ondarra','Círculo ligeramente tumular y elíptico de 12 m. de diámetro y 0,3 m. de altura. Rodeado por 12 pequeños testigos de piedras areniscas. Las señaladas como 1 y 2 son mayores: 1.: 0,65 m. de alto; 0,9 m de largo; 0,07 m. de grosor 2.: 0,75 m. de alto; 0,8 m de largo; 0,07 m. de grosor','No se conoce','Desde este lugar, a 1,5 km y por el camino que rodea Errebulu y va Lanz, podríamos empalmar en Harriurdineta con los itinerrios de Ulzama- Velate - Lanz. Bibliografía: Príncipe de Viana nº 140/141 pág 419 A lápiz: Con fecha 6-8-1983 F.O. señala un ? y también un M que está pendiente de hacer ficha porque faltan datos y fotos.',NULL,'13 Baztan Sur'),
(267,'BAGAZELAI',2,'Túmulo','Baztan - Almandoz','Entre cotas 833 NE y 866 SW, a la derecha de la carretera Hoja cartográfica Nº: 90-12','Bagazelai',NULL,614340,4770250,741,43.074477,-1.596824,'utm','1972-07-11','martes, julio 11, 1972','Francisco Ondarra','Túmulo de 14 m. de diámetro y 1,5 m. de altura de piedra y tierra. Hoyo central de unos 2 m. de diámetro y poca profundidad.','No se conoce','Bibliografía: Príncipe de Viana nº 165 pág 17',NULL,'13 Baztan Sur'),
(268,'PARAMENDI',2,'Túmulo','Baztan - Almandoz','En el monte encima de Almandoz Hoja cartográfica Nº: 90-7','Almandoz',NULL,614180,4772500,620,43.094756,-1.598326,'utm','1972-02-19','sábado, febrero 19, 1972','Francisco Ondarra','Túmulo de 5 m. de diámetro y 0,4/0,5 m. de altura de piedra y tierra. Materiales: calizas y pizarras arcillosas',NULL,'En la loma y con una altitud de 635 m. hay otro túmulo muy similar. Bibliografía: Príncipe de Viana nº 138/139 pág 44',NULL,'13 Baztan Sur'),
(269,'APURTXI',1,'Dolmen','Baztan - Almandoz','A 100 m de la ermita de Santa Bárbara Hoja cartográfica Nº: 90-7','Almandoz',NULL,612820,4771880,715,43.089378,-1.615158,'utm','1957-01-06','domingo, enero 06, 1957','Tomás López Sellés','Túmulo circular de 15 m. de diámetro y 2,25 m. de altura. Cámara con una losa en pie y otras tendidas, de calizas del terreno.','No se conoce','Está catalogado en Munibe con el nº 54-15 Bibliografía: Munibe 1973',NULL,'13 Baztan Sur'),
(270,'BIDEGURUTZETA',1,'Dolmen','Baztan - Berroeta','En la estribación NE de Abartan Hoja cartográfica Nº: 90-8','Berroeta',NULL,615440,4772940,497,43.098526,-1.582757,'utm','1988-07-04','lunes, julio 04, 1988','Luis Millan',NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(271,'ERMITAKO LEPOA',5,'Crómlech','Baztan','A 800 m. al SE de Venta Quemada (Benterre) Hoja cartográfica Nº: 90-7','Saioa',NULL,612750,4766750,910,43.043207,-1.617058,'utm','1982-05-16','domingo, mayo 16, 1982','Luis Millan','crómlech circular de 8 m. de diámetro compuesto por 5 testigos: 1.- Al NNE: Súmamente pequeño y oculto 2.- Al ESE: 0,3 m. de alto; 0,43 m. de largo; 0.08 m. de grosor 3.- Al SSE: 0,4 m. de alto; 0,8 m. de largo; 0.04/0,1 m. de grosor 4.- Al SSW: 0,35 m. de alto; 0,6 m. de largo; 0.04/0,1 m. de grosor 5.- Al W: 0,35 m. de alto; 0,83 m. de largo; 0.1/0,16 m. de grosor Las número 2, 3, 4 y 5 se hallan inclinadas hacia afuera.','No se conoce','Bibliografía: Arqueología nº 7, 1988',NULL,'13 Baztan Sur'),
(272,'ERMITAKO LEPOA I',2,'Túmulo','Baztan','A 6 km. Del crómlech de Ermitako Lepoa, a 330º. Hoja cartográfica Nº: 90-11','Saioa',NULL,612750,4766750,910,43.043207,-1.617058,'utm','1982-04-25','domingo, abril 25, 1982','Luis Millan','Túmulo circular de 4 m. de diámetro y 0,3 m. de altura, sin hoyo en el centro. Cubierto de hierba. Algunas piedras en el centro.','No se conoce','Bibliografía: Arqueología nº 7, 1988',NULL,'13 Baztan Sur'),
(273,'ERMITAKO LEPOA II',2,'Túmulo','Baztan','A 6 km. del crómlech de Ermitako Lepoa, a 90º. Hoja cartográfica Nº: 90-11','Saioa',NULL,612750,4766750,910,43.043207,-1.617058,'utm','1982-04-25','domingo, abril 25, 1982','Luis Millan','Túmulo circular de 3 m. de diámetro y 0,2 m. de altura. Cubierto de hierba. Algunas piedras en el centro. No tiene cráter central.','No se conoce','Pedro Arrese efectuó una cata de reconocimiento. Aparecieron abundantes restes orgánicos quemados. Bibliografía: Arqueología nº 7, 1988',NULL,'13 Baztan Sur'),
(274,'ERMITAKO LEPOA III',2,'Túmulo','Baztan','A 70 m. del crómlech de Ermitako Lepoa, a 325º. Hoja cartográfica Nº: 90-11','Saioa',NULL,612750,4766750,910,43.043207,-1.617058,'utm','1982-04-25','domingo, abril 25, 1982','Luis Millan','Túmulo circular de 5 m. de diámetro y 0,5 m. de altura, sin cráter central. Cubierto de hierba. Algunas piedras en el centro.','No se conoce','Bibliografía: Arqueología nº 7, 1988',NULL,'13 Baztan Sur'),
(275,'ERMITAKO LEPOA',13,'Monolito','Baztan','A 55 m. del túmulo de Ermitako Lepoa, a 320º. Hoja cartográfica Nº: 90-11','Saioa',NULL,612750,4766750,910,43.043207,-1.617058,'utm','1983-07-14','jueves, julio 14, 1983','Luis Millan','Monolito de 1,25 m. de altura; 0,75 m. de ancho y 0,4 m. de grosor. Actualmente parece como se se tratase de dos gruesas losas colacadas una frente a otra, en posición vertical. Entre ambas hay piedras de menores dimensiones y más delgadas, colocadas por alguien, o acaso sea todo ello efecto de la erosión. La orientación es a 25º. Areniscas del terreno.','No se conoce','Bibliografía: Arqueología nº 7, 1988',NULL,'13 Baztan Sur'),
(276,'MATRAKOLA',1,'Dolmen (arruinado)','Baztan','250 m. al E. del collado de Matrakola Hoja cartográfica Nº: 90-11','Saioa',NULL,612690,4766650,925,43.042315,-1.617814,'utm','1974-09-05','jueves, septiembre 05, 1974','Francisco Ondarra','Túmulo de 16 m. de diámetro sin apenas altura. Tiene una losa hincada en su sitio. El conjunto presenta un aspecto arruinado.',NULL,'Bibliografía: Príncipe de Viana 140/141, pág. 422',NULL,'13 Baztan Sur'),
(277,'GOROSPIL LEPOA (I y II)',5,'Crómlech','Baztan - Ciga','En le collado entre las cotas 1108 m. por el S. y 1043 m. y 1050 m. nor el N. A 7 m. del llamado Pikuda Ipar. Hoja cartográfica Nº: 90-12','Zuraurre',NULL,617000,4770500,1000,43.076322,-1.564107,'utm','1975-06-14','sábado, junio 14, 1975','Tomás López Sellés','crómlech nº 1: 6 m. de diámetro y 8 testigos. Otros en el interior. crómlech nº 2: 4,5 m. de diámetro y 5 testigos. Los testigos son de material calizo.','No se conoce','Bibliografía: Príncipe de Viana 144/145, pág. 339',NULL,'13 Baztan Sur'),
(278,'GOROSPIL LEPOA III',5,'Crómlech','Baztan - Ciga','En le collado entre las cotas 1108 m. por el S. y 1043 m. y 1050 m. nor el N. Hoja cartográfica Nº: 90-12','Zuraurre',NULL,617000,4770480,1005,43.076142,-1.564111,'utm','1983-07-27','miércoles, julio 27, 1983','Francisco Ondarra','4 m. de diámetro y unos 10 testigos. Otros en el interior y también próximos en el exterior, todos pequeños y ocultos en entre la hierba. Areniscas. Hito 1 (S.): 0,2 m. alto; 0,52 m. largo; 0,23/0,31 m. grueso. Hito 2 (SSW): 0,4 m. largo.','No se conoce','Bibliografía: Arqueología nº 7, 1988',NULL,'13 Baztan Sur'),
(279,'GOROSPIL I',13,'Monolito','Baztan - Ciga','100 m. al N. de Gorospilgo Lepoa Hoja cartográfica Nº: 90-12','Zuraurre',NULL,617000,4770400,1015,43.075422,-1.564128,'utm','1982-08-16','lunes, agosto 16, 1982','Luis Millan','Completamente tumbado. Mide 3,6 m. de largo y 0,42/0,98/0,4 m. de ancho y el material es arenisca del terreno.','No se conoce','Bibliografía: Arqueología nº 7, 1988',NULL,'13 Baztan Sur'),
(280,'GOROSPIL II',13,'Monolito','Baztan','A 25 m. y 220º de orientación de Gorospil I Hoja cartográfica Nº: 90-12','Zuraurre',NULL,617000,4770300,1030,43.074522,-1.564149,'utm','1984-07-17','martes, julio 17, 1984','Francisco Ondarra','2,5 m. de largo por 1,1/1,45 m. de ancho por 0,3 m. de grueso. Está tumbado. Material: areniscas.',NULL,'Bibliografía: Arqueología nº 7, 1988',NULL,'13 Baztan Sur'),
(281,'PIKUDA IPAR',5,'Crómlech','Baztan - Ciga','En el collado de su nombre Hoja cartográfica Nº: 90-12','Zuraurre',NULL,617000,4770500,1000,43.076322,-1.564107,'utm','1966-10-10','lunes, octubre 10, 1966','Francisco Ondarra','6 m. de diámetro y 13/14 testigosque destacan poco sobre el nivel del terrreno.','No se conoce','Bibliografía: Munibe 73. Contribución …',NULL,'13 Baztan Sur'),
(282,'KATILLEGIKO LEPOA (I y II)',5,'Crómlech','Baztan - Ciga','25 m. al SW del dolmen Hoja cartográfica Nº: 90-12','Zuraurre',NULL,616925,4769920,1050,43.071112,-1.565150,'utm','1973-05-17','jueves, mayo 17, 1973','Francisco Ondarra','crómlech nº 1: Círculo de 5,5 m. de diámetro y 19 testigos, siendo el mayor el marcado con el nº1 con 0,2 m. de alto; 0,5 m. de largo y 0,05 m. de grueso. Arenisca. crómlech nº 2: Situado a 1,5 m. del anterior. Es un círculo de 6 m. de diámetro y 12 testigos. El mayor mide 0,6 m. de alto, por 0,3 m. de largo y 0,2 m. de grueso e inclinado hacia el exterior.','No se conoce','Bibliografía: Príncipe de Viana 140/141, pág. 409',NULL,'13 Baztan Sur'),
(283,'KATILLEGIKO LEPOA (III a IX)',5,'Crómlech','Baztan - Ciga','250 m. al S de Kateilegiko Lepoa I-II Hoja cartográfica Nº: 90-12','Zuraurre',NULL,616830,4769650,1095,43.068696,-1.566373,'utm','1973-05-17','jueves, mayo 17, 1973','Francisco Ondarra (7). 1982-04-25 Luis Millan (3).','crómlech nº 3: Diámetro de 7 m. Piedras pequeñas de arenisca. crómlech nº 4: Diámetro de 12 m. Testigos de unos 0,8 m. de altura. crómlech nº 5: Diámetro de 6 m. En la periferia tiene 4 testigos. crómlech nº 6: Diámetro de 5 m. En la periferia tiene 16 testigos. crómlech nº 7: Diámetro de 6 m. En la periferia tiene 9 testigos. crómlech nº 8: Diámetro de 7 m. 16 testigos, el mayor tiene 0,7 m. de largo. crómlech nº 9: Diámetro de 7,5 m. 21 testigos de reducidas dimensiones.','No se conoce','Bibliografía: Príncipe de Viana 140/141, pág. 409',NULL,'13 Baztan Sur'),
(284,'PIKUDA HEGO',5,'Crómlech','Baztan - Ciga','Hoja cartográfica Nº: 90-12','Zuraurre',NULL,616830,4769650,1100,43.068696,-1.566373,'utm','1966-10-10','lunes, octubre 10, 1966','Tomás López Sellés','crómlech tumulalr de 1 m. de altrua. Consta de 25/30 piedras de poca alzada.','No se conoce','Bibliografía: Munibe 1973. contribución…',NULL,'13 Baztan Sur'),
(285,'BAZTANADAR - BAZTANIBAR',1,'Dolmen','Gaztelu','En la divisoria territorial y de vertientes, cota 748. Hoja cartográfica Nº: 90-7','Gaztelu',NULL,610790,4772790,750,43.097870,-1.639912,'utm','1972-10-10','martes, octubre 10, 1972','Francisco Ondarra','Túmulo de 16 m. de diámetro y 2 m. de altura. 3 losas y otros tantos fragmentos de la tapa. Medidas: Losa W: 1 m. alto por 1,9 m. largo y 0,3 m. grueso. Losa N: 1,2 m. alto por 0,6 m. largo y 0,18 m. grueso. Losa E: 1,2 m. alto por 2 m. largo y 0,45/0,5 m. grueso. Losa 4 (fragmento): 1 m. largo por 0,7 m. ancho y 0,15 m. grueso. Losa 5 (fragmento): 0,9 m. largo por 0,9 m. ancho y 0,15 m. grueso. Losa 6 (fragmento): 0,9 m. largo por 0,9 m. ancho y 0,2/0,3 m. grueso. Las losas W y N destacan por encima del túmulo. La cámara mediría 1,5 m. de largo y 1 m. de ancho. Orientación N-S. Las tres primeras losas y la mayoría del túmulo son de areniscas. Las losas tumbadas son calizas piritosas.','No se conoce','Bibliografía: Príncipe de Viana 138/139, pág. 42',NULL,'13 Baztan Sur'),
(286,'KATILLEGI',13,'Monolito','Baztan - Ciga','80 m. al W de los crómlech Hoja cartográfica Nº: 90-12','Zuaurre',NULL,616750,4769600,1085,43.068259,-1.567366,'utm','1988-02-13','sábado, febrero 13, 1988','Luis Millan',NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(287,'KATILLEGIKO LEPOA II',1,'Dolmen','Baztan - Ciga','En el collado de su nombre Hoja cartográfica Nº: 90-12','Zuaurre',NULL,616925,4769920,1050,43.071112,-1.565150,'utm','1973-05-17','jueves, mayo 17, 1973','Francisco Ondarra','Túmulo de 5 m. de diámetro y 0,6 m. de altura, formado por piedras. En el centro se elevan 2 losas. Medidas: Losa 1: 0,9 m. largo y 0,03 m. grueso. Losa 2: 0,3 m. largo y 0,3 m. grueso. Las losas son de areniscas y el galgal está compuesto por una mezcla de calizas y otras rocas.','No se conoce','En una palomera vecina hay una piedra de 1,9 m. de largo por 0,6 m. de ancho y 0,5 m. de grueso. Bibliografía: Príncipe de Viana 140/141, pág. 408',NULL,'13 Baztan Sur'),
(288,'ARMATELA',1,'Dolmen corto?',NULL,'Hoja cartográfica Nº: 91-5/A','Itinerario nº 29.C',NULL,621700,4774700,480,43.113391,-1.505472,'utm',NULL,'domingo, mayo 28, 1905','F. Ondarra','Túmulo circular de 10 m. de ? y 0,7/0,8 m. de altura, compuesto de tierra y piedras; cráter central de 3 m. de ? y 0,7 m. de profundidad máxima y en él 3 losas sumamente inclinadas al N, casi tumbadas. Areniscas del terreno.',NULL,NULL,NULL,'13 Baztan Sur'),
(289,'MEAKAKO LEPOA',1,'Dolmen?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,43.106456,-1.505852,'gpx',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(290,'TURREIKO ASKA',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,43.101425,-1.496321,'gpx',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(291,'LARREBELTZ SORTALDE',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(292,'LARREBELTZ MENDEBAL',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(293,'TRANPAKO LEPOA',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,43.101976,-1.493181,'gpx',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(294,'TRANPAKO BORDA',7,'Dolmen corto abierto?',NULL,'Hoja cartográfica Nº: 91-5/C',NULL,NULL,622900,4772310,790,43.091683,-1.491257,'utm',NULL,'domingo, mayo 28, 1905','T. López Sellés y F. Ondarra','Túmulo circular de 6,5 m. de ? y poca altura. Cámara formada por dos losas, siendo la más larga de 1,4 m. destacando poco del suelo. Areniscas del terreno.',NULL,NULL,NULL,'13 Baztan Sur'),
