INSERT INTO `megalitos` (`id`,`nombre`,`tipologia_id`,`tipologia_texto`,`municipio`,`ubicacion`,`itinerario_texto`,`hoja_cartografica`,`utm_x`,`utm_y`,`altitud`,`lat`,`lon`,`coord_fuente`,`localizado_fecha`,`localizado_fecha_texto`,`localizado_autor`,`descripcion`,`excavacion`,`observaciones`,`caracteristicas`,`otros_aspectos`) VALUES
(302,'MUNDDURRU',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,43.111376,-1.465411,'gpx',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(303,'EHIARTZEKO LEPOA',13,'Monolito',NULL,'Aldudes',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(304,'ARGIBELKO LEPOA',1,'Dolmen corto cerrrado?',NULL,NULL,NULL,NULL,624500,4771570,920,43.084760,-1.471770,'utm',NULL,'jueves, mayo 11, 1905','J.M.Barandiaran','Túmulo circular poco acusado. Cámara de tres losas que dibujan recinto rectangular. Parece faltar la losa de cierre, ya que las losas mayores presentan sendas muescas o cortes en su extremo inferior de lado SW como para encajar en ellas una losa transversal. Esta losa parecería formar ventana. Hoy se ha construido sobre el recinto una choza o pequeño redil, levantando una pared al E y otra al W. Orientación SW. Areniscas del terreno.','No se conoce','Las últimas noticias sobre este dolmen datan del 11-01-1973 dadas por Francisco Ondarra, quien no ha podido localizarlo, viendo solamente en el lugar donde estuvo ubicado ruinas de alguna palomera.',NULL,'13 Baztan Sur'),
(305,'ARGIBELKO - I',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(306,'ARGIBEL - II',5,'Crómlech',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(307,'ARGIBEL - III',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(308,'ARGIBEL - IV',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(309,'ARGIBELGO LEPOA',13,'Monolito?',NULL,'Hoja cartográfica Nº: 91-5/D','Nº 29-D',NULL,624570,4771300,940,43.082318,-1.470971,'utm',NULL,NULL,NULL,'Tendido en posición horizontal. Piedra de arenisca roja que mide 4,3 m. de largo; 1,2 m. a 2,8 m. de ancho y 0,35 m. de grueso medio. Mira a los 50º.',NULL,'71-LL/XIII',NULL,'13 Baztan Sur'),
(310,'HARRIKULUNKA',13,'Monolito',NULL,'Situada al E del monte Agibel, pocos mmetros antes de la pala.','Nº 29-D',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Roca de unas 30 Tm. Y en equilibrio inestable. Puede ser fácilmente movida con la mano o encaramándose sobre ella. Tiene 4 m. de larga; 3,65 m. de ancha y 1,4 m. de grosor.',NULL,NULL,NULL,'13 Baztan Sur'),
(311,'ZAGUA',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,43.092976,-1.476691,'gpx',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(312,'ZAGUA',13,'Monolito',NULL,NULL,NULL,NULL,NULL,NULL,NULL,43.092976,-1.476691,'gpx',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(313,'ZAGUAKO LEPOA',2,'Túmulo',NULL,NULL,NULL,NULL,622870,4766715,1165,43.041322,-1.492860,'utm',NULL,'domingo, junio 04, 1905','L.M.S.',NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(314,'ZAHO',1,'Dolmen? y monolito','Alduides',NULL,'Nº 29-D',NULL,624660,4771150,920,43.080953,-1.469899,'utm',NULL,'miércoles, mayo 03, 1905','J.M. Barandiaran','Túmulo circular de 10 m. de ? y 1,5 m. de altura. Cráter central sin losas de cámara. Areniscas del terreno.','No se conoce','La zona está considerada como una estación dolménica, a uno y otro lado de la frontera internacional. En esta zona, además de este dolmen y del monolito, se encuentran un túmulo y tres crómlech.',NULL,'13 Baztan Sur'),
(315,'SUSTERRA',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(316,'SUSTERRA HEGO',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(317,'EGURTEGI',5,'Crómlech',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'13 Baztan Sur'),
(318,'ESKAINKO LEPOA (ORIENTAL)',5,'Crómlech (3)','Ezkurra','A pocos metros de los otros en línea E-W Hoja cartográfica Nº: 90-5','Erasun',NULL,595765,4772450,975,43.096855,-1.824558,'utm',NULL,'martes, abril 18, 1905','Juan Miguel Sansinenea','Situado en el vértice del collado. Son sencillos y pequeños, salvo el mediano. Su diámetro de 4,3 m por 3,6 m. y consta de 8 losas con una hincada en el eje.',NULL,'Bibliografía: Munibe, Cuadernos 2 y 3 de 1960.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(319,'ESKAINKO LEPOA (CENTRAL)',5,'Crómlech (2)','Ezkurra','En la faldaz SE del monte Olegi, poco antes del collado Hoja cartográfica Nº: 90-5','Erasun',NULL,595740,4772460,978,43.096948,-1.824863,'utm',NULL,'martes, abril 18, 1905','Juan Miguel Sansinenea','Difíciles de reconocer, al igual que los siguientes en línea W-E','No se conoce','José Miguel Barandiaran en su trabajo "Contribución al estudio de los curomlechs pirenaicos" de 1949 menciona 6 crómlech y no 14, como posteriormente inventarió el Sr. Sansinenea . Lo cierto es que más hacia el S del collado se distinguen algunas formaciones más o menos circulares, estando el terreno salpicado de piedras que confunden. Bibliografía: Munibe, Cuadernos 2 y 3 de 1960.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(320,'ESKAINKO LEPOA (OCCIDENTAL)',5,'Crómlech','Ezkurra','En el collado, divisoria de aguas, entre Olegi y Elazmumo Hoja cartográfica Nº: 90-5','Erasun',NULL,595670,4772480,975,43.097137,-1.825720,'utm',NULL,'martes, abril 18, 1905','Juan Miguel Sansinenea','28 testigos. Lajas de areniscas triásicas de color rojizo. Dos de ellas se yerguen en el vértice del arco oriental y forman una puerta de 3,1 m. de ancho. Frente a ellas y al W aparece tumbada una gran losa de 2,65 m. por 3,5 m. inmediatemanete al exterior del vértice occidental. El conjunto forma un círculo cuyo diámetro EW es de 7,6 m. y el SN tiene 6,8 m.','No se conoce','Existen crómlech análogos en Goizueta, en las zonas Kalbario Gurutz (antes Arriurdiñeta) y Abade Gurutz. Los datos anaotados son de Luis Peña Basurto en 1960. Bibliografía: Munibe, Cuadernos 2 y 3 de 1960.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(321,'OLEGI',5,'Crómlech (4)','Ezkurra','En la falda oriental del monte Olegi Hoja cartográfica Nº: 90-5','Erasun',NULL,595000,4772500,1000,43.097401,-1.833948,'utm',NULL,'martes, abril 18, 1905','Juan Miguel Sansinenea','Siete formaciones circulares se distinguen en la parte más llana de Olegi. Aunque sólo cuatro pueden diferenciarse con claridad.','No se conoce','Posiblemente exitan más formaciones circulares con menos definición. Igualmente se distingue otro en el collado formado entre Erakurri y Olegi, cercano y al W de la cima de Olegi, a 1042 m. de altura. En cuanto al topónimo Erakurri, se ha recogido otro para el mismo lugar: Irakurri.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(322,'GARATAMA',1,'Dolmen','Ituren','500 m. al N de Ituren Hoja cartográfica Nº: 90-2','Ituren',NULL,605215,4776750,250,43.134314,-1.707650,'utm','1987-05-09','sábado, mayo 09, 1987','Francisco Ondarra','Túmulo de 7 m. de diámetro y 0,3 m. de altura. Una losa de 0,3 m. de alto por 1 m. de largo por 0,1/0,05 m. de ancho. Orientado a 115º.','No se conoce','Bibliografía: Kobie, XVII - 1988.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(323,'EPEINTZAKO KASKUA',1,'Dolmen','Ituren','A 1 km. al N de Ituren Hoja cartográfica Nº: 90-2','Ituren',NULL,605320,4777150,342,43.137900,-1.706283,'utm','1987-05-02','sábado, mayo 02, 1987','Francisco Ondarra','Túmulo de 8 m. de diámetro y 0,5 m. de altura. Losa W: 1,5 m. de largo por 1,16 m. de ancho y 0,15 m. grueso Losa N: 0,95 m. de largo por 0,65 m. de ancho y 0,07 m. grueso Losa E: 0,9 m. de largo por 0,4 m. de ancho y 0,15 m. grueso','No se conoce','Bibliografía: Kobie, XVII - 1988.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(324,'ARRUTALA',1,'Dolmen','Ituren','A 1,1 km. al N de Ituren Hoja cartográfica Nº: 90-2','Ituren',NULL,605185,4777330,326,43.139540,-1.707908,'utm','1987-05-02','sábado, mayo 02, 1987','Francisco Ondarra','Túmulo rebajado sobre el que se pueden ver tres losas. Losa N: 0,3 m. de alto por 1,8 m. de largo y 0,15 m. grueso. Orientada a 80º. Losa W: 0,85 m. de alto por 0,65 m. de largo y 0,14 m. grueso. Losa 3: 0,7 m. de alto por 1,6 m. de largo y 0,17 m. grueso. En las cercanías del túmulo se eleva un murete de piedras de 1,8 m. de largo y 0,85 m. de grueso y 0,7 m. de ancho.','No se conoce','Bibliografía: Kobie, XVII - 1988.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(325,'AITZURRA',1,'Dolmen','Ituren','A 1,8 km. al N de Ituren Hoja cartográfica Nº: 90-2','Ituren',NULL,605000,4777800,490,43.143797,-1.710094,'utm','1987-04-29','miércoles, abril 29, 1987','Francisco Ondarra','Túmulo de unos 8 m. de diámetro y 0,5 m. de altura, con 5 losas sobre el mismo. Losa N: 0,75 m. de alto por 2 m. de largo y 0,15 m. grueso. Losa cabecera: 0,35 m. de alto por 0,11 m. de largo y 0,11 m. grueso. Losa S: 0,3 m. de alto por 2,65 m. de largo y 0,1 m. grueso. Cubierta: 1,55 m. de largo por 1,1 m. de ancho. Orientación de la cámara: 115º.','No se conoce','Bibliografía: Kobie, XVII - 1988.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(326,'ERDIKO XENDA',1,'Dolmen','Ituren','A 1,8 km. al N de Ituren Hoja cartográfica Nº: 90-2','Ituren o Aurtiz',NULL,604000,4778530,850,43.150506,-1.722251,'utm','1987-10-07','miércoles, octubre 07, 1987','Francisco Ondarra','Túmulo de 4 m. de diámetro y 0,4 m. de altura, rodeado por un círculo de piedras. Consta de 5 losas: Losa S: 0,9 m. de alto por 1,8 m. de largo y 0,1/0,15 m. grueso. Losa W: 0,1 m. de alto por 0,75 m. de largo y 0,07 m. grueso. Losa 3: 0,85 m. de alto por 075 m. de largo y 0,08 m. grueso. Cubierta: Entre 1,57 m. y 0,7 m. de ancho y 2,35 m. de largo y 0,1 m. de grosor.','No se conoce','Bibliografía: Kobie, XVII - 1988.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(328,'BUZTIZKO LEPOA',13,'Monolito','Aranaz (muga con Ituren)','Al SE del Mendieder (1072 m.) Hoja cartográfica Nº: 90-2','Aurtiz',NULL,603890,4779350,931,43.157904,-1.723450,'utm',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(329,'AMABURU',1,'Dolmen','Narvarte','Al W de la cima del monte Amaburu Hoja cartográfica Nº: 90-3','Narvarte',NULL,612220,4777950,425,43.144111,-1.621301,'utm','1987-12-30','miércoles, diciembre 30, 1987','Francisco Ondarra?','Túmulo de piedras y tierra. Cámara con dos losas laterales. La losa E. bascula al interior de la cámara y ésta se estrecha hacia el N., donde aparecen dos pequeñas losas hincadas en la misma dirección, pero no alineadas. Al S. de la cámara y apoyada en el túmulo, hay una losa grande y al E. otra más pequeña. El lugar es muy pedregoso y tiene muchos helechos.','No se conoce',NULL,NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(330,'OTALTZU',9,'Dolmen largo abierto','Narvarte','En el collado, a mitad de camino entre Amaburu y Menta Hoja cartográfica Nº: 90-3','Narvarte',NULL,612050,4778500,492,43.149087,-1.623280,'utm','1975-01-05','domingo, enero 05, 1975','Francisco Ondarra','Túmulo de 9 m. de diámetro y 0,3 m. de altura, formado por piedras. En él crecen varios quejigos. La cámara está enmarcada por cuatro losas y 4 losas y hay otras dos más desplazadas (una de ellas es la tapa) 1.- Losa NW: 1,05 m. de largo por 1,3 m. de ancho y 0,3/0,06 m. grueso 2.- Losa NE: 1,1 m. de largo por 0,75 m. de ancho y 0,08 m. grueso 3.- Losa SE: 0,95 m. de largo por 2 m. de ancho y 0,15 m. grueso 4.- Losa SE: 1,1 m. de largo por 1,5 m. de ancho y 0,07 m. grueso 6.- Losa SW: 1,2 m. de largo por 0,85 m. de ancho y 0,1 m. grueso 5.- Cubierta: 2,4 m. de largo por 2 m. de ancho y0,15 m. grueso las señaladas como 1, 3 y 4 "in situ" y verticales; la 2 se halla muy inclinada hacia el interior de la cámara; las 5 y 6, tumbadas y desplazadas. La cámara tendría unos 0,8 m. de anchura por 2 m. de largo. Orientación: 45º.','No se conoce',NULL,NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(331,'MALLURKETA',1,'Dolmen corto','Narvarte','A unos 300 m. al SSE de la cota 640 Hoja cartográfica Nº: 90-3','Narvarte',NULL,611420,4778600,607,43.150081,-1.631006,'utm','1975-01-05','domingo, enero 05, 1975','Francisco Ondarra','Túmulo de 10 m. de diámetro y entre 0,7 m. por el lado S y 0,9 m. por el lado N de altura, formado por tierra y piedras. La cámara está formada por dos losas y 4 losas y su anchura oscila entre 1 m. y 1,1 m. 1.- Losa N: 1,2 m. de alto por 2,4 m. de largo y 0,2 m. de grueso 2.- Losa S: 0,95 m. de alto por 1,2 m. de largo y 0,08 m. de grueso Ambas inclinadas hacia el S, más la segunda que la primera. Orientación: 80º.','No se conoce','En visita efectuada el 12-8-1989, se observa un trozo de losa tirado en el túmulo; es probable que perteneciera a la cubierta. Bibliogarfía: F. Ondarra en Revista Príncipe de Viana, 1944/145.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(332,'MIATE',7,'Dolmen corto abierto','Narvarte','En el collado de su nombre, 20 m. al W de una borda ruinosa Hoja cartográfica Nº: 90-3','Narvarte',NULL,610780,4778700,561,43.151075,-1.638854,'utm','1959-03-15','domingo, marzo 15, 1959','Tomás López Sellés','Túmulo de 10 m. de diámetro y entre 0,9 m. de altura. La cámara está formada por 3 losas con recinto rectangular, orientada al S. con una longitud de 1,96 m. y una anchura de 0,97 m. Calizas. 1.- Losa N: 0,76 m. de largo por 0,28 m. de alto y 0,08 m. de grueso 2.- Losa E: 1,96 m. de largo por 0,38 m. de alto y 0,11 m. de grueso 3.- Losa W: 1,54 m. de largo por 0,56 m. de alto y 0,18 m. de grueso','No se conoce','Visitado con fecha 12-8-1989, se observa mayor altura en túmulo (1,5 m. aprox.) y una basculación hacia el interior de las losas de la cámara. A 5 m. al SE del túmulo y al otro lado del camino se puede ver una piedra hincada a modo de monolito señalizador del dolmen; puede tratarse de una vieja muga. Catálogo en Munibe: nº 69-7. Bibliogarfía: Munibe 1973, Suplemento nº1.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(333,'SUSPIRU',1,'Dolmen','Narvarte','A unos 800 m. al N de Miate, en el collado Hoja cartográfica Nº: 90-3','Narvarte',NULL,610700,4779000,410,43.153787,-1.639778,'utm',NULL,'miércoles, septiembre 30, 2443','Luis Peña Santiago','Túmulo de rebajado de unos 13 m. de diámetro con una losa hincada. Al NE asoma una pequeña losa que bien pudiera ser la de cabecera. Delante del dolmen hay un muro de piedras y una alambrada. No se descarta que el muro haya sido construido con piedras pertenecientes al dolmen.','No se conoce','Hasta el dolmen llega una pista por el SW, aparentemente en buen estado. Hay duda sobre el autor del la localización. Consta por un lado lo ya apuntado y por otro aparece Francisco Ondarra el 27-12-1987, aunque cabe que se refiera a otro.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(334,'AIANSORO',1,'Dolmen','Bertiz','En el comino que pasa por Bertiz a la loma de Lerate Hoja cartográfica Nº: 65-16','Bertiz',NULL,613650,4780570,385,43.167483,-1.603183,'utm','1988-03-04','viernes, marzo 04, 1988','Francisco Ondarra','Túmulo rebajado de 6 losas: Losa 1: 0,2 m. de alto por 0,7 m. de largo y 0,06 m. de grueso Losa 2: 0,28 m. de alto por 0,85 m. de largo y 0,06 m. de grueso Losa 3: 0,15 m. de alto por 0,5 m. de largo y 0,05 m. de grueso Estas tres losas están situadas al S. Losa 4: 0,5 m. de alto por 0,3 m. de largo y 0,12 m. de grueso Losa 5: 0,5 m. de alto por 0,8 m. de largo y 0,1 m. de grueso Losa 6: 0,4 m. de alto por 0,42 m. de largo y 0,15 m. de grueso Losas 5 y 6 al N. Tres losas más, fuera de la cámara. Orientado a 100º.','No se conoce','Bibliografía: Kobie XVII-1988',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(335,'ARTOLA',1,'Dolmen','Bertiz','A 1,8 km. Al W de legate y a 1,2 km de Aiansoro Hoja cartográfica Nº: 65-16','Bertiz',NULL,614770,4781060,390,43.171725,-1.589308,'utm','1988-03-19','sábado, marzo 19, 1988','Francisco Ondarra','Túmulo de 8 m. de diámetro y 1,8 m. de altura máxima. Cámara de 5 losas: Losa 1.- N: 0,65 m. de alto por 2 m. de largo y 0,35 m. de grueso Losa 2.- E: 0,80 m. de alto por 0,55 m. de largo y 0,1 m. de grueso Losa 3.- S: 0,75 m. de alto por 1,2 m. de largo y 0,05/0,2 m. de grueso Losa 4 tumbada: 1,2 m. de largo por 1,2 m. de ancho y 0,3 m. de grueso Losa 5 tumbada: 1,85 m. de largo por 1,2 m. de ancho y 0,3 m. de grueso Orientado a 80º.','No se conoce','Citamos los datos geográficos dados por Luis Millan. Los datos dados paor F. Ondarra (Y = 4781320; X = 615150) situarían el dolmen con una diferencia de 440m. Bibliografía: Kobie XVII-1988',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(336,'ZUMALEKU',1,'Dolmen','Elgorriaga','Unos 400 m. al W del monte Askin Hoja cartográfica Nº: 90-3','Elgorriaga NE',NULL,607020,4778260,460,43.147655,-1.685171,'utm','1976-04-03','sábado, abril 03, 1976','Petete Sarobe','Túmulo de 16 m. de diámetro y 1,4 m. de altura en el lado S. (en el lado N es algo menor). 3 losas forman la cámara que mide 2 m. de largo; entre 0,8 y 0,95 m. de ancho y 0,6 m. de profundidad. Medidas de las 3 losas: Losa SW: 1,02 m. de alto por 2,5 m. de largo y 0,14 m. de grueso Losa NW: 0,58 m. de alto por 0,8/0,9 m. de largo y 0,17 m. de grueso Losa NE: 0,96 m. de alto por 2,6 m. de largo y 0,27/0,17 m. de grueso',NULL,'Fue localizado por Petete Sarobe, quien lo comunicó a Tomás López Sellés. Los datos son de F. Ondarra. Bibliografía: F. Ondarra en Príncipe de Viana 1982- nº 165.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(337,'MALKORGAINA',1,'Dolmen','Elgorriaga','En la falda del monte Mendaur Hoja cartográfica Nº: 90-2','Basaburua Menor - Elgorriaga',NULL,606060,4777998,470,43.145431,-1.697024,'utm','1976-10-27','miércoles, octubre 27, 1976','Francisco Ondarra','Túmulo de 5,5 m. de diámetro y 0,3 m. de altura de piedra arenisca. En el túmulo hay varias losas de reducido tamaño distribuidas desordenadamente. Una de ellas mide 1,1 m. de largo por 0,8 m. de ancho por 0,1 m. de grueso y otras dos losas más o menos iguales.','No se conoce','Bibliografía: F. Ondarra en Príncipe de Viana 1982- nº 165.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(338,'BAIKUNTZEKO ETXOLA',1,'Dolmen','Ituren','En el paraje Ataketa del monte Iruinaga Hoja cartográfica Nº: 90-2','Aurtiz',NULL,603150,4777850,700,43.144501,-1.732829,'utm','1980-01-26','sábado, enero 26, 1980','Francisco Ondarra','Túmulo de 11 m. de diámetro y 0,5 m. de altura. 6 losas de arenicas forman un recinto que recuerda un polígono irregular de 2,45 m. de EW por 2,38 m. de NS. Losa 1.-(W): 1,07 m. de alto por 1,32 m. de largo y 0,28 m. de grueso Losa 2.-(S): 1,8 m. de alto por 1,04 m. de largo y 0,21 m. de grueso Losa 3.-(E): 1,64 m. de alto por 1 m. de largo y 0,21 m. de grueso Losa 4.-(E): 1,52 m. de alto por 1,23 m. de largo y 0,12 m. de grueso Losa 5.-(E): 1,68 m. de alto por 1,34 m. de largo y 0,2 m. de grueso Losa 6.-(N): 1,34 m. de alto por 1,32 m. de largo y 0,25 m. de grueso','No se conoce','Según Francisco Ondarra, el topónimo que significa " la cabaña del docmiso o prendamiento" sería un puesto para vigilar las infracciones de parte del ganado del pueblo vecino de Zubieta, habiendo otras más abajo del mismo monte. Otra versión es que fue utilizado para cazar lobos con la ayuda de perros. Bibliografía: F. Ondarra en Príncipe de Viana 1982- nº 165.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(339,'BOSTORRATZ',1,'Dolmen','Elgorriaga?','En la muga Elgorriaga - Sumbilla - Santesteban Hoja cartográfica Nº: 90-2','Elgorriaga',NULL,606500,4778500,445,43.149889,-1.691518,'utm',NULL,NULL,NULL,'Túmulo de 11 m. de diámetro y 0,5 m. de altura. 6 losas de arenicas forman un recinto que recuerda un polígono irregular de 2,45 m. de EW por 2,38 m. de NS. Losa 1.-(W): 1,07 m. de alto por 1,32 m. de largo y 0,28 m. de grueso Losa 2.-(S): 1,8 m. de alto por 1,04 m. de largo y 0,21 m. de grueso Losa 3.-(E): 1,64 m. de alto por 1 m. de largo y 0,21 m. de grueso Losa 4.-(E): 1,52 m. de alto por 1,23 m. de largo y 0,12 m. de grueso Losa 5.-(E): 1,68 m. de alto por 1,34 m. de largo y 0,2 m. de grueso Losa 6.-(N): 1,34 m. de alto por 1,32 m. de largo y 0,25 m. de grueso','No se conoce','Según Francisco Ondarra, el topónimo que significa " la cabaña del docmiso o prendamiento" sería un puesto para vigilar las infracciones de parte del ganado del pueblo vecino de Zubieta, habiendo otras más abajo del mismo monte. Otra versión es que fue utilizado para cazar lobos con la ayuda de perros. Bibliografía: F. Ondarra en Príncipe de Viana 1982- nº 165.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(340,'¿ ELGORRIAGA ? ( a lápiz: posible el MARKOR GINA)',1,'Dolmen','Elgorriaga','A 1,5 km.de Elgorriaga en dirección NW Hoja cartográfica Nº: 90-2',NULL,NULL,605700,4777950,475,43.145050,-1.701459,'utm',NULL,NULL,'Eduardo Mauleon',NULL,'No se conoce','En la línea entre Elgorriaga y Mendaur, cercano a los dos caseríos situados en la encrucijada de caminos.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(341,'BAIKUNTZEKO ETXOLA',13,'Monolito','Ituren','A 200 m. al SE del dolmen Hoja cartográfica Nº: 90-2',NULL,NULL,603290,4777720,650,43.143312,-1.731132,'utm',NULL,NULL,NULL,NULL,'No se conoce',NULL,NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(342,'ERROLDAN - ARRIYA',13,'Monolito','Urrotz',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(343,'ERASUN - IGOA',1,'Dolmen','Basaburua','Hoja cartográfica Nº: 90-9',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'17-02-1990. Recorrido el collado señalado en la Hoja 90-9, no lo vimos. Aunque se ven huellas de máquinas, la posibilidad de que lo hubieran derruido no creo que sea grande, pues tampoco se ven restos. Es posible que este dolmen se ubique en algún otro lugar.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(344,'TANTADI',1,'Dolmen','Basaburua','Hoja cartográfica Nº: 90-9','Hasta el collado Goiko - Gaina se accede fácilmente, tanto desde Igoa como desde Erasun. A partir de aquí hay que acarrear el material al hombro unos 700 m., salvando al principio un corto pero fuerte repecho. Otra posibilidad sería subir desde el colladoBeltzuri (al N del dolmen), pero la pista que llega hasta sus proximidades no la hemos visitado.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Localizado según los datos de la reseña en el lugar marcado en el mapa Hoja 90-9. Aunque no es espectacular, sí sería digno de marcar, pues parece estar intacto. Reposa encima del túmulo una losa (de color gris oscuro, tipo pizarra) algo fragmentada, que parece ser la cubierta. El resto de la cámara se supone tapado por ella y el túmulo.',NULL,'17-02-1990. Recorrido el collado señalado en la Hoja 90-9, no lo vimos. Aunque se ven huellas de máquinas, la posibilidad de que lo hubieran derruido no creo que sea grande, pues tampoco se ven restos. Es posible que este dolmen se ubique en algún otro lugar.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(345,'ZURITTU BERRI',1,'Dolmen','Basaburua','A unos 125 m. al SSE de la cota 962, aproximadamente en cota 958 m., en la loma que se extiende hasta el collado Mende Zelai. Hoja cartográfica Nº: 90-13','Se puede tomar la pista que desde Igoa sube al collado Aztarketa, remontando el Artius, hasta un cruce de pistas, lugar donde hay un aska (este lugar se sitúa al NNE de Mende Zelai). De aquí hay que tomar un ancho camino a mano derecha que sube a media ladera hasta el collado Lerza Ondo. Una vez bordeada la cota 962, subir hasta el dolmen. Este cmino está bastante transitable, excepto en un punto en que se vuelve pedregoso. Quizás habría dificultades ahí. No obstante, a Leiza Ondo llega otro ancho camino que creo que sube desde el collado Gorostieta (en la carretera Oroquieta a Saldias), pero no sabemos cómo está.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Está rodeado de hayas y su túmulo resalta poco, pero lo que puede pasar inadvertido. El túmulo tiene unos 7 m. de diámetro y está muy rebajado. El conjunto está desfigurado porque ha crecido una gran haya en medio de lo que debió ser la cámara. Actualmente está derribada, pero quedan el tocon y las raíces. No obstante quedan en pie 6 losas (o trozos de ellas), lo que le da cierta entidad, suficiente para marcarlo (se puede confirmar con las fotografías).',NULL,NULL,NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(346,'MENDE ZELAI',2,'Túmulos y Crómlech','Basaburua',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Aunque no se puede afirmar con seguridad la existencia de crómlech en la colina, ésta es una zona muy interesante. La hierba está salpicada de piedras, que apenas sobresalen y algunas de ellas parecen formar arcos (nunca círculos enteros). Han podido ser crómlech, pero hoy no se puede afirmar tal cosa. El interés de la zona viene determinado por otra circunstancia: existen varias formaciones tumulares alargadas u ovaladas. De ellas, cuatro son bastante claras. Son de parecido tamaño ( 5 o 6 m. dde largo y 2 m. de ancho), pero las orientaciones son diferentes. El paraje es muy apropiado para ubicar cualquier enterramiento de este tipo, puesto que es despejado y domina una amplia zona. Por todo ello creo que no encontramos con una necrópolis de algún colectivo humano. De cualquier forma, como los posibles crómlech no están definidos y los túmulos están sin estudiar, no es necesaria la colocación de ningún hito.',NULL,NULL,NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(347,'ARRONDO',2,'Túmulo','Basaburua',NULL,NULL,NULL,NULL,NULL,NULL,43.122656,-1.474111,'gpx',NULL,NULL,NULL,'No existe tal túmulo. La cima de la cota Arrondo está formada por un amontonamiento de piedras, pero es un conformación natual. No tiene ninguna regularidad ni en forma circular, ni de altura, ni en composición. Tampoco advertimos la presencia del túmulo en las cercanías. Creo que hay una ficha de él, en cuyo caso habría que anularla.',NULL,NULL,NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(348,'IRUÑARRI - BERA',2,'Túmulo','Ezkurra - Saldias','Hoja 90- 5/10',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Ante todo debemos decir que la zona en donde serhalla ubicado se denomina "LATARGI". Está situado en la loma que baja del monolito Iruñarri, hacia el sur, más debajo de un cruce de caminos y donde termina el bosque. Para situarlo en la hoja cartográfica, tomamos referencias con la brújula desde el túmulo. Tomando como centro el túmulo tenemos: - Ezkurra a 240º y Erasun a 150º. La altura dada en la reseña, 830 m. snm) es correcta.',NULL,NULL,NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(349,'ENTSUSA',2,'Túmulo? O crómlech?','Ezkurra - Saldias','Hoja 90- 10',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'En la zona señalada en la Hoja 90-10 (al SSW de la cota Gora) aparece un abultamiento del terreno, muy irregular, con alguna piedra asomando (formando línea) Parece que este abultamiento ha podido ser producido por la raíces de una gran haya que crece en ese lugar, puesto que no tiene una forma en absoluto regular. Las piedras que asoman tampoco tienen aspecto de testigos. Pensamos que esta formación no es una constucción humana y, aunque lo hubiese sido en su momento, ahora no quedan suficientes rasgos de ella como para aseverarlo.',NULL,NULL,NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(350,'ELEZMUNO BERA',2,'Túmulo','Erasun','En la loma SW del monte Elazmuno, a unos 300 m. Hoja 90- 5',NULL,NULL,596250,4772600,960,43.098144,-1.818574,'utm',NULL,'sábado, octubre 10, 2443','Iñaki Gaztelu','Túmulo circular de entre 7,2 y 7,6 m. de diámetro y 0,6 m. de altura, en el que afloran algunas piedras',NULL,'Cercano al mismo, exite otra formación tumular,',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(351,'ATZAKO MEAKA',1,'Dolmen','Saldias - Erasun','En el collado de su nombre; divisoria de aguas; 60 m. E. mojón. Hoja 90- 5',NULL,NULL,598150,4773590,775,43.106813,-1.795056,'utm','1961-03-25','sábado, marzo 25, 1961','Jesús Elosegui','Túmulo de 10 m. de diámetro y 0,8/1 m. de altura, en el que destaca una losa inclinada al S. En el túmulo existen restos de material lítico que se empleó para hacer una txabola. Dos hayas crecen al W.','No se conoce','Está catalogado en Munibe con el nº 56-1 y con topónimo Azango Miaka. El nombre que encabeza la ficha ha sido recogido de la corrección hecha por Petete Sarobe. Bibliografía: Munibe 1973, suplemento nº1',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(352,'ENTSUTSA',5,'Crómlech','Saldias','En el collado de su nombre; divisoria de aguas; 60 m. E. mojón. Hoja 90- 10',NULL,NULL,600595,4770340,795,43.077234,-1.765602,'utm','1987-12-20','domingo, diciembre 20, 1987','Petete Sarobe','crómlech. 6 testigos formando un arco muy definido.','No se conoce','No se tienen má datos por parte del localizador',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)');
INSERT INTO `megalitos` (`id`,`nombre`,`tipologia_id`,`tipologia_texto`,`municipio`,`ubicacion`,`itinerario_texto`,`hoja_cartografica`,`utm_x`,`utm_y`,`altitud`,`lat`,`lon`,`coord_fuente`,`localizado_fecha`,`localizado_fecha_texto`,`localizado_autor`,`descripcion`,`excavacion`,`observaciones`,`caracteristicas`,`otros_aspectos`) VALUES
(353,'IRUÑARRI',13,'Monolito','Erasun','En la ladera del monte Elazmuno Hoja 90- 5',NULL,NULL,596730,4772900,1030,43.100784,-1.812624,'utm',NULL,'domingo, abril 30, 1905','Peña Basurto (primeras noticias)','Monolito de 2,96 m. de altura, con una anchura media que supera el metro y entre 22 y 25 cm de grueso. Orientado a los cuatro puntos cardinales. Arenisca roja.',NULL,'Su existencia es conocida en la zona desde muy antiguo, siendo Luis Peña Basurto quien dio los primeros datos. En el año 1936 J.M.Sansinenea y J.M.Barandiran reconocieron Irun-Arri, haciendo excavación en la base. Se desconocen los resultados, aunque, al parecer, fueron negativos. Bibliografía: Munibe. Fascículos 3 y 4, 1983 (en donde se recogen las anteriores menciones)',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(354,'IRUÑARRI BERA',1,'Dolmen','Erasun','450 m. al S del monolito Iruñarri Hoja 90- 5',NULL,NULL,597210,4772270,860,43.095051,-1.806837,'utm','1988-01-17','domingo, enero 17, 1988','Iñaki Gaztelu','Túmulo de 5 m. de diámetro y 0,5 m. de altura en el lado S; desde el lado N no se aprecia. Compuesto de tierra y piedras areniscas. Hay una piedra hincada en el centro y otras dos tumbadas. En su periferia, y a modo de crómlech, se aprecian tres piedras hincadas.',NULL,'Se desconoce el topónimo del lugar, por lo que se le aplica, provisionalmente, el citado arriba.',NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(355,'ERAKURRI - MENDARU',14,'Estación megalítica',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'11 Ezkurra - Bertiz Arana (Basaburua Menor)'),
(356,'GERASUNKO ATAKA (ESTACIÓN)',5,'Crómlech y túmulo','Goizueta (finca Artikutza) Aranaz','Centro del collado, junto al paso de Aranaz a Artikutza','Aranaz Hoja cartográfica nº 65-14','65-14',600410,4780990,980,43.173138,-1.765947,'utm','1951-03-19','lunes, marzo 19, 1951','Luis Peña Basurto','La estación consta, según Luis del Barrio, de 4 crómlech y un túmulo (probablemente pertenecía a un dolmen. Crómlech nº 1: 8 testigos en forma de bloques de los que destacan 7 con alturas entre 0,4 y 0,15 m. El resto, a nivel del terreno. El arco septentrional carece prácticamente de testigos. Pizarras y cuarcitas del terreno. Crómlech nº 2: 7 testigos en forma de bloques de los que testacan 4 con alturas entre 0,6 y 0,2 m. El resto a nivel del terreno. Carece de testigos en los sectores E, SW, NW. Una alambrada de muga lo atraviesa por su centro en dirección N-S. Pizarras y cuarcitas del terreno. Crómlech nº 3: 6 testigos con forma de bloques y con alturas entre 0,7 y 0,15 m. El resto a niverl del terreno. La parte nororiental y el arco accidental carecen de testigos. Diámetro NS - EW: 4,5 m. Crómlech nº 4: 9 testigos con forma de bloques de los que destacan 6 con alturas entre 0,55 y 0,15 m. El resto a nivel del terreno. En los sectores NE, SW y NW carece de testigos. El diámetro NS es de 11 m. y el EW es de 7,5 m. La alambrada de muga atraviesa el arco occidental en dirección N-S. Cuarcitas y pizarras del terreno. Crómlech nº 5: El diámetro NS es de 6,5 m. y el EW es de 8 m. La altura en el centro es de 0,7 m. Está formado por tierra y pequeños bloques que apenas se distinguen por la vegetación que lo cubre. Zona central rebajada. Pizarras y cuarcitas del terreno.','Se desconoce','Esta estación estaba documentada por Luis Peña Basurto, cuyos datos difieren notablemente de los dados por Luis del Barrio. Visto sobre el terreno, colocamos en la placa del hito señalizador los datos de Luis del Barrio. Las diferencias documentales de estos dos autores (números de testigos, diámetro, situación del terreno) son tan notables que no encontramos ninguna relación entre ambas. Por ello creemos que puede tratarse o bien de un error de imprenta (ya que no dudamos del buen hacer de ambos prospectores), o bien que la estación haya sufrido alguna manipulación fraudulenta y que hace que los datos nos parezcan como deformados (probablemente éste sea el motivo). Bibliografía: Luis del Barrio. Catálogo de la estación Aginaga - Lesaka 1989. Munibe 1960. Cuadernos 2 y 3.',NULL,'Lesaca - Aranaz - Vera'),
(357,'BARAXAR PAGOXAR',2,'Crómlech','Goizueta Aranaz','Entre la cota Izu y txabolas de Ollargarata','Goizueta Aranaz Hoja cartográfica nº 65-14','65-14',600625,4783240,740,43.193365,-1.762893,'utm',NULL,'lunes, mayo 29, 1905','A. Leibar','Cromlech. El diámetro NS - EW es de 7,7 m. Formado por al menos 14 testigos con forma de bloques y lajas, de los que destacan 12 con alturas entre 0,78 y 0,1 m. El resto yacen tendidos en el terreno a causa de la excavación incontrolada, practicada recientemente en la estructura o a nivel de éste. La zona central se encuentra ahondada por una excavación incontrolada, con unas dimensiones de 2 m. por 1,5 m. por 0,6 m. en dirección SE - NW. Así mismo, en el extremo del arco oriental existe una zanja de 3 m. por 0,4 m. por 4 m. Materiales: pizarras del terreno. La alambrada Goizueta (finca Artikutza) - Aranaz corta la estructura en el arco nororiental.',NULL,'Bibliografía: Munibe 1984. Nº 41.',NULL,'Lesaca - Aranaz - Vera'),
(358,'ARRANAGAITA',5,'Túmulo','Yanci','En la divisoria de aguas Aranaz - Yanci','Ventas de Yanci Hoja cartográfica nº 65-10','65-10',605340,4786670,225,43.223601,-1.704225,'utm','1976-10-09','sábado, octubre 09, 1976','Francisco Ondarra','Túmulo circular de unos 10 m. de diámetro por 0,8 m. de alto; compuesto de piedra arenisca y algún trozo de cuarzo blanco. Desfigurado en parte por senderos que pasan por él. No se aprecia hoyo central; en cambio, se levanta una pequeña pared encima de él, posiblemente resto de parapeto de palomera.','No se conoce','Los datos geográficos dados por Ondarra en la publicación "Príncipe de Viana" no parecen estar bien, ya que no encajan en la hoja correspondiente. Es posble que se trate de un error de imprenta. Coordenadas: longitud 1º 00´ 00´´; latitud 43º 12´ 56´´. Bibliografía: Príncipe de Viana 165, pág. 25',NULL,'Lesaca - Aranaz - Vera'),
(359,'AMARGUNGO ZEHARRA',7,'Crómlech','Lesaka','Entre Illasumendi (al NW) y Amaragungo Ziburra (al SE)','Lesaka I Hoja cartográfica 65-6','65-6',603775,4791140,340,43.264059,-1.722649,'utm','1954-01-24','domingo, enero 24, 1954','J. Elósegui, P. Otegui y J.M. Salaverria','Crómlech tumular de 11,4 m. de diámetro en dirección NS y 9,5 m. en EW. La altura en el centro es de 1,2 m. Consta de 21 testigos con forma de bloques. En el interior de la estructura hay inmersos pequeños bloques informes y tierra. Materiales: cuarcitas y pizarras del terreno.','No se conoce','Fue publicado como Amargurgo Egia-I, haciendo referencia a la existencia de un dolmen en la proximidades. Se trata sin duda de un afloramiento del terreno que ha servido para almacenar cantos y piedras del helechal del lugar. Catalogado en Munibe con el nº 48-4 Bibliografía: J.Elósegui 1956 Munibe 1973',NULL,'Lesaca - Aranaz - Vera'),
(360,'AGINA',5,'Dolmen corto abierto','Lesaka','A 30 m. de la carretera Oiartzun - Lesaka, en el km. 8 y 9.','Agina Hoja cartográfica nº 65-6','65-6',600751,4791150,550,43.264559,-1.759899,'utm','1958-02-22','sábado, febrero 22, 1958','T. Atauri, J.M. Barandiaran y M. Laborde','Dolmen. Túmulo rebajado y prácticamente desaparecido. En la actualidad la cámara compuesta por cuatro bloques de granito con forma de losa; recinto rectangular abierto al ESE, cuyas medidas son 1,2 m. por 1 m. y 0,3 m. de profundidad. Orientación 120º. El túmulo está formado por pequeños bloques de granito y tierra, materiales del terreno.','No se conoce','Catálogo en Munibe con el nº 48-5 En el invierno de 1984 existía un gran bloque de granito tendido sobre el túmulo, al NW, que recientemente ha sido introducido en el interior de la cámara de forma incontrolada. Bibliografía: J.M. Barandiaran. Monumentos megalíticos en la Loma de Agina (Lesaka). En Munibe, IX 1957. Munibe Suplemento nº 1 - 1973 Luis Del Barrio. Catátlogo de la Estación Agiña - Lesaka - Goizueta. 1987.',NULL,'Lesaca - Aranaz - Vera'),
(361,'AGINA-I (Aginako trintxera, estación)',5,'Crómlech','Lesaka','A 30 m. NNE del dolmen Agina y al otro lado de la carretera','Agina Hoja cartográfica nº 65-6','65-6',600800,4791235,555,43.265318,-1.759280,'utm','1958-08-15','viernes, agosto 15, 1958','Luis Peña Basurto','Yacimiento formado por 9 crómlech definidos entre otros bloques que puedieran ser estructuras del mismo tipo, aunque hoy es difícil de precisar. Crómlech nº 1: Formado por 12 testigos en forma de bloques de granito del terreno. Destacan 6 con alturas entre 0,25 y 0,15 m.; el resto, a nivel del terreno. En esta estructura parecen coincidir L.P.Basurto y L. Del Barrio. Diámetro estimado NS 4,35 m. y EW 3,7 m. Crómlech nº 2: Formado por 5 testigos en forma de bloques de granito del terreno. Destacan 2 con una altura de 0,1 m.; el resto, a nivel del terreno. Diámetro estimado 3,1 m.; solo tiene testigos a la vista en el arco oriental. Crómlech nº 3: Formado por 8 testigos en forma de bloques de granito del terreno. Destacan 3 con alturas entre 0,25 m. y 0,15 m.; el resto, a nivel del terreno. Diámetro estimado 5,5 m. Crómlech nº 4: Formado por 13 testigos en forma de bloques de granito del terreno. Destacan 7 con alturas entre 0,1 m. y 0,2 m.; el resto, a nivel del terreno. Diámetro NS 4,8 m. y EW 4,5 m. Crómlech nº 5: Formado por 9 testigos en forma de bloques de granito del terreno. Destacan 4 con alturas entre 0,3 m. y 0,1 m.; el resto, a nivel del terreno. Diámetro estimado 4 m.; carece de testigos en el arco N. Crómlech nº 6: Formado por 15 testigos en forma de bloques de granito del terreno. Destacan 7 con alturas entre 0,25 m. y 0,1 m.; el resto, a nivel del terreno. Diámetro estimado 5 m.; carece de testigos en el arco NO. Crómlech nº 7: Formado por 9 testigos en forma de bloques de granito del terreno. Destacan 6 con alturas entre 0,2 m. y 0,1 m.; el resto, a nivel del terreno. Diámetro estimado 6 m.Parece hacer contacto con el nº8 en el arco SE. Crómlech nº 8: Formado por 10 testigos en forma de bloques de granito del terreno y una laja de arenisca triásica en las inmediaciones. Destacan 6 con alturas entre 0,3 m. y 0,1 m.; el resto, a nivel del terreno. Diámetro estimado 5,7 m.Parece hacer contacto con el nº 7 en el arco SO. Crómlech nº 9: Formado por 6 testigos de granito del terreno y pizarras del terreno. Destacan 2 con alturas entre 0,15 m. y 0,1 m.; el resto, a nivel del terreno. Diámetro estimado 5 m.','No se conoce','Luis Peña en su trabajo de 1960 dio la referencia de que 500 m. al N existen restos de un túmulo. Posiblemente la referencia tenga error y se refiera al S. El número de crómlech del yacimiento fue posterriormente completado por I.Arbelaiz, Luis Del Barrio y Luis Millán en marzo de 1984. La placa del hito marca una altitud de 555 msm. Se localiza a 20 m. de la carretera (escrito a lápiz) Bibliografía: Luis Peña Basurto 1960 Luis Del Barrio. Catátlogo de la Estación Agiña - Lesaka - Goizueta. 1987.',NULL,'Lesaca - Aranaz - Vera'),
(362,'AGINA-II (estación)',5,'Crómlech','Lesaka','A la derecha de pista, antes del monumento al P. Donosti','Agina Hoja cartográfica nº 65-6','65-6',600620,4790855,540,43.261921,-1.761567,'utm','1958-02-22','sábado, febrero 22, 1958','Luis Peña Basurto','Se trata de un conjunto de 4 crómlech. Crómlech nº 1: 6 testigos con forma de bloques granito del terreno. Destacan 5 con alturas entre 0,5 m. y 0,1 m. Carece de testigos en el arco oriental y sectro noroccidental. Diámetro estimado: 5 m. Crómlech nº 2: 6 testigos con forma de bloques granito del terreno. Destacan 5 con alturas entre 0,5 m. y 0,1 m. Un solo testigo destaca con una altura de 0,1 m.; el resto, a la altura del terreno. Carece de testigo en el sector oriental. Diámetro estimado: 5,4 m. Crómlech nº 3: 11 testigos con forma de bloques granito del terreno. Destacan 6 con alturas entre 0,15 m. y 0,1 m.; el resto, a nivel del terreno. Carece de testigos en el arco oriental y sectro noroccidental. Diámetro estimado: 6 m. Crómlech nº 4: 9 testigos con forma de bloques granito del terreno. Destacan 2 con alturas entre 0,7 m. y 0,35 m. ; el resto, a nivel del terreno. Carece de testigos en el arco meridional y en parte del sector nororiental. Diámetro estimado: 8 m.','No se conoce','Repetidas veces miembros de Gorosti han intentado conservar este yacimiento colocando en su sitio testigos desplazados o señalizando el yacimiento con su correspondiente hito, etc. Desgraciadamente este conjunto está en vías de desaparición, ya que es utilizado por los "domingueros" como zona de acampada, aparcamiento de coches, incluso pueden verse los testigos cercando hogueras. El hito señalizador no ha servido para que este lugar sea respetado, si no que la misma placa ha sido rota. Bibliografía: J.M.Barandiaran. Monumentos megalíticos en la Loma de Agina (Lesaka). Munibe IX, 1957. Luis Del Barrio. Catálogo de la estación de Agina - Lesaka - Goizueta, 1987. Luis Peña Basurto. Reconstrucción y catalogación de los crómlech existentes en Guipúzcoa y sus zonas fronterizas en Navarra. En Munibe XII, 1960.',NULL,'Lesaca - Aranaz - Vera'),
(363,'AGINA-III (estación)',5,'Crómlech','Lesaka','En casco donde se erige el monumento al P. Donosti','Lesaka Hoja cartográfica nº 65-6','65-6',600635,4790680,555,43.260344,-1.761414,'utm',NULL,'miércoles, mayo 10, 1905','N.M.Sansisenea','Se trata de un conjunto de 3 crómlech. Crómlech nº 1: 13 testigos con forma de bloques granito del terrenoque apenas sobresalen del terreno. Diámetro NS 2,8 m. y EW 3,2 m. Crómlech nº 2: 7 testigos con forma de bloques granito del terreno. Destaca uno de 0,7 m. y los demás a ras de suelo. Diámetro: 3,1 m. Crómlech nº 3: 8 testigos con forma de bloques granito del terreno. Apenas sobrealen del suelo. Diámetro: 4,1 m. Estructura nº 4: Probablemente erigida en 1957, cuando se construyó el monumento al P.Donosti, según proyecto de L.Vallet y J.Oteiza. Por sus proporciones entre 18 y 20 metros de diámetro y por su disposición y el tamaño de la mayor parte de los testigos que lo componen, no parece tener carácte prehistórico-pirenáico.','No se conoce','Bibliografía: J.M.Sansinenea y L.Rodríguez, 1957. L.Valleta y J.Oteiza, 1957. J.M.Barandiaran. Monumentos megalíticos en la Loma de Agina (Lesaka). Munibe IX, 1957. Luis Del Barrio. Catálogo de la estación de Agina - Lesaka - Goizueta, 1987. Luis Peña Basurto. Reconstrucción y catalogación de los crómlech existentes en Guipúzcoa y sus zonas fronterizas en Navarra. En Munibe XII, 1960. J.Elósegui y J.Pérez, 1981.',NULL,'Lesaca - Aranaz - Vera'),
(364,'AGINA-IV',5,'Crómlech y túmulo','Lesaka','A 280 m. al N (tachado y escrito a lápiz: SUR) sur del monumento al P. Donosti (izda de pista)','Lesaka Hoja cartográfica nº 65-6','65-6',600610,4790460,543,43.258366,-1.761762,'utm','1954-03-03','miércoles, marzo 03, 1954','J.M. Barandiaran y A.Leibar (túmulo). 1958-02-22 J.M. Barandiaran y M. Laborde (crómlech)','Túmullo: 16 m. de diámetro y 1,8 m de altura, formado por pequeños bloques de granito y tierra. En el sector noroccidental se aprecian dos depresiones de 3,5 m. por 2 m. y 3 m. por 2,5 m. por 0,25 m. de profundidad. Crómlech: Formado por 6 testigos de los que destacan 4 de 0,25 m. y 0,1 m.; el resto a nivel del terreno. Carece de testigos en el arco oriental. Diámetro estimado: 6,5 m.','No se conoce','En su publicación, J.Elósegui denominó a este yacimiento como Agina - Domiko. Bibliografía: Jesús Elósegui, 1956. J.M.Barandiaran. Monumentos megalíticos en la Loma de Agina (Lesaka). Munibe IX, 1957. Luis Del Barrio. Catálogo de la estación de Agina - Lesaka - Goizueta, 1987.',NULL,'Lesaca - Aranaz - Vera'),
(365,'GAZTARRITA - I (GAZTARRIETA)',5,'Crómlech','Goizueta (Finca de Artikutza)','En la loma SE de la cota de su nombre','Lesaka Hoja cartográfica nº 65-9','65-9',598740,4788550,765,43.241418,-1.785138,'utm','1984-05-05','sábado, mayo 05, 1984','I.Arbelaiz, L.Del Barrio, Txomin Ugalde y A. Uriz','Crómlech tumular de 5,7 m. de diámetro y 0,45 m. de altura en el centro. Totalmente cubierto de brezo y vegetación, por lo que no se distinguen a simple vista los testigos que lo componen. Se aprecian algunos bloques en su interior. Granito del terreno.','No se conoce','Bibliografía: Luis Del Barrio. Catálogo de la estación de Agina - Lesaka - Goizueta, 1987.',NULL,'Lesaca - Aranaz - Vera'),
(366,'GAZTARRITA - II (GAZTARRIETA)',5,'Crómlech','Goizueta (Finca de Artikutza)','En la loma SE de la cota de su nombre, a 110 m. al NW del I','Lesaka Hoja cartográfica nº 65-9','65-9',598820,4788465,755,43.240643,-1.784168,'utm','1984-05-05','sábado, mayo 05, 1984','I.Arbelaiz, L.Del Barrio, Txomin Ugalde y A. Uriz','Crómlech tumular de 6 testigos de bloques de granito del terreno; con alturas ntre 0,9 m. y 0,35 m. Se encuentra cubierto en su mayor parte de brezo y vegetación. El diámetro NS es de 7,6 m. y el EW es de 7,8 m.','No se conoce','Bibliografía: Luis Del Barrio. Catálogo de la estación de Agina - Lesaka - Goizueta, 1987.',NULL,'Lesaca - Aranaz - Vera'),
(367,'ELUTXO ARRIA',5,'Crómlech','Goizueta (Finca de Artikutza)','En el collado Bidango, a 50 m. del vértice de un pinar','Agina Hoja cartográfica nº 65-9','65-9',599125,4787885,754,43.235381,-1.780516,'utm',NULL,'viernes, marzo 03, 2434','Luis Peña Basurto','22 testigos, 20 de ellos hincados y 2 caídos (uno sobre el túmulo y otro al exterior), destacando 9 con alturas entre 0,55 y 0,15 m. Granito, cuarzo y pizarras del terreno. Cubierto totalmente por matorrales de brezo. Tiene forma circular, cuyo diámetro es de 6,2 m. y la altura en el centro es de 0,65 m.','No se conoce','Luis Del Barrio aclara que el yacimiento se denomina y conoce como Elutxo Arria o Elutxoko Korralia desde el momento en que se dio a conocer. Pero que el lugar se encuentra ubicado a 800 m. al E en el mismo cordal, al otro lado del barranco que forma el espolón meridional de Bidango. Por nuestra parte, observamos alguna diferencia en las reseñas de Luis Peña y Luis Del Barrio: diferencia pequeña en cuanto a la ubicación, pero no así en el número de testigos. Bibliografía: Luis Del Barrio. Catálogo de la estación de Agina - Lesaka - Goizueta, 1984. Munibe 1960. Cuadernos 2 y 3.',NULL,'Lesaca - Aranaz - Vera'),
(368,'BIDANGO GAINA',5,'Crómlech','Lesaka - Goizueta','Junto al puesto de caza nº 68, en lo alto de la cota','Lesaka Hoja cartográfica nº 65-9','65-9',599310,4788170,781,43.237923,-1.778187,'utm',NULL,'domingo, enero 06, 2441','A.Leibar','Crómlech tumular (rebajado) de 4,5 m. de diámetro. Formado por pequeños y numerosos bloques (probablemente debido a los destrozos del yacimiento por el camino y las rodadas de los vehículos todoterreno que pasan por encima del mismo) que apenas destacan del terreno. Hay un gran bloque de cuarcita con forma triangular, situado en el arco meridional, que mide 1,5 m. de alto, entre 1,5 y 0,25 m. de ancho y entre 0,25 y 0,35 m. de grueso. En la cara septentrional, en la parte interior del recinto, tiene grabado el "báculo" de la antigua colegiata de Roncesvalles. Materiales: cuarcitas, granitos y pizarras del terreno.','No se conoce','Bibliografía: A.Leibar 1976/1977. Luis Del Barrio. Catálogo de la estación de Agina - Lesaka - Goizueta, 1984.',NULL,'Lesaca - Aranaz - Vera'),
(369,'BURNAIZTIETAKO LEPOA',1,'Crómlech','Goizueta (finca de Artikutza)','En el collado de su nombre','Lesaka Hoja cartográfica nº 65-9','65-9',598805,4788440,748,43.240420,-1.784357,'utm','1984-05-14','lunes, mayo 14, 1984','Luis Del Barrio y A.Uriz','Se trata de dos crómlech: Crómlech nº 1: 10 testigos con forma de bloque de granito del terreno; destacando dos de ellos con alturas entre 0,35 y 0,1 m. y el resto a nivel del terreno. El arco meridional parece seccionado, en parte por el sendero que discurre por el lugar en dirección EW. Tiene un diámetro de 4 m. Crómlech nº 2: 8 testigos con forma de bloque; destacando 4 de ellos con alturas entre 0,45 y 0,1 m. y el resto a nivel del terreno. El arco meridional parece seccionado, en parte por el sendero que discurre por el lugar en dirección EW. Tiene un diámetro de 4,5 m.','No se conoce','Bibliografía: Luis Del Barrio. Catálogo de la estación de Agina - Lesaka - Goizueta, 1987.',NULL,'Lesaca - Aranaz - Vera'),
(370,'BURNAIZTEGI',5,'Dolmen','Goizueta (finca de Artikutza)','En el espolón de su nombre, a 250 m. del collado','Lesaka Hoja cartográfica nº 65-9','65-9',598645,4788240,744,43.238640,-1.786363,'utm',NULL,'lunes, marzo 16, 2443','Luis Milan San Emeterio','Dolmen deformado y rebajado. Túmulo de 9,7 m. de diámetro de NS y de 8,5 m. de EW. Su altura oscila entre 0,6 y 0,8 m. Depresión central en la que se localiza hincado un bloque de granito con forma de losa, que mide 0,5 m. de largo; 0,15 m. de grueso medio y 0,3 m. de alto. Orientación 155º.','No se conoce','El dolmen se encuentra en condiciones de ruina y con perspectivas de desapracer en próximas talas. Bibliografía: Luis Del Barrio. Catálogo de la estación de Agina - Lesaka - Goizueta, 1987.',NULL,'Lesaca - Aranaz - Vera'),
(371,'EXKAXPE',5,'Crómlech','Goizueta','A 325 m. de la Casa Forestal de Excax','Lesaka Hoja cartográfica nº 65-9','65-9',597310,4788000,630,43.236653,-1.802844,'utm',NULL,'lunes, mayo 29, 1905','A.Leibar','Dos crómlech alineados EW y separados 5 m. Crómlech nº 1: Diámetro de 6,2 m. orientación NS y 6 m. orientación EW. Formado por 28 testigos con forma de bloque, de los que destacan 15 con alturas entre 0,5 y 0,1 m., los demás a nivel del terreno o tendidos. Crómlech nº 2: Diámetro de 6 m. orientación NS y 5,7 m. orientación EW. Formado por 30 testigos con forma de bloque, de los que destacan 9 con alturas entre 0,8 y 0,1 m., los demás a nivel del terreno o tendidos. En el interior de la estructura se localizan tendidos tres bloques de mediano tamaño. Materiales del conjunto: granitos y cuarcitas del lugar.','No se conoce','Bibliografía: A.Leibar 1976 y 1977. Munibe 1989 nº 41.',NULL,'Lesaca - Aranaz - Vera'),
(372,'ENOBIETA TXIKIA',5,'Crómlech','Lesaka','En el centro del collado de su nombre','Lesaka Hoja cartográfica nº 65-10','65-10',600340,4787400,645,43.230854,-1.765644,'utm','1985-02-16','sábado, febrero 16, 1985','Luis Del Barrio y A.Uriz','Crómlech de 4,5 m. de ?, compuesto por 10 testigos con forma de bloque, de los que destacan 4 con alturas en 0,46 y 0,1 m. y el resto a nivel del terreno. En el arco septentrional crece un haya que ha dañado y deformado la estructura. Materiales: pizarras del terreno.',NULL,'La placa del hito con que ha sido señalado indica el topónimo de Enubieta txikia porque así lo dio el autor. Bibliografía: Munibe 1989 nº 41.',NULL,'Lesaca - Aranaz - Vera'),
(373,'PAGOLLETAKO GAÑA',5,'Crómlech','Goizueta - Lesaka - Aranaz','En el vértice del límite de los tres términos municipales','Lesaka Hoja cartográfica nº 65-10','65-10',600735,4786110,685,43.219188,-1.761017,'utm','1956-12-23','domingo, diciembre 23, 1956','J.Elósegui. 2ºy3º en marzo de 1984 por Luis Millan','Crómlech tumular nº 1: de 9,8 m. de ? y de 0,5 m. de altura al N y de 0,3 m. al W según la disposición del terreno y formado por numerosos bloques tanto en el interior de la estructura como en el perímetro, entre los que destacan 4 con alturas entre 0,76 y 0,1 m., estando el resto a nivel del terreno. Materiales que en su mayor parte son pizarras del terreno, 7 bloques de cuarcita, 1 bloque de granito y uno de arenisca triásica de las inmediaciones. Crómlech tumular nº 2: de 5,4 m. de ? y altura entre 0,5 m. y 0,2 m., formado por numerosos bloques repartidos por toda la superficie de la estructura. Materiales que en su mayor parte son pizarras y algún granito. Crómlech tumular nº 3: de 9 m. de ? y de 0,4 m. de altura en el centro y formado por numerosos bloques tanto en el interior de la estructura como en el perímetro, entre los que destacan en el sector SW-NE 10 testigos con alturas entre 0,5 y 0,1 m., estando el resto a nivel del terreno. Materiales que en su mayo parte son pizarras y granitos del terreno.','No se conoce','La placa del hito con que ha sido señalado se grabó el topónimo de Pagolleta Gaña, que es el nombre con el que lo denominó primeramente Luis Del Barrio. El crómlech nº1 lo dio a conocer J.Elósegui y lo denominó Biandiz - Izo Bibliografía: J.Elósegui 1962 Munibe 1989 nº 41.',NULL,'Lesaca - Aranaz - Vera'),
(374,'PAGOLLETA',8,'Crómlech','Goizueta','En el collado de su nombre, a 11 m. de la alambrada de Goizueta - Lesaka','Lesaka Hoja cartográfica nº 65-10','65-10',600440,4786415,650,43.221974,-1.764592,'utm',NULL,'lunes, mayo 29, 1905','A.Leibar','Crómlech nº 1: de 5,8 m. de ? y compuesto de 10 testigos, bloques de pqueño tamaño, destacando 6 con alturas entre 0,3 y 0,1 m., estando el resto a nivel del terreno. Materiales: 6 de pizarra y 4 de granito del terreno. Crómlech nº 2: de 5,9 m. de ?, carece de testigos en los acos NE y SW y formado por 4 testigos entre los que destacan 6 con alturas entre 0,3 y 0,15 m., estando el resto a nivel del terreno. Materiales: 1 de pizarra y 3 de granito.','No se conoce','Bibliografía: A. Leibar 1976',NULL,'Lesaca - Aranaz - Vera'),
(375,'PAGOLLETA',1,'Dolmen corto cerrado','Lesaka','En el centro del collado de su nombre','Lesaka Hoja cartográfica nº 65-10','65-10',600480,4786415,655,43.221968,-1.764100,'utm','1952-05-25','domingo, mayo 25, 1952','J.Elósegui y C.Menaya','Túmulo de 16 m. de ? al NS y 15,5 m. al EW y de 1,5 m. de altura; zona central junto a la cámara y parte del arco SW, rebajados. Cámara central en lo que se conserva del túmulo formada por cuatro losas: dos laterales de 1 m. por 0,4 m (N) y por 0,7 m. (S), más dos losas de cierre de 0,72 m., por 0,15 m. (W) y de 0,7 m. por 0,12 m. €, esta últimas ligeramente basculada hacia el interior. Cámara vaciada hasta 0,7 m. de profundidad con fondo relleno de pqueños bloques revueltos. Orientación 93º. Materiales de la cámara, pizarras del terreno y el túmulo es de piz<arras y granito del terreno.','No se conoce','Desde su descubrimiento se le denominó Biandiz - Izo por su autor y catalogado en Munibe en 1973 con ese nombre y con nº 48-2 y con 48-3 un túmulo cercano. Junto al final del túmulo, en la línea de la alambrada que limita Lesaka y Goizueta, existe un mojón con la incripción N-2 en la cara N., dos cruces en la cara E y en la cara W, el báculo de la Colegiata de Orrega de Roncesvalles. Bibliografía: J.Elósegui 1956 y 1962. Munibe 1973.',NULL,'Lesaca - Aranaz - Vera'),
(376,'BUTXI',1,'Dolmen','Aranaz','Al NE del collado de su nombre en la muga de Goizueta','Aranaz Hoja cartográfica nº 65-14','65-14',600570,4784720,794,43.206697,-1.763301,'utm','1984-03-30','viernes, marzo 30, 1984','I.Arbelaiz, L.Del Barrio, Tx. Ugalde y A.Uriz','Túmulo de 6 m. de ? NS y 4,5 m. al EW, formado por pqueños bloques y tierra, altura en el centro de 0,5 m. Zona central revuelta y ahondada en tiempo reciente, en la que se localizan tres grandes bloques tendidos, desplazados de su posición. Materiales del conjunto: pizarras y cuarcitas del terreno.','Profanado recientemente','En un principio Luis Del Barrio lo denominó Izu Lepoa Bibliografía: Munibe 1989 nº 41.',NULL,'Lesaca - Aranaz - Vera'),
(377,'ARRAMALETA (ESTACIÓN)',5,'Crómlech - túmulo','Goizueta','En el collado de su nombre, en el espolón occidental Mendiribil','Goizueta 3 Hoja cartográfica nº 90-1? 65-13',NULL,NULL,NULL,825,NULL,NULL,NULL,'1953-04-12','domingo, abril 12, 1953','Luis Peña Basurto','La estación consta de 4 crómlech y 1 túmulo. Crómlech nº 1: Formado por 10 testigos en forma de bloque y laja, destacando 3 con alturas entre 0,12 m. y 0,1 m. Pizarras del terreno. Diámetro NS de 2,6 m. y EW de 2,25 m. Crómlech nº 2: Formado por 11 testigos en forma de bloque y laja, destacando 6 con alturas entre 0,45 m. y 0,1 m., el resto a nivel del terreno y uno de ellos con forma de laja de 1 m. x 0,75 m. tendido. Pizarras del terreno. Diámetro NS de 2,6 m. y EW de 2,25 m. Crómlech nº 3: Formado por 21 testigos, destacando 15 con alturas entre 0,4 m. y 0,1 m., el resto a nivel del terreno. Materiales: pizarras 16, granito 1, arenisca 4 del terreno. Pizarras del terreno. Diámetro NS de 2,7 m. y EW de 3,85 m. Crómlech nº 4: Formado por 16 testigos que destacan sobre el terreno. Alturas entre 0,52 y 0,1 . Pizarras del terreno. Diámetro NS de 2,7 m. y EW de 2,9 m. Túmulo (nº 5): Formado por loques de pizarra y tierra. Diámetro NS de 3 m. y EW de 2,5 m. Alturua en el centro de 0,2 m.','No se conoce','La estación fue dada a conocer como Illarbiteko Soroa. El lugar que hace referencia estadenominación se localiza a 2 km. Al ESE dentro del mismo cordal. Luis Del Barrio aclara que el dolmen o cista identificado por Luis Peña Basurto era alguno de los cromlech o el pequeño túmulo descrito con el nº 5. Por nuestra parte, colocamos el hito señalizador correspondiente al yacimiento según los datos de Luis del Barrio, una vez comprobados. Al igual que en la estación de Gerasunko Ataka, encontramos diferencias notables respecto a la descripción hecha por Luis Peña Basurto. Suponemos que en el tiempo transcurrido entre1953 y 1987 han podido acaecer manipulaciones que hayan hecho variar el número de testigos. Bibliografía: Luis Del Barrio. Catálogo de la estación Agina - Lesaka - Goizueta. 1984 Munibe 1960. Cuadernos 2 y 3.',NULL,'Lesaca - Aranaz - Vera'),
(378,'URRIZTI O IZURRIZTI',5,'Crómlech',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Lesaca - Aranaz - Vera'),
(379,'ERREKALEKU (estación)',5,'Cromlech','Arano / Goizueta','En el collado de su nombre','Arano - Goizueta - 1 Hoja cartográfica 64-16','64-16',588500,4780650,656,43.171564,-1.912505,'utm',NULL,'lunes, julio 06, 2426','Jose Miguel Barandiaran','La estación está formada por 18 crómlech, de los que 12 se distinguen con alguna claridad, como indica el hito señalizador. Según el croquis de situación, estas son las medidas: Crómlech nº 1: Es la pieza circular más grande y mejor consevada del sector. Consta de 30 testigos de piedra y tiene un diámetro de 9m. Crómlech nº 2: Constituido por 12 testigos de piedra, bastante distantes entre sí, aun cuando por su posición no debió contar en sus orígenes por muchos más. Diámetro EW: 9,3 m. y NS: 8,8 m. Crómlech nº 3: Consta de 23 testigos formando una figura ovalada. El diámetro EW: 6,7 m. y NS: 3,7 m. Crómlech nº 4: Pequeño óvalo con 6 testigos, incrustado entre los crómlech vecinos, de los que aprovecha algunas piedras. Diámetro EW: 3,4 m. y NS: 3,7 m. Crómlech nº 5: Ligéramente ovalado con 18 testigos. Diámetro EW: 5,85 m. y NS: 3,7 m. Crómlech nº 6: Bien conservado. Forma un círculo con 33 testigos de piedra. En el centro del arco meridional tiene una abertura a modo de puerta de 2,5 m. señalada por dos hitos. Diámetro EW: 7,7 m. y NS: 7,6 m. Crómlech nº 7: Es el más pequeño de todo el conjunto. Tiene 9 testigos, 2 son piedras muy reducidas. Diámetro EW: 2,5 m. y NS: 4,7 m. Crómlech nº 8: Ovalado con 15 testigos. Diámetro EW: 5,6 m. y NS: 4,7 m. Crómlech nº 9: Formado por 24 testigos. Diámetro EW: 7 m. y NS: 7,3 m. Crómlech nº 10: A 1,5 m. del anterior, formado por 24 testigos y de menores dimensiones. Diámetro EW: 6,9 m. y NS: 7 m. Crómlech nº 11: Ligéramente ovalado con 12 testigos. Diámetro EW: 6,6 m. y NS: 6 m. Los demás crómlech de la estación tienen menos definición y no los reseño. El material es piedra arenisca veteada de mármol.','No se conoce','El collado donde está situada la estación es conocido en Arano o Goizueta como Errekalko o Errekaleku. Bibliografía: L.Peña Basurto. Munibe 1960. Cuadernos 2 y 3.',NULL,'Arano - Goizueta'),
(380,'BURNIN BURU',5,'Cromlech','Arano','Ladera NE de Arriurdiñeta','Arano - Goizueta - 1 Hoja cartográfica 64-16','64-16',589820,4782055,605,43.184058,-1.896040,'utm',NULL,'lunes, julio 06, 2426','Jose Miguel Barandiaran','Figura nº 1 y nº 2: Entre los dos forman un conjunto de dos cámaras, una pequeña al interior adosada al vértice del arco occidental y otra de mayores proporciones, al exterior y contigua al vértice de su arco septentrional. Las medidas del nº 1 son 4 m. de largo y 2,3 m. de ancho. Las del nº 2 son: eje EW de 9,7 m. y el eje SN de 8,9 m. En total entre los dos crómlech tienen 37 testigos, de los cuales 23 forman el círculo mayor y los restantes dan forma a sus dos cámaras. Las alturas de los hitos varían entre los 60 y 80 cm. los más altos. La naturaleza del material empleado es de areniscas marmóreas del paleozoico. Figura nº 3: Se sitúa a occidente y muy próximo a los anteriores. Son 30 testigos relativamente poco prominentes, que dan forma a un óvalo de 9 m. en el eje EW y 7,6 m. en el NS. Según Millan se distinguen 5 crómlech.','Blas Taracena Aguirre en 1949. No se conocen datos de la misma.','Luis Peña Basurto , de quien son estos datos, los da a conocer como Arriurdiñeta. J.M.Barandiaran los denomió Kulpitzarre. Luis Millan San Emeterio lo marca como Oraune el 21-06-1986. Se observa que estos cambios de nombres son muy frecuentes en la zona. Los topónimos que hemos utilizado corresponden al estudio de topónimos de Fernando Etxeberria de Goizueta. Los datos de localización del sector de Arriurdiñeta-Norte, Central y Occidental, según Luis Peña Basurto son: Longitud, entre 1º 47´ y 1º 47´ 40´´; latitud entre 43º 10´ 30´´ y 43º 11´. Bibliografía: Reconstrucción de los crómleh existentes en Guipúzcoa y sus zonas franterizas con Navarra. Munibe 1960. Cuadernos 2 y 3. Luis Peña Basurto.',NULL,'Arano - Goizueta'),
(381,'BURNIN BURU TXABALA o Zabala',5,'Cromlech','Arano','Ladera NE de Arriurdiñeta, a unos 200 m. de Burnin buru','Arano - Goizueta - 1 Hoja cartográfica 64-16','64-16',589720,4781900,620,43.182675,-1.897296,'utm',NULL,'lunes, julio 06, 2426','Jose Miguel Barandiaran','Las descripciones, las de los croquis. Figura nº 4: A mayor altura que los anteriores. Situado al borde de una profunda zanja, cuyos constructores lo respetaron. Formado por 13 piedras de pequeñas dimensiones de naturaleza marmórea. Eje EW 3,3 m. y eje SN 4 m. En las cercanías otro crómlech muy averiado; se le pueden contar 15 testigos pequeños: eje EW 5,8 m. y eje SN 6,5 m. Figura nº 5.',NULL,'Como se señala en el anterior de Burnin Buru, los topónimos son varios los aplicados. A éste Luis Millan lo denominó Iturriketa. Todo ello se ha prestado a muchas confusiones, que hoy siguen persisten, porque todavía no se ha dicho cuántos testigos tiene cada denominación. Por ello le damos en los croquis un orden de como van situados. La placa colocada en el hito señalizador también presenta errores; por ejemplo: señala burmin en vez de Burnin, en donde aparecen grabados también dos círculos como si ambos fueran dobles, cuando solamente uno es tangente. También al de Bunin Buruko Txabala se la da una altitud de 615 m. cuando su situación en la hoja corresponde a 620 m. Todo ello requiere hacer un repaso para dejarlo claro.',NULL,'Arano - Goizueta'),
(382,'KALBARIO GURUTZ - ARGARATA',5,'Cromlech','Arano','Ladera NE de Arriurdiñeta','Arano - Goizueta - 1 Hoja cartográfica 64-16','64-16',589550,4781550,675,43.179544,-1.899444,'utm',NULL,'lunes, julio 06, 2426','Jose Miguel Barandiaran','Emplazados en el nivel más alto, a no mucha distancia de la cumbre de Arriurdneta. Crómlech Ipara: (fig. nº 6) 53 testigos grandes, algunas piedras llegan a medir 1,2 m. de altura por 0,7 m. de anchura, Las más destacadas de entre ellas yacen al exterior derribadas por los elementos. El eje EW mide 10,4 m. y el SN mide 10,4 m. Crómlech Hego: (fig. nº 7) Próximo al anterior y formado por 25 testigos no muy destacados. En su arco occidental aparece un monolito de 1,5 m. por 0,75 m. tendido hacia el exterior.','Realizada por B.Taracena. Se desconoce la memoria de ella','La zona donde están ubicados se conoce con varios nombres. L.P.Basurto antes de la reseña la denomina Arriurdineta Occidental. Luis Millan los llama Argarata N. y S. L.F.Etxebarria los aplica en su estudio el topónimo de esta ficha. Se sitúan en el linde con Goizueta. La placa del hito colocado indica erróneamente 655 m. Bibliografía: Munibe 1960. Cuadernos 2 y 3.',NULL,'Arano - Goizueta'),
(383,'EZKITURRITAKO GAINA',5,'Cromlech','Arano','Ladera NE de Arriurdiñeta','Arano - Goizueta - 1 Hoja cartográfica 64-16','64-16',589630,4781750,645,43.181335,-1.898427,'utm',NULL,'lunes, julio 06, 2426','Jose Miguel Barandiaran','L.Peña Basurto denomina a este sector Arriurdiñeta Central y Occidental. Luis Millan le da el topónio de Urkamendi y al igual que los de la zona aplicamos el topónimo, basado en el estudio realizado por Fernando Etxeberria de Goizueta y presntado a Euskaltzaindia. En el sector aparecen 6 crómlech y L.Peña solo nombra uno; no hay datos de los demás, por lo que toda la zona está para ser reconsiderada. (A lápiz) La figura 6 indica solamente 3 piedras y un eje de EW de 12,2 m. y de SN de 10,2 m. Hay otros 5 crómlech más.','Al igual que los de la zona, parece ser realizada por B.Taracena sin que se conozca la memoria de las excavaciones.',NULL,NULL,'Arano - Goizueta'),
(384,'LAKENDIKO GAINA',5,'Cromlech','Arano','Al E. del collado Errekaleku','Arano - Goizueta - 1 Hoja cartográfica 64-16','64-16',588950,4780850,690,43.173312,-1.906938,'utm',NULL,'lunes, julio 06, 2426','Jose Miguel Barandiaran','Es el más oriental del sector. 16 testigos forman el círculo. Al NNE de su arco septentrional uno de sus elementos está constituido por un gran bloque de arenisca marmórea, que mide 1,1 m. por 0,85 m. por 0,45 m. El eje EW mide 8,6 m. y el SN tiene 8,8 m.','No se conoce','Luis Millan lo cataloga como Errekalko Gaina y Luis Peña Basurto lo incluye en Errekalko. Al igual que los de la zona, aplicamos el topónimo que encabeza la ficha por ser el dado en el estudio de L.F. Etxeberria. La placa indica Lekendiko porque la primera nota de Etxeberria así lo indicaba. ¿Error? Bibliogrrafía: Minibe 1960. Cuaernos 2 y 3.',NULL,'Arano - Goizueta'),
(385,'IRAURTZA',5,'Cromlech','Goizueta','En una estribación al SE de Zalkuba','Goizueta - III Hoja cartográfica 64-16','64-16',591600,4782465,415,43.187536,-1.874073,'utm',NULL,NULL,NULL,'Se trata de dos crómlech. No se han tomado datos de los testigos.','No se conoce','En la placa del hito señalizador, colocada por Gorosti en colaboración con la sociedad Umore Ona de Goizueta, se indica la altitud errónea de 435 msm.',NULL,'Arano - Goizueta'),
(386,'LEPAKO ESTUA (estación)',5,'Cromlech','Goizueta','En el cresterío que une Zalbuka con Bigurutzeta','Goizueta - III Hoja cartográfica 64-16','64-16',590800,4782310,519,43.186237,-1.883941,'utm',NULL,NULL,NULL,'Conjunto de 5 crómlech. No se conoce diámetro ni número de testigos.','No se conoce',NULL,NULL,'Arano - Goizueta'),
(387,'URGARATAKO GAINA',5,'Cromlech','Goizueta','En el alto del cerro que hay sobre el collado Urgarata','Arano - Goizueta - 1 Hoja cartográfica 64-16','64-16',590315,4781515,596,43.179138,-1.890038,'utm','1952-04-11','viernes, abril 11, 1952','Luis Peña Basurto','37 testigos de piedra de color gris claro bastante grandes. Forman un óvalo con eje EW de 6 m. y NS de 7,3 m. Los testigos más voluminosos son los de la parte septentrional del arco oriental. Tras su vértice N sobresalen al exterior los restos de una cámara que mide 1,4 m. de largo por 0,7 m. de ancho.','No se conoce','La exitencia de este crómlech fue cominicada a Luis Peña Basurto por Jesus Elosegui Irazusta en 1951 y fue registrado como Añoeneko Gaina, con nombre corregido por Fernando Etxeberria. Bibliografía: Munibe 1960. Cuadernos 2 y 3.',NULL,'Arano - Goizueta'),
(388,'URGARA',5,'Cromlech','Goizueta','En el collado Urgarata','Arano - Goizueta - 1 Hoja cartográfica 64-16','64-16',590005,4781380,583,43.177959,-1.893874,'utm','1952-04-11','viernes, abril 11, 1952','Luis Peña Basurto','Estación con 8 crómlech, de los cuales se describen 7. Crómlech nº 1: 21 testigos. Diámetro 7,2 m. Los testigos del arco oriental son grendes bloques semicúbicos de areniscas paleozoicas grises veteadas de cuarcita blanca; los del arco occidental son pequeños y del mismo material. Destacan las piedras que señalan N, E y W. La que indica N tiene su parte alta cubierta de una masa brillante de mineral fundido que en parte chorretea por los costados. Crómlech nº 2: 35 testigos de tamaño regular. Tiene forma ovalada. En el arco occidental pàrece conservar los restos de una pequeña cámara. Al N., la piedra aue lo señala queda un tanto rebajada entre sus vecinas, lo que parece inidcar un simulacro de puerta de 0,85 m. de anchura. El eje EW de 7 m. y el NS de 7,6 m. Crómlech nº 3: 36 testigos de piedras más bien pequeñas y de poca alzada. Inclinado en la ladera y próximo al comino, presenta la particularidad de tener abierta al saliente una ancha entrada de 3,7 m. formada por dos grandes losas sobresalientes que miden una 1,1 m. por 0,45 m. por 0,25 m. y otra 1,1 m. por 0,45 m. por 0,8 m. El eje EW es de 10,8 m. y el eje NS es de 11,1 m. Crómlech nº 4: A la izquierda de la encrucijada de caminos y en la parte llana del collado aparecen dos círculos de piedras tangentes. El mayor consta de 32 testigos de piedras en general bajas. Diámetro EW: 7,8 m. ; NS: 8 m. El aspecto de las piedras es blanqui-marmóreo. Crómlech nº 5: El pequeño, al S., cuenta con 14 testigos de poca alzada. Su coloración, en curiosa contraposición al nº 4, es negruzca con vetas de cuarcita. Sus diámetros son exactamente la mitad de los del anterior, lo que no deja de ser curioso. Crómlech nº 6: En la ladera del pequeño cerro que corona el collado. Círculo ligeramente elíptico con 42 testigos apretados y de forma cúbica bastante regular. Fuera del círculo, tras las tres grandes piedras que indican el N., puede verse lo que queda de una cámara ancha de 2,7 m. El diámetro EW es de 9,6 m. y el NS es 10 m. Crómlech nº 7: Es el más oriental del sector (está en Urgaratako Gaina). 26 testigos de piedras pequeñas y negruzcas de naturaleza marmórea. El diámetro EW es de 5,5 m. y el NS es de 5,4 m. La piedra que señala el S es la más destacada. De los demás crómlech no hay medidas.','No se conoce','La exitencia de este crómlech fue cominicada a Luis Peña Basurto por Jesus Elosegui Irazusta en 1951. Fue registrado como Añonako Lepoa, topónimo que fue corregido por Fernando Etxeberria en un trabajo publicado en Forum. Bibliografía: Munibe 1960. Cuadernos 2 y 3.',NULL,'Arano - Goizueta'),
(389,'AINOENE',7,'Dolmen corto abierto','Goizueta','En la majada de su nombre, camino de Goizueta a Errekalku','Arano - Goizueta - 1 Hoja cartográfica 64-16','64-16',589900,4781360,570,43.177791,-1.895169,'utm','1949-04-15','viernes, abril 15, 1949','Luis Peña Basurto','Túmulo de 10 m. de diámetro y de 1,3 m. de alto. Cámara de 3 losas que conforman un recinto rectangular, ligeramente cerrado a la entrada. Cubierta un poco desplazada hacia el E. Orientación a 85º. Material: areniscas grises casi blancas a causa de la abundancia de vetas marmóreas que contienen.','No se conoce','Fue registrado con el nombre de Añoenea Soroa y corregido por el trabajo de Luis Fernando Etxeberria publicado en Forum en 1989. En cuanto a la altitud, fue registrado a 550 m. Luis Millan corrige a 560 m. Javier Etxeberria los sitúa a 580 m. Según la Hoja Cartográfica, nosotros lo hemos situado a 570 m. Catalogado en Munibe con el nº 45-5 Bibliografía: Munibe 1973',NULL,'Arano - Goizueta'),
(390,'UNAMENE HEGO',5,'Crómlech','Arano','Estribaciones de Leuneta, al W de Errekalku','Arano - Goizueta - II Hoja cartográfica 64-16','64-16',587720,4781200,760,43.176607,-1.922012,'utm',NULL,'lunes, julio 06, 2426','J.M.Barandiaran','Formado por 23 testigos de piedras pequeñas. El eje EW es de 8,4 m. y el SN de 8,5 m.','No se conoce','Luis Peña Basurto lo denominó Unamene Meridional y se encuentra cerca del collado de Etzela (Otxola). Entre este crómlech y de Ipar, existen dos pequeñas prominencias cercanas entre sí. En ellas pueden verse algunas piedras que indican vestigios megalíticos, pero de difícil clasificación. Uno de ellos tiene 6 m. de diámetro por 0,5 m. de alto; el otro tiene 6,4 m. de diámetro por 0,6 m. de altura. También se aprecian restos de un segundo crómlech de 5 m. de diámetro y 8 testigos de escasa alzada, que lo dieron a conocer Luis Del Barrio y Txomin Ugalde en 1981. Bibliografía: Munibe 1960. Cuadernos 2 y 3.',NULL,'Arano - Goizueta'),
(391,'UNAMENE IPAR',5,'Crómlech','Arano','A 150 m. de Unamene Hego','Arano - Goizueta - II Hoja cartográfica 64-16','64-16',587720,4781350,755,43.177957,-1.921989,'utm',NULL,'sábado, abril 29, 1905','Luis Peña Basurto','35 testigos de irregulares dimensiones forman un círculo envolviendo una forma tumular. Las losas mayores delimitan el arco eridional. Tiene la característica de que entre los testigos se diferencican claramente cuatro, uno en cada punto cardinal. El testigo que señala el S es el más prominente con 1,4 m de altura y la máxima altura de la formación tumular. En el centro aforan rocas paleozoicas y piedras sueltas. El diámetro es de 11,3 m.','No se conoce','Jose Miguel Barandiaran visitó la zona en 1923 y solo dio a conocer un crómlech , sin que se sepa a cuál se refería. Por este motivo, anotamos la localización de éste a Luis Peña Basurto que es quien aclara la zona y denomina a este crómlech con Unamene Central. Bibliografía: Munibe 1960. Cuadernos 2 y 3.',NULL,'Arano - Goizueta'),
(392,'SAN MIGUEL SORO',5,'Crómlech','Arano','A unos 200 m. de la aguda colina, en dirección N.','Arano - Goizueta - II Hoja cartográfica 64-16','64-16',587670,4781500,700,43.179314,-1.922580,'utm',NULL,'sábado, abril 29, 1905','Luis Peña Basurto','Posiblemenete sea este el ejemplar más monumental y mejor conservado de la zona. El túmulo está bordeado de 41 testigos de piedras grises, casi blanquecinas por la buendacia de anchas vetas marmóreas. El consjunto se eleva más de 1 m. sobre el nivel del terreno. También puede apreciarse claramente la premediatada orientación, colando como piedras maestras de la construcción de hitos que habían de señalar para siempre sus conocimientos acerca de la existencia del punto de la tierra o el firmamento que denominamos norte. El diámetor del círculo es de 10,8 m. Los testigos alcanzan sus mayores dimensiones en el arco meridional. La forma tumular sobrepasa un poco la máxima altura de los testigos. Posee una pequeña cámara adyacente, al exterior, en el vértice de su arco septentrional. La cámara mide 0,9 m. por 2,3 m. con la abertura la N.','No se conoce','Forma parte de la estación de Unamene, zona que Jose Miguel Barandiaran visitó la zona en 1923 y solo dio a conocer un crómlech. Posteriormente las noticias provienen de Luis Peña Basurto y Txomin Ugalde y de Luis del Barrio en los años 1946 y 1989 respectivamente. Bibliografía: Munibe 1960. Cuadernos 2 y 3.',NULL,'Arano - Goizueta'),
(393,'DESKARGAKO ARRIETA',5,'Crómlech','Goizueta','Entre el collado y la cota Deskarga','Goizueta Hoja cartográfica 90-1','90-1',594770,4779210,670,43.157840,-1.835627,'utm',NULL,'sábado, octubre 03, 2443','J.Argomaniz','Crómlech de diámetro 3,4 m. Compuesto por 5 testigos con forma de bloque, entre los que destaca uno con una altura de 0,55 m. El resto a nivel del terreno. La zona central contiene tres bloques. Materiales: pizarras y cuarcitas del terreno.','No se conoce','Bibliografía: Munibe 1989, nº 41.',NULL,'Arano - Goizueta'),
(394,'GAZTARROZKO BIZKARRA',5,'Crómlech','Goizueta','En el collado de su nombre','Goizueta Hoja cartográfica 65-9','65-9',593970,4785150,512,43.211418,-1.844457,'utm',NULL,'miércoles, junio 24, 2443','Y.Tellabide','Se trata de un conjunto de 2 crómlech tumulares: Crómlech nº 1: El eje NS es de 4,2 m. y el eje EW es de 4,3 m. Revuelto y deformado. Peristalito y forma interior formados por numerosos bloque de pequeño tamaño, parte de ellos hincados en el terreno, con tierra y pequeñas piedras entre ellos. Materiales: pizarras y cuarcitas del terreno. En el extremo de arco SE crece un gran ejemplar de haya. Crómlech nº 2: El eje NS es de 4,7 m. y el EW, de 4,5 m. Revuelto y deformado. Peristalito y forma interior formados por numerosos bloque de mediano tamaño, parte de ellos hincados en el terreno, con pequeñas piedras y tierra entre ellos. Materiales: pizarras y cuarcitas del terreno.','No se conoce','Bibliografía: Luis Del Barrio. Munibe 1989.',NULL,'Arano - Goizueta'),
(395,'BIAMENDI LEPOA',5,'Crómlech','Labaien','430 m. al N del domen Biamendi Bizkarra','Goizueta Hoja cartográfica 65-9','65-9',599415,4778615,953,43.151888,-1.778612,'utm','1985-10-20','domingo, octubre 20, 1985','L.Millan','Crómlech. El eje NS es de 2,9 m. y el eje EW es de 2,5 m. Formado por numerosos bloques pequeños y lajas de pizarra, de las que destacan 11 hincadas en el terreno. Las alturas oscilan entre 0,18 m. y 0,1 m.; el resto a ras del suelo o caídos. Arco septentrional deformado tras haber crecido un haya en el centro del mismo. En el interior del sector suroccidental se ubican dos bloques de cuarcita. Materiales: pizarras del terreno. 4 m. al SE se localizan 3 bloques hincados en el terreno que pueden constituir los restos de otra estructura, una vez elimanada la densa hojarasca que cubre el lugar.','No se conoce','Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(396,'BIAMENDI BIZKARRA',1,'Dolmen','Labaien','1 km al S de Loizate','Goizueta Hoja cartográfica 90-1','90-1',599475,4778205,970,43.148189,-1.777948,'utm','1985-10-20','domingo, octubre 20, 1985','L.Millan','Túmulo de 6 m. de ? y 0,2 m. de alto. Formado por lajas y bloques de grauwacas y lajas de pizarra; está revuelto. Cráter central de 2,2 m. de ? NS y 2 m. EW y 0,15 m de profundidad. En el arco meridional se localizan 2 losas: - una hincada de 1,2 m. de largo; entre 0,35 m. y 0,15 m. de ancho y 0,35 m. de alto. y orientada a 160º en materiales de grauwaca - otra tendida junto a ésta, de 0,77 m. por 0,4 m. y por 0,07 m. de grueso, en material de pizarra. Contorneando el túmulo, se identifican algunos bloques hincados a modo de ortostratos, que definen la estructura circular del mismo.','No se conoce','Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(397,'LOIZATE SOROA',5,'Crómlech','Beinza - Labaien','450 m. al SW de la cota de Loizate','Goizueta Hoja cartográfica 90-1','90-1',598710,4778950,980,43.154996,-1.787222,'utm','1984-06-16','sábado, junio 16, 1984','L.Del Barrio y Tx. Ugalde','Crómlech deformado. Diámetro estimativo NS - EW de 3,5 m., 5 testigos con forma de bloque y lajas; destacando 3 con alturas entre 0,12 y 0,1 m. Materiales: (4) pizarras del terreno y (1) arenisca triásica de la inmediaciones.','No se conoce','Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(398,'IENGO ATAKA',5,'Crómlech (3)','Goizueta','En el collado posterior al Loizate, dirección Mindiribil.','Goizueta Hoja cartográfica 90-1','90-1',598710,4779710,970,43.161838,-1.787086,'utm',NULL,'lunes, octubre 05, 2443','L.Del Barrio y Tx. Ugalde','1.- Crómlech. Deformado. Diámetro NS - EW de 2,4 m.; 5 testigos con forma de bloque; destacando 3 con alturas entre 0,35 y 0,15 m.; el resto a nivel del terrreno. 2.- Crómlech. Deformado. Diámetro NS de 2,5 m. y EW de 2 m.; 5 testigos con forma de bloques; destacando 3 con alturas entre 0,35 y 0,15 m.; el resto a nivel del terrreno. 3.- Crómlech. Deformado. Diámetro NS de3 m. y EW de 3,5 m.; 7 testigos con forma de bloque que apenas afloran del terreno. Un bloque aflora en el centro de la estructura. Materiales: pizarra y cuarcitas del terreno.','No se conoce','En principio, Luis Del Barrio aplicó al conjunto el topónimo que encabeza la ficha, que es el mismo que aparece en el hito señalizador. Posteriormente ha aparecido publicado con el topónimo de Irango Ataka. Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(399,'IZURRIZTI - I',5,'Crómlech (9)','Goizueta','A 300 m. antes de la cota Izu','Aranaz Hoja cartográfica 65-14','65-14',600090,4784645,780,43.206085,-1.769222,'utm',NULL,'lunes, octubre 05, 2443','I.Arbelaiz, L.Del Barrio, Tx Ugalde y A.Uriz','Crómlech nº 1: 5,5 m. de ? NS y 4,6 m. de ? EW. 14 testigos en forma de bloque; destacan 8 con alturas entre 0,5 y 0,2 m. Carece de testigos en el sector SE. Hace contacto con el nº 2 en el sector suroccidental. Pizarras y cuarcitas (2) del terreno. Crómlech nº 2: 5,3 m. de ?. 15 testigos en forma de laja y bloque; destacan 5 con alturas entre 0,35 y 0,1 m. Hace contacto con el nº 1 en el sector nororiental. Pizarras y cuarcitas (1) del terreno. Crómlech nº 3: 2,45 m. de ?. 5 testigos en forma de bloque que apenas sobresalen del terreno. En el arco oriental carece de testigos. Cuarcitas del terreno. Crómlech nº 4: 4,5 m. de ?. 21 testigos en forma de bloque; destacan 11 con alturas entre 0,3 y 0,1 m. Hace contacto con el nº 5 en el sector noroccidental. Pizarras del terreno y una arenisca triásica. Crómlech nº 5: 3,2 m. de ?. 12 testigos en forma de laja y bloque; destacan 3 con alturas entre 1 m. y 0,1 m, al oeste el testigo mayor de 1 m. x 0,55 m. x 0,3 m. Carece de testigos en el sector septentrional. Hace contacto con el nº 4 en el arco suroriental. Pizarras del terreno. Crómlech nº 6: 3,6 m. de ?. 10 testigos en forma de bloque; destacan 5 con alturas entre 0,32 y 0,1 m. Carece de testigos en el sector occidental. Pizarras del terreno y una arenisca triásica. Crómlech nº 7: 4,5 m. de ?. 10 testigos en forma de bloque; destacan 6 con alturas entre 0,25 y 0,1 m. Carece de testigos en el arco oriental. Pizarras y cuarcitas (3) del terreno. Crómlech nº 8: 4,1 m. de ? NS y 3,7 m. de ? EW. 20 testigos en forma de laja y bloque; destacan 19 con alturas entre 0,4 y 0,1 m. Pizarras del terreno. Crómlech nº 9: 3,7 m. de ?. 7 testigos en forma de bloque; destacan 5 con alturas entre 0,25 y 0,1 m. Crece de testigos en el arco meridional. Pizarras del terreno.','No se conoce','Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(400,'IZURRIZTI - II',5,'Crómlech (6)','Goizueta','En el rellano anterior a la cumbre, estribación W de la cota Izu','Aranaz Hoja cartográfica 65-14','65-14',599940,4784680,765,43.206420,-1.771061,'utm','1984-03-30','viernes, marzo 30, 1984','I.Arbelaiz, L.Del Barrio, Tx Ugalde y A.Uriz','Crómlech nº 1: 5,7 m. de ?. 8 testigos en forma de bloque; destacan 6 con alturas entre 0,5 y 0,3 m. Pizarras (4) y cuarcitas (4) del terreno, destacando un gran bloque en el sector oriental de 1,5 m. x 0,8 m. x 0,5 m. de cuarcita. Crómlech nº 2: 3,9 m. de ?. 7 testigos en forma de laja y bloque, con alturas entre 0,25 y 0,18 m. Carece de testigos en el arco septentrional y los sectores SE y SW. Pizarras del terreno. Crómlech nº 3: 5 m. de ?. 25 testigos en forma de bloque y laja; destacan 8 con alturas entre 0,35 y 0,12 m. Pizarras del terreno. El slendero que discurre por el lugar atraviesa el yacimiento. Crómlech nº 4: 4,8 m. de ?. 4 testigos ; destacan 3 con alturas entre 0,3 m. y 0,25 m. Carece de testigos en los arcos oriental y occidental. Crómlech nº 5: 5,2 m. de ?. 5 testigos con alturas entre 0,25 y 0,15 m. Carece de testigos en el sector SW-SE. Pizarras del terreno. Crómlech nº 6: 3,8 m. de ?. 4 testigos con uno de 0,2m. Carece de testigos en el arco oriental y occidental. Pizarras del terreno.','No se conoce','Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(401,'IZURRIZTI',5,'Crómlech tumular','Goizueta','A 380 m. al SSW del conjunto de Arramaleta','Goizueta Hoja cartográfica 65-13','65-13',596775,4782130,603,43.183875,-1.810460,'utm',NULL,'miércoles, junio 24, 2443','J.Tellabide','Crómlech tumular desfigurado. Eje NS-EW de 4 m. La altura en el centro es de 0,2 m. Formado por numerosos pqueños bloques que afloran entre el relleno de tierra, parte de ellos hincados en el terreno. En el arco occidental se localiza un tocón de una gran haya',NULL,'Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(402,'IZU',5,'Crómlech (5)','Goizueta','En la cota de su nombre, a 230 m. al SW del dolmen de Izu Lepoa','Aranaz Hoja cartográfica 65-14','65-14',600410,4784570,829,43.205368,-1.765297,'utm','1984-03-30','viernes, marzo 30, 1984','I.Arbelaiz, L.Del Barrio, Tx Ugalde y A.Uriz','Se trata de un conjunto de 5 crómlech, 2 de ellos de tipo tumular ubicados en la cota máxima sobre el cordal principal a 50 m. de la cumbre y sobre el ramal que se desarrolla al NW. Crómlech nº 1: Diámetro estimativo NS-EW de 4,6 m. Formado por numerosos bloques revueltos y desplazados de su lugar por la erección de postes de alambrada y el testigo de la cota geodésica que se ubica en el lugar. Materiales: pizarras del terreno. Crómlech nº 2: Diámetro estimativo NS-EW de 5,3 m. Formado por 7 testigos con forma de laja que destacan del terreno entre 0,67 y 0,1 m. Carece de testigos en el arco oriental, donde contacta con la alambrada. Materiales: pizarras del terreno. Crómlech nº 3: De tipo tumular. Diámetro NS-EW de 7 m. Altura en el centro de 0,2 m. Tiene 7 testigos con forma de laja y de ellos 6 destacan del terreno entre 0,35 y 0,15 m. Hace contacto con el nº 4 en el sector NW. Materiales: pizarras, cuarcita (1) del terreno y areniscas triásicas (3). Crómlech nº 4: De tipo tumular. Diámetro NS-EW de 5,8 m. Altura en el centro de 0,2 m. Tiene 18 testigos con forma de laja y bloques, de ellos 4 destacan del terreno entre 0,45 y 0,2 m. Es tangente con el nº 3 en el sector SE. Materiales: pizarras de terreno. Crómlech nº 5: Diámetro NS-EW de 7,4 m. Tiene 6 testigos con forma de laja y bloques, de ellos 5 destacan del terreno entre 0,54 y 0,16 m. Carece de testigos en el sector oriental. Materiales: pizarras de terreno. Se sitúa a 50 m. al SSE del grupo principal.',NULL,'En 1976 A.Leibar en su publicación "Sendero de Crómlech" insinúa la conveniencia de revisar la cota Izu en relación con la existencia de posibles estructura megalíticas sobre ella. Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta');
INSERT INTO `megalitos` (`id`,`nombre`,`tipologia_id`,`tipologia_texto`,`municipio`,`ubicacion`,`itinerario_texto`,`hoja_cartografica`,`utm_x`,`utm_y`,`altitud`,`lat`,`lon`,`coord_fuente`,`localizado_fecha`,`localizado_fecha_texto`,`localizado_autor`,`descripcion`,`excavacion`,`observaciones`,`caracteristicas`,`otros_aspectos`) VALUES
(403,'UNALBIDE',5,'Crómlech','Goizueta','Estribación septentrional de Altueta','Goizueta Hoja cartográfica 65-14','65-14',595705,4784680,565,43.206969,-1.823183,'utm','1986-05-23','viernes, mayo 23, 1986','J.Argomaniz','Crómlech con eje NS de 4 m. y eje EW de 4,6 m. consta de 15 testigos con forma de lajas y bloques, de loa que destacan 5 con altura entre 0,2 m. y 0,1 m. y el resto, a nivel del terreno. Materiales: pizarras y cuarcitas del terreno.',NULL,'Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(404,'AUNTZBIZKAR',5,'Crómlech (3)','Goizueta','En el primer collado posterior a la cota de Loizate desde Goizueta.','Goizueta Hoja cartográfica 65-13','65-13',597435,4780300,924,43.167315,-1.802663,'utm','1985-06-01','sábado, junio 01, 1985','L.Del Barrio y P.López','Conjunto de 3 crómlech, cortados dos de ellos por una alambrada de separación de terrenos. Crómlech nº 1: Diámetro NS-EW de 4,5 m. Formado por 15 testigos con forma de bloques, de los que destacan 7 con alturas entre 0,5 y 0,1 m. y los demás a nivel del terreno. Crómlech nº 2: DiámetroNS-EW de 3,8 m. Formado por 11 testigos con forma de bloques y pequeñas laja que destacan con alturas entre 0,2 y 0,1 m.; el resto, a nivel del terreno. Materiales: pizarras del terreno y areniscas triásicas de las inmediaciones. Crómlech nº 3: Diámetro NS de 5 m. y EW de 5,9 m. Tiene 9 testigos con forma de bloques, que apenas sobresalen del terreno. Materiales: pizarras del terreno.',NULL,'Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(405,'LIZARROZKO SOROA',5,'Crómlech (5)','Goizueta','En el collado Lizarrozko Soroa','Goizueta Hoja cartográfica 90-1','90-1',594645,4778885,624,43.154930,-1.837220,'utm',NULL,'sábado, octubre 03, 2443','J.Argomaniz y V.Hernandorena','Conjunto de 5 crómlech, 4 de ellos de forma tumular. Crómlech tumular nº 1: Diámetro NS-EW de 5 m. y altura de 0,25 m. con depresión central de 3 x 3 m. y 0,1 m de profundidad. Formado por pequeños bloques, que aprenas sobresalen del terreno. Crómlech tumular nº 2: Diámetro NS-EW de 4,2 m. y altura de 0,2 m. 11 testigos con forma de bloques, de los que destacan 5 con alturas entre 0,2 y 0,1 m. Materiales: pizarras y grauwacas del terreno. Crómlech tumular nº 3: Diámetro NS 4 m. y EW de 3,5 m. Formado por numerosos y pequeños bloques que apenas sobresalen del terreno. Materiales: pizarras del terreno. Crómlech tumular nº 4: Diámetro NS 6 m. y EW de 5,5 m. y altura en el centro de 0,4 m. Formado por numerosos bloques y tierra. Materiales: pizarras y grauwacas del terreno. Crómlecn nº 5: Sólo se conserva parte del arco septentrional, en el que se distinguen 6 testigos con forma de lajas y bloques, de los que destacan 5 con alturas entre 0,15 y 0,1 m. La estructura está seccionada por el sendero que discurre por el lugar, fuertemente erosianado.',NULL,'Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(406,'ALTUETA LEPOA - I',5,'Crómlech','Goizueta','En el collado, entre las cotas Altueta y Keskantzuko Bizkarra','Goizueta Hoja cartográfica 65-13','65-13',594905,4784110,534,43.201938,-1.833127,'utm',NULL,'miércoles, junio 24, 2443','Y.Tellabide','Crómlech tumular rebajado y desfigurado, prácticamente desaparecido. Diámetro estimativo NS-EW de 3,2 m. con la zona central totalmente rebajada. Formado por numerosos bloques de reducido tamaño, de los que destacan del conjunto 2 en el arco septentrional, uno en pie de 0,4 m. y otro tendido. Materiales: pizarras y cuarcitas del terreno.',NULL,'Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(407,'ALTUETA LEPOA - II',2,'Túmulo','Goizueta','A 32 m. al N del crómlech de Altueta Lepoa','Goizueta Hoja cartográfica 65-13','65-13',594905,4784070,534,43.201578,-1.833134,'utm',NULL,'miércoles, junio 24, 2443','Y.Tellabide','Túmulo. Diámettro NS-EW de 7 m. La altura en el centro oscila entre 0,8 m. y 1,25 m Formado por pequeños bloques de cuarcita, pizarras del terreno y tierra. Arco occidental rebajado, al parecer, por aprovechamiento de sus materiales. Próximo al E. se localiza junto a la pista, y cortado por ésta, un amontonamiento de similares características que pudiera constituir otro túmulo.',NULL,'Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(408,'BELTZUNTZA - AKU',5,'Crómlech','Goizueta','En la cota de su nombre','Goizueta Hoja cartográfica 65-13','65-13',599455,4781150,880,43.174705,-1.777665,'utm','1984-06-16','sábado, junio 16, 1984','I.Arbelaiz, L.Del Barrio y Tx Ugalde','Crómlech. Diámetro NS de 5,5 m. y EW de 6 m. Formado por 11 testigos con forma de bloques, de los que destacan 4 con alturas entre 0,25 y 0,1 m.; el resto a nivel del terreno. Materiales: pizarras y cuarcitas del terreno.',NULL,'Luis Del Barrio lo dio a conocer en principio como Aku y así es como figura en la placa del hito señalizador Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(409,'IBINTZA',5,'Crómlech (2)','Goizueta','En el centro del collado de su nombre','Goizueta Hoja cartográfica 90-2','90-2',600475,4780250,950,43.166467,-1.765282,'utm','1984-06-16','sábado, junio 16, 1984','I.Arbelaiz, L.Del Barrio y Tx Ugalde','Conjunto de 2 crómlech: Crómlech nº 1: Diámetro NS de 7,2 m. y EW de 7,5 m. Formado por 11 testigos con forma de bloques, de los que destacan 7 con alturas entre 0,53 y 0,1 m.; el resto a nivel del terreno. La alambrada de muga corta la estructura en dirección NS. Crómlech nº 2: Sólo posee testigos en el arco SW-NE. Diámetro estimativo NS-EW de 5,5 m. Formado por 7 testigos con forma de bloques (4) y lajas (3), de los que destacan 5 con alturas entre 0,18 y 0,1 m.; el resto a nivel del terreno y otro tendido hacia el exterior. Materiales: Pizarras del terreno.',NULL,'Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(410,'ENEKO ELORRITA - I',5,'Crómlech (3)','Goizueta','En el collado de su nombre, en dirección de la cota de Deskarga','Goizueta Hoja cartográfica 90-1','90-1',595340,4779510,682,43.160470,-1.828566,'utm','1984-05-04','viernes, mayo 04, 1984','L.Del Barrio y J.Argomaniz','Conjunto de 3 crómlech de tipo tumular: Crómlech tumular nº 1: Revuelto y rebajado. Diámetro NS-EW de 4 m. Formado por numerosos bloques pequeños y tierra, con gran depresión central de 3 x 3 m. Materiales: pizarras y cuarcitas del terreno. Crómlech tumular nº 2: Revuelto y rebajado. Diámetro NS-EW de 4 m. Formado por numerosos bloques pequeños y tierra, con gran depresión central que abarca prácticamente la totalidad de la estructura. Materiales: pizarras y cuarcitas del terreno. Crómlech tumular nº 3: Revuelto y rebajado. Diámetro NS de 4 m. y EW de 3,5 m. Formado por numerosos bloques pequeños y tierra, con depresión central de 3 x 2 m. Materiales: pizarras y cuarcitas del terreno.',NULL,'Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(411,'ENEKO ELORRITA - II',5,'Crómlech (3)','Goizueta','A 100 m. del centro del collado de su nombre','Goizueta Hoja cartográfica 90-1','90-1',595460,4779520,695,43.160545,-1.827089,'utm','1984-05-04','viernes, mayo 04, 1984','L.Del Barrio y J.Argomaniz','Conjunto de 3 crómlech de tipo tumular: Crómlech nº 1: Diámetro NS de 5 m. y EW de 4,5 m., con 8 testigos con forma de pequeñas lajas y bloques, de los que destaca uno con 0,1 m de altura y el resto a nivel del terreno. Materiales: areniscas y pizarras del terreno. Crómlech nº 2: Diámetro NS-EW de 4 m., con 10 testigos con forma de pequeñas lajas y bloques, de los que destaca uno con 0,1 m de altura y el resto a nivel del terreno. Materiales: areniscas y pizarras del terreno. Crómlech nº 3: Diámetro estimado NS-EW de 3,5 m., con solo 3 testigos a la vista, de los que destacan 2 con 0,1 m de altura. Materiales: areniscas y pizarras del terreno.',NULL,'En un principio, Luis Del Barrio lo catalogó como Eneko Elorrita-I Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(412,'ALTZANBURU',2,'Túmulo',NULL,'Más al E. de Uragaratako Gaina, en dirección a Goizueta',NULL,NULL,NULL,NULL,NULL,43.178103,-1.886080,'gpx',NULL,NULL,NULL,'No hay datos',NULL,'En un principio, Luis Del Barrio lo catalogó como Eneko Elorrita-I Bibliografía: Munibe 1989. nº 41.',NULL,'Arano - Goizueta'),
(413,'GOLDANBURU',2,'Túmulo','Gorriti','En el camino de Gorriti a Huici','Gorriti (Itinerarios Larraun-Ipar) Hoja cartográfica 89-11','89-11',586600,4766575,840,43.045062,-1.938071,'utm',NULL,'lunes, abril 10, 1905','D. Ciaurriz','Túmulo circular de 18 m. de diámetro y 1,5 m. de altura, de tierra y piedras. Cráter central del que han desaparecido las losas que existieron en 1877. Ajuar de la excavación: - 1 cristal de roca en prisma, apuntado y facetado. - 1 puñal corto triangular de lengüeta con rebordes ligeramente marillados con biseles en ambos márgenes. - 2 lascas informes de sílex. - 1 botón circular de perforación en U con el dorso decorado con una hilera de incisiones menudas. - Restos humanos y de animales. Se dice que con ocasión de la extracción del material o sosas del dolmen se halló un esqueleto humano. Colección de las Sociedad de Ciencias Aranzadi de San Sebastián. Museo de San Telmo.','T. Aranzadi y J.M.Barandiaran en 1927','Catalogado en Munibe con el nº 53-1 La Sociedad Merkualde Kixmi Taldea le colocó un hito señalizador al que le falta la placa. Parece arrancada. Bibliografía: Munibe 1973, suplemento nº 1.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(414,'SOKILLETE',1,'Dolmen','Huici','En la cima llamada Mugarriberri','Gorriti (Itinerarios Larraun-Ipar) Hoja cartográfica 89-12','89-12',586840,4766910,870,43.048051,-1.935073,'utm',NULL,'lunes, abril 10, 1905','D. Ciaurriz','Dolmen. Túmulo de 18 m. de diámetro. En el lado S. mide 1,7 m. de altura y 1 m. al W. Al N. tenemos la ladera que baja al collado. Cámara reducida a 2 losas que están tumbadas en el cráter central. Orientación E. Calizas del terreno. Ajuar de excavación: - 1 guijo asurcado hemisférico - 1 raspador sobre extremo de lasca patenado. - 1 cuenta globular de azabache. - 1 punta trapezoidal (trapecio asimétrico de truncadura cóncava ?) de sílex. - 1 cuenta de tipo tonelete pasando a cilíndrico - 1 Dentalium - 2 cuentas discoideas de hueso. - restos humanos.','T. Aranzadi y J.M.Barandiaran en 1927','Catalogado en Munibe con el nº 53-2 Tiene un hito señalizador, colocado por la Sociedad Merkualde Kixmi Taldea de Larraun al que le ha desaparecido la placa. Hay que señalar que este lugar tiene dos topónimos: Mugarriberri y Sokillete. Esto ha dado lugar, en opinión de Tomás López Sellés, a un desdoblemiento de dólmenes, cuando en realidad sólo hay restos de uno. Al NE. Del dolmen se puede ver la línea de viejas mugas y hacia el SE., en el prado anexo, hay varias formaciones tumulares en el borde del bosque. Entre ellas destaca una de forma ovalada y compuesta por piedras de regular tamaño. Este fenómeno se está dando con frecuencia en distintas zonas de Navarra y merecería un estudio particular. A 30 m. de este dolmen y en dirección NW existe un túmulo bien definido de 9 m. de diámetro. El desdoblamiento de topónimos y el consiguiente desdoblamiento de dólmentes tuvo como consecuencia dos número de catalogación en Munibe: 53-2 y 53-3 Bibliografía: Munibe 1973, suplemento nº 1.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(415,'ATXITXIA',7,'Dolmen corto abierto','Huici',NULL,'Huici (Itinerarios Larraun-Ipar) Hoja cartográfica 89-12','89-12',588900,4766700,865,43.045922,-1.909818,'utm',NULL,'lunes, abril 03, 1905','J.M. Barandiaran','Dolmen corto abierto. Túmulo de 10 m. de diámetro y 0,8 m. de altura. Galgal de piedras. Tres losas con recinto rectangular. No tiene cubierta. Calizas del terreno.','No se conoce','Según Munibe, este dolmen ha podido ser confundido con Titinzulo. Probablemente, y dado que en la zonase encuentra el túmulo, es también posible que la descripción dada no se corresponda en la actual. En tanto no exisa una aclaración definitiva, se recogen estos datos. Está catalogado por Munibe con el nº 54-1. Bibliografía: Munibe 1973, suplemento nº 1.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(416,'TITINZULO',1,'Dolmen corto','Huici','En paraje Amazkar; 60 m. al S de la divisoria de aguas cantábrico-mediterránea y 70 m. al SE de la borda Txonkoenea.','Huici (Itinerarios Larraun-Ipar) Hoja cartográfica 89-12','89-12',589140,4766580,850,43.044813,-1.906891,'utm',NULL,'martes, mayo 09, 1905','Eduardo Mauleón','Dolmen corto ?. Túmulo circular de 8 m. de diámetro y 0,6 m. de altura. Cámara con dos losas, formando escuadra; una de ellas, la más pequeña, talvez sea la cabecera. Sin cubierta. Orientación a 108º. Calizas del terreno.','No se conoce','En su día se pensó que Atxitxia y Titinzulo eran el mismo dolmen. Hemos recogido estos datos en la ficha en tanto no exista una aclaración definitiva. Tiene un hito señalizador, colocado por la Sociedad Merkualde Kixmi Taldea de Larraun al que le ha desaparecido la placa. Está catalogado por Munibe con el nº 54-13. Bibliografía: Munibe 1973, suplemento nº 1.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(417,'TXUTXUIN',7,'Dolmen corto abierto','Huici','En estrecha planicie; a 2 km del puerto de Huici.','Huici (Itinerarios Larraun-Ipar) Hoja cartográfica 89-12','89-12',590450,4766750,808,43.046189,-1.890783,'utm',NULL,'viernes, mayo 19, 1905','M. Laborde','Dolmen corto abierto. Túmulo de 9 m. de diámetro de tierra y piedras; más relevante por el lado N. que por el lado S. Cámara de recinto rectangular, formada por tres losas basculadas hacia el interior. Dos losas pequeñás en la entrada junto a las laterales. Actualmente, diciembre de 1989, el túmulo tiene un amontonamiento de piedras en su arco NW., que parecen ser ajenas al mismo. Orientación 145º.','No se conoce','Tiene un hito señalizador, colocado por la Sociedad Merkualde Kixmi Taldea de Larraun al que le ha desaparecido la placa. Erróneamente esta sociedad le dio este topónimo al dolmen Esita Está catalogado por Munibe con el nº 54-24. Bibliografía: Munibe 1973, suplemento nº 1.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(418,'BIDEBERRIETA',1,'Dolmen','Huici',NULL,'Huici (Itinerarios Larraun-Ipar) Hoja cartográfica 89-12','89-12',589800,4766740,800,43.046176,-1.898763,'utm','1953-06-07','domingo, junio 07, 1953','E.Mauleon y T.López Sellés','Dolmen. Tapa de cubierta de 2 m. de largo y 1,7 m. de ancho. El resto de la construcción se halla debajo de la misma.','No se conoce','Túmulos Y: 4766580; X: 589800; Z: 816 Tanto el dolmen como los túmulos estan para repasarlos, ubicarlos de nuevo en la 89-12, fotografiarlo y hacer croquis.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(420,'AZPELATEGI',7,'Dolmen corto abierto','Huici','300 m. al S. de la ermita de Santa Engracia.','Goikozuloa Erreka (Itinerarios Larraun-Ipar) Hoja cartográfica 89-16','89-16',590870,4765940,770,43.038846,-1.885759,'utm','1955-04-10','domingo, abril 10, 1955','Eduardo Mauleon','Dolmen corto abierto. Túmulo tierra y piedras; de 10 m. de diámetro y 1,5 m. de alto en la parte más definida. Cámara de 3 losas, abierta al E. Losa S.: Orientada a 30º. Mide 2 m. de largo; 0,7 m. de alto (parte interior) y 0,4 m. (parte exterior); 0,2 m. de grosor. Losa lateral. Losa N.: Orientada a 36º. Mide 2 m. de largo; 0,8 m. de alto (parte interior) y 0,3 m. (parte exterior); 0,3 m. de grosor. Losa lateral. Losa W.: Mide 1 m. de largo; 0,9 m. de alto (parte interior) y 0,4 m. (parte exterior); 0,3 m. de grosor. Está ubicada en la cabecera. Losa E.: Mide 1 m. de largo; la alltura exterior es también de 1 m. El grosor oscila entre 0,2 y 0,25 m. Se encuentra recostada sobre un trozo seguido de la losa N. Otros trozos esparcidos por el túmulo son probablemente restos de la cubierta.','Cata realizada por Eduardo Mauleón.','Resultado de la cata: - 1 punta de flecha. - Fragmentos de cerámica. - Restos humanos: trozos de cráneo; incisivos y molares; otros huesos. Catalogado por Munibe con el nº 54-12. La Sociedad Merkualde Kixmi Taldea de Larrun le colocó un hito señálizador. Afortunadamente esta placa está intacta. Bibliografía: Munibe 1973; Suplemento nº 1.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(421,'ESITA MENDEBAL',1,'Dolmen','Huici','En lo alto de la cota; 150 m. al W. de Esita Sortalde','Huici (Itinerarios Larraun-Ipar) Hoja cartográfica 89-12','89-12',591550,4767260,875,43.050649,-1.877196,'utm','1989-12-09','sábado, diciembre 09, 1989','M. Sierra y C. Ballesteros','Túmulo de tierra y piedras; de 8 m. de diámetro y 0,65 m. de altura. Sobre el mismo reposa una losa fragmentada en tres trozos. En las proximidades hay un pqueño monolito similar a otros existentes cerca de algunos dólmenes.','No se conoce','Inspeccionada la zona para determinar el estado de los monumentos con vistas a su señalización, se observó la existencia de éste que ahora se da a conocer y que no estaba registrado con anterioridad ( lo que sigue está escrito con lápiz) como túmulo. Sin duda se trata del mismo que J.M.Barandiaran dio a conocer el 8-6-1920, que dijo haber dos dólmenes, aunque uno es túmulo, aclarando este concepto Miguel Sierra. Luis Millan el 12-10-1985 da a conocer el túmulo como inédito.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(422,'ESITA SORTALDE',2,'Túmulo','Huici','En la cresta; en la estribación del Erazote (Lizarragan)','Huici (Itinerarios Larraun-Ipar) Hoja cartográfica 89-12','89-12',591770,4767360,880,43.051523,-1.874478,'utm','1920-06-08','martes, junio 08, 1920','J.M.Barandiaran','Dolmen ?. Cámara desaparecida y oculta ?. Túmulo de 15 m. de diámetro y 2,5 m. de alto; de tierra y piedras.','No se conoce','La Sociedad Merkualde Kixmi Taldea de Larraun le colocó un hito señalizador. Al leer la placa, constatamos que llaman a este dolmen Txutxuin y le dan una altura de 950 m. Creemos que ambos datos son erróneos, pues desde que ambos dólmenes se dieron a conocer (1966 y 1920) nadie ha rectificado sus topónimos. No sabemos con qué nombre señaló la citada sociedad el dolmen Txutxuin, pues la placa ha sido arrancada del hito. A unos 500 m. de este dolmen y en direcciónW. hay un monolito triangular que parece estar calzado con el fin de sujetarlo. Para registrarlo debidamente habría que medirlo Catalogado en Munibe con el nº 54-8 Bibliografía: Munibe 1973. Suplemento nº 1.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(423,'ARROLA',1,'Dolmen','Huici','Al S. del monte Guratz','Guratz (Itinerarios Larraun-Ipar) Hoja cartográfica 89-12 Desde el Alto de Huici una pista toma la dirección NE. que transcurre por la divisoria de aguas al nonte Goratz. A unos 20/25 m. en la tercera loma. En un cruce de caminos, donde se distingue la losa orientada de E. a W. entre las hayas. Al SW. en una loma que se extiende a Arrite, en términos de ¿Gurite? a 900 m. snm. I.G. da a conocer un túmulo (no hay datos del túmulo) llamado Guratz.','89-12 D',587680,4767740,865,43.055427,-1.924630,'utm','1979-12-09','domingo, diciembre 09, 1979','Iñaki Gaztelu','Túmulo. Sobre el mismo una losa orientada de E. a W. y que mide 1,6 m. de largo, por 0,4 m. de alto y 0,3 m. de grueso. (Lo que sigue, a lápiz). Orientada a 150º. Hay otra losa hincada más al N. y a 1,1 m distante de la anterior, que mide 0,4 m. largo; 0.1 m. alto; 0,05 m. grosor. El túmulo de unos 9 m. de ? y 0,5 m. alto. Una pista pasa tangente por terreno rebajado, lo que le hace parecer más alto. El túmulo parecer ser de tierra con algunas piedras.','No se conoce','A criterio de Miguel Sierra, no merece la colocación de un hito. Hay una reseña de Gaztelu de la posible existencia de un dolmen en la loma SW. del monte Guratz. Posible error; debería ser la loma SE. Al hablar de una loma de tres promontorios hacia el pueblo de Huici. Según Patxi Ripa dice "conocerlo de antiguo" al no encontrar referencias del mismo le asigna el año 1942 y se da el nombre de Guratz.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(424,'URDOLA',5,'Cromlech','Leiza','Ladera septentrional de la cota Aizan, en el collado.','Leiza septentrional Hoja cartográfica 89-8','89-8',590640,4774050,740,43.111890,-1.887261,'utm','1981-01-25','domingo, enero 25, 1981','E.García, J.A.Gracía y F.Ubierna','Cromlech nº 1: Diámetro de 5,5 m. Compuesto de 11 testigos de pequeñas lajas y bloques que apenas sobresalen del terreno. No se observan testigos en el arco meridional. Ofitas del terreno. Es atravesado por una antigua pista forestal. Cromlech nº 2: Diámetro de 5 m. Compuesto de 28 testigos en forma de laja. Destacan 6 con altura entre 0,3 y 0,1 m. El resto , a nivel del terreno. No se observan testigos en el arco meridional. 5 testigos de ofitas del terreno y 23 testigos son de areniscas triásicas. Cromlech nº 3: Diámetro de 4,25. Compuesto de 22 testigos con forma de laja. Destacan 6 con altura entre 0,3 y 0,1 m. Areniscas triásicas. Cromlech nº 4: Diámetro de 5 m. Compuesto de 28 testigos en forma de laja. Destacan 14 con altura entre 0,77 y 0,1 m. El resto , a nivel del terreno. 1 laja es de ofitas del terreno y 27 testigos son de areniscas triásicas.','No se conoce','Los localizadores pertenecen a la sección de ciencias del Club Vasco de Camping de San Sebastián. Ellos lo comunicaron el hallazgo a Luis Del Barrio Bazako, quien lo publicó en marzo de 1983. En 1981 varios testigos fueron removidos sin que se pueda especificar cuáles, en un intento de resaltar el conjunto. El terreno en que se asientan es de ofitas, aunque prácticamente la totalidad de los tedtigos que los componen son de arenisca triásica. Este material aflora en una zona distante al menos 1 km. Bibliografía: L. Millan 1982. Kobie nº XV - 1985/86.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(425,'MENDIBIL',8,'Dolmen corto cerrado','Leiza','En la ladera SSW.; próximo a la cota Mendibil','Leiza septentrional Hoja cartográfica 89-8','89-8',591590,4775450,820,43.124380,-1.875355,'utm','1981-01-25','domingo, enero 25, 1981','E.García, J.A.Gracía y F.Ubierna','Dolmen corto cerrado. Túmulo rebajado y revuelto de 11 m. de diámetro y 0,5 m. de altura; formado por bloques, lajas y tierra. En la zona intermedia del túmulo afloran algunas lajas hincadas formando un estructura circular que contornea la cámara. Cámara cuadrada formada por 13 lajas que probablemente proceden de la exfolicación de otras más gruesas. El fondo de la cámara aparece enlosado por una laja en dirección 110º, que cubre prácticamente la mitad del mismo. Terreno, bajo esta laja y contorno, rebajado a 0,2 m. Cubierta original en su lugar, apoyada sobre una losa lateral y caída, en el otro extremo, hasta el fondo de la cámara. Las dimensiones de la cámara son 2,2 m. de largo por 2,1 m. de ancho y por 0,15 m. de profundidad. Está orientada a 110º. Materiales: areniscas triásicas del terreno.','No se conoce','Los localizadores pertenecen a la sección de ciencias del Club Vasco de Camping de San Sebastián. Ellos lo comunicaron el hallazgo a Luis Del Barrio. Éste publicó datos y croquis. Los datos geográficosque presenta Luis Del Barrio de Long. 01º 52´ 28´´ y Lat. 43º 07´ 31´´ se refieren a la hoja 1:25.000 I.G.N. (elipsoide internacional Hayford-Postan 1950) Proyección U.T.M. Datum Europeum. Meridiano Greenwich, extendión W. Diferente a las coordinadas que habitualmente se vienen danto sobre mapa a escala 1:50.000 del I.G.C. Merediano Madrid, de extensión E. Las hojas 1:10.000 correspondern a Mercator U.T.M. Latitudes refereidas al Ecuador, siendo positivas hacia el N. Longitudes referidas al meridiano de Greenwich, positivas hacia el E. Bibliografía: L. Millan 1982. Kobie nº XV - 1985/86.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(426,'ERROLE GAIN',9,'Dolmen largo abierto','Leiza','A unos 800 m. al E. de la cota Mendibil','Leiza septentrional Hoja cartográfica 89-4','89-4',592390,4775740,600,43.126894,-1.865474,'utm','1982-06-26','sábado, junio 26, 1982','J.M.Elosegui','Túmulo rebajado y revuelto de 7,5 m. de diámetro y 0,5 m. de altura; formado por bloques de buen tamaño. Cámara compuesta por 4 losas que forman recinto rectangular de paredes paralelas baculadas al interior y abierto en sus extremos. Cubierta formada por dos losas; una al E. que mide 1,6 m. por 1,35 m y por 0,15 m. y basculada al SE. hasta contactar con el túmulo; otra al W. de 1,25 m. por 0,6 m. y por 0,2 m., apoyada sobre dos losas de la cámara. Esta última losa parece haber sido colocada con posterioridad a la construcción del dolmen con el fin de aprovechar el recinto de cámara como refugio de animales domésticos, removiéndose para ello parte del túmulo. Interior de la cámara rebajado 0,35 m. en relación con lo que se conserva del túmulo. Orientación: 70º. Materiales de construcción de la cámara: areniscas triásicas del terreno. El túmulo añade algún conglomerado triásico y bloques de cuarzo de las proximidades.','No se conoce','Sobre los datos geográficos, véase la nota del domen Mendibil. Existe un comunicado de Luis Millan que señala como fecha de localización el 12-0-1981. Habla sobre un dolmen de Erroia y a una altura de 550 m. Lo localiza así: "nada más cruzar la erreka y llegar a la borda, se puede ver el dolen aproximadamente a unos 100 m. a la derecha. El túmulo tiene 7 m. de diámetro y 1 m. de alto; doble cámara con 5 losas hincadas y varias sueltas. Tapa con dostrozos " in situ" y otro basculado al S. Interior de la cámara mide 0,5 por 3,3 m. Losas hincadas al N.: 0,9 m. alto; 1,4 m. largo; 10/12 cm. grosor. 1,2 " ; 1,7 m. " ; 20/30 cm. " 0,75 " ; 0,55 m. " ; 10 cm. " 2 losas al S,: 0,5 " ; 1,1m. " ; 10 cm. " 0,8 " ; 1,5 m. " ; 15/20 cm. " Cubierta N.: 0,9 " ; 0,8 m. " ; 20 cm. " Cubierta S,: 1,1 m. de N.a S.; 1,5 m. de E. a W.; 15/20 cm. de grueso. Bibliografía: L. Millan Pyrenaica nº 127. Kobie nº XV - 1985/86.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(427,'BIUZTAIN IPAR',1,'Dolmen','Leiza','200 m. al W. de la cota Baztarla o Biuztain (936)','Leiza noroeste Hoja cartográfica 89-8','89-8',589230,4772680,932,43.099723,-1.904808,'utm',NULL,'lunes, abril 03, 1905','J.M.Barandiaran','Dolmen. Túmulo circular con cráter central donde aparece una losa en la cámaa destruida. Areniscas del terreno. Orientación de la cámara E-W. Según informe de M.Sierra y Carmen Ballesteros, de fecha 24-2-1990, el túmulo es prácticamente inapreciable. La losa de la cámara tiene orientación E-W y mide 1,5 m. de largo; 0,25 m. de grueso y 0,65 m. de altura; en la parte E. asoma una pequeña losa de 0,55 x 0,05 x 0,15 m.; hay algún trozo de losa cercano. El conjunto es de areniscas.','No se conoce','En su reseña, Barandiaran lo pone como dudoso. Bibliografía: Munibe 1973. Suplemento nº 1.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(428,'BIUZTAIN HEGO',2,'Túmulo','Leiza','A 30 m. de Biuztain Ipar','Leiza noroeste Hoja cartográfica 89-8','89-8',589260,4772640,932,43.099359,-1.904446,'utm',NULL,'lunes, abril 03, 1905','J.M.Barandiaran','Túmulo circular de 10 m. de diámetro y 0,6 m. de altura. Cráter central sin losas. Areniscas del terreno. Según informe de Miguel sierra y Carmen Ballesteros de fecha 24-2-1990 el túmulo está formado por piedras de regular tamaño.','No se conoce','Bibliografía: Munibe 1973. Suplemento nº 1.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(429,'IRUMOA',5,'Cromlech','Beruete','Al S. del collado de Iontza (borda nueva)','Basaburua Mayor - Beruete NW.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(430,'ORIN',1,'Dolmen (derruido)','Beruete','A 1,5 km. Al NNW. de los pastos de Iontza.','Basaburua Mayor - Beruete NW. Hoja cartográfica 89-12','89-12',593180,4767760,1064,43.054952,-1.857102,'utm','1951-10-06','sábado, octubre 06, 1951','Jesús Elósegui','Situado en un prominente altito, rodeado de galgal de poca elevación. Dos losas forman un desfigurada cámara. Orientado a 72º. Losa meridonal desgajada. Losas y galgao de piedra caliza.','No se conoce','Catalogado en Munibe con elnº 54-7, reseñando que "solamente queda una losa y un fragmento de otra". Visitada la zona en diciembre de 1989 se comprobó que los datos de ubicación no se ajustaban a su emplazamiento real, situándolo tal y como queda más arriba reflejado. En vista del aspecto que presenta, no se considera nerecedor de un hito señalizador. Bibliografía: Munibe 1973. Suplemento nº 1.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(431,'LAONTZEKO LEPOA - BI AIZPEN SEPULTURE',1,'Dolmen de doble cámara','Beruete',NULL,'Basaburua Mayor - Beruete NW. Hoja cartográfica 90-9','90-9',594240,4767400,1170,43.051580,-1.844149,'utm',NULL,'domingo, abril 09, 1905','J.M.Barandiaran','Dolmen corto abierto de doble cámara. Túmulo de 12 m. de diámetro y 1 m. de altura. Cámara de 4 losas con recinto rectangular. Calizas del terreno.','No se conoce','El collado donde se encuentra el dolmen es conocido también como Letzegi. El nombre Bi Aizpen fue puesto por Barandiaran atendiendo sin duda a una leyenda. En la placa colocada por Gorosti con fecha 7-10- 1989, se respetan ambos topónimos. Munibe lo cataloga con el nombre de la leyenda y le da el nº 54-2. Bibliografía: Munibe 1973. Suplemento nº 1.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(432,'BEIGANE',1,'Dolmen','Arraras','En la cumbre de su nombre, al N. de Arraras (680 m.)','Basaburua Mayor - Arraras Hoja cartográfica 90-9','90-9',597640,4767060,1110,43.048090,-1.802469,'utm',NULL,'miércoles, mayo 10, 1905','Jesús Elósegui','Túmulo rebajado y desfigurado. Una losa vertical sobre el túmulo. Al N. y S. de ella hay gragmentos sueltos de carácter dudoso. Calizas del terreno.','No se conoce','Catalogado en Munibe con el nº 54-19 Bibliografía: Munibe 1973. Suplemento nº 1.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(433,'ZURITU BERRI (PATATALOR) (PAYO)',7,'Dolmen corto abierto','Igoa',NULL,'Basaburua Mayor - Igoa Hoja cartográfica 90-9','90-9',600010,4767000,960,43.047241,-1.773387,'utm',NULL,'miércoles, mayo 10, 1905','Jesús Elósegui','Túmulo circular de 7 m. de diámetro y de 0,4 m. de altura. Cámara de tres losas con recinto rectangular. Orientación a 112º. Calizas del terreno.','No se conoce','Catalogado en Munibe con el nº 54-17, con el topónimo Patat - Alor. Patxi Ripa y Petete Sarobe lo corrigen, denominándolo Zuritu Berri. En posteriores verificaciones, Francisco Ondarra y L. Millan encuentran como verdadero nombre "Payo". Siguiendo las normas de Euskaltzaindia de respetar los topónimos con cien años de uso y estanto en la zona de su monbre, vemos como necesario el cambio de topónimo, entendiendo el anterior como un erro. Bibliografía: Munibe 1973. Suplemento nº 1. Patxi Ripa: Gure Mendiak nº 76.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(434,'PALLO',1,'Dolmen','Saldias','En una loma al N. de Gora (801 m.); entre Saldias y Beintza - Labayen','Basaburua Menor - Saldias Hoja cartográfica 90-6','90-6',600340,4771900,690,43.091312,-1.768452,'utm',NULL,NULL,'Patxi Ripa','Túmulo de unos 12 m. de diámetro de tierra y piedras pequeñas dispersas. Dos grandes piedras en pie, de material calizo, que se cierran al NE. Al E.de las mismas otro bloque de conglomerado de piedrecillas rodadas. La piedra del NW. Titen forma rara para considerarla como losa.','No se conoce','Catalogado en Munibe con el nº 54-17, con el topónimo Patat - Alor. Patxi Ripa y Petete Sarobe lo corrigen, denominándolo Zuritu Berri. En posteriores verificaciones, Francisco Ondarra y L. Millan encuentran como verdadero nombre "Payo". Siguiendo las normas de Euskaltzaindia de respetar los topónimos con cien años de uso y estanto en la zona de su monbre, vemos como necesario el cambio de topónimo, entendiendo el anterior como un erro. Bibliografía: Munibe 1973. Suplemento nº 1. Patxi Ripa: Gure Mendiak nº 76.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(435,'AZERILAR',8,'Dolmen corto cerrado','Beruete','A unos 250 m. al SE. De Leiza en la loma de su nombre, en el monte ¿Arretz?, debajo de Kornita a 850 msm.',NULL,NULL,NULL,NULL,NULL,43.061721,-1.868227,'gpx',NULL,'miércoles, abril 05, 1905','J.M.Barandiaran','Dolmen corto cerrado. Túmulo de 10 m. de diámetro y 1 m. de altura; de piedras. Cámara de 4 losas con recinto rectangular casi cuadrado. fue violado en 1925','No se conoce','Patxi Ripa y Sarobe estiman que son confusas las orientaciones que se dan para su localización. En la fuente doble de Kornieta una alambrada separa ambos abrevaderos y los términos de Beruete y Leiza. De la puerta en la misma, situada al sur, recorrer 45 pasos en líenea recta al W. para hallarlo al pie de un pino albar. Sierra el 10-02-1990 no lo encontró. La reseña de Munibe dice: "En término municipal de Beruete. A unos 250 m. al SE. De Leiza en la loma de su nombre, en el monte ¿Arretz?, debajo de Kornita a 850 msm." Bibliografía: "RIEV" San Sesbastián 1926. Pág 356-358. Estaciones Megalíticas.',NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(436,'AGORRITZ',1,'Dolmen',NULL,NULL,NULL,NULL,NULL,NULL,NULL,43.056781,-1.869677,'gpx',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'10 Larraun Alto - Leiza - Basaburua Mayor'),
(437,'IPAR IGARATZA',1,'Dolmen','Unión Aralar - Enirio (Guipúzcoa)','Junto al prado de Perileku y camino que sube de Amezketa','Corto. Pago Mari, Intzazelai, Errenaga, Igaratza, Trikuarri Hoja cartográfica nº 114-2','114-2',578260,4760420,1195,42.990549,-2.041315,'utm',NULL,'jueves, marzo 30, 1905','Jose Miguel Barandiaran','Cámara definida en la que se ve una losa lateral y otra, posiblemente la de cubierta, desplazada. El monumento no está bien conservado. De la excavación se conoce: - 1 esquirla de sílex y piedras ennegrecidas. - 1 muela humana. - 1 muela animal. Colección de la Sociedad de Ciencias Aranzadi de San Sebastián. Museo de San Telmo.','En 1923 por T. Aranzadi y J.M.Barandiaran','Aunque el dolmen pertenece al Aralar guipuzcoano, se incluye en los itinerarios de Navarra por encontrarse muy accesible y por ser uno de los primeros que fueron excavados, de forma anárquica por ser los medios y las técnicas atrasadas. Entonces no lo fueron. Se indican dos itinerarios solamente por dar una orientación al que no conozca bien la Sierra de Arala; en realidad se pueden hacer otros itinerarios y muy variados. Bibliografía: - Barandiaran, J.M.: Prehistoria vasca (1961) 561 - " Discurso leído (1917) 501 - " El mundo … (1961) 166 y ss - Aranzadi, T.: Exploración de Aralar (1924)',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(438,'HEGO IGARATZA',11,'Dolmen poligonal','Unión Aralar - Enirio (Guipúzcoa)','Junto al prado de Perileku y camino que sube de Amezketa','Corto. Pago Mari, Intzazelai, Errenaga, Igaratza, Trikuarri Hoja cartográfica nº 114-2','114-2',578180,4760310,1195,42.989566,-2.042311,'utm',NULL,'jueves, marzo 30, 1905','Jose Miguel Barandiaran','Cámara de 8 losas movidas en parte, que fue recinto casi exagonal. Reseña de fecha localización, ver figura. Losa baja como de ventana y cubierta desplazada. En 1958 las losas se han desordenado y la cubierta ha desaparecido. Orientación al E. s/ T.Aranzadi y J.M.Barandiaran. Calizas del terreno en túmulo y 6 losas; areniscas de un afloro al S. de Igaratza en dos losas de cámara.','En 1923 por T. Aranzadi y J.M.Barandiaran','Ver en observaciones de Ipar Igaratza, comentarios de itinerarios similares. Bibliografía: - Barandiaran, J.M.: Prehistoria vasca (1961) 561 - " Discurso leído (1917) 501 - " Hombre prehistórico (1953) - " El mundo … (1961) 166 y ss - Aranzadi, T.: Exploración de Aralar (1924) - Pericot, L: Sepulcros megalíticos. (1950) - Arnal, J.Petit: Lexique du megalitisme (1956)',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(439,'IGARATZA',13,'Monolito','Unión Aralar - Enirio (Guipúzcoa)','Junto al prado de Perileku','Corto. Pago Mari, Intzazelai, Errenaga, Igaratza, Trikuarri Hoja cartográfica nº 114-2','114-2',578415,4760310,1200,42.989542,-2.039429,'utm',NULL,NULL,NULL,'Monolito tendido sobre el terreno con forma de laja de 3,4 m. de largo y partido en dos, estando separadas ambas parte entre 0,1 m. y 0,3 m. entre si. La cara 1 o superior del bloque mayor tiene una anchura que oscila entre 1,2 m. y 1,5 m. La cara 2 tiene la misma longitud y grosor que destaca sobre el terreno entre 0,15 m. en su extremo SE. Y 0,25 m. en su extremo opuesto, siendo la anchura de la mayor parte de esta cara de 0,3 m. La cara 3 con la misma longitud tiene un grosor medio de 0,25 m. El bloque menor tiene unas dimensiones de 0,8 m. de largo por 0,8 m. de ancho y entre 0,15 y 0,25 m. de grosor. Este bloque menor parece coincidir con el extremo SE. del bloque mayor. La orientación del eje mayor es de 160º. Su estado de conservación es malo. No existe ningún grabado o marca visible.','En su derredor se ha practicado una zanja de 0,13 m. de profundidad. Se desconoce el autor de la excavación.','Datos de Xabier Peñalver. Munibe 1983 nº 35 Bibliografía: Luis Millan y Arantxa Lizarralde (1982) El monolito se encuentra tendido junto al sendero que sube por el prado de Perileku; en el collado hacia la loma de Trikuarri.',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(440,'BEASKIN',2,'Túmulo. ¿Dolmen?','Unión Aralar - Enirio (Guipúzcoa)','A 800 m. al NW. de los refugios de Errenaga (Igaratza)','Corto. Pago Mari, Intzazelai, Errenaga, Igaratza, Trikuarri Hoja cartográfica nº 114-2','114-2',577710,4759845,1157,42.985428,-2.048141,'utm',NULL,'viernes, marzo 31, 1905','J.M.Barandiaran','Túmulo poco definido como dolmen.','No se conoce','Incluido en los itinerarios por el Aralar Navarro, con el fin de dar una información más completa.',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(441,'TRIKUARRI TRIKUHARRI',1,'Dolmen corto ?','Terrenos de realengo de Aralar. Erregeneko Aralar.','En el collado de su nombre a 15 m. de la divisoria Navarra - Guipúzcoa','Corto. Pago Mari, Intzazelai, Errenaga, Igaratza, Trikuarri Hoja cartográfica nº 114-2','114-2',577710,4759845,1157,42.985428,-2.048141,'utm',NULL,'jueves, marzo 30, 1905','J.M.Barandiaran','Cámara con una losa en pie y otra caída, opuestas. Al pie del túmulo otra losa caída ¿la cubierta? Orientación al E. Ajuar encontrado en la excavación: - nº 1: 1 hoja simple de sílex - nº 2: 9 las lascas de sílex - n º3: 1 cuenta de piedra de tonelete pasando a globular - 2 cristales de roca - restos humanos de al menos 7 inhumados (objetos modernos) colección de la Sociedad de Ciencias Naturales Aranzadi. San Sebastián. Museo de San Telmo.','T.Aranzadi, J.M.Barandiaran y E.Eguren en 1923','Este dolmen tiene un hito de identificación colocado, por lo que Gorosti no lo colocó, al igual que hizo en los demás dólmenes de la zona de Navarra. Este dolmen es muy visitado por encontrarse en el camino que asciende a la cima de Irumugarrieta. Se hace necesario hacer una medición',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(442,'IPAR OBIONETA',8,'Dolmen corto cerrado','Terrenos de realengo de Aralar. Erregeneko Aralar.','Junto al camino que va desde Trikuarri al pozo de Unaga','Pago Mari Hoja cartográfica nº 114-2','114-2',579820,4760120,1205,42.987685,-2.022224,'utm',NULL,'jueves, marzo 30, 1905','J.M.Barandiaran','Cámara de recinto trapezoidal. Orientación 110º. Trozos rotos de tamaño considerable ¿cubierta rota? alrededor del túmulo; como unos 12 trozos y alguna piedra pequeña. Ajuar: - 1 hoja de sílex - 1 hoja de escotadura retocada fina - 1 cuenta discoidea de piedra verde - 1 punzón de tipo brújula, pequeño, no analizado - 4 colgantes en hueso casi rectangulares; uno un poco ovalado - restos humanos de al menos 4 inhumados; de elllos un infantil. Colección de la Sociedad de Ciencias Aranzadi de San Sebastián. Museo de San Telmo.','T.Aranzadi, J.M.Barandiaran y E.Eguren en 1923','Previsto para hacer una medición. Bibliografía: - Barandiaran, J.M.: Mitología… (1923-24) 100 - Las cuevas... (1926) pág 7 y 16 - " Hombres prehistóricos (1953) - Aranzadi, T.: Exploración de Aralar (1924) - Eguren, E.: Nuevas investigaciones (1927) 17-33 - Pericot, L: Sepulcros megalíticos. (1950) - " La España primitiva (1950) pág 374',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(443,'HEGO OBIONETA',8,'Dolmen corto cerrado','Terrenos de realengo de Aralar. Erregeneko Aralar.','A 60 m. al SW del dolmen Ipar Obioneta; al ENE. Del alto de Logorrita.','Pago Mari Hoja cartográfica nº 114-2','114-2',579760,4760050,1206,42.987062,-2.022970,'utm',NULL,'jueves, marzo 30, 1905','J.M.Barandiaran','Cámara de recinto rectangular. Orientación 85º. Cámara empedrada con lajas formando el suelo. En la fecha de su localización el monumento tenía 5 losas. Calizas del terreno. Túmulo de 13,7 m. de diámetro y 2 m. de altura. Colección de la Sociedad de Ciencias Aranzadi de San Sebastián. Museo de San Telmo.','T.Aranzadi, J.M.Barandiaran y E.Eguren en 1923','Previsto para hacer una medición. Bibliografía: - Barandiaran, J.M.: Mitología del pueblo… (1923-24) 100 - Las cuevas... (1926) pág 7 y 16 - " El mundo... (1961) - Aranzadi, T.: Exploración de Aralar (1924) - Elósegui, J.: Nuevos datos obioneta (1949) 3-6 - Pericot, L: Sepulcros megalíticos. (1950) 374 - " La España primitiva (1950) pág 374 - Junghans, S.: Kupfer und Bronze (1968) 36 y 37 - Sangmeister, E.: Contribución… (1961) pág 49-55',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(444,'OTSOTESARE',7,'Dolmen corto abierto','Terrenos de realengo de Aralar. Erregeneko Aralar.','A la izquierda de la pista a Pago Mari. Y de Arbazazu - Arratea, cercano.','Pago Mari Hoja cartográfica nº 114-2','114-2',579650,4757360,1108,42.962853,-2.024702,'utm',NULL,'miércoles, marzo 29, 1905','T. Aranzadi y F. Ansoleaga','Cámara con recinto reatangular y loas losas que tienden a cerrarse a la entrada. Sin cubierta. Orientación a 105º. En el túmulo crecen dos hayas. 3 losas en cámara; calizas del terreno; túmulo rebajado.','En 1915 por T. Aranzadi y F. Ansoleaga. Restos humanos de un inhumado.','Previsto para hacer una medición. Bibliografía: - Aranzadi, T.: Exploración de Aralar (1918) - Barandiaran, J.M.: Hombre prehistórico… (1953)',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(445,'OTSOTESARE - II',2,'Túmulo','Terrenos de realengo de Aralar. Erregeneko Aralar.','Junto a la pista forestal; a 15 m. de la pared divisoria con Lakunza','Pago Mari Hoja cartográfica nº 114-2','114-2',579945,4757355,1117,42.962777,-2.021086,'utm',NULL,'domingo, mayo 07, 1905','J.Elosegui','Es dudosa la catalogación como dolmen. El túmulo está formado por piedras. Cráter central sin losas de cámara.','No se conoce','Difícil de localizar; la zona tiene otros promontorios que hacen dudar. Bibliografía: Elosegui, J.: Prospecciones dolménicas (1956) 134',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(446,'ALBIA',7,'Dolmen corto abierto','Terrenos del realengo de Aralar. Erregeneko Aralar.','Junto a la carretera que desde Baraibar sube a San Miguel, hacia el km. 12.','Albia - N Hoja cartográfica nº 114-3','114-3',581780,4757175,990,42.960961,-1.998617,'utm',NULL,'miércoles, marzo 29, 1905','T. Aranzadi y F. Ansoleaga','Cámara de 3 losas con recinto rectangular y paredes que tienden a cerrarse en la entrada. Cubierta desplazada hacia el N. Orientación a 90º. Ajuar encontrado en la excavación: - 1 nódulo de hematites - 1 concha fósil - 1 lasca informe de sílex - 3 cuentas de piedra azul verdosa translúcida, de disco - restos de animales, entre ellos roedores. - restos humanos de dos inhumados. Museo de Navarra. Pamplona.','En 1915, por T. Aranzadi y F. Ansoleaga','Previsto para realizar medición Bibliografía: - Aranzadi, T.: Exploración de Aralar (1918) - Barandiaran, J.M.: Hombre prehistórico… (1953)',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(447,'ALBIA ZUTARRIA',13,'Monolito','Terrenos del realengo de Aralar. Erregeneko Aralar.','Enfrente y al otro lado de la carretera donde se ubica el dolmen Albia','Albia - N Hoja cartográfica nº 114-3','114-3',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'José Mª Gamboa de Arruazu','Piedra inhiesta de unos 55 cm. sobresaliendo del suelo; de forma rectangular, que parece haber sido trabajada en sus cuatro caras. Tiene grabadas dos cruces.',NULL,'Es posible que trate de un (mojón) señalizador, de la misma época ?',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(448,'OTADI',7,'Dolmen corto abierto','Terrenos del realengo de Aralar. Erregeneko Aralar.','A poco más de 200 m. a la izquierda del camino de Albia a Urdan. Itin. Albia N.','Albia - N Hoja cartográfica nº 114-3','114-3',580890,4757350,1030,42.962632,-2.009502,'utm',NULL,'sábado, mayo 06, 1905','J. Elosegui y C. Menaya. J. Zubiaur.','Cámara de recinto triangular. Faltan losas y la cubierta. 4 losas camerales. Calizas. Túmulo de 8 m. de diámetro y 0,8 m. de alto. Orientación a 90º. En terrenos de margas.','No se conoce','Previsto para medición Bibliografía: - Barandiaran, J.M.: Hombre prehistórico… (1953)',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(449,'LERRITZ',7,'Dolmen corto abierto?','Terrenos del realengo de Aralar. Erregeneko Aralar.','En la loma oriental del monte Txemiñe','Albia - N Hoja cartográfica nº 114-3','114-3',581235,4758970,1233,42.977181,-2.005037,'utm',NULL,'viernes, mayo 19, 1905','Tomás López Sellés','Cámara reducida a tres losas casi cubiertas por el túmulo, des figurado y de 8 m. de ?. Orientación E.W.','No se conoce',NULL,NULL,'4 Sierra de Aralar - Cental y Occidental'),
(450,'GARRASTITA',7,'Dolmen corto abierto','Terrenos del realengo de Aralar. Erregeneko Aralar.','A 250 m. al NNW del pozo de Unaga. Unagoko Putzua.','Albia - N Hoja cartográfica nº 114-3','114-3',580520,4760035,1180,42.986846,-2.013651,'utm',NULL,'miércoles, marzo 29, 1905','T. Aranzadi y F. Ansoleaga','Cámara de tres losas que se estrechan formado un recinto casi triangular. Calizas del terreno. El túmulo de cantos circular de 8 m. de ? y 1 m. de altura. Orientación a 190º. Ajuar en contrado en la excavación: - 1 hachita de firolita pulimentada con contera rota y sección ovalada - 1 cristal de roca facetado - 1 fragmento de horquilla de cuerno - restos humanos de un inhumado Colección de la Sociedad de Ciencias Aranzadi de San Sebastián. Museo de San Telmo.','Por T. Aranzadi, J.M. Barandiaran y E. Eguren en 1923','La localización del dolmen resultó tan difícil que prácticamente se volvió a descubrir en 1917 por J.M.Barandiaran. Previsto para medición. Bibliografía: - Aranzadi, T.: Exploración de Aralar (1924) - Pericot, L: Sepulcros megalíticos. (1950) 374 - Atauri, T.: Exploración de …. Igoin - Akola (1951)',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(451,'MAANTSA - ZEAUNTZA',7,'Dolmen corto abierto?','Terrenos del realengo de Aralar. Erregeneko Aralar.','A 350 m. al NW del dolmen de Garrastita','Albia - N Hoja cartográfica nº 114-3','114-3',580225,4760205,1193,42.988408,-2.017245,'utm',NULL,'miércoles, marzo 29, 1905','T. Aranzadi y F. Ansoleaga','Cámara de 5 losas con recinto rectangular, de las que tres se han movido y dejan decidir mal la planta. Cubierta desplazada. Calizas del terreno. El túmulo de 11 m. de ? y 1 m. de altura. Orientación a ESE. Hoy se abre hacia 300º. Ajuar en contrado en la excavación:- restos humanos de un inhumado Colección de la Sociedad de Ciencias Aranzadi de San Sebastián. Museo de San Telmo.','Por T. Aranzadi, J.M. Barandiaran y E. Eguren en 1923','En 1915 se le denomió Zeauntza. En 1923 lo dieron como Maantsa T. Aranzadi, J.M. Barandiaran y E. Eguren Previsto para medición. Bibliografía: - Aranzadi, T.: Exploración de Aralar (1924) - Barandiaran, J.M.: Hombre prehistórico… (1953)',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(452,'ZEONTZA',9,'Dolmen largo abierto','Terrenos del realengo de Aralar. Erregeneko Aralar.','A 320 m. al SSW del dolmen Maantsa','Albia - N Hoja cartográfica nº 114-3','114-3',580070,4759865,1218,42.985363,-2.019195,'utm',NULL,'miércoles, marzo 29, 1905','T. Aranzadi y F. Ansoleaga','Hoy varias de las losas están derribadas y la reconstrucción de la planta no es fácil. Unas de las losas parece iniciar una pared de cierre. 8 losas en cámara. Sin cubierta. Calizas. Túmulo de 14 m. ? y 0,5 m. de altura. Terreno de margas y areniscas. Orientación actual a 270º? Ajuar de la excavación: - 1 fragamento de hoja de sílex - 1 pitón de cuerno de ciervo - restos humanos de 8 inhumados - restos de pequeños mamíferos En la colección de la Sociedad de Ciencias Aranzadi de San Sebastián se encuentran: - 1 raspador en morro? sobre extremo de hoja - 1 lasca con frente de raedera o raspador atípico - 1 botón prismático con perforación doble en V','Por T. Aranzadi, J.M. Barandiaran y E. Eguren en 1923','En 1915 se le denomió Zeauntza. En 1923 lo dieron como Maantsa T. Aranzadi, J.M. Barandiaran y E. Eguren Previsto para medición. Bibliografía: - Aranzadi, T.: Exploración de Aralar (1924) - Barandiaran, J.M.: Hombre prehistórico… (1953)',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(453,'ATAKAZAR',1,'Dolmen ?','Terrenos del realengo de Aralar. Erregeneko Aralar.','A unos 20 m. al N. del collado Ataka-xar, cerca de gran agujero','Albia - N Hoja cartográfica nº 114-3','114-3',582450,4759740,1174,42.983984,-1.990025,'utm',NULL,'miércoles, mayo 21, 2442','Luis Millan','Cámara de losas rostas y revueltas ?. Túmulo arruinado por el W-S, elevándose 0,5 m. por el lado E. En la actualidad no tiene todo el aspecto requerible para un dolmen, conserva algún rasgo parecido. El nombre dado por el localizador fue de Ataka-Xar y rectificado por la Real Academia de la Lengua Vasca. La reseña de Milan es la siguiente: ? túmulo por el E, 1/2 m. 4,8 m. de S-N y 6,4 m. de E-W. En la cámara restos de 5 losas, que miden: losa N, 0,8 m. de largo, por 0,5 m. de alto. La losa E. 0,6 m. de largo y 0,75 m. de alto. La losa S, mi de 0,5 m. de alto y 0,5 m. de largo , y las dos losas del W, miden 0,4 m. de alto y 1 m. largo un y la otra 0,25 m. de largo y 0,8 m. de alto. El grosor de las losas oscila entre 0,05 m. y 0,1 m.','No se conoce','Lo que se ve, no es merecedor por sí solo de distinción de dolmen, el lugar donde se emplaza tampoco reune de forma clara lo que habitualente nos decen el emplazamiento de otros dólmenes. En atención al crédito reconocido como prospector de Luis Millan, socio de Gorosti, se le colocó el hito de señalización el 21 de abril de 1985. La situación indicada por Millan es la siguiente: Emplazado a 25 m. al N del collado de Ataka-zar, entre el monte Beloqui al S. y el Tuturre al N. La pradera de Ezanda se halla al E. y la majada de Irulizarreta y el collado de Atallun al S. Bibliografía: - Millan, L.: Pirenaica nº 127, pág. 83. 1982 - Millan, L., Lizarralde, A.: La Sierra de Aralar. 1982. Pág. 71',NULL,'4 Sierra de Aralar - Cental y Occidental');
INSERT INTO `megalitos` (`id`,`nombre`,`tipologia_id`,`tipologia_texto`,`municipio`,`ubicacion`,`itinerario_texto`,`hoja_cartografica`,`utm_x`,`utm_y`,`altitud`,`lat`,`lon`,`coord_fuente`,`localizado_fecha`,`localizado_fecha_texto`,`localizado_autor`,`descripcion`,`excavacion`,`observaciones`,`caracteristicas`,`otros_aspectos`) VALUES
(454,'ARRATE - XAR',2,'Túmulo','Terrenos del realengo de Aralar. Erregeneko Aralar.',NULL,'Albia - N Hoja cartográfica nº 114-3','114-3',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Luis Millan San Emeterio',NULL,NULL,'No es seguro que tenga carácter funerario. Se espera más información del mismo.',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(455,'MURUKO HARRIPILA - MUKURUKU',1,'Dolmen ?','Terrenos del realengo de Aralar. Erregeneko Aralar.','En la ladera occidental del monte Arriolatz, rodeado de txozas pastoriles.','Albia - N Hoja cartográfica nº 114-3','114-3',583450,4759960,1135,42.985856,-1.977729,'utm',NULL,'jueves, mayo 04, 1905','J.Elosegui','Cráter central en túmulo sin losas de cámara. Túmulo de 15 m. de ?, con piedras de caliza. Tiene poco aspecto de monumento funerario, por lo que no se ha señalizado con hito. Es posible hacerlo se se arregla de forma que adquiera más aspecto.','No se conoce','Previsto para estudiarlo más a fondo y ver si merece la pena señalizarlo. Las txabolas que lo rodean son : Olatxiki, Palleti, Urdanote y Alborta, que sitan en radio muy poco. Bibliografía: - Elosegui, J.: Cinco nuevos dólmenes… 1951 ss. - Barandiaran, J.M.: Hombre Prehistórico… 1953.',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(456,'MOZKORDI',7,'Dolmen corto abierto ?','Terrenos del realengo de Aralar. Erregeneko Aralar.','Al SE de la altura de la cota y a la izq. del camino','Albia - N Hoja cartográfica nº 114-3','114-3',582565,4756960,1065,42.958941,-1.989025,'utm',NULL,'miércoles, marzo 29, 1905','T. Aranzadi y F. Ansoleaga','Túmulo de difícil precisión, de 13 m. de ? rebajado. Cámara de cuatro losas de recinto rectangular, con una losa que tiende a cerrar el recinto a modo de trapecio. Losas sueltas al N, S y E. Sin cubierta. Losa de la cabecera apuntada. Calizas del terreno. Orientación a 70º.','No se conoce','La cámara fue vaciada y se encontró un hacha de esquisto dura de tipo rectangular un poco ovalado y sección oval. Propiedad privada s/Apillaniz. Previsto para medición. Bibliografía: - Aranzadi, T.: Exploración de Aralar… 1918 - Barandiaran, J.M.: Hombre Prehistórico… 1953.',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(457,'ZUBARRIETA',7,'Dolmen corto abierto ?','Terrenos del realengo de Aralar. Erregeneko Aralar.','Al NNW del dolmen Mozkordi y a 100 m. del camino de Baraibar a Arruazu.','Albia - N Hoja cartográfica nº 114-3','114-3',583369,4757180,1035,42.960834,-1.979136,'utm',NULL,'miércoles, marzo 29, 1905','T. Aranzadi y F. Ansoleaga','Túmulo de 13 m. de ? y 1 m. de alura. rebajado. Cámara de cuatro losas de recinto rectangular que tiende a estrecharse en la entrada. Calizas del terreno. Orientación a 93º.','No se conoce','Previsto para medición. Bibliografía: - Aranzadi, T.: Exploración de Aralar… 1918 - Barandiaran, J.M.: Hombre Prehistórico… 1953.',NULL,'4 Sierra de Aralar - Cental y Occidental'),
(458,'ANSARETAKO ZAPARRA',1,'Dolmen largo ?',NULL,NULL,'Lizarrusti Hoja cartográfica nº 114-3','114-3',NULL,NULL,NULL,42.972957,-2.071099,'gpx',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'4 Sierra de Aralar - Cental y Occidental'),
(459,'OLABERTA',10,'Dolmen largo cerrado','Huarte Araquil','En el paraje de su nombre; a 1,7 km. a 280º NW del Santuario','Guardetxe-E Hoja cartográfica 114-7','114-7',582700,4755965,1015,42.949968,-1.987517,'utm',NULL,'jueves, marzo 09, 1905','J.Iturralde y Suit','Cámara de recinto rectangular, hoy un tanto poligonal. Cubierta partida que lleva un surco o canal de 9 cm. de ancho y que primitivamente debía de tener una longitud de 1,3 m. y parte del centro para llegar hasta el borde occidental. Aranzadi y Ansoleaga lo interpretaron como un reguero de sacrificio. J.M.Barandiaran lo considera artificial. Hoy parece natural. Orientación a 120º. Ajuar encontrado en la excavación: - 2 nódulos de hematites. - 3 láminas de sílex. - 1 fragmento de punta de flecha de metal no analizado. - varios fragmentos de cerámica de varios vasos - 1 cuenta de cuerno - huesos humanos de más de 11 inhumados. En el Musero de Navarra de Pamplona se conservan como pertenecientes los siguientes objetos: - 2 hojas de sílex partidas - 1 hoja rota con dos escotaduras retocadas, una muy ligera en el margen derecho. - 1 cuenta de piedras de tipo tonelete - 1 fragmento de borde y cuello con arranque de panza de vaso mediano ovóideo de cuello corto. -1 fragmento de borde y arranque de panza de vaso ovoide? con verdugón liso y tal vez de cuello vuelto. - 1 fragmento de borde liso inidentificable - 1 fragmento de panza de vaso ovóideo - varios de cerámica informes. - huesos de animales.','T.Aranzadi y F.Ansoleaga en 1915.','Previsto para su medición. Bibliografía: - Iturralde, J.: La prehistoria en Navarra. 1911 - Aranzadi, T.: Exploración de… Aralar. 1918 - " Los gentiles de Aralar. 1919 - Barandiaran, J.M.: Huellas de arte. 1935. Pág. 375-426 - " Hombre prehistórico. 1953 - Pericot, L.: Los sepulcros megalíticos. 1950. Pág. 273',NULL,'Bloc 3. Sierra de Aralar meridional'),
(460,'DEBATA ARRUAZU.I',9,'Dolmen largo abierto?','Arruazu','En el collado entre Debata y Saldiasgain; a 2,2 al W del Santuario','Guardetxe-E Hoja cartográfica 114-7','114-7',582035,4756135,1082,42.951570,-1.995643,'utm',NULL,'sábado, mayo 06, 1905','J.Elosegui','Cámara con recinto rectangular con 5 losas, dos de ellas desplazadas. Túmulo de 12 m. de ? y 1 m. de altura. Calizas del terreno. Orientación a 85º.','No se conoce','Previsto para su medición. Bibliografía: - Aranzadi, T.: Exploración de… Aralar. 1918 - Barandiaran, J.M.: Hombre prehistórico. 1953 - Pericot, L.: Los sepulcros megalíticos. 1950.',NULL,'Bloc 3. Sierra de Aralar meridional'),
(461,'DEBATA ARRUAZU.II',9,'Dolmen largo abierto','Arruazu','En el collado entre Debata y Saldiasgain; a 120 m. al NE de Debata.I','Guardetxe-E Hoja cartográfica 114-7','114-7',582145,4756190,1065,42.952053,-1.994287,'utm',NULL,'miércoles, marzo 29, 1905','T.Aranzadi y F.Ansoleaga','Cámara con recinto rectangular con 3 losas y cubierta en tres trozos partida con dinamita . Túmulo de piedras de 18 m. de ? y 2,3 m. de altura. Calizas del terreno. Orientación a 120º.','T.Aranzadi y F.Ansoleaga en 1915.','En los años 1982 y 1984 se viene notando que algún aprovechado ha sustraído piedras del túmulo. Se ha denunciado en prensa y radio este hecho. Previsto para su medición. Bibliografía: - Aranzadi, T.: Exploración de… Aralar. 1918 - Barandiaran, J.M.: Hombre prehistórico. 1953 - Pericot, L.: Los sepulcros megalíticos. 1950.',NULL,'Bloc 3. Sierra de Aralar meridional'),
(462,'EKIALDEKO ELURMENTA',9,'Dolmen largo abierto','Arruazu','Junto al muro divisorio del Realengo y Huarte Arakil y Arruzau','Guardetxe-E Hoja cartográfica 114-7','114-7',582220,4756380,1101,42.953756,-1.993340,'utm',NULL,'miércoles, marzo 29, 1905','T.Aranzadi y F.Ansoleaga','Túmulo de piedras de 21 m. de ? y 2,8 m. de altura. Cámara con recinto rectangular con 4 losas laterales que tienden a cerrarse en la entrada. La cubierta partida en dos trozos y basculada al SW, en parte cubierta por el túmulo . Calizas del terreno. Orientación a 120º. Ajuar encontrado en la excavación: - 2 hematites rojos - 1 fragmento de estalactita - 3 fragamentos de punta de flecha - 1 trozo de mineral de hierro, carbón, restos animales y restos humanos de al menos tres inhumados, uno infantil. El Museo de Navarra en Pamplona conserva como pertenecientes a este dolmen: - 3 lascas informes - 1 lasca retocada','T.Aranzadi y F.Ansoleaga en 1915.','Previsto para su medición.',NULL,'Bloc 3. Sierra de Aralar meridional'),
(463,'MENDEBAL ELURMENTA',2,'Túmulo','Arruazu',NULL,'Hoja cartográfica 114-7','114-7',582030,4756345,1070,42.953461,-1.995674,'utm',NULL,NULL,NULL,'Túmulo de piedras con cráter central sin losas. Parece indudable que en principio fuese dolmen. No consta en el catálogo de Munibe, lo que se hace extraño.',NULL,'Según J.M.Gamboa, la zona recibe el nombre de Elurmendi. El monumento tiene un túmulo grande y, al parecer, sufrió ataque brutal, al igual que los colindantes, que incluso alguno fue dinamitado y posiblemente éste también. Tal atropello se atribuye a la época en que se construyeron las pistas. Previsto para medir el túmulo.',NULL,'Bloc 3. Sierra de Aralar meridional'),
(464,'ERREGENEKO DEBATA.III',8,'Dolmen corto cerrado','Realengo de Aralar','En la cima de Debata; a pocos metros de la muga Huarte, Arruazu y Realengo.','Guardetxe-E Hoja cartográfica 114-7','114-7',582570,4756390,1135,42.953808,-1.989048,'utm',NULL,'miércoles, marzo 29, 1905','T.Aranzadi y F.Ansoleaga','Túmulo de piedras de 16 m. de ? y 1,6 m. de altura. Cámara con recinto rectangular con 6 losas y cubierta; un tanto poligonalizada por las losas de cierre. La cubierta al parecer in situ. La poligonalización del recinto parece deberse a la presión de las piedras del túmulo. Calizas del terreno. Orientación a 105º. Ajuar encontrado: ver abajo ficha 0464_TEX_546','T.Aranzadi y F.Ansoleaga en 1915','Previsto para medir el túmulo. Bibliografía: - Aranzadi, T.: Exploración de… Aralar. 1918 - " Los gentiles de Aralar. 1919 - Barandiaran, J.M.: Hombre prehistórico. 1953 - " El mundo… 1966. Pág 166 - Pericot, L.: Los sepulcros megalíticos. 1950. - Castillo, A.: El Neoeneolítico. 1954 pág. 480-714',NULL,'Bloc 3. Sierra de Aralar meridional'),
(465,'ERBILERRI',7,'Dolmen corto abierto','Realengo de Aralar','A 300 m. al SSE de Guardetxe y a la derecha de la carretera al Santuario','Guardetxe-E Hoja cartográfica 114-7','114-7',581830,4756580,1061,42.955599,-1.998091,'utm',NULL,'miércoles, marzo 29, 1905','T.Aranzadi y F.Ansoleaga','Túmulo desfigurado de piedras de 8 m. de ? y 2,3 m. de altura. Cámara de 3 losas que tienden ligeramente a cerrarse en la entrada y cubierta desplazada al N y probablemente rota, de la que se conserva un fragmento al E. Puesto de caza de palomas en el túmulo, desfigurándolo; en la actualidad parece que se respeta no poniéndo puesto. Calizas del terreno. Ajuar encontrado en la excavación: - 1 concha fósil - 3 cuentas cilíndircas de varios fragmentos de cerámica gris y basta. El Museo de Navarra de Pamplona conserva como pertenecientes a este dolmen los siguientes objetos: - 2 cuentas globulares de piedra verde - 1 mitad de cuenta globular de caliza - 1 ocre - 2 cuentas de hueso de tipo tonelete - 2 cuentas discoideas de hueso','T.Aranzadi y F.Ansoleaga en 1915','Previsto para su medición. Bibliografía: - Aranzadi, T.: Exploración de… Aralar. 1918 - " Los gentiles de Aralar. 1919 - Barandiaran, J.M.: Hombre prehistórico. 1953 - Pericot, L.: Los sepulcros megalíticos. 1950.',NULL,'Bloc 3. Sierra de Aralar meridional'),
(466,'HEGO AUBIA',7,'Dolmen corto abierto?','Lakunza','A 600 m. al W de Guardetxe, cerca de la muga con el Realengo','Guardetxe-W Hoja cartográfica 114-7','114-7',581890,4756580,1072,42.955592,-1.997355,'utm',NULL,'miércoles, marzo 29, 1905','T.Aranzadi y F.Ansoleaga','Túmulo de piedras de 12 m. de ?. Cámara de 2 losas en pie, basculadas al interior, cerrando la entrada. Otras losas o trozos de ellas en su alrededor. Calizas del terreno. Ajuar encontrado en la excavación: restos humanos de al menos un individuo inhumado. Museo de Navarra de Pamplona.','T.Aranzadi y F.Ansoleaga en 1918','Previsto para medición. El túmulo de piedras es dintingible a distancia las losas removidas rodeando un haya. Bibliografía: - Aranzadi, T.: Exploración de… Aralar. 1918 - Barandiaran, J.M.: Hombre prehistórico. 1953',NULL,'Bloc 3. Sierra de Aralar meridional'),
(467,'HIRUZULO TXIKITA',7,'Dolmen corto abierto','Lakunza','A 820 m. de la Guardetxe, al W de la misma','Guardetxe-W Hoja cartográfica 114-7','114-7',580655,4756660,1085,42.956444,-2.012482,'utm',NULL,'miércoles, marzo 29, 1905','T.Aranzadi y F.Ansoleaga','Túmulo de piedras de 12,4 m. de ?. En el momento de su localización, la cámara tenía tres losas formando el recinto rectangular sin cubierta; hoy no queda más que una. Calizas del terreno. Orientación a 90º. Ajuar encontrado en la excavación: - 2 fragamentos de cerámica con surcos incisos En el Museo de Navarra de Pamplona existe: - 1 fragmento de borde de un vaso con boca de vertedero, decorado en el borde con una hilera de impresiones de uñas muy difícilmente reconocible. Una reconstrucción del borde u boca.','T.Aranzadi y F.Ansoleaga en 1915','Previsto para su medición. Bibliografía: - Aranzadi, T.: Exploración de… Aralar. 1918 - Barandiaran, J.M.: Hombre prehistórico. 1953',NULL,'Bloc 3. Sierra de Aralar meridional'),
(468,'IPAR AUBIA',7,'Dolmen corto abierto?','Errealengo de Aralar','Junto a la tapia mojonera con Lakunza y la pista a Pago Mari','Guardetxe-W Hoja cartográfica 114-7','114-7',581020,4756680,1068,42.956586,-2.008005,'utm',NULL,'miércoles, marzo 29, 1905','T.Aranzadi y F.Ansoleaga','Cuando se localizó tenía 3 losas. Las 2 losas que hoy existen tienden a estrecharse a la entrada del recinto. Orientación a 250º. El monumento se encuentra removido. Calizas del terreno.',NULL,'Previsto para su medición. El dolmen está catalogado por Munibe con el topónimo Iruzulo Txikia Realengo. Bibliografía: - Aranzadi, T.: Exploración de… Aralar. 1918 - Barandiaran, J.M.: Hombre prehistórico. 1953',NULL,'Bloc 3. Sierra de Aralar meridional'),
(469,'SOILTXIKI',7,'Dolmen corto abierto','Lakuntza','Pequeña llanada a unos 100 m. de pared mojonera con Lakuntza y Realengo','Guardetxe-W Hoja cartográfica 114-7','114-7',580325,4756710,1091,42.956929,-2.016520,'utm',NULL,'viernes, mayo 05, 1905','J.Elosegui','Túmulo circular de piedras de 20 m. de ? y 2,3 m. de altura. Cámara de tres losas; la losa N buza a 40º. Cubierta partida en dos trozos, con dos surcos longitudinales, tal vez naturales. Orientación a 85º. Calizas del terreno.','No se conoce','La cámara ha sido totalmente vaciada y se conserva una lasca con retoques de uso en propiedad privada? Previsto para su medición. Bibliografía: - Elosegui, J.: Notas previas… 1953 pág 21. " Materiales para el catálogo… 1953 - Barandiaran, J.M.: Hombre prehistórico. 1953',NULL,'Bloc 3. Sierra de Aralar meridional'),
(470,'TXAGADI',7,'Dolmen corto abierto','Huarte Araquil','Collado entre Debata y Saldiasgain, a 13 m. W de la pared mojonera','Guardetxe-W Hoja cartográfica 114-7','114-7',582385,4755990,1053,42.950227,-1.991374,'utm',NULL,'sábado, mayo 06, 1905','J.Elosegui y C.Menaya','Túmulo desfigurado en los sectores ENE y S y enmascarada al N. Tres losas forman la cámara , con recinto triangular. En su interior yace un trozo de losa, tal vez fragmento de cubierta. Cabecera un poco apuntadada. Orientación a 93º. Calizas del terreno.','No se conoce','Previsto para su medición. Bibliografía: - Barandiaran, J.M.: Hombre prehistórico. 1953',NULL,'Bloc 3. Sierra de Aralar meridional'),
(471,'ETXABEKO ARANTZADI',7,'Dolmen corto abierto','Huarte Araquil','A 450 m. aproximadamente, al NW de la borda de Etxabe','Huarte Araquil-A Hoja cartográfica 114-7','114-7',585570,4755155,915,42.942358,-1.952464,'utm',NULL,'miércoles, marzo 08, 1905','J.Iturralde y Suit','Túmulo de 12 m. de ? y 0,5 m. de alto. En su localización se habla de una cámara de 5 losas; hoy solo hay tres. Según sus excavadores es un sepulcro de corredor. J.M.Barandiaran lo acepta con reservas y se inclina por el dolmen. La tapa de cubierta tiene calculado un peso del orden de las 5 toneladas. Orientación a 95º. Calizas del terreno. Ajuar encontrado en la excavación: - 1 cristal de roca - 1 pulserita de cobre analizada - varios fragmentos de cerámica gris - 1 cuenta de madera - restos humanos de al menos nueve personas inhumadas (cráneos con camecefalia moderada; cráneo femenino deíndice cefálico 78) El museo de Navarra de Pamplona guarda como perteneciente a este dolmen: - varios fragmentos de vaso mediano carenado, con carena alta, fondo globular y cuello alto y ligeramente vuelto. - 1 cristal de roca facetado.','En 1913 por T.Aranzadi y F.Ansoleaga','Previsto para su medición. Tiene colocado un hito señalizador. Bibliografía: - Aranzadi, T.: Exploración de… Aralar. 1918 - Barandiaran, J.M.: Hombre prehistórico. 1953 - Pericot, L.: Los sepulcros megalíticos. 1950. - Iturralde, J.:La prehistoria en Navarra… 1911 - Isturiz, F.: Excursión a San Miguel. 1911 - Fita, F.: Dólmenes de Navarra. 1911 - Riquet, R.: Les crenes de Urtiaga.1926',NULL,'Bloc 3. Sierra de Aralar meridional'),
(472,'URDENATS',7,'Dolmen corto abierto','Huarte Araquil','En el alto de su nombre y cercanías de la divisoira de Baraibar','Huarte Araquil-A Hoja cartográfica 114-7','114-7',585935,4756870,1070,42.957758,-1.947728,'utm',NULL,'miércoles, marzo 08, 1905','J.Iturralde y Suit','Túmulo de 12 m. de ? y 1,85 m. de altura. Cámara de recinto rectangular de tres losas y cubierta al parecer insitu que ha obligado a las losas laterales a cerrarse. Orientación a 140º. Calizas del terreno. Ajuar encontrado en la excavación: - 1 cuenta de piedra verdosa-azulada, translúcida, discodea. - 1 asa de cerámica gris oscura de sección circular - huesos humanos y dientes, escasos Museo de Navarra de Pamplona.','En 1913 por T.Aranzadi y F.Ansoleaga','Previsto para su medición. Tiene colocado un hito señalizador. Bibliografía: - Iturralde y Suit, J.: La prehistoria de Navarra. 1911. - Aranzadi, T.: Exploración de… Aralar. 1918 - Barandiaran, J.M.: Hombre prehistórico. 1953',NULL,'Bloc 3. Sierra de Aralar meridional'),
(473,'ZUBIGOIEN',7,'Dolmen corto abierto','Huarte Araquil','A 150 m. y a 350 N.A de la fuente de Zubigoien','Huarte Araquil-A Hoja cartográfica 114-7','114-7',586500,4756550,965,42.954813,-1.940851,'utm',NULL,'miércoles, mayo 03, 1905','J.Elosegui','Túmulo de piedras de 12 m. de ? y 1,5 m. de altura. Cámara de recinto rectangular de 5 losas ladeadas, sin cubierta. Orientación a 80º. Calizas del terreno.','No se conoce','Previsto para su medición. Tiene colocado un hito señalizador. Bibliografía: - Elosegui, J.: 5 dólmenes en Navarra. 1951 - Barandiaran, J.M.: Hombre prehistórico. 1953',NULL,'Bloc 3. Sierra de Aralar meridional'),
(474,'OTANSUR',1,'Dolmen','Huarte Araquil','En lo más alto de la cota de su nombre','Huarte Araquil-A Hoja cartográfica 114-7','114-7',586280,4756920,1075,42.958169,-1.943491,'utm',NULL,'sábado, mayo 06, 1905','J.Elosegui','Túmulo de 9 m. de ?. 2 losas, desaparecida una losa que estaba en el túmulo. Orientación a 104º. Calizas del terreno.','No se conoce','Previsto para su medición. Tiene no tiene un hito señalizador. Bibliografía: - Barandiaran, J.M.: Hombre prehistórico. 1953',NULL,'Bloc 3. Sierra de Aralar meridional'),
(475,'OTSOPASAJE',7,'Dolmen corto abierto','Huarte Araquil','En el collado de su nombre; a la derecha del camino al Santuario de San Miguel','Santuario-S Hoja cartográfica 114-7','114-7',584820,4754820,971,42.939425,-1.961706,'utm',NULL,'miércoles, marzo 08, 1905','J.Iturralde y Suit','Túmulo casi circular de entre 12 y 13 m. de ?. En su arco N. tiene 1,3 m. de altura. Cámara con recinto rectangular con 3 losas. Orientación al E. según T. Aranzadi y F. Ansoleaga. En la actualidad el dolmen está abierto en dirección N-S ligeramente desviado. Calizas del terreno. Ajuar encontrado en la excavación: - piedrecitas de areniscas - fragamentos informes de sílex y de carbón de madera - restos humanos de al menos tres inhumados En el Museo de Navarra se conserva como perteneciente a este dolmen: - 1 fragmento de cuenta de azabache del tipo de tonelete grande o gigante.','Por T. Aranzadi y F. Ansoleaga en 1913.','Previsto para su medición. Bibliografía: - Aranzadi, T.: Exploración de… Aralar. 1918 - Barandiaran, J.M.: Hombre prehistórico. 1953 - Iturralde, J.:La prehistoria en Navarra… 1911 - Isturiz, F.: Excursión a San Miguel. 1911 - Fita, F.: Dólmenes de Navarra. 1911',NULL,'Bloc 3. Sierra de Aralar meridional'),
(476,'ZUBENTA',8,'Dolmen corto cerrado','Huarte Araquil','En el collado de su nombre; junto y a la derecha del camino de la mina.','Santuario-S Hoja cartográfica 114-7','114-7',583620,4754970,850,42.940909,-1.976390,'utm',NULL,'miércoles, marzo 08, 1905','J.Iturralde y Suit','Cámara de 4 losas y cubierta con recinto hoy trapezoidal, originariamente rectangular probablemente. Una losa lateral se ha corrido probablemente hacia el interior. Cubierta desplazada hacia el E. Orientación a 90º. Ajuar cencontrado durante la excavación: - 1 piedrita brllante - 1 bolita - 1 fragmento de polípero fósil - 1 fragmento de pulser de bronce analizada - 1 cuenta de hoja de cobre no analizada - 1 fondo esférico de vaso - 1 cuenta globular de azabache - huesos humanos de al menos 4 inhumados En el Museo de Navarra de Pamplona se conserva como perteneciente a estes dolmen: - 1 cuenta discoidea de azabache.','Por T. Aranzadi y F. Ansoleaga en 1913.','Previsto para su medición. Bibliografía: - Iturralde y Suit: La Prehistoria en Navarra. 1911. Pág 68 - Aranzadi, T.: Exploración de… Aralar. 1918 - Barandiaran, J.M.: Hombre prehistórico. 1953 - Pericot, L.: Los sepulcros megalíticos. 1950. Pág 250 - Castillo, A.: El Neoeneolítico. 1954 pág. 480-714. Pág 489',NULL,'Bloc 3. Sierra de Aralar meridional'),
(477,'ARTZABAL',8,'Dolmen corto cerrado','Huarte Araquil','A unos 30 m. a la izquierda y a la altura de la primera cruz del camino','Santuario-S Hoja cartográfica 114-7','114-7',584740,4754140,858,42.933312,-1.962790,'utm',NULL,'miércoles, marzo 08, 1905','J.Iturralde y Suit','En la publicación en la que se relata la excavación se habla de una doble cámara (oriental y occidental) de la que se detalla el número de inhumados según Juan Mª Apellaniz, debe tratarse de otro dolmen. Dice que excabó parte del túmulo para cerciorarse de su construcción sin resultado alguno. Cámara de 3 losas y cubierta al parecer in situ con losas de paredes poco abiertas hacia el exterior. Orientación a 90º. Túmulo de 17 m. de diámetro y 1,15 m. de altura. Calizas del terreno.','Por T. Aranzadi y F. Ansoleaga en 1913.','No está clara la definición de sus características originales. Previsto para su medición. Bibliografía: - Iturralde y Suit: La Prehistoria en Navarra. 1911. Pág 68 - Aranzadi, T.: Exploración de… Aralar. 1915. 1918. 1924 - " Los gentiles de Aralar. 1919. Pág 30. - Barandiaran, J.M.: Hombre prehistórico. 1953 - Pericot, L.: Los sepulcros megalíticos. 1950. Pág 250 - Castillo, A.: El Neoeneolítico. 1954 pág. 480-714. Pág 489 - Iturralde, J.:La prehistoria en Navarra… 1911 - Isturiz, F.: Excursión a San Miguel. 1911 - Fita, F.: Dólmenes de Navarra. 1911 - Maluquer de Motes, J.: Notas. 1957, pág. 3-14. 1963, 93-117',NULL,'Bloc 3. Sierra de Aralar meridional'),
(478,'LUPERTA',8,'Dolmen corto cerrado','Huarte Araquil','En el paraje de su nombre; a 1,1 km del Santuario de San Miguel','Santuario-S Hoja cartográfica 114-7','114-7',583625,4755000,910,42.941178,-1.976324,'utm',NULL,'jueves, marzo 09, 1905','J.Iturralde y Suit','Túmulo ligeramente ovalado de 14,5 m. en el eje N-S y de 16,5 m. en el eje E-W. Dolmen formado por dos losas bajas con recinto rectangular y bubierta, pasando a poligonal. Orientación a 100º. Calizas del terreno. Ajuar encontrado en la excavación: - 1 guijo - 1 hoja partida y 1 con escotadura de uso - 1 cuenta de azabache de tipo tonelete - 1 hoja discoidea de cuerno - huesos humanos de al menos dos inhumados. - huesos de animales - (objetos modernos) Museo de Navarra. Pamplona','Por T. Aranzadi y F. Ansoleaga en 1915.','Previsto para su medición. Bibliografía: - Iturralde y Suit: La Prehistoria en Navarra. 1911. Pág 68 - Isturiz, F.: Excursión a San Miguel. 1911 - Fita, F.: Dólmenes de Navarra. 1911 - Aranzadi, T.: Exploración de… Aralar. 1918 - Barandiaran, J.M.: Hombre prehistórico. 1953 - Pericot, L.: Los sepulcros megalíticos. 1950. Pág 250',NULL,'Bloc 3. Sierra de Aralar meridional'),
(479,'ATA (Piedra de Roldán)',13,'Monolito','Huarte Araquil','Valle de Ata; camino de Madoz al Santuario, en zona media.','Hoja cartográfica 114-7','114-7',588557,4756070,960,42.950255,-1.915714,'utm',NULL,'jueves, marzo 09, 1905','J.Iturralde y Suit','Monolito en pie con una altura sobre el terreno de 1,15 m. y una anchura en su base de 0,5 m., variando a lo largo de su desarrollo entre 0,45 y 0,5 m. en su cara 1. La cara 2 tiene 1,1 m. de altura y 0,8 m. de anchura en su base. Conforme se acerca al vértice se va estrechando en anchura, dando medidas que oscilan entre 0,8 y 0,6 m. La cara 3 tiene una altura de 1,15 m., siendo la anchura en su base de 0,52 m. manteniéndose aproximadamente a lo largo de toda la cara. La orientación es de 130º y su conservación es buena. El monolito tiene varias marcas en una de sus caras. La cara 1 tiene 7 incisiones, 6 de ellas paralelas, que desciendende izquierda a derecha con separaciones entre sí que oscilan entre 0,02 y 0,07 m. La longitud de estas marcas varía entre los 0,3 m. la mayor y 0,08 m. la menor. A unos 0,3 m. del suelo y hasta una altura aproximada de 0,6 m. en las partes más salientes, la piedra está pulida. En el año 1986, Jose Mª Ustarroz de Huarte Araquil comunica que corre peligro , dado que un haya que le crece en su cercanía va ser derribada y corre peligro. El 14-1-1988, Enrique Ferranz comunica que el 20-12-1987, con motivo de una excursión del Mitiko, observó que la piedra de Ata se movía como si estuviera rota, al cortar un árbol. En 1988 M. Sierra la vio tumbada en el suelo. Otras comunicaciones fueron de Iosu Imaz de lkuntza y de Iñaki Gaztelu el 15-1-1990. De acuerdo con José Mª ustarroz, se propuso a Ángeles Mezquiriz, reparar y aprovechar para una excavación. Ustarroz tenía un pegamento, pero la Mezquiriz lo supeditó a que lo viera su cuñado antes de nada, y no ha sido así. Nada, un buen día apareció erguida y nos pareció que había sifo apegada, pero por lo visto no ha sido así. Según informe de Miguel Sierra y Carmen Ballesteros, de fecha 24-2-1990, comprobaron que la piedra que creíamos había sido reparada no ha sido así, aunque tiene una pequeña roca en su base, solamente le sirve de apoyo, que si se quitara la piedra volvería a caer.','El mismo año 1895 J.Iturralde y Suit realizó una excavación de la que describe:','"Comenzola mi guía, pero contra lo que yo suponía, la piedra triangular, conservando su forma, penetraba a gran profundidad en el terreno. Era este formado por tierra vegetal finísima, compacta y limpia, sin que en ella se encontrase ni el más pequeño guijarro. A un metro de profundidad la tierra se presentaba más comapacta todavía; tenía el color negruzco azulado del acero y salía adherida a la azada o ael pico en trozos lisos, brillantes y finos comon el barro mejor prensado de una alfarería mecánica. Continuose la excavación y observé que la piedra variaba de forma, naciendo de la arista de donde arrancaban los misteriosos signos una especie de rama o brazo pegado a dicha arista, cuya parte más gruesa está en la parte baja, cual si formase el hombro de una estatua invertida. Ponto alcanzó la excavación 1,87 m. de profundidad y, aunque la piedra continuaba todavía, no fue posible seguir el trabajo emprendido por impedirlo la dificultad de extraer la tierra desde el fondo, careciendo de cestas o terreras, y aplacé para otra ocasión el verficar una excavación completa, cuidando de rellenar, entre tanto la excavación. Desde el punto en que se abandonó ésta, la piedra alcanzaba la longitud de tres metros u se hundía aún en la tierra, conservando siempre, salvo el brazo, su forma triangular." Tras la excavación la interpretación que el prehistoriador dio a este monolito, es la siguiente: "Evidentemente no era una muga prehistórica, como yo sospeché , tan extraño monumento, y dada su extraordinaria altura, más parece un mehir, notable por ser muy escasos los que como este ostentan una inscripción o signos grabados. Pero si es un menhir y ocupa la posición en que se le colocara como los demás monumentos de su clase, el nivel de tierra ha variado considerablemente, aumentando su altura hasta dejarlo casi enterrado. Y ¿ es creíble que si ete monumento fuese debido, no a una elevación insensible y constante del terreno, sino a despendimientos de tierras de alturas inmediatas, quedara en pie esa piedra escasa base (0,56 m de lado) y tan considerable elevación?. Eso no es verosímil, y nos hace pensar que la piedra ha sido enterrada al erigirse el monumento con arreglo quizás a un rito, creencia o superstición que hoy desconocemos y que tal vez explicaran los surcos misteriosos grabados en su parte superior, que es la única dejada al descubierto" Posteriormente no se conoce excavación o cata alguna. Bibliografía: - Barandiaran, J.M.: 1972. 1973. 1980 - Frankowski, E.: 1920 - Iturrralde y Suit, J.: 1911 - Mélida, J.R.: 1942 - Saralegui y Medina, M.: 1918 Bibliografía: - Iturralde y Suit: La Prehistoria en Navarra. 1911. Pág 68 - Isturiz, F.: Excursión a San Miguel. 1911 - Fita, F.: Dólmenes de Navarra. 1911 - Aranzadi, T.: Exploración de… Aralar. 1918 - Barandiaran, J.M.: Hombre prehistórico. 1953 - Pericot, L.: Los sepulcros megalíticos. 1950. Pág 250',NULL,'Bloc 3. Sierra de Aralar meridional');
